function embeddedTestHarnessAuthorized(): boolean {
  const supplied = process.env.VERITAS_TEST_HARNESS_CAPABILITY;
  return (
    TEST_HARNESS_BUILD_CAPABILITY !== TEST_HARNESS_DISABLED_SENTINEL &&
    typeof supplied === "string" &&
    /^[0-9a-f]{64}$/.test(supplied) &&
    supplied === TEST_HARNESS_BUILD_CAPABILITY
  );
}

function boundedTestLaneActive(): boolean {
  return selfTestWitnessConstructionEnabled || embeddedTestHarnessAuthorized();
}

