type Subject = {
  subjectType: "REQUEST" | "RESPONSE" | "DECLARED_OUTPUT" | "FINAL_CANDIDATE" | "ACCEPTED_ARTIFACT" | "DESTINATION_RESULT";
  digest: string;
};

type SubjectLineageV1 = {
  schemaVersion: 1;
  request: Subject;
  response: Subject;
  declaredOutput: Subject;
  finalCandidate: Subject;
  acceptedArtifact: Subject;
  destinationResult: Subject;
};

function validateSubjectLineage(lineage: SubjectLineageV1): void {
  const entries: Array<[Subject, Subject["subjectType"]]> = [
    [lineage.request, "REQUEST"], [lineage.response, "RESPONSE"], [lineage.declaredOutput, "DECLARED_OUTPUT"],
    [lineage.finalCandidate, "FINAL_CANDIDATE"], [lineage.acceptedArtifact, "ACCEPTED_ARTIFACT"], [lineage.destinationResult, "DESTINATION_RESULT"],
  ];
  if (lineage.schemaVersion !== 1 || entries.some(([subject, expected]) => subject.subjectType !== expected || !isSha256Digest(subject.digest))) {
    fail("SUBJECT_LINEAGE_INVALID", "Every lineage subject must have its exact typed schema and digest.");
  }
  if (new Set(entries.map(([subject]) => subject.digest)).size !== entries.length) {
    fail("SUBJECT_LINEAGE_COLLISION", "Each transformation must emit a distinct subject digest.");
  }
}

type EvidenceStatusV1 = "PASS" | "FAIL" | "NOT_RUN" | "ERROR" | "INCONCLUSIVE";
type EvidenceRecordV1 = {
  schemaVersion: 1;
  status: EvidenceStatusV1;
  participated: boolean;
  scope: string;
  issuer: string;
  subjectDigest: string;
};

function validateEvidenceRecord(record: EvidenceRecordV1): void {
  if (record.schemaVersion !== 1 || !["PASS", "FAIL", "NOT_RUN", "ERROR", "INCONCLUSIVE"].includes(record.status) || typeof record.participated !== "boolean" || typeof record.scope !== "string" || record.scope.length === 0 || typeof record.issuer !== "string" || record.issuer.length === 0 || !isSha256Digest(record.subjectDigest)) {
    fail("EVIDENCE_RECORD_INVALID", "Evidence status, participation, scope, issuer, and subject digest are mandatory and typed.");
  }
  if (record.status !== "PASS" && record.participated === true && record.status === "NOT_RUN") fail("EVIDENCE_PARTICIPATION_CONTRADICTION", "NOT_RUN evidence cannot claim participation.");
}

function evaluateCertificationPolicy(records: EvidenceRecordV1[], requiredScopes: string[]): "CERTIFIED" | "UNCERTIFIED" {
  for (const record of records) validateEvidenceRecord(record);
  const byScope = new Map(records.map((record) => [record.scope, record]));
  return requiredScopes.length > 0 && requiredScopes.every((scope) => {
    const record = byScope.get(scope);
    return record?.status === "PASS" && record.participated === true;
  }) ? "CERTIFIED" : "UNCERTIFIED";
}

type EventRecordV1 = { schemaVersion: 1; eventId: string; eventType: string; payload: JsonValue; eventDigest: string };
class AppendOnlyEventStoreV1 {
  #events = new Map<string, EventRecordV1>();
  append(event: Omit<EventRecordV1, "eventDigest">): EventRecordV1 {
    const eventDigest = sha256Bytes(canonicalJson(event));
    const record = { ...event, eventDigest };
    const prior = this.#events.get(event.eventId);
    if (prior !== undefined) {
      if (prior.eventDigest !== eventDigest) fail("EVENT_MUTATION_REJECTED", "An event ID cannot be reused for divergent bytes.");
      return { ...prior };
    }
    this.#events.set(event.eventId, record);
    return { ...record };
  }
  replay(): EventRecordV1[] { return [...this.#events.values()].map((event) => ({ ...event })); }
}

function materializeEventState(events: EventRecordV1[]): { stateDigest: string; viewDigest: string } {
  let prior = "GENESIS";
  for (const event of events) {
    if (!isSha256Digest(event.eventDigest) || event.eventDigest !== sha256Bytes(canonicalJson({ schemaVersion: event.schemaVersion, eventId: event.eventId, eventType: event.eventType, payload: event.payload }))) fail("MATERIALIZER_EVENT_INVALID", "Materializer requires canonical event digests.");
    prior = sha256Bytes(canonicalJson({ prior, eventDigest: event.eventDigest }));
  }
  return { stateDigest: prior, viewDigest: sha256Bytes(canonicalJson({ view: "default", stateDigest: prior })) };
}

type ExplainBundleV1 = { schemaVersion: 1; status: string; evidence: EvidenceRecordV1[]; limitations: string[]; dependencyDigest: string };
function explainBundle(evidence: EvidenceRecordV1[], limitations: string[]): ExplainBundleV1 {
  evidence.forEach(validateEvidenceRecord);
  return { schemaVersion: 1, status: evaluateCertificationPolicy(evidence, evidence.map((record) => record.scope)), evidence: evidence.map((record) => ({ ...record })), limitations: [...limitations], dependencyDigest: sha256Bytes(canonicalJson({ evidence, limitations })) };
}
type EstablishedEvidenceEnvelopeV1 = { schemaVersion: 1; establishedAt: string; expiresAt: string | null; evidence: EvidenceRecordV1[] };
function importEstablishedEvidence(value: unknown, now = new Date()): EstablishedEvidenceEnvelopeV1 {
  const candidate = value as Partial<EstablishedEvidenceEnvelopeV1>;
  if (candidate?.schemaVersion !== 1 || typeof candidate.establishedAt !== "string" || !Array.isArray(candidate.evidence)) {
    fail("ESTABLISHED_EVIDENCE_INVALID", "Established evidence requires schema, establishment time, and evidence records.");
  }
  const established = new Date(candidate.establishedAt);
  if (!Number.isFinite(established.getTime()) || (candidate.expiresAt !== null && typeof candidate.expiresAt !== "string")) {
    fail("ESTABLISHED_EVIDENCE_INVALID", "Established evidence timestamps must be valid ISO values.");
  }
  const expires = candidate.expiresAt === null ? null : new Date(candidate.expiresAt);
  if (expires !== null && (!Number.isFinite(expires.getTime()) || expires.getTime() <= established.getTime())) fail("ESTABLISHED_EVIDENCE_INVALID", "Evidence expiry must follow establishment.");
  candidate.evidence.forEach((record) => validateEvidenceRecord(record));
  if (expires !== null && now.getTime() >= expires.getTime()) fail("ESTABLISHED_EVIDENCE_EXPIRED", "Established evidence is expired and cannot participate.");
  return { schemaVersion: 1, establishedAt: established.toISOString(), expiresAt: expires?.toISOString() ?? null, evidence: candidate.evidence.map((record) => ({ ...record })) };
}
type DevelopmentAttestationV1 = { schemaVersion: 1; issuer: string; subjectDigest: string; signature: string };
function signDevelopmentAttestation(subjectDigest: string, issuer: string, privateKey: ReturnType<typeof generateKeyPairSync>["privateKey"]): DevelopmentAttestationV1 {
  const body = { schemaVersion: 1 as const, issuer, subjectDigest };
  return { ...body, signature: signEd25519(null, Buffer.from(canonicalJson(body)), privateKey).toString("base64url") };
}
function verifyDevelopmentAttestation(attestation: DevelopmentAttestationV1, publicKey: ReturnType<typeof generateKeyPairSync>["publicKey"]): boolean {
  if (attestation.schemaVersion !== 1 || typeof attestation.issuer !== "string" || !isSha256Digest(attestation.subjectDigest)) return false;
  const { signature: _signature, ...body } = attestation;
  return verifyEd25519(null, Buffer.from(canonicalJson(body)), publicKey, Buffer.from(attestation.signature, "base64url"));
}

