class VeritasError extends Error {
  readonly code: string;
  readonly details: JsonValue;

  constructor(
    code: string,
    message: string,
    details: JsonValue = null,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "VeritasError";
    this.code = code;
    this.details = details;
  }
}

class SimulatedCrash extends Error {
  readonly point: SimulatedCrashPoint;

  constructor(point: SimulatedCrashPoint) {
    super(`Simulated abrupt process loss at ${point}.`);
    this.name = "SimulatedCrash";
    this.point = point;
  }
}

function fail(code: string, message: string, details: JsonValue = null): never {
  throw new VeritasError(code, message, details);
}

function canonicalize(value: unknown): JsonValue {
  if (value === null || typeof value === "string" || typeof value === "boolean") {
    return value;
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) {
      fail("INVALID_JSON_NUMBER", "Canonical JSON cannot contain a non-finite number.");
    }
    return value;
  }
  if (Array.isArray(value)) {
    return value.map((item) => canonicalize(item));
  }
  if (typeof value === "object") {
    const object = value as Record<string, unknown>;
    const output: { [key: string]: JsonValue } = {};
    for (const key of Object.keys(object).sort(codePointCompare)) {
      if (object[key] === undefined) {
        fail("INVALID_JSON_VALUE", `Canonical JSON cannot contain undefined at ${key}.`);
      }
      output[key] = canonicalize(object[key]);
    }
    return output;
  }
  fail("INVALID_JSON_VALUE", `Unsupported canonical JSON value: ${typeof value}.`);
}

function canonicalJson(value: unknown): string {
  return JSON.stringify(canonicalize(value));
}

function requireExactObjectKeys(
  value: unknown,
  expectedKeys: readonly string[],
  code: string,
  label: string,
): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail(code, `${label} must be an object with exact fields.`);
  }
  const record = value as Record<string, unknown>;
  const observedKeys = Object.keys(record).sort(codePointCompare);
  const expected = [...expectedKeys].sort(codePointCompare);
  if (canonicalJson(observedKeys) !== canonicalJson(expected)) {
    fail(code, `${label} fields differ from the frozen schema.`, { observedKeys, expectedKeys: expected });
  }
  return record;
}

function sha256Bytes(value: string | Buffer): string {
  return createHash("sha256").update(value).digest("hex");
}

type PinnedNpmInvocationEvidence = {
  npm: string;
  node: string;
  lifecycleEvent: "test";
  lifecycleScript: string;
  packageJsonPath: string;
  nodeExecPath: string;
  execArgv: [];
  nodeOptions: null;
  nodePath: null;
};

function requirePinnedNpmTestInvocation(): PinnedNpmInvocationEvidence {
  const sourceArgument = process.argv[1];
  const npmUserAgent = process.env.npm_config_user_agent;
  const npmRuntimeMatch = npmUserAgent?.match(/^npm\/([^ ]+) node\/([^ ]+) /);
  const expectedPackageJsonPath =
    sourceArgument === undefined
      ? null
      : join(dirname(resolve(sourceArgument)), "package.json");
  const observedPackageJsonPath = process.env.npm_package_json;
  const observedNodeExecPath = process.env.npm_node_execpath;
  if (
    npmRuntimeMatch === undefined ||
    npmRuntimeMatch === null ||
    npmRuntimeMatch[1] !== PINNED_TOOLCHAIN_V1.npm ||
    npmRuntimeMatch[2] !== PINNED_TOOLCHAIN_V1.node ||
    process.env.npm_lifecycle_event !== "test" ||
    process.env.npm_lifecycle_script !== PINNED_PACKAGE_MANIFEST_V1.scripts.test ||
    expectedPackageJsonPath === null ||
    observedPackageJsonPath === undefined ||
    resolve(observedPackageJsonPath) !== expectedPackageJsonPath ||
    observedNodeExecPath === undefined ||
    resolve(observedNodeExecPath) !== resolve(process.execPath) ||
    process.execArgv.length !== 0 ||
    process.env.NODE_OPTIONS !== undefined ||
    process.env.NODE_PATH !== undefined
  ) {
    fail(
      "TOOLCHAIN_RUNTIME_MISMATCH",
      "Self-test must run through the exact pinned npm test lifecycle.",
      {
        npmUserAgent: npmUserAgent ?? null,
        lifecycleEvent: process.env.npm_lifecycle_event ?? null,
        lifecycleScript: process.env.npm_lifecycle_script ?? null,
        packageJsonPath: observedPackageJsonPath ?? null,
        expectedPackageJsonPath,
        npmNodeExecPath: observedNodeExecPath ?? null,
        processExecPath: process.execPath,
        execArgv: process.execArgv,
        nodeOptions: process.env.NODE_OPTIONS ?? null,
        nodePath: process.env.NODE_PATH ?? null,
      },
    );
  }
  return {
    npm: npmRuntimeMatch[1],
    node: npmRuntimeMatch[2],
    lifecycleEvent: "test",
    lifecycleScript: process.env.npm_lifecycle_script,
    packageJsonPath: expectedPackageJsonPath,
    nodeExecPath: resolve(process.execPath),
    execArgv: [],
    nodeOptions: null,
    nodePath: null,
  };
}

function codePointCompare(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function updateFrame(hash: ReturnType<typeof createHash>, tag: number, value: Buffer): void {
  const header = Buffer.alloc(9);
  header.writeUInt8(tag, 0);
  header.writeBigUInt64BE(BigInt(value.byteLength), 1);
  hash.update(header);
  hash.update(value);
}

function isWithin(parentPath: string, childPath: string): boolean {
  const parent = resolve(parentPath);
  const child = resolve(childPath);
  const pathFromParent = relative(parent, child);
  return (
    pathFromParent === "" ||
    (!pathFromParent.startsWith(`..${sep}`) && pathFromParent !== ".." && !isAbsolute(pathFromParent))
  );
}

function normalizeRelativePath(input: string): string {
  const normalized = input.split(sep).join("/");
  if (
    normalized === "" ||
    normalized.startsWith("/") ||
    normalized.includes("\0") ||
    normalized.split("/").some((part) => part === "" || part === "." || part === "..")
  ) {
    fail("INVALID_RELATIVE_PATH", `Unsafe relative path: ${input}.`);
  }
  return normalized;
}

async function pathExists(path: string): Promise<boolean> {
  try {
    await lstat(path);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

async function readStableRegularFile(
  path: string,
  errorCode: string,
  label: string,
): Promise<{ bytes: Buffer; identity: FileIdentityStamp }> {
  if (typeof fsConstants.O_NOFOLLOW !== "number") {
    fail(
      "FILESYSTEM_IDENTITY_PROFILE_UNSUPPORTED",
      "This host does not expose O_NOFOLLOW for stable file admission.",
    );
  }
  let handle: Awaited<ReturnType<typeof open>> | null = null;
  try {
    const pathBefore = await lstat(path, { bigint: true });
    if (!pathBefore.isFile() || pathBefore.isSymbolicLink()) {
      fail(errorCode, `${label} must be a regular non-symlink file.`);
    }
    await stableReadTestHook?.({ path, stage: "AFTER_PATH_STAT" });
    handle = await open(path, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
    await stableReadTestHook?.({ path, stage: "AFTER_HANDLE_OPEN" });
    const handleBefore = await handle.stat({ bigint: true });
    const pathBeforeIdentity = fileIdentityStamp(pathBefore);
    const handleBeforeIdentity = fileIdentityStamp(handleBefore);
    if (!fileIdentityStampsEqual(pathBeforeIdentity, handleBeforeIdentity)) {
      fail(errorCode, `${label} pathname changed before its file handle was pinned.`);
    }
    const bytes = await handle.readFile();
    const handleAfter = await handle.stat({ bigint: true });
    const pathAfter = await lstat(path, { bigint: true });
    const handleAfterIdentity = fileIdentityStamp(handleAfter);
    const pathAfterIdentity = fileIdentityStamp(pathAfter);
    if (
      !fileIdentityStampsEqual(handleBeforeIdentity, handleAfterIdentity) ||
      !fileIdentityStampsEqual(handleAfterIdentity, pathAfterIdentity) ||
      BigInt(bytes.byteLength) !== handleAfter.size
    ) {
      fail(errorCode, `${label} identity changed while its pinned handle was read.`);
    }
    return { bytes, identity: handleAfterIdentity };
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    return fail(errorCode, `${label} could not be read through a stable file handle.`, {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  } finally {
    if (handle !== null) await handle.close();
  }
}

async function readPinnedToolchainEvidence(): Promise<{
  toolchain: {
    schemaVersion: 1;
    profile: string;
    node: string;
    npm: string;
    modules: string;
    sqlite: string;
    uv: string;
    v8: string;
    openssl: string;
  };
  packageEvidenceDigests: {
    packageManifest: string;
    packageLock: string;
    npmrc: string;
  };
  npmInvocation: PinnedNpmInvocationEvidence;
  sourceSnapshot: {
    sourceDigest: string;
  };
}> {
  await assertSelfTestSourceSnapshotStable();
  const npmInvocation = requirePinnedNpmTestInvocation();
  const sourceDirectory = dirname(npmInvocation.packageJsonPath);
  const packageManifestRead = await readStableRegularFile(
    join(sourceDirectory, "package.json"),
    "TOOLCHAIN_MANIFEST_MISMATCH",
    "Private package manifest",
  );
  const packageLockRead = await readStableRegularFile(
    join(sourceDirectory, "package-lock.json"),
    "TOOLCHAIN_MANIFEST_MISMATCH",
    "Private package lock",
  );
  const npmrcRead = await readStableRegularFile(
    join(sourceDirectory, ".npmrc"),
    "TOOLCHAIN_MANIFEST_MISMATCH",
    "Private npm configuration",
  );
  const packageEvidenceDigests = {
    packageManifest: sha256Bytes(packageManifestRead.bytes),
    packageLock: sha256Bytes(packageLockRead.bytes),
    npmrc: sha256Bytes(npmrcRead.bytes),
  };
  if (
    canonicalJson(packageEvidenceDigests) !==
    canonicalJson(PINNED_PACKAGE_EVIDENCE_DIGESTS_V1)
  ) {
    fail(
      "TOOLCHAIN_MANIFEST_MISMATCH",
      "Private package evidence bytes differ from the exact digest contract.",
      {
        observedDigests: packageEvidenceDigests,
        expectedDigests: PINNED_PACKAGE_EVIDENCE_DIGESTS_V1,
      },
    );
  }
  let packageManifest: unknown;
  let packageLock: unknown;
  try {
    packageManifest = JSON.parse(packageManifestRead.bytes.toString("utf8"));
    packageLock = JSON.parse(packageLockRead.bytes.toString("utf8"));
  } catch {
    fail("TOOLCHAIN_MANIFEST_MISMATCH", "Private package evidence is not exact JSON.");
  }
  if (canonicalJson(packageManifest) !== canonicalJson(PINNED_PACKAGE_MANIFEST_V1)) {
    fail(
      "TOOLCHAIN_MANIFEST_MISMATCH",
      "The private package manifest differs from the exact embedded contract.",
    );
  }
  if (canonicalJson(packageLock) !== canonicalJson(PINNED_PACKAGE_LOCK_V1)) {
    fail(
      "TOOLCHAIN_MANIFEST_MISMATCH",
      "The private dependency lock differs from the exact zero-dependency contract.",
    );
  }
  if (npmrcRead.bytes.toString("utf8") !== PINNED_NPMRC_V1) {
    fail(
      "TOOLCHAIN_MANIFEST_MISMATCH",
      "The private npm enforcement configuration differs.",
    );
  }
  const sqliteVersion = process.versions.sqlite;
  if (sqliteVersion === undefined) {
    fail(
      "TOOLCHAIN_RUNTIME_MISMATCH",
      "The active Node runtime does not expose the required SQLite version evidence.",
    );
  }
  const observedToolchain = {
    schemaVersion: 1 as const,
    profile: TOOLCHAIN_PROFILE,
    node: process.version,
    npm: npmInvocation.npm,
    modules: process.versions.modules,
    sqlite: sqliteVersion,
    uv: process.versions.uv,
    v8: process.versions.v8,
    openssl: process.versions.openssl,
  };
  if (canonicalJson(observedToolchain) !== canonicalJson(PINNED_TOOLCHAIN_V1)) {
    fail(
      "TOOLCHAIN_RUNTIME_MISMATCH",
      "The active Node runtime differs from the exact private toolchain manifest.",
      {
        observedToolchain,
        expectedToolchain: PINNED_TOOLCHAIN_V1,
      },
    );
  }
  await assertSelfTestSourceSnapshotStable();
  return {
    toolchain: observedToolchain,
    packageEvidenceDigests,
    npmInvocation,
    sourceSnapshot: {
      sourceDigest: requireSelfTestSourceSnapshot().sourceDigest,
    },
  };
}

async function listTreeEntries(rootPath: string): Promise<TreeEntry[]> {
  const root = resolve(rootPath);
  const rootInfo = await lstat(root);
  if (!rootInfo.isDirectory()) {
    fail("CANDIDATE_NOT_DIRECTORY", `Candidate must be a directory: ${root}.`);
  }

  const entries: TreeEntry[] = [];
  const collisionKeys = new Map<string, string>();

  async function walk(directory: string, prefix: string): Promise<void> {
    const children = await readdir(directory, { withFileTypes: true });
    children.sort((left, right) => codePointCompare(left.name, right.name));

    for (const child of children) {
      const relativeName = prefix === "" ? child.name : `${prefix}/${child.name}`;
      const normalizedName = normalizeRelativePath(relativeName);
      if (normalizedName === ".veritas" || normalizedName.startsWith(".veritas/")) {
        fail("RESERVED_CANDIDATE_PATH", "Candidate content may not contain .veritas state.", {
          path: normalizedName,
        });
      }

      const absoluteName = join(directory, child.name);
      const before = await lstat(absoluteName, { bigint: true });
      if (before.isSymbolicLink()) {
        fail("SYMLINK_UNSUPPORTED", "Symlinks are rejected by the first artifact profile.", {
          path: normalizedName,
        });
      }
      if (before.isDirectory()) {
        await walk(absoluteName, normalizedName);
        continue;
      }
      if (!before.isFile()) {
        fail("SPECIAL_FILE_UNSUPPORTED", "Only regular files are supported.", {
          path: normalizedName,
        });
      }

      const collisionKey = normalizedName.normalize("NFC").toLocaleLowerCase("en-US");
      const earlier = collisionKeys.get(collisionKey);
      if (earlier !== undefined && earlier !== normalizedName) {
        fail("PORTABLE_PATH_COLLISION", "Candidate contains a Unicode or case-colliding path.", {
          first: earlier,
          second: normalizedName,
        });
      }
      collisionKeys.set(collisionKey, normalizedName);

      const stableRead = await readStableRegularFile(
        absoluteName,
        "SOURCE_CHANGED_DURING_READ",
        `Candidate file ${normalizedName}`,
      );
      if (!fileIdentityStampsEqual(fileIdentityStamp(before), stableRead.identity)) {
        fail("SOURCE_CHANGED_DURING_READ", "Candidate changed after directory enumeration.", {
          path: normalizedName,
        });
      }
      const bytes = stableRead.bytes;

      entries.push({
        absolutePath: absoluteName,
        relativePath: normalizedName,
        deviceId: stableRead.identity.deviceId,
        inodeId: stableRead.identity.inodeId,
        ctimeNs: stableRead.identity.ctimeNs,
        mtimeNs: stableRead.identity.mtimeNs,
        linkCount: stableRead.identity.linkCount,
        mode: stableRead.identity.mode,
        executableBits: Number(before.mode & 0o111n),
        size: bytes.byteLength,
        contentDigest: sha256Bytes(bytes),
      });
    }
  }

  await walk(root, "");
  entries.sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  return entries;
}

async function fingerprintTree(rootPath: string): Promise<TreeFingerprint> {
  const entries = await listTreeEntries(rootPath);
  const hash = createHash("sha256");
  updateFrame(hash, 0, Buffer.from(TREE_PROFILE, "utf8"));

  for (const entry of entries) {
    const stableRead = await readStableRegularFile(
      entry.absolutePath,
      "SOURCE_CHANGED_DURING_READ",
      `Candidate file ${entry.relativePath}`,
    );
    if (
      stableRead.identity.deviceId !== entry.deviceId ||
      stableRead.identity.inodeId !== entry.inodeId ||
      stableRead.identity.ctimeNs !== entry.ctimeNs ||
      stableRead.identity.mtimeNs !== entry.mtimeNs ||
      stableRead.identity.linkCount !== entry.linkCount ||
      stableRead.identity.mode !== entry.mode ||
      stableRead.identity.size !== entry.size.toString()
    ) {
      fail("SOURCE_CHANGED_DURING_READ", "Candidate file identity changed before hashing.", {
        path: entry.relativePath,
      });
    }
    const bytes = stableRead.bytes;
    if (
      bytes.byteLength !== entry.size ||
      sha256Bytes(bytes) !== entry.contentDigest
    ) {
      fail("SOURCE_CHANGED_DURING_READ", "Candidate changed between listing and hashing.", {
        path: entry.relativePath,
      });
    }
    updateFrame(hash, 1, Buffer.from(entry.relativePath, "utf8"));
    updateFrame(hash, 2, Buffer.from("regular-file", "utf8"));
    const mode = Buffer.alloc(4);
    mode.writeUInt32BE(entry.executableBits);
    updateFrame(hash, 3, mode);
    updateFrame(hash, 4, bytes);
  }

  return { digest: hash.digest("hex"), entries };
}

async function readPrivateDirectoryIdentity(
  directoryPath: string,
  errorCode: string,
  label: string,
  exactMode?: "0700",
): Promise<DirectoryIdentityStamp> {
  try {
    const resolvedPath = resolve(directoryPath);
    const information = await lstat(resolvedPath, { bigint: true });
    if (!information.isDirectory() || information.isSymbolicLink()) {
      fail(errorCode, `${label} must be a real directory.`);
    }
    if ((await realpath(resolvedPath)) !== resolvedPath) {
      fail(errorCode, `${label} must retain its exact canonical path.`);
    }
    const effectiveUid = typeof process.getuid === "function" ? String(process.getuid()) : null;
    const mode = (information.mode & 0o7777n).toString(8).padStart(4, "0");
    if (
      effectiveUid === null ||
      String(information.uid) !== effectiveUid ||
      (exactMode !== undefined ? mode !== exactMode : (information.mode & 0o022n) !== 0n)
    ) {
      fail(errorCode, `${label} ownership or permissions are outside the local private profile.`, {
        observedUid: String(information.uid),
        effectiveUid,
        observedMode: mode,
        expectedMode: exactMode ?? "NOT_GROUP_OR_WORLD_WRITABLE",
      });
    }
    return {
      deviceId: String(information.dev),
      inodeId: String(information.ino),
      ownerUid: String(information.uid),
      ownerGid: String(information.gid),
      mode,
    };
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail(errorCode, `${label} could not be validated as an exact private directory.`, {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

function directoryIdentityStampsEqual(
  left: DirectoryIdentityStamp,
  right: DirectoryIdentityStamp,
): boolean {
  return canonicalJson(left) === canonicalJson(right);
}

function derivedWorkspaceDirectorySet(entries: TreeEntry[]): string[] {
  const directories = new Set<string>();
  for (const entry of entries) {
    const parts = entry.relativePath.split("/");
    for (let depth = 1; depth < parts.length; depth += 1) {
      directories.add(parts.slice(0, depth).join("/"));
    }
  }
  return [...directories].sort(codePointCompare);
}

function observedAlphaWorkspaceDeviceId(path: string, actualDeviceId: string): string {
  if (alphaWorkspaceDeviceIdTestHook === null) return actualDeviceId;
  if (!boundedTestLaneActive()) {
    fail("TEST_ONLY_ALPHA_WORKSPACE_HOOK_REJECTED", "Alpha workspace device hook escaped the bounded test lane.");
  }
  return alphaWorkspaceDeviceIdTestHook(path, actualDeviceId);
}

function assertAlphaWorkspaceFingerprintOnDevice(
  fingerprint: TreeFingerprint,
  expectedDeviceId: string,
  errorCode: string,
  label: string,
): void {
  for (const entry of fingerprint.entries) {
    const observedDeviceId = observedAlphaWorkspaceDeviceId(entry.absolutePath, entry.deviceId);
    if (observedDeviceId !== expectedDeviceId) {
      fail(errorCode, `${label} contains a regular file on a foreign device.`, {
        path: entry.relativePath,
        expectedDeviceId,
        observedDeviceId,
      });
    }
  }
}

async function assertAlphaWorkspaceDirectoryTreeOnDevice(
  rootPath: string,
  expectedDeviceId: string,
  errorCode: string,
  label: string,
): Promise<void> {
  async function walk(directory: string, prefix: string): Promise<void> {
    const children = await readdir(directory, { withFileTypes: true });
    children.sort((left, right) => codePointCompare(left.name, right.name));
    for (const child of children) {
      const relativeName = normalizeRelativePath(prefix === "" ? child.name : `${prefix}/${child.name}`);
      const absoluteName = join(directory, child.name);
      const information = await lstat(absoluteName, { bigint: true });
      if (information.isSymbolicLink() || (!information.isDirectory() && !information.isFile())) {
        fail(errorCode, `${label} may contain only real directories and regular files.`, { path: relativeName });
      }
      const observedDeviceId = observedAlphaWorkspaceDeviceId(absoluteName, String(information.dev));
      if (observedDeviceId !== expectedDeviceId) {
        fail(errorCode, `${label} contains an entry on a foreign device.`, {
          path: relativeName,
          expectedDeviceId,
          observedDeviceId,
        });
      }
      if (information.isDirectory()) await walk(absoluteName, relativeName);
    }
  }
  await walk(resolve(rootPath), "");
}

async function listWorkspaceDirectorySet(
  rootPath: string,
  expectedDeviceId: string,
): Promise<string[]> {
  const root = resolve(rootPath);
  const rootIdentity = await readPrivateDirectoryIdentity(root, "ALPHA_WORKSPACE_ROOT_INVALID", "Alpha workspace root", "0700");
  if (observedAlphaWorkspaceDeviceId(root, rootIdentity.deviceId) !== expectedDeviceId) {
    fail("ALPHA_WORKSPACE_DEVICE_MISMATCH", "Alpha workspace root is on a foreign device.");
  }
  const directories: string[] = [];
  async function walk(directory: string, prefix: string): Promise<void> {
    const children = await readdir(directory, { withFileTypes: true });
    children.sort((left, right) => codePointCompare(left.name, right.name));
    for (const child of children) {
      const relativeName = normalizeRelativePath(prefix === "" ? child.name : `${prefix}/${child.name}`);
      const absoluteName = join(directory, child.name);
      const information = await lstat(absoluteName);
      if (information.isSymbolicLink()) {
        fail("ALPHA_WORKSPACE_ROOT_INVALID", "Alpha workspace content may not contain symbolic links.", { path: relativeName });
      }
      if (information.isDirectory()) {
        const identity = await readPrivateDirectoryIdentity(absoluteName, "ALPHA_WORKSPACE_ROOT_INVALID", `Alpha workspace directory ${relativeName}`, "0700");
        if (observedAlphaWorkspaceDeviceId(absoluteName, identity.deviceId) !== expectedDeviceId) {
          fail("ALPHA_WORKSPACE_DEVICE_MISMATCH", "Alpha workspace directory is on a foreign device.", { path: relativeName });
        }
        directories.push(relativeName);
        await walk(absoluteName, relativeName);
      } else if (!information.isFile()) {
        fail("ALPHA_WORKSPACE_ROOT_INVALID", "Alpha workspace content may contain only regular files and directories.", { path: relativeName });
      }
    }
  }
  await walk(root, "");
  directories.sort(codePointCompare);
  return directories;
}

function alphaWorkspaceDirectorySetDigest(directories: string[]): string {
  return sha256Bytes(`veritas-alpha-workspace-directory-set-v1\0${canonicalJson(directories)}`);
}

function assertAlphaWorkspaceLimits(fingerprint: TreeFingerprint): { fileCount: number; totalBytes: number } {
  const fileCount = fingerprint.entries.length;
  const totalBytes = fingerprint.entries.reduce((sum, entry) => sum + entry.size, 0);
  if (fileCount > ALPHA_WORKSPACE_LIMITS.maxFiles || totalBytes > ALPHA_WORKSPACE_LIMITS.maxTotalBytes) {
    fail("ALPHA_WORKSPACE_LIMIT_EXCEEDED", "Alpha workspace materialization exceeds the frozen file-count or byte limit.", {
      fileCount,
      totalBytes,
      limits: ALPHA_WORKSPACE_LIMITS,
    });
  }
  for (const entry of fingerprint.entries) {
    const pathBytes = Buffer.byteLength(entry.relativePath, "utf8");
    const depth = entry.relativePath.split("/").length;
    if (pathBytes > ALPHA_WORKSPACE_LIMITS.maxPathBytes || depth > ALPHA_WORKSPACE_LIMITS.maxDepth) {
      fail("ALPHA_WORKSPACE_LIMIT_EXCEEDED", "Alpha workspace materialization exceeds the frozen path limit.", {
        path: entry.relativePath,
        pathBytes,
        depth,
      });
    }
  }
  return { fileCount, totalBytes };
}

function assertAlphaWorkspaceSourceSingleLinks(fingerprint: TreeFingerprint): void {
  for (const entry of fingerprint.entries) {
    if (entry.linkCount !== "1") {
      fail("ALPHA_WORKSPACE_SOURCE_HARDLINK_ALIAS", "Prepared-object files must have one filesystem link before workspace materialization.", {
        path: entry.relativePath,
        linkCount: entry.linkCount,
      });
    }
  }
}

function assertAlphaWorkspaceSourceStable(
  before: TreeFingerprint,
  after: TreeFingerprint,
): void {
  if (canonicalJson(before) !== canonicalJson(after)) {
    fail("ALPHA_WORKSPACE_SOURCE_CHANGED", "Prepared-object identity changed during workspace materialization.");
  }
}

function assertAlphaWorkspaceIndependentCopy(
  source: TreeFingerprint,
  destination: TreeFingerprint,
): void {
  const destinationByPath = new Map(destination.entries.map((entry) => [entry.relativePath, entry]));
  if (source.entries.length !== destination.entries.length) {
    fail("ALPHA_WORKSPACE_COPY_MISMATCH", "Workspace file count differs from the prepared object.");
  }
  for (const sourceEntry of source.entries) {
    const destinationEntry = destinationByPath.get(sourceEntry.relativePath);
    if (destinationEntry === undefined) {
      fail("ALPHA_WORKSPACE_COPY_MISMATCH", "Workspace is missing a prepared-object file.", { path: sourceEntry.relativePath });
    }
    if (
      sourceEntry.linkCount !== "1" ||
      destinationEntry.linkCount !== "1" ||
      (sourceEntry.deviceId === destinationEntry.deviceId && sourceEntry.inodeId === destinationEntry.inodeId)
    ) {
      fail("ALPHA_WORKSPACE_ALIAS_REJECTED", "Workspace files must be independent single-link inodes.", {
        path: sourceEntry.relativePath,
      });
    }
    if (
      sourceEntry.contentDigest !== destinationEntry.contentDigest ||
      sourceEntry.size !== destinationEntry.size ||
      sourceEntry.executableBits !== destinationEntry.executableBits
    ) {
      fail("ALPHA_WORKSPACE_COPY_MISMATCH", "Workspace file bytes or executable bits differ from the prepared object.", {
        path: sourceEntry.relativePath,
      });
    }
    const destinationPermissions = Number(BigInt(destinationEntry.mode) & 0o7777n);
    if (destinationPermissions !== (0o600 | sourceEntry.executableBits)) {
      fail("ALPHA_WORKSPACE_COPY_MISMATCH", "Workspace file permissions differ from the frozen copy profile.", {
        path: sourceEntry.relativePath,
      });
    }
  }
}

function validateAuthority(value: unknown): Authority {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("INVALID_AUTHORITY", "Authority must be a JSON object.");
  }
  const candidate = value as Partial<Authority>;
  if (candidate.schemaVersion !== 1) {
    fail("INVALID_AUTHORITY", "Authority schemaVersion must equal 1.");
  }
  if (typeof candidate.profileId !== "string" || candidate.profileId.trim() === "") {
    fail("INVALID_AUTHORITY", "Authority profileId must be a non-empty string.");
  }
  if (!Array.isArray(candidate.requiredFiles) || !candidate.requiredFiles.every((item) => typeof item === "string")) {
    fail("INVALID_AUTHORITY", "Authority requiredFiles must be a string array.");
  }
  if (
    !Array.isArray(candidate.forbiddenSuffixes) ||
    !candidate.forbiddenSuffixes.every((item) => typeof item === "string" && item !== "")
  ) {
    fail("INVALID_AUTHORITY", "Authority forbiddenSuffixes must be a non-empty-string array.");
  }
  const maxFileBytes = candidate.maxFileBytes;
  if (typeof maxFileBytes !== "number" || !Number.isSafeInteger(maxFileBytes) || maxFileBytes < 1) {
    fail("INVALID_AUTHORITY", "Authority maxFileBytes must be a positive safe integer.");
  }

  const requiredFiles = candidate.requiredFiles.map(normalizeRelativePath).sort(codePointCompare);
  if (new Set(requiredFiles).size !== requiredFiles.length) {
    fail("INVALID_AUTHORITY", "Authority requiredFiles contains duplicates.");
  }
  const forbiddenSuffixes = [...candidate.forbiddenSuffixes].sort(codePointCompare);
  if (new Set(forbiddenSuffixes).size !== forbiddenSuffixes.length) {
    fail("INVALID_AUTHORITY", "Authority forbiddenSuffixes contains duplicates.");
  }

  return {
    schemaVersion: 1,
    profileId: candidate.profileId,
    requiredFiles,
    forbiddenSuffixes,
    maxFileBytes,
  };
}

function fileIdentityStamp(info: Awaited<ReturnType<typeof lstat>>): FileIdentityStamp {
  const value = info as unknown as {
    dev: bigint;
    ino: bigint;
    ctimeNs: bigint;
    mtimeNs: bigint;
    nlink: bigint;
    size: bigint;
    mode: bigint;
  };
  return {
    deviceId: value.dev.toString(),
    inodeId: value.ino.toString(),
    ctimeNs: value.ctimeNs.toString(),
    mtimeNs: value.mtimeNs.toString(),
    linkCount: value.nlink.toString(),
    size: value.size.toString(),
    mode: value.mode.toString(),
  };
}

function fileIdentityStampsEqual(left: FileIdentityStamp, right: FileIdentityStamp): boolean {
  return canonicalJson(left) === canonicalJson(right);
}

function fileStructuralIdentityStampsEqual(
  left: FileIdentityStamp,
  right: FileIdentityStamp,
): boolean {
  return canonicalJson({
    deviceId: left.deviceId,
    inodeId: left.inodeId,
    linkCount: left.linkCount,
    size: left.size,
    mode: left.mode,
  }) === canonicalJson({
    deviceId: right.deviceId,
    inodeId: right.inodeId,
    linkCount: right.linkCount,
    size: right.size,
    mode: right.mode,
  });
}

async function readAuthority(authorityPath: string): Promise<{
  authority: Authority;
  digest: string;
  identity: FileIdentityStamp;
}> {
  const absolutePath = resolve(authorityPath);
  const stableRead = await readStableRegularFile(
    absolutePath,
    "AUTHORITY_CHANGED_DURING_READ",
    "Authority",
  );
  const parsed = JSON.parse(stableRead.bytes.toString("utf8")) as unknown;
  const authority = validateAuthority(parsed);
  return {
    authority,
    digest: sha256Bytes(`${AUTHORITY_PROFILE}\0${canonicalJson(authority)}`),
    identity: stableRead.identity,
  };
}

function assertAuthorityNotAliasedByCandidate(
  authority: { identity: FileIdentityStamp },
  candidate: TreeFingerprint,
): void {
  const alias = candidate.entries.find(
    (entry) =>
      entry.deviceId === authority.identity.deviceId &&
      entry.inodeId === authority.identity.inodeId,
  );
  if (alias !== undefined) {
    fail(
      "AUTHORITY_HARDLINK_ALIAS_IN_CANDIDATE",
      "Candidate contains a hard-link alias to the authority file.",
      { path: alias.relativePath },
    );
  }
}

function runDeterministicChecks(
  authority: Authority,
  fingerprint: TreeFingerprint,
): Decision["checks"] {
  const entryByPath = new Map(fingerprint.entries.map((entry) => [entry.relativePath, entry]));

  for (const requiredPath of authority.requiredFiles) {
    if (!entryByPath.has(requiredPath)) {
      fail("REQUIRED_FILE_MISSING", `Required file is missing: ${requiredPath}.`, {
        requiredPath,
      });
    }
  }

  for (const entry of fingerprint.entries) {
    if (entry.size > authority.maxFileBytes) {
      fail("FILE_TOO_LARGE", `File exceeds authority limit: ${entry.relativePath}.`, {
        path: entry.relativePath,
        size: entry.size,
        maxFileBytes: authority.maxFileBytes,
      });
    }
    const forbidden = authority.forbiddenSuffixes.find((suffix) => entry.relativePath.endsWith(suffix));
    if (forbidden !== undefined) {
      fail("FORBIDDEN_FILE", `Candidate contains a forbidden file: ${entry.relativePath}.`, {
        path: entry.relativePath,
        suffix: forbidden,
      });
    }
  }

  return [
    {
      checkId: "required-files",
      status: "PASS",
      evidence: { required: authority.requiredFiles.length },
    },
    {
      checkId: "forbidden-suffixes",
      status: "PASS",
      evidence: { scanned: fingerprint.entries.length },
    },
    {
      checkId: "file-size-limit",
      status: "PASS",
      evidence: { maxFileBytes: authority.maxFileBytes },
    },
  ];
}

function makeEnvelope<T>(record: T): Envelope<T> {
  return {
    envelopeVersion: 1,
    recordDigest: sha256Bytes(canonicalJson(record)),
    record,
  };
}

function verifyEnvelope<T>(envelope: Envelope<T>): T {
  if (envelope.envelopeVersion !== 1) {
    fail("INVALID_ENVELOPE", "Unsupported envelope version.");
  }
  const observedDigest = sha256Bytes(canonicalJson(envelope.record));
  if (observedDigest !== envelope.recordDigest) {
    fail("RECORD_TAMPERED", "Stored record digest does not match its content.", {
      expected: envelope.recordDigest,
      observed: observedDigest,
    });
  }
  return envelope.record;
}

async function readEnvelope<T>(path: string): Promise<T> {
  await lstat(path);
  const { bytes } = await readStableRegularFile(path, "RECORD_TAMPERED", "Stored envelope");
  const envelope = JSON.parse(bytes.toString("utf8")) as Envelope<T>;
  return verifyEnvelope(envelope);
}

async function readVerifiedEnvelope<T>(path: string): Promise<{
  record: T;
  recordDigest: string;
}> {
  await lstat(path);
  const { bytes } = await readStableRegularFile(path, "RECORD_TAMPERED", "Stored envelope");
  const envelope = JSON.parse(bytes.toString("utf8")) as Envelope<T>;
  const record = verifyEnvelope(envelope);
  return { record, recordDigest: envelope.recordDigest };
}

async function readStableVerifiedEnvelope<T>(
  path: string,
  errorCode: string,
  label: string,
): Promise<{ record: T; recordDigest: string; identity: FileIdentityStamp }> {
  const { bytes, identity } = await readStableRegularFile(path, errorCode, label);
  let envelope: Envelope<T>;
  try {
    envelope = JSON.parse(bytes.toString("utf8")) as Envelope<T>;
  } catch {
    fail(errorCode, `${label} is not valid JSON.`);
  }
  const record = verifyEnvelope(envelope);
  return { record, recordDigest: envelope.recordDigest, identity };
}

async function readStableEnvelope<T>(path: string, errorCode: string, label: string): Promise<T> {
  return (await readStableVerifiedEnvelope<T>(path, errorCode, label)).record;
}

async function syncDirectory(directoryPath: string): Promise<void> {
  const handle = await open(directoryPath, "r");
  try {
    await handle.sync();
  } finally {
    await handle.close();
  }
}

async function removeDurable(path: string): Promise<void> {
  await rm(path, { force: true });
  await syncDirectory(dirname(path));
}

async function writeAtomic(path: string, value: unknown): Promise<void> {
  await mkdir(dirname(path), { recursive: true });
  const temporaryPath = join(dirname(path), `.${randomUUID()}.tmp`);
  let handle: Awaited<ReturnType<typeof open>> | null = null;
  let renamed = false;
  try {
    handle = await open(temporaryPath, "wx", 0o600);
    await handle.writeFile(`${JSON.stringify(value, null, 2)}\n`, "utf8");
    await handle.sync();
    await handle.close();
    handle = null;
    await rename(temporaryPath, path);
    renamed = true;
    await syncDirectory(dirname(path));
  } finally {
    if (handle !== null) await handle.close();
    if (!renamed) await rm(temporaryPath, { force: true });
  }
}

async function writeEnvelope<T>(path: string, record: T): Promise<void> {
  await writeAtomic(path, makeEnvelope(record));
}

function validateWitnessTip(value: unknown): WitnessTipV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("WITNESS_RECORD_INVALID", "Witness tip is not an object.");
  }
  const tip = value as Partial<WitnessTipV1>;
  if (
    typeof tip.storeId !== "string" ||
    tip.storeId.length === 0 ||
    !Number.isSafeInteger(tip.revision) ||
    (tip.revision ?? -1) < 0 ||
    !isSha256Digest(tip.commitRecordDigest) ||
    (tip.previousCommitRecordDigest !== null && !isSha256Digest(tip.previousCommitRecordDigest)) ||
    !isSha256Digest(tip.stateDigest) ||
    !isSha256Digest(tip.headRecordDigest)
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness tip fields are malformed.");
  }
  return tip as WitnessTipV1;
}

function validateWitnessRecoveryIntent(value: unknown): WitnessRecoveryIntentV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("WITNESS_RECORD_INVALID", "Witness recovery intent is not an object.");
  }
  const intent = value as Partial<WitnessRecoveryIntentV1>;
  const transactionIds = intent.transactionIds;
  if (
    !isCanonicalUuidV4(intent.storeId) ||
    !Number.isSafeInteger(intent.fromRevision) ||
    (intent.fromRevision ?? -1) < 0 ||
    !isSha256Digest(intent.fromStateDigest) ||
    !isSha256Digest(intent.fromCommitRecordDigest) ||
    !Number.isSafeInteger(intent.toRevision) ||
    intent.toRevision !== (intent.fromRevision ?? -2) + 1 ||
    intent.toPhase !== "RECOVERY_REQUIRED" ||
    typeof intent.reasonCode !== "string" ||
    intent.reasonCode.length === 0 ||
    !isSha256Digest(intent.reasonDigest) ||
    !Array.isArray(transactionIds) ||
    transactionIds.some((id) => typeof id !== "string" || id.length === 0 || id.length > 256) ||
    canonicalJson(transactionIds) !== canonicalJson([...transactionIds].sort(codePointCompare)) ||
    new Set(transactionIds).size !== transactionIds.length ||
    (intent.observedReferenceDigest !== null && !isSha256Digest(intent.observedReferenceDigest)) ||
    (intent.observedReferenceTransactionId !== null &&
      (typeof intent.observedReferenceTransactionId !== "string" ||
        intent.observedReferenceTransactionId.length === 0 ||
        intent.observedReferenceTransactionId.length > 256)) ||
    !["NONE", "REVERIFY_REQUIRED"].includes(intent.nextTrustLifecycle ?? "")
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness recovery intent fields are malformed.");
  }
  if (
    intent.reasonDigest !== sha256Bytes(intent.reasonCode) ||
    ((intent.observedReferenceDigest === null) !==
      (intent.observedReferenceTransactionId === null))
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness recovery intent semantics are inconsistent.");
  }
  return { ...(intent as WitnessRecoveryIntentV1), transactionIds: [...transactionIds] };
}

function validateWitnessWithdrawalRequest(value: unknown): WitnessWithdrawalRequestV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("WITNESS_RECORD_INVALID", "Witness withdrawal request is not an object.");
  }
  const request = value as Partial<WitnessWithdrawalRequestV1>;
  const recoveryIntent = validateWitnessRecoveryIntent(request.recoveryIntent);
  if (
    !isSha256Digest(request.recoveryIntentDigest) ||
    request.recoveryIntentDigest !== sha256Bytes(canonicalJson(recoveryIntent))
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness withdrawal request digest is invalid.");
  }
  return { recoveryIntent, recoveryIntentDigest: request.recoveryIntentDigest };
}

function validateWitnessWithdrawal(value: unknown): WitnessWithdrawalV1 {
  const request = validateWitnessWithdrawalRequest(value);
  const withdrawnAt = (value as Partial<WitnessWithdrawalV1>).withdrawnAt;
  if (!isCanonicalIsoInstant(withdrawnAt)) {
    fail("WITNESS_RECORD_INVALID", "Witness withdrawal timestamp is malformed.");
  }
  return { ...request, withdrawnAt };
}

function validateWitnessRecord(value: unknown): WitnessRecordV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("WITNESS_RECORD_INVALID", "Witness record is not an object.");
  }
  const record = value as Partial<WitnessRecordV1>;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "MONOTONIC_WITNESS" ||
    record.protocol !== WITNESS_PROTOCOL ||
    typeof record.witnessId !== "string" ||
    record.witnessId.length === 0 ||
    !isSha256Digest(record.bindingDigest) ||
    !Number.isSafeInteger(record.witnessVersion) ||
    (record.witnessVersion ?? -1) < 0 ||
    (record.previousWitnessRecordDigest !== null &&
      !isSha256Digest(record.previousWitnessRecordDigest)) ||
    !["SELECTED", "WITHDRAWN"].includes(record.state ?? "") ||
    record.highWatermark === undefined ||
    typeof record.recordedAt !== "string"
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness record fields are malformed.");
  }
  if (
    (record.witnessVersion === 0 && record.previousWitnessRecordDigest !== null) ||
    ((record.witnessVersion ?? 0) > 0 && record.previousWitnessRecordDigest === null)
  ) {
    fail("WITNESS_RECORD_INVALID", "Witness record ancestry is malformed.");
  }
  const highWatermark = validateWitnessTip(record.highWatermark);
  if (record.state === "SELECTED") {
    const selectedTip = validateWitnessTip(record.selectedTip);
    if (
      canonicalJson(selectedTip) !== canonicalJson(highWatermark) ||
      record.withdrawal !== null
    ) {
      fail("WITNESS_RECORD_INVALID", "SELECTED witness must select its exact high-watermark.");
    }
    return { ...(record as WitnessRecordV1), highWatermark, selectedTip, withdrawal: null };
  }
  const withdrawal = validateWitnessWithdrawal(record.withdrawal);
  if (record.selectedTip !== null) {
    fail("WITNESS_RECORD_INVALID", "WITHDRAWN witness must retain no selected tip.");
  }
  return {
    ...(record as WitnessRecordV1),
    highWatermark,
    selectedTip: null,
    withdrawal,
  };
}

function validateCoordinatorRecoveryResolution(
  value: unknown,
): CoordinatorRecoveryResolutionV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion",
      "recordType",
      "profile",
      "disposition",
      "storeId",
      "witnessId",
      "witnessBindingDigest",
      "withdrawnRecordDigest",
      "withdrawalOperationId",
      "highWatermark",
      "recoveryIntentDigest",
      "barrierId",
      "barrierRecordDigest",
      "recoveryRevision",
      "recoveryStateDigest",
      "recoveryCommitRecordDigest",
      "recoveryHeadRecordDigest",
      "observedReferenceDigest",
      "observedReferenceTransactionId",
      "authorizing",
      "barrierActive",
    ],
    "RECOVERY_RESOLUTION_INVALID",
    "Coordinator recovery resolution",
  ) as Partial<CoordinatorRecoveryResolutionV1>;
  const highWatermark = validateWitnessTip(record.highWatermark);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "COORDINATOR_RECOVERY_RESOLUTION" ||
    record.profile !== RECOVERY_RESOLUTION_PROFILE ||
    record.disposition !== "HOLD_RECOVERY_REQUIRED" ||
    !isCanonicalUuidV4(record.storeId) ||
    !isCanonicalUuidV4(record.witnessId) ||
    !isSha256Digest(record.witnessBindingDigest) ||
    !isSha256Digest(record.withdrawnRecordDigest) ||
    typeof record.withdrawalOperationId !== "string" ||
    !/^withdraw:v1:[0-9a-f]{64}$/u.test(record.withdrawalOperationId) ||
    !isSha256Digest(record.recoveryIntentDigest) ||
    typeof record.barrierId !== "string" ||
    record.barrierId !== `withdrawal-${sha256Bytes(record.withdrawalOperationId)}` ||
    !isSha256Digest(record.barrierRecordDigest) ||
    !Number.isSafeInteger(record.recoveryRevision) ||
    record.recoveryRevision !== highWatermark.revision + 1 ||
    !isSha256Digest(record.recoveryStateDigest) ||
    !isSha256Digest(record.recoveryCommitRecordDigest) ||
    !isSha256Digest(record.recoveryHeadRecordDigest) ||
    (record.observedReferenceDigest !== null &&
      !isSha256Digest(record.observedReferenceDigest)) ||
    (record.observedReferenceTransactionId !== null &&
      !isCanonicalUuidV4(record.observedReferenceTransactionId)) ||
    ((record.observedReferenceDigest === null) !==
      (record.observedReferenceTransactionId === null)) ||
    record.authorizing !== false ||
    record.barrierActive !== true
  ) {
    fail("RECOVERY_RESOLUTION_INVALID", "Coordinator recovery resolution fields are malformed.");
  }
  if (
    highWatermark.storeId !== record.storeId ||
    highWatermark.stateDigest === record.recoveryStateDigest ||
    highWatermark.commitRecordDigest === record.recoveryCommitRecordDigest
  ) {
    fail(
      "RECOVERY_RESOLUTION_INVALID",
      "Coordinator recovery resolution does not separate the withdrawn tip from recovery closure.",
    );
  }
  return { ...(record as CoordinatorRecoveryResolutionV1), highWatermark };
}

function recoveryResolutionDigest(value: CoordinatorRecoveryResolutionV1): string {
  return sha256Bytes(canonicalJson(validateCoordinatorRecoveryResolution(value)));
}

function witnessRecoveryResolutionOperationKey(
  witnessId: string,
  bindingDigest: string,
  withdrawnRecordDigest: string,
  barrierRecordDigest: string,
  resolutionDigestValue: string,
): JsonValue {
  if (
    !isCanonicalUuidV4(witnessId) ||
    !isSha256Digest(bindingDigest) ||
    !isSha256Digest(withdrawnRecordDigest) ||
    !isSha256Digest(barrierRecordDigest) ||
    !isSha256Digest(resolutionDigestValue)
  ) {
    fail("RECOVERY_RESOLUTION_INVALID", "Recovery resolution operation binding is malformed.");
  }
  return {
    schemaVersion: 1,
    protocol: RECOVERY_RESOLUTION_SELECTION_PROTOCOL,
    operation: "SELECT_HOLD_RECOVERY_REQUIRED",
    witnessId,
    bindingDigest,
    withdrawnRecordDigest,
    barrierRecordDigest,
    resolutionDigest: resolutionDigestValue,
  };
}

function witnessRecoveryResolutionOperationId(
  witnessId: string,
  bindingDigest: string,
  withdrawnRecordDigest: string,
  barrierRecordDigest: string,
  resolutionDigestValue: string,
): string {
  return `resolve:v1:${sha256Bytes(canonicalJson(
    witnessRecoveryResolutionOperationKey(
      witnessId,
      bindingDigest,
      withdrawnRecordDigest,
      barrierRecordDigest,
      resolutionDigestValue,
    ),
  ))}`;
}

function validateWitnessRecoveryResolutionSelection(
  value: unknown,
): WitnessRecoveryResolutionSelectionV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion",
      "recordType",
      "protocol",
      "witnessId",
      "bindingDigest",
      "withdrawnRecordDigest",
      "resolutionDigest",
      "resolution",
      "operationId",
    ],
    "RECOVERY_RESOLUTION_INVALID",
    "Witness recovery resolution selection",
  ) as Partial<WitnessRecoveryResolutionSelectionV1>;
  const resolution = validateCoordinatorRecoveryResolution(record.resolution);
  const expectedResolutionDigest = recoveryResolutionDigest(resolution);
  const expectedOperationId = witnessRecoveryResolutionOperationId(
    resolution.witnessId,
    resolution.witnessBindingDigest,
    resolution.withdrawnRecordDigest,
    resolution.barrierRecordDigest,
    expectedResolutionDigest,
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "WITNESS_RECOVERY_RESOLUTION_SELECTION" ||
    record.protocol !== RECOVERY_RESOLUTION_SELECTION_PROTOCOL ||
    record.witnessId !== resolution.witnessId ||
    record.bindingDigest !== resolution.witnessBindingDigest ||
    record.withdrawnRecordDigest !== resolution.withdrawnRecordDigest ||
    record.resolutionDigest !== expectedResolutionDigest ||
    record.operationId !== expectedOperationId
  ) {
    fail("RECOVERY_RESOLUTION_INVALID", "Witness recovery resolution selection is inconsistent.");
  }
  return { ...(record as WitnessRecoveryResolutionSelectionV1), resolution };
}

const RECOVERY_RESOLUTION_LIMITATIONS = Object.freeze([
  "SAME_USER_PERSISTENT_FIXTURE",
  "NO_PROTECTED_AUTHORITY",
  "NO_POWER_LOSS",
  "NO_MULTI_WRITER",
  "NO_PRODUCTION_OR_RELEASE_CREDIT",
] as const);

function validateCoordinatorRecoveryResolutionClosure(
  value: unknown,
): CoordinatorRecoveryResolutionClosureV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion",
      "recordType",
      "profile",
      "status",
      "storeId",
      "recoveryStateDigest",
      "recoveryCommitRecordDigest",
      "barrierId",
      "barrierRecordDigest",
      "withdrawnRecordDigest",
      "resolutionDigest",
      "witnessSelectionRecordDigest",
      "operationId",
      "authorizing",
      "barrierActive",
      "limitations",
    ],
    "RECOVERY_RESOLUTION_INVALID",
    "Coordinator recovery resolution closure",
  ) as Partial<CoordinatorRecoveryResolutionClosureV1>;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "COORDINATOR_RECOVERY_RESOLUTION_CLOSURE" ||
    record.profile !== RECOVERY_RESOLUTION_PROFILE ||
    record.status !== "RECOVERY_RESOLUTION_SELECTED_TRUST_WITHHELD" ||
    !isCanonicalUuidV4(record.storeId) ||
    !isSha256Digest(record.recoveryStateDigest) ||
    !isSha256Digest(record.recoveryCommitRecordDigest) ||
    typeof record.barrierId !== "string" ||
    record.barrierId.length === 0 ||
    !isSha256Digest(record.barrierRecordDigest) ||
    !isSha256Digest(record.withdrawnRecordDigest) ||
    !isSha256Digest(record.resolutionDigest) ||
    !isSha256Digest(record.witnessSelectionRecordDigest) ||
    typeof record.operationId !== "string" ||
    !/^resolve:v1:[0-9a-f]{64}$/u.test(record.operationId) ||
    record.authorizing !== false ||
    record.barrierActive !== true ||
    canonicalJson(record.limitations) !== canonicalJson(RECOVERY_RESOLUTION_LIMITATIONS)
  ) {
    fail("RECOVERY_RESOLUTION_INVALID", "Recovery resolution closure fields are malformed.");
  }
  return record as CoordinatorRecoveryResolutionClosureV1;
}

function validateCoordinatorRecoveryResolutionReference(
  value: unknown,
): CoordinatorRecoveryResolutionReferenceV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion",
      "recordType",
      "storeId",
      "resolutionDigest",
      "closureRecordDigest",
      "witnessSelectionRecordDigest",
    ],
    "RECOVERY_RESOLUTION_INVALID",
    "Coordinator recovery resolution reference",
  ) as Partial<CoordinatorRecoveryResolutionReferenceV1>;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "COORDINATOR_RECOVERY_RESOLUTION_REFERENCE" ||
    !isCanonicalUuidV4(record.storeId) ||
    !isSha256Digest(record.resolutionDigest) ||
    !isSha256Digest(record.closureRecordDigest) ||
    !isSha256Digest(record.witnessSelectionRecordDigest)
  ) {
    fail("RECOVERY_RESOLUTION_INVALID", "Recovery resolution reference fields are malformed.");
  }
  return record as CoordinatorRecoveryResolutionReferenceV1;
}

function witnessSelectOperationKey(
  witnessId: string,
  bindingDigest: string,
  expectedRecordDigest: string,
  nextTipValue: WitnessTipV1,
): JsonValue {
  const nextTip = validateWitnessTip(nextTipValue);
  return {
    schemaVersion: 1,
    protocol: WITNESS_PROTOCOL,
    operation: "SELECT",
    witnessId,
    bindingDigest,
    expectedRecordDigest,
    nextTip,
  };
}

function witnessSelectOperationId(
  witnessId: string,
  bindingDigest: string,
  expectedRecordDigest: string,
  nextTip: WitnessTipV1,
): string {
  return `select:v1:${sha256Bytes(canonicalJson(
    witnessSelectOperationKey(witnessId, bindingDigest, expectedRecordDigest, nextTip),
  ))}`;
}

function witnessWithdrawalOperationKey(
  witnessId: string,
  bindingDigest: string,
  expectedRecordDigest: string,
  requestValue: WitnessWithdrawalRequestV1,
): JsonValue {
  const request = validateWitnessWithdrawalRequest(requestValue);
  return {
    schemaVersion: 1,
    protocol: WITNESS_PROTOCOL,
    operation: "WITHDRAW",
    witnessId,
    bindingDigest,
    expectedRecordDigest,
    request,
  };
}

function witnessWithdrawalOperationId(
  witnessId: string,
  bindingDigest: string,
  expectedRecordDigest: string,
  request: WitnessWithdrawalRequestV1,
): string {
  return `withdraw:v1:${sha256Bytes(canonicalJson(
    witnessWithdrawalOperationKey(witnessId, bindingDigest, expectedRecordDigest, request),
  ))}`;
}

function witnessWithdrawalRequestMatchesTip(
  requestValue: WitnessWithdrawalRequestV1,
  tipValue: WitnessTipV1,
): boolean {
  const request = validateWitnessWithdrawalRequest(requestValue);
  const tip = validateWitnessTip(tipValue);
  return (
    request.recoveryIntent.storeId === tip.storeId &&
    request.recoveryIntent.fromRevision === tip.revision &&
    request.recoveryIntent.fromStateDigest === tip.stateDigest &&
    request.recoveryIntent.fromCommitRecordDigest === tip.commitRecordDigest
  );
}

function cloneWitnessRecord(record: VerifiedWitnessRecord): VerifiedWitnessRecord {
  return JSON.parse(JSON.stringify(record)) as VerifiedWitnessRecord;
}

let selfTestWitnessConstructionEnabled = false;

class TestOnlyMonotonicWitnessOracle implements MonotonicWitnessV1 {
  readonly protocol = WITNESS_PROTOCOL;
  readonly implementationClass = "TEST_ONLY_ORACLE" as const;
  readonly witnessId: string;
  #available = true;
  #history: VerifiedWitnessRecord[] = [];

  private constructor(witnessId: string) {
    this.witnessId = witnessId;
    Object.freeze(this);
  }

  static createForSelfTest(): TestOnlyMonotonicWitnessOracle {
    if (!selfTestWitnessConstructionEnabled) {
      fail(
        "TEST_ONLY_WITNESS_CONSTRUCTION_REJECTED",
        "The in-memory witness oracle can be constructed only inside the embedded self-test.",
      );
    }
    return new TestOnlyMonotonicWitnessOracle(randomUUID());
  }

  setAvailableForSelfTest(available: boolean): void {
    this.#available = available;
  }

  async observe(bindingDigest: string): Promise<VerifiedWitnessRecord> {
    if (!this.#available) fail("WITNESS_UNAVAILABLE", "Monotonic witness is unavailable.");
    const current = this.#history.at(-1);
    if (current === undefined) fail("WITNESS_UNINITIALIZED", "Monotonic witness is not enrolled.");
    if (current.record.bindingDigest !== bindingDigest) {
      fail("WITNESS_BINDING_MISMATCH", "Witness is enrolled to another kernel binding.");
    }
    return cloneWitnessRecord(current);
  }

  async enroll(bindingDigest: string, tipValue: WitnessTipV1): Promise<VerifiedWitnessRecord> {
    if (!this.#available) fail("WITNESS_UNAVAILABLE", "Monotonic witness is unavailable.");
    if (this.#history.length !== 0) {
      fail("WITNESS_CAS_CONFLICT", "Witness enrollment already exists.");
    }
    if (!isSha256Digest(bindingDigest)) {
      fail("WITNESS_BINDING_MISMATCH", "Witness binding digest is malformed.");
    }
    const tip = validateWitnessTip(tipValue);
    const record: WitnessRecordV1 = {
      schemaVersion: 1,
      recordType: "MONOTONIC_WITNESS",
      protocol: WITNESS_PROTOCOL,
      witnessId: this.witnessId,
      bindingDigest,
      witnessVersion: 0,
      previousWitnessRecordDigest: null,
      state: "SELECTED",
      highWatermark: tip,
      selectedTip: tip,
      withdrawal: null,
      recordedAt: new Date().toISOString(),
    };
    return this.#append(record);
  }

  async compareAndSelect(
    expectedRecordDigest: string,
    nextTipValue: WitnessTipV1,
    operationId: string,
  ): Promise<VerifiedWitnessRecord> {
    const current = await this.#currentForCas(expectedRecordDigest);
    if (current.record.state !== "SELECTED") {
      fail("WITNESS_WITHDRAWN", "A withdrawn witness is terminal in this protocol slice.");
    }
    const nextTip = validateWitnessTip(nextTipValue);
    if (
      operationId !== witnessSelectOperationId(
        this.witnessId,
        current.record.bindingDigest,
        expectedRecordDigest,
        nextTip,
      )
    ) {
      fail(
        operationId.startsWith("select:v1:")
          ? "WITNESS_OPERATION_ID_CONFLICT"
          : "WITNESS_OPERATION_ID_INVALID",
        "Witness selection operation ID is not transition-bound.",
      );
    }
    const previousTip = current.record.highWatermark;
    if (
      nextTip.storeId !== previousTip.storeId ||
      nextTip.revision !== previousTip.revision + 1 ||
      nextTip.previousCommitRecordDigest !== previousTip.commitRecordDigest
    ) {
      fail("WITNESS_MONOTONICITY_VIOLATION", "Witness selection is not the exact next commit.");
    }
    const record: WitnessRecordV1 = {
      ...current.record,
      witnessVersion: current.record.witnessVersion + 1,
      previousWitnessRecordDigest: current.recordDigest,
      state: "SELECTED",
      highWatermark: nextTip,
      selectedTip: nextTip,
      withdrawal: null,
      recordedAt: new Date().toISOString(),
    };
    return this.#append(record);
  }

  async compareAndWithdraw(
    expectedRecordDigest: string,
    requestValue: WitnessWithdrawalRequestV1,
    operationId: string,
  ): Promise<VerifiedWitnessRecord> {
    const current = await this.#currentForCas(expectedRecordDigest);
    if (current.record.state !== "SELECTED") {
      fail("WITNESS_WITHDRAWAL_CONFLICT", "Witness is already withdrawn.");
    }
    const request = validateWitnessWithdrawalRequest(requestValue);
    if (!witnessWithdrawalRequestMatchesTip(request, current.record.highWatermark)) {
      fail(
        "WITNESS_WITHDRAWAL_CONFLICT",
        "Witness withdrawal does not describe the exact selected high-watermark.",
      );
    }
    if (
      operationId !== witnessWithdrawalOperationId(
        this.witnessId,
        current.record.bindingDigest,
        expectedRecordDigest,
        request,
      )
    ) {
      fail(
        operationId.startsWith("withdraw:v1:")
          ? "WITNESS_OPERATION_ID_CONFLICT"
          : "WITNESS_OPERATION_ID_INVALID",
        "Witness withdrawal operation ID is not transition-bound.",
      );
    }
    const withdrawal = validateWitnessWithdrawal({
      ...request,
      withdrawnAt: new Date().toISOString(),
    });
    const record: WitnessRecordV1 = {
      ...current.record,
      witnessVersion: current.record.witnessVersion + 1,
      previousWitnessRecordDigest: current.recordDigest,
      state: "WITHDRAWN",
      highWatermark: current.record.highWatermark,
      selectedTip: null,
      withdrawal,
      recordedAt: withdrawal.withdrawnAt,
    };
    return this.#append(record);
  }

  async #currentForCas(expectedRecordDigest: string): Promise<VerifiedWitnessRecord> {
    if (!this.#available) fail("WITNESS_UNAVAILABLE", "Monotonic witness is unavailable.");
    const current = this.#history.at(-1);
    if (current === undefined) fail("WITNESS_UNINITIALIZED", "Monotonic witness is not enrolled.");
    if (current.recordDigest !== expectedRecordDigest) {
      fail("WITNESS_CAS_CONFLICT", "Witness record changed before compare-and-swap.", {
        expectedRecordDigest,
        observedRecordDigest: current.recordDigest,
      });
    }
    return current;
  }

  #append(recordValue: WitnessRecordV1): VerifiedWitnessRecord {
    const record = validateWitnessRecord(recordValue);
    const verified = {
      record,
      recordDigest: sha256Bytes(canonicalJson(record)),
    };
    this.#history.push(cloneWitnessRecord(verified));
    return cloneWitnessRecord(verified);
  }
}

const AUTHENTICATED_TRANSPORT_PROTOCOL_V1 =
  "veritas-authenticated-transport-v1";

type AuthenticatedTransportOperationV1 = "SELECT" | "WITHDRAW";
type AuthenticatedTransportTailV1 = {
  witnessVersion: number;
  state: "SELECTED" | "WITHDRAWN";
  tipDigest: string;
};

type AuthenticatedTransportRequestV1 = {
  schemaVersion: 1;
  protocol: typeof AUTHENTICATED_TRANSPORT_PROTOCOL_V1;
  serviceId: string;
  enrollmentId: string;
  generation: number;
  witnessId: string;
  bindingDigest: string;
  clientKeyId: string;
  operation: AuthenticatedTransportOperationV1;
  operationId: string;
  requestDigest: string;
  expectedVersion: number;
  expectedTipDigest: string;
  payload: JsonValue;
  signature: string;
};

type AuthenticatedTransportResultV1 = {
  schemaVersion: 1;
  protocol: typeof AUTHENTICATED_TRANSPORT_PROTOCOL_V1;
  serviceId: string;
  enrollmentId: string;
  generation: number;
  witnessId: string;
  clientKeyId: string;
  operation: AuthenticatedTransportOperationV1;
  operationId: string;
  requestDigest: string;
  status: "APPLIED" | "REPLAYED" | "CONFLICT" | "ABORTED";
  witnessVersion: number;
  tipDigest: string;
  signature: string;
};

type AuthenticatedTransportResultWithoutSignature = Omit<
  AuthenticatedTransportResultV1,
  "signature"
>;

function authenticatedTransportRequestBody(
  request: AuthenticatedTransportRequestV1,
): Omit<AuthenticatedTransportRequestV1, "signature"> {
  const { signature: _signature, ...body } = request;
  return body;
}

function authenticatedTransportResultBody(
  result: AuthenticatedTransportResultV1,
): AuthenticatedTransportResultWithoutSignature {
  const { signature: _signature, ...body } = result;
  return body;
}

function authenticatedTransportRequestDigest(
  request: Omit<AuthenticatedTransportRequestV1, "requestDigest" | "signature">,
): string {
  return sha256Bytes(canonicalJson(request));
}

class SameUidAuthenticatedTransportFixture {
  readonly protocol = AUTHENTICATED_TRANSPORT_PROTOCOL_V1;
  readonly implementationClass = "AUTHENTICATED_TRANSPORT_PROTOCOL_FIXTURE" as const;
  readonly serviceId: string;
  readonly enrollmentId: string;
  readonly generation = 1;
  readonly witnessId: string;
  readonly bindingDigest: string;
  readonly clientKeyId = "fixture-client-key-v1";
  readonly #clientPrivateKey;
  readonly #clientPublicKey;
  readonly #servicePrivateKey;
  readonly #servicePublicKey;
  #tail: AuthenticatedTransportTailV1;
  #operations = new Map<string, {
    requestDigest: string;
    result: AuthenticatedTransportResultV1;
  }>();

  constructor() {
    this.serviceId = "fixture-service-v1";
    this.enrollmentId = "fixture-enrollment-v1";
    this.witnessId = "fixture-witness-v1";
    this.bindingDigest = sha256Bytes(
      canonicalJson({
        protocol: this.protocol,
        serviceId: this.serviceId,
        enrollmentId: this.enrollmentId,
        generation: this.generation,
        witnessId: this.witnessId,
      }),
    );
    const clientKeys = generateKeyPairSync("ed25519");
    const serviceKeys = generateKeyPairSync("ed25519");
    this.#clientPrivateKey = clientKeys.privateKey;
    this.#clientPublicKey = clientKeys.publicKey;
    this.#servicePrivateKey = serviceKeys.privateKey;
    this.#servicePublicKey = serviceKeys.publicKey;
    this.#tail = {
      witnessVersion: 0,
      state: "SELECTED",
      tipDigest: sha256Bytes("fixture-genesis-tip-v1"),
    };
  }

  createRequest(
    operation: AuthenticatedTransportOperationV1,
    operationId: string,
    expectedTipDigest = this.#tail.tipDigest,
    expectedVersion = this.#tail.witnessVersion,
    payload: JsonValue = { operation },
  ): AuthenticatedTransportRequestV1 {
    const unsigned: Omit<AuthenticatedTransportRequestV1, "requestDigest" | "signature"> = {
      schemaVersion: 1 as const,
      protocol: this.protocol,
      serviceId: this.serviceId,
      enrollmentId: this.enrollmentId,
      generation: this.generation,
      witnessId: this.witnessId,
      bindingDigest: this.bindingDigest,
      clientKeyId: this.clientKeyId,
      operation,
      operationId,
      expectedVersion,
      expectedTipDigest,
      payload,
    };
    const requestDigest = authenticatedTransportRequestDigest(unsigned);
    const body = { ...unsigned, requestDigest };
    const signature = signEd25519(null, Buffer.from(canonicalJson(body)), this.#clientPrivateKey)
      .toString("base64url");
    return { ...body, signature };
  }

  tamperRequest(request: AuthenticatedTransportRequestV1): AuthenticatedTransportRequestV1 {
    return { ...request, payload: { tampered: true } };
  }

  substituteClientKey(request: AuthenticatedTransportRequestV1): AuthenticatedTransportRequestV1 {
    const substituteKeys = generateKeyPairSync("ed25519");
    const body = authenticatedTransportRequestBody(request);
    const signature = signEd25519(
      null,
      Buffer.from(canonicalJson(body)),
      substituteKeys.privateKey,
    ).toString("base64url");
    return { ...request, signature };
  }

  async dispatch(
    request: AuthenticatedTransportRequestV1,
  ): Promise<AuthenticatedTransportResultV1> {
    this.#verifyRequest(request);
    const stored = this.#operations.get(request.operationId);
    if (stored !== undefined) {
      if (stored.requestDigest !== request.requestDigest) {
        return this.#signedResult({
          ...this.#resultIdentity(request),
          status: "CONFLICT",
          witnessVersion: this.#tail.witnessVersion,
          tipDigest: this.#tail.tipDigest,
        });
      }
      return this.#signedResult({
        ...authenticatedTransportResultBody(stored.result),
        status: stored.result.status === "ABORTED" ? "ABORTED" : "REPLAYED",
      });
    }
    if (this.#tail.state === "WITHDRAWN") {
      const aborted = this.#signedResult({
        ...this.#resultIdentity(request),
        status: "ABORTED",
        witnessVersion: this.#tail.witnessVersion,
        tipDigest: this.#tail.tipDigest,
      });
      this.#operations.set(request.operationId, {
        requestDigest: request.requestDigest,
        result: aborted,
      });
      return aborted;
    }
    if (request.expectedVersion !== this.#tail.witnessVersion ||
        request.expectedTipDigest !== this.#tail.tipDigest) {
      return this.#signedResult({
        ...this.#resultIdentity(request),
        status: "CONFLICT",
        witnessVersion: this.#tail.witnessVersion,
        tipDigest: this.#tail.tipDigest,
      });
    }
    const nextState = request.operation === "WITHDRAW" ? "WITHDRAWN" : "SELECTED";
    const nextVersion = this.#tail.witnessVersion + 1;
    const nextTipDigest = sha256Bytes(canonicalJson({
      protocol: this.protocol,
      operationId: request.operationId,
      requestDigest: request.requestDigest,
      expectedVersion: this.#tail.witnessVersion,
      expectedTipDigest: this.#tail.tipDigest,
      payload: request.payload,
      nextVersion,
      nextState,
    }));
    this.#tail = {
      witnessVersion: nextVersion,
      state: nextState,
      tipDigest: nextTipDigest,
    };
    const result = this.#signedResult({
      ...this.#resultIdentity(request),
      status: "APPLIED",
      witnessVersion: nextVersion,
      tipDigest: nextTipDigest,
    });
    this.#operations.set(request.operationId, {
      requestDigest: request.requestDigest,
      result,
    });
    return result;
  }

  verifyResult(
    result: AuthenticatedTransportResultV1,
    expectedRequest: AuthenticatedTransportRequestV1,
  ): boolean {
    try {
      this.#verifyRequest(expectedRequest);
    } catch {
      return false;
    }
    const body = authenticatedTransportResultBody(result);
    const requestBound =
      result.serviceId === expectedRequest.serviceId &&
      result.enrollmentId === expectedRequest.enrollmentId &&
      result.generation === expectedRequest.generation &&
      result.witnessId === expectedRequest.witnessId &&
      result.clientKeyId === expectedRequest.clientKeyId &&
      result.operation === expectedRequest.operation &&
      result.operationId === expectedRequest.operationId &&
      result.requestDigest === expectedRequest.requestDigest;
    return requestBound && verifyEd25519(
      null,
      Buffer.from(canonicalJson(body)),
      this.#servicePublicKey,
      Buffer.from(result.signature, "base64url"),
    );
  }

  simulateLostResponse(
    request: AuthenticatedTransportRequestV1,
  ): Promise<AuthenticatedTransportResultV1> {
    return this.dispatch(request).then(() => this.dispatch(request));
  }

  #resultIdentity(request: AuthenticatedTransportRequestV1): AuthenticatedTransportResultWithoutSignature {
    return {
      schemaVersion: 1,
      protocol: this.protocol,
      serviceId: request.serviceId,
      enrollmentId: request.enrollmentId,
      generation: request.generation,
      witnessId: request.witnessId,
      clientKeyId: request.clientKeyId,
      operation: request.operation,
      operationId: request.operationId,
      requestDigest: request.requestDigest,
      status: "CONFLICT",
      witnessVersion: this.#tail.witnessVersion,
      tipDigest: this.#tail.tipDigest,
    };
  }

  #signedResult(body: AuthenticatedTransportResultWithoutSignature): AuthenticatedTransportResultV1 {
    const signature = signEd25519(
      null,
      Buffer.from(canonicalJson(body)),
      this.#servicePrivateKey,
    ).toString("base64url");
    return { ...body, signature };
  }

  #verifyRequest(request: AuthenticatedTransportRequestV1): void {
    const body = authenticatedTransportRequestBody(request);
    const { requestDigest: _requestDigest, ...unsignedBody } = body;
    if (
      request.schemaVersion !== 1 ||
      request.protocol !== this.protocol ||
      request.serviceId !== this.serviceId ||
      request.enrollmentId !== this.enrollmentId ||
      request.generation !== this.generation ||
      request.witnessId !== this.witnessId ||
      request.bindingDigest !== this.bindingDigest ||
      request.clientKeyId !== this.clientKeyId ||
      !(["SELECT", "WITHDRAW"] as const).includes(request.operation) ||
      typeof request.operationId !== "string" ||
      request.operationId.length === 0 ||
      !isSha256Digest(request.requestDigest) ||
      request.requestDigest !== authenticatedTransportRequestDigest(unsignedBody)
    ) {
      fail(
        "TRANSPORT_REQUEST_IDENTITY_INVALID",
        "Authenticated request identity or digest is not exact.",
      );
    }
    const validSignature = verifyEd25519(
      null,
      Buffer.from(canonicalJson(body)),
      this.#clientPublicKey,
      Buffer.from(request.signature, "base64url"),
    );
    if (!validSignature) {
      fail(
        "TRANSPORT_AUTHENTICATION_FAILED",
        "Authenticated request signature is invalid.",
      );
    }
  }
}

type ProtectedPrincipalOperationV1 = AuthenticatedTransportOperationV1;
type ProtectedPrincipalRequestV1 = {
  principal: "COORDINATOR" | "PROJECT";
  operation: ProtectedPrincipalOperationV1;
  operationId: string;
  enrollmentId: string;
  generation: number;
  expectedVersion: number;
  expectedTipDigest: string;
  payload: JsonValue;
  requestDigest: string;
};
type ProtectedPrincipalResultV1 = {
  operationId: string;
  requestDigest: string;
  status: "APPLIED" | "REPLAYED" | "CONFLICT" | "ABORTED";
  witnessVersion: number;
  tipDigest: string;
};

/**
 * Deterministic protected-principal seam. It models custody separation and
 * operation semantics without claiming OS UIDs, TLS, or durable external keys.
 */
class ProtectedPrincipalTransportFixture {
  readonly implementationClass = "PROTECTED_EXTERNAL_FIXTURE" as const;
  readonly witnessPrincipal = "_veritaswitness";
  readonly coordinatorPrincipal = "_veritascoordinator";
  readonly servicePin = sha256Bytes("fixture-service-spki-v1");
  readonly clientPin = sha256Bytes("fixture-client-spki-v1");
  #enrollment: { enrollmentId: string; generation: number; clientPin: string } | null = null;
  #tail: { state: "SELECTED" | "WITHDRAWN"; version: number; tip: string } = {
    state: "SELECTED",
    version: 0,
    tip: sha256Bytes("protected-genesis-v1"),
  };
  #operations = new Map<string, ProtectedPrincipalResultV1>();
  #recoveryResolutionDigest: string | null = null;

  enroll(principal: string, enrollmentId: string, generation: number, clientPin: string): void {
    if (principal !== "ADMIN") fail("PROTECTED_ENROLLMENT_DENIED", "Only the enrollment authority may enroll a client.");
    const next = { enrollmentId, generation, clientPin };
    if (this.#enrollment !== null && canonicalJson(this.#enrollment) !== canonicalJson(next)) {
      fail("PROTECTED_ENROLLMENT_CONFLICT", "Divergent enrollment cannot replace an existing mapping.");
    }
    this.#enrollment = next;
  }

  enrollmentSnapshot(): { enrollmentId: string; generation: number; clientPin: string } {
    if (this.#enrollment === null) fail("PROTECTED_ENROLLMENT_MISSING", "No protected enrollment exists.");
    return { ...this.#enrollment };
  }

  createRequest(
    principal: "COORDINATOR" | "PROJECT",
    operation: ProtectedPrincipalOperationV1,
    operationId: string,
    expectedVersion = this.#tail.version,
    expectedTipDigest = this.#tail.tip,
    payload: JsonValue = { operation },
  ): ProtectedPrincipalRequestV1 {
    if (principal !== "COORDINATOR") fail("PROTECTED_OPERATION_DENIED", "Project principal cannot mutate protected state.");
    if (this.#enrollment === null) fail("PROTECTED_ENROLLMENT_MISSING", "Protected mutation requires enrollment.");
    const unsigned = { principal, operation, operationId, enrollmentId: this.#enrollment.enrollmentId, generation: this.#enrollment.generation, expectedVersion, expectedTipDigest, payload };
    return { ...unsigned, requestDigest: sha256Bytes(canonicalJson(unsigned)) };
  }

  async dispatch(request: ProtectedPrincipalRequestV1): Promise<ProtectedPrincipalResultV1> {
    if (request.principal !== "COORDINATOR") fail("PROTECTED_OPERATION_DENIED", "Only the coordinator principal may dispatch.");
    const expected = sha256Bytes(canonicalJson({ principal: request.principal, operation: request.operation, operationId: request.operationId, enrollmentId: request.enrollmentId, generation: request.generation, expectedVersion: request.expectedVersion, expectedTipDigest: request.expectedTipDigest, payload: request.payload }));
    if (expected !== request.requestDigest) fail("PROTECTED_REQUEST_INVALID", "Protected request digest is not self-consistent.");
    const stored = this.#operations.get(request.operationId);
    if (stored !== undefined) return stored.requestDigest === request.requestDigest ? { ...stored, status: stored.status === "APPLIED" ? "REPLAYED" : stored.status } : { operationId: request.operationId, requestDigest: request.requestDigest, status: "CONFLICT", witnessVersion: this.#tail.version, tipDigest: this.#tail.tip };
    if (this.#tail.state === "WITHDRAWN") return this.#store({ operationId: request.operationId, requestDigest: request.requestDigest, status: "ABORTED", witnessVersion: this.#tail.version, tipDigest: this.#tail.tip });
    if (request.expectedVersion !== this.#tail.version || request.expectedTipDigest !== this.#tail.tip) return { operationId: request.operationId, requestDigest: request.requestDigest, status: "CONFLICT", witnessVersion: this.#tail.version, tipDigest: this.#tail.tip };
    const nextState = request.operation === "WITHDRAW" ? "WITHDRAWN" : "SELECTED";
    const nextVersion = this.#tail.version + 1;
    const nextTip = sha256Bytes(canonicalJson({ requestDigest: request.requestDigest, nextVersion, nextState, prior: this.#tail.tip }));
    this.#tail = { state: nextState, version: nextVersion, tip: nextTip };
    return this.#store({ operationId: request.operationId, requestDigest: request.requestDigest, status: "APPLIED", witnessVersion: nextVersion, tipDigest: nextTip });
  }

  restart(): ProtectedPrincipalTransportFixture {
    const reopened = new ProtectedPrincipalTransportFixture();
    reopened.#enrollment = this.#enrollment === null ? null : { ...this.#enrollment };
    reopened.#tail = { ...this.#tail };
    for (const [id, result] of this.#operations) reopened.#operations.set(id, { ...result });
    reopened.#recoveryResolutionDigest = this.#recoveryResolutionDigest;
    return reopened;
  }

  selectRecoveryResolution(resolutionDigest: string): string {
    if (this.#tail.state !== "WITHDRAWN") fail("RECOVERY_WITHDRAWAL_REQUIRED", "Recovery resolution requires terminal withdrawal first.");
    if (!isSha256Digest(resolutionDigest)) fail("RECOVERY_RESOLUTION_INVALID", "Recovery resolution must be an exact digest.");
    if (this.#recoveryResolutionDigest !== null && this.#recoveryResolutionDigest !== resolutionDigest) fail("RECOVERY_RESOLUTION_CONFLICT", "A different recovery resolution cannot replace the selected digest.");
    this.#recoveryResolutionDigest = resolutionDigest;
    return resolutionDigest;
  }

  recoveryResolutionDigest(): string {
    if (this.#recoveryResolutionDigest === null) fail("RECOVERY_RESOLUTION_MISSING", "No recovery resolution has been selected.");
    return this.#recoveryResolutionDigest;
  }

  #store(result: ProtectedPrincipalResultV1): ProtectedPrincipalResultV1 { this.#operations.set(result.operationId, result); return { ...result }; }
}

class FencedStagingFixture {
  #generation = 1;
  #owner: string | null = null;
  #baseDigest: string;
  constructor(base = "base-v1") { this.#baseDigest = sha256Bytes(base); }
  acquire(owner: string, generation: number): void {
    if (generation !== this.#generation) fail("FENCE_GENERATION_STALE", "Writer generation is stale.");
    if (this.#owner !== null && this.#owner !== owner) fail("FENCE_WRITER_BUSY", "A second writer cannot acquire the fence.");
    this.#owner = owner;
  }
  rotate(): number { this.#generation += 1; this.#owner = null; return this.#generation; }
  stage(owner: string, generation: number, baseDigest: string, declaredBytes: string, declaredDigest: string): string {
    if (this.#owner !== owner || generation !== this.#generation) fail("FENCE_WRITER_STALE", "Stale or non-owner writer cannot stage.");
    if (baseDigest !== this.#baseDigest) fail("STAGING_BASE_MISMATCH", "Staging base is not the exact accepted base.");
    if (sha256Bytes(declaredBytes) !== declaredDigest) fail("STAGING_DECLARED_BYTES_MISMATCH", "Declared bytes digest does not match bytes.");
    return sha256Bytes(canonicalJson({ generation, baseDigest, declaredDigest }));
  }
}

