function candidateStageEncodedLength(byteLength: number): number {
  return byteLength === 0 ? 0 : 4 * Math.ceil(byteLength / 3);
}

function decodeCanonicalCandidateStageBase64(
  value: unknown,
  declaredByteLength?: number,
): Buffer {
  if (typeof value !== "string") {
    fail("CANDIDATE_STAGE_FILE_INVALID", "Declared file bytes must use canonical base64.");
  }
  if (
    value.length > candidateStageEncodedLength(CANDIDATE_STAGING_LIMITS.maxFileBytes) ||
    (declaredByteLength !== undefined && value.length !== candidateStageEncodedLength(declaredByteLength))
  ) {
    fail("CANDIDATE_STAGE_LIMIT_EXCEEDED", "Declared base64 length exceeds or disagrees with its pre-decode bound.");
  }
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    fail("CANDIDATE_STAGE_FILE_INVALID", "Declared file bytes are not canonical base64 text.");
  }
  const bytes = Buffer.from(value, "base64");
  if (bytes.toString("base64") !== value) {
    fail("CANDIDATE_STAGE_FILE_INVALID", "Declared file bytes are not canonical base64.");
  }
  return bytes;
}

function candidateStageExecutableBits(mode: CandidateStageDeclaredFileV1["mode"]): number {
  return mode === "100755" ? 0o111 : 0;
}

function validateCandidateStageDeclaredFiles(
  value: unknown,
): CandidateStageDeclaredFileV1[] {
  if (!Array.isArray(value) || value.length === 0 || value.length > CANDIDATE_STAGING_LIMITS.maxFiles) {
    fail("CANDIDATE_STAGE_FILES_INVALID", "Declared staging input requires a bounded non-empty file array.");
  }
  const files: CandidateStageDeclaredFileV1[] = [];
  const exactPaths = new Set<string>();
  const collisionKeys = new Set<string>();
  let totalBytes = 0;
  let totalEncodedCharacters = 0;
  for (const item of value) {
    const record = requireExactObjectKeys(
      item,
      ["relativePath", "mode", "byteLength", "bytesBase64", "bytesSha256"],
      "CANDIDATE_STAGE_FILE_INVALID",
      "Declared staging file",
    );
    if (
      typeof record.relativePath !== "string" ||
      record.relativePath.includes("\\") ||
      record.relativePath.includes("\0")
    ) {
      fail("CANDIDATE_STAGE_PATH_INVALID", "Declared staging paths must use canonical forward-slash relative names.");
    }
    const relativePath = normalizeRelativePath(record.relativePath);
    if (relativePath === ".veritas" || relativePath.startsWith(".veritas/")) {
      fail("CANDIDATE_STAGE_PATH_INVALID", "Declared staging input cannot contain reserved Veritas state.", { path: relativePath });
    }
    if (record.mode !== "100644" && record.mode !== "100755") {
      fail("CANDIDATE_STAGE_FILE_INVALID", "Declared staging file mode must be exactly 100644 or 100755.", { path: relativePath });
    }
    if (!Number.isSafeInteger(record.byteLength) || (record.byteLength as number) < 0) {
      fail("CANDIDATE_STAGE_FILE_INVALID", "Declared staging byte length must be a non-negative safe integer.", { path: relativePath });
    }
    if ((record.byteLength as number) > CANDIDATE_STAGING_LIMITS.maxFileBytes) {
      fail("CANDIDATE_STAGE_LIMIT_EXCEEDED", "Declared staging byte length exceeds the frozen per-file limit.", { path: relativePath });
    }
    totalBytes += record.byteLength as number;
    if (totalBytes > CANDIDATE_STAGING_LIMITS.maxTotalBytes) {
      fail("CANDIDATE_STAGE_LIMIT_EXCEEDED", "Declared staging input exceeds the frozen total-byte limit.");
    }
    if (typeof record.bytesBase64 !== "string") {
      fail("CANDIDATE_STAGE_FILE_INVALID", "Declared file bytes must use canonical base64.", { path: relativePath });
    }
    totalEncodedCharacters += record.bytesBase64.length;
    if (totalEncodedCharacters > CANDIDATE_STAGING_LIMITS.maxEncodedCharacters) {
      fail("CANDIDATE_STAGE_LIMIT_EXCEEDED", "Declared staging input exceeds the aggregate pre-decode base64 limit.");
    }
    const bytes = decodeCanonicalCandidateStageBase64(
      record.bytesBase64,
      record.byteLength as number,
    );
    if (
      bytes.byteLength !== record.byteLength ||
      !isSha256Digest(record.bytesSha256) ||
      sha256Bytes(bytes) !== record.bytesSha256
    ) {
      fail("CANDIDATE_STAGE_DECLARED_BYTES_MISMATCH", "Declared staging bytes, length, or digest disagree.", { path: relativePath });
    }
    const pathBytes = Buffer.byteLength(relativePath, "utf8");
    const depth = relativePath.split("/").length;
    if (pathBytes > CANDIDATE_STAGING_LIMITS.maxPathBytes || depth > CANDIDATE_STAGING_LIMITS.maxDepth) {
      fail("CANDIDATE_STAGE_LIMIT_EXCEEDED", "Declared staging path exceeds the frozen limit.", { path: relativePath, pathBytes, depth });
    }
    if (exactPaths.has(relativePath)) {
      fail("CANDIDATE_STAGE_PATH_COLLISION", "Declared staging input repeats a path.", { path: relativePath });
    }
    const collisionKey = relativePath.normalize("NFC").toLocaleLowerCase("en-US");
    if (collisionKeys.has(collisionKey)) {
      fail("CANDIDATE_STAGE_PATH_COLLISION", "Declared staging paths collide under the portable path profile.", { path: relativePath });
    }
    exactPaths.add(relativePath);
    collisionKeys.add(collisionKey);
    files.push({
      relativePath,
      mode: record.mode,
      byteLength: record.byteLength,
      bytesBase64: record.bytesBase64,
      bytesSha256: record.bytesSha256,
    } as CandidateStageDeclaredFileV1);
  }
  const sorted = [...files].sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  if (canonicalJson(files) !== canonicalJson(sorted)) {
    fail("CANDIDATE_STAGE_FILES_INVALID", "Declared staging files must already be sorted by canonical relative path.");
  }
  for (const file of files) {
    const parts = file.relativePath.split("/");
    for (let depth = 1; depth < parts.length; depth += 1) {
      const prefix = parts.slice(0, depth).join("/");
      if (exactPaths.has(prefix)) {
        fail("CANDIDATE_STAGE_PATH_COLLISION", "A declared file path is also another file path prefix.", { path: file.relativePath, prefix });
      }
    }
  }
  return files;
}

function candidateStageTreeDigest(files: CandidateStageDeclaredFileV1[]): string {
  const hash = createHash("sha256");
  updateFrame(hash, 0, Buffer.from(TREE_PROFILE, "utf8"));
  for (const file of files) {
    const bytes = decodeCanonicalCandidateStageBase64(file.bytesBase64, file.byteLength);
    updateFrame(hash, 1, Buffer.from(file.relativePath, "utf8"));
    updateFrame(hash, 2, Buffer.from("regular-file", "utf8"));
    const mode = Buffer.alloc(4);
    mode.writeUInt32BE(candidateStageExecutableBits(file.mode));
    updateFrame(hash, 3, mode);
    updateFrame(hash, 4, bytes);
  }
  return hash.digest("hex");
}

function validateCandidateStageBaseBinding(value: unknown): CandidateStageBaseBindingV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "storeId",
      "coordinatorRevision",
      "coordinatorHeadRecordDigest",
      "coordinatorStateDigest",
      "coordinatorCommitRecordDigest",
      "acceptedReference",
      "acceptedReferenceRecordDigest",
    ],
    "CANDIDATE_STAGE_BASE_INVALID",
    "Candidate staging base binding",
  );
  const acceptedReference = validateAcceptedReference(
    record.acceptedReference,
    "CANDIDATE_STAGE_BASE_INVALID",
  );
  if (
    typeof record.storeId !== "string" ||
    record.storeId.length === 0 ||
    !Number.isSafeInteger(record.coordinatorRevision) ||
    (record.coordinatorRevision as number) < 0 ||
    !isSha256Digest(record.coordinatorHeadRecordDigest) ||
    !isSha256Digest(record.coordinatorStateDigest) ||
    !isSha256Digest(record.coordinatorCommitRecordDigest) ||
    !isSha256Digest(record.acceptedReferenceRecordDigest) ||
    record.acceptedReferenceRecordDigest !== sha256Bytes(canonicalJson(acceptedReference))
  ) {
    fail("CANDIDATE_STAGE_BASE_INVALID", "Candidate staging base fields or digests are malformed.");
  }
  return {
    storeId: record.storeId,
    coordinatorRevision: record.coordinatorRevision,
    coordinatorHeadRecordDigest: record.coordinatorHeadRecordDigest,
    coordinatorStateDigest: record.coordinatorStateDigest,
    coordinatorCommitRecordDigest: record.coordinatorCommitRecordDigest,
    acceptedReference,
    acceptedReferenceRecordDigest: record.acceptedReferenceRecordDigest,
  } as CandidateStageBaseBindingV1;
}

function candidateStageRequestBody(
  request: Omit<CandidateStageRequestV1, "requestDigest"> | CandidateStageRequestV1,
): Omit<CandidateStageRequestV1, "requestDigest"> {
  const { requestDigest: _requestDigest, ...body } = request as CandidateStageRequestV1;
  return body;
}

function validateCandidateStageRequest(value: unknown): CandidateStageRequestV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "profile", "operationId", "inputMode", "ownerId", "generation",
      "base", "files", "expectedCandidateDigest", "authorityMode", "authorizing",
      "mayPromote", "mayExecute", "requestDigest",
    ],
    "CANDIDATE_STAGE_REQUEST_INVALID",
    "Candidate staging request",
  );
  const base = validateCandidateStageBaseBinding(record.base);
  const files = validateCandidateStageDeclaredFiles(record.files);
  if (
    record.schemaVersion !== 1 ||
    record.profile !== CANDIDATE_STAGING_PROFILE ||
    !isCanonicalUuidV4(record.operationId) ||
    record.inputMode !== "DECLARED_FULL_TREE_BYTES" ||
    typeof record.ownerId !== "string" ||
    !/^[a-z][a-z0-9._-]{0,63}$/.test(record.ownerId) ||
    !Number.isSafeInteger(record.generation) ||
    record.generation !== base.coordinatorRevision ||
    !isSha256Digest(record.expectedCandidateDigest) ||
    record.expectedCandidateDigest !== candidateStageTreeDigest(files) ||
    record.authorityMode !== "SELF_ADMINISTERED" ||
    record.authorizing !== false ||
    record.mayPromote !== false ||
    record.mayExecute !== false ||
    !isSha256Digest(record.requestDigest)
  ) {
    fail("CANDIDATE_STAGE_REQUEST_INVALID", "Candidate staging request fields or zero-authority contract are invalid.");
  }
  const request = {
    schemaVersion: 1,
    profile: CANDIDATE_STAGING_PROFILE,
    operationId: record.operationId,
    inputMode: "DECLARED_FULL_TREE_BYTES",
    ownerId: record.ownerId,
    generation: record.generation,
    base,
    files,
    expectedCandidateDigest: record.expectedCandidateDigest,
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayPromote: false,
    mayExecute: false,
    requestDigest: record.requestDigest,
  } as CandidateStageRequestV1;
  if (request.requestDigest !== sha256Bytes(canonicalJson(candidateStageRequestBody(request)))) {
    fail("CANDIDATE_STAGE_REQUEST_INVALID", "Candidate staging request digest is not exact.");
  }
  return request;
}

function createCandidateStageRequest(
  operationId: string,
  ownerId: string,
  base: CandidateStageBaseBindingV1,
  files: CandidateStageDeclaredFileV1[],
): CandidateStageRequestV1 {
  const validatedBase = validateCandidateStageBaseBinding(base);
  const validatedFiles = validateCandidateStageDeclaredFiles(files);
  const body: Omit<CandidateStageRequestV1, "requestDigest"> = {
    schemaVersion: 1,
    profile: CANDIDATE_STAGING_PROFILE,
    operationId,
    inputMode: "DECLARED_FULL_TREE_BYTES",
    ownerId,
    generation: validatedBase.coordinatorRevision,
    base: validatedBase,
    files: validatedFiles,
    expectedCandidateDigest: candidateStageTreeDigest(validatedFiles),
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayPromote: false,
    mayExecute: false,
  };
  return validateCandidateStageRequest({
    ...body,
    requestDigest: sha256Bytes(canonicalJson(body)),
  });
}

type GitBaseObjectTypeV1 = "blob" | "tree" | "commit";

type GitBaseManifestRequestV1 = {
  schemaVersion: 1;
  profile: typeof GIT_BASE_MANIFEST_PROFILE;
  base: CandidateStageBaseBindingV1;
  refName: string;
  objectFormat: "sha1";
  expectedCommitObjectId: string;
  expectedRootTreeObjectId: string;
  authorityMode: "SELF_ADMINISTERED";
  authorizing: false;
  mayCreateDecision: false;
  mayStage: false;
  mayPromote: false;
  mayExecute: false;
  requestDigest: string;
};

type GitBaseObjectPortV1 = {
  readRef: (refName: string) => Promise<GitBaseRefObservationV1 | null>;
  readObject: (objectId: string) => Promise<Buffer | null>;
  listObjectIds: () => Promise<string[]>;
};

type GitBaseRefObservationV1 = {
  objectId: string;
  revisionToken: string;
};

type GitBaseManifestHooksV1 = {
  afterInitialRefRead?: (context: {
    refName: string;
    commitObjectId: string;
    revisionToken: string;
  }) => Promise<void> | void;
  afterGraphRead?: (context: {
    commitObjectId: string;
    rootTreeObjectId: string;
    snapshotObjectIds: string[];
  }) => Promise<void> | void;
};

type GitBaseManifestResultV1 = {
  schemaVersion: 1;
  recordType: "GIT_BASE_MANIFEST_VERIFICATION";
  status: "VERIFIED_INERT";
  profile: typeof GIT_BASE_MANIFEST_PROFILE;
  requestDigest: string;
  baseBindingDigest: string;
  refName: string;
  objectFormat: "sha1";
  commitObjectId: string;
  commitRawSha256: string;
  rootTreeObjectId: string;
  rootTreeRawSha256: string;
  refRevisionToken: string;
  acceptedTreeDigest: string;
  snapshotObjectClosureDigest: string;
  objects: GitBaseManifestObjectV1[];
  files: GitBaseManifestFileV1[];
  snapshotObjectCount: number;
  fileCount: number;
  totalFileBytes: number;
  gitSnapshotClosureValidated: true;
  acceptedTreeMatched: true;
  protectedRef: false;
  authorizing: false;
  mayCreateDecision: false;
  mayStage: false;
  mayPromote: false;
  mayExecute: false;
  limitations: typeof GIT_BASE_MANIFEST_LIMITATIONS;
  resultDigest: string;
};

type GitBaseManifestObjectV1 = {
  objectId: string;
  objectType: GitBaseObjectTypeV1;
  rawSha256: string;
  contentByteLength: number;
};

type GitBaseManifestFileV1 = {
  relativePath: string;
  mode: "100644" | "100755";
  blobObjectId: string;
  blobRawSha256: string;
  byteLength: number;
  contentSha256: string;
};

type ParsedGitBaseObjectV1 = {
  objectType: GitBaseObjectTypeV1;
  content: Buffer;
  rawSha256: string;
};

type ParsedGitTreeEntryV1 = {
  mode: "40000" | "100644" | "100755";
  name: string;
  objectId: string;
};

function validateGitBaseManifestObject(value: unknown): GitBaseManifestObjectV1 {
  const record = requireExactObjectKeys(
    value,
    ["objectId", "objectType", "rawSha256", "contentByteLength"],
    "GIT_BASE_RESULT_INVALID",
    "Git-base manifest object",
  );
  if (
    !isGitSha1ObjectId(record.objectId) ||
    (record.objectType !== "blob" && record.objectType !== "tree" && record.objectType !== "commit") ||
    !isSha256Digest(record.rawSha256) ||
    typeof record.contentByteLength !== "number" ||
    !Number.isSafeInteger(record.contentByteLength) ||
    record.contentByteLength < 0 ||
    record.contentByteLength > GIT_BASE_MANIFEST_LIMITS.maxObjectBytes
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest object fields are invalid.");
  }
  return {
    objectId: record.objectId,
    objectType: record.objectType,
    rawSha256: record.rawSha256,
    contentByteLength: record.contentByteLength,
  };
}

function validateGitBaseManifestFile(value: unknown): GitBaseManifestFileV1 {
  const record = requireExactObjectKeys(
    value,
    ["relativePath", "mode", "blobObjectId", "blobRawSha256", "byteLength", "contentSha256"],
    "GIT_BASE_RESULT_INVALID",
    "Git-base manifest file",
  );
  if (
    typeof record.relativePath !== "string" ||
    normalizeRelativePath(record.relativePath) !== record.relativePath ||
    Buffer.byteLength(record.relativePath, "utf8") > GIT_BASE_MANIFEST_LIMITS.maxPathBytes ||
    (record.mode !== "100644" && record.mode !== "100755") ||
    !isGitSha1ObjectId(record.blobObjectId) ||
    !isSha256Digest(record.blobRawSha256) ||
    typeof record.byteLength !== "number" ||
    !Number.isSafeInteger(record.byteLength) ||
    record.byteLength < 0 ||
    record.byteLength > GIT_BASE_MANIFEST_LIMITS.maxFileBytes ||
    !isSha256Digest(record.contentSha256)
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest file fields are invalid.");
  }
  for (const component of record.relativePath.split("/")) gitBasePortableNameKey(component);
  return {
    relativePath: record.relativePath,
    mode: record.mode,
    blobObjectId: record.blobObjectId,
    blobRawSha256: record.blobRawSha256,
    byteLength: record.byteLength,
    contentSha256: record.contentSha256,
  };
}

// This checks summary consistency only on output freshly produced after raw snapshot
// verification. It is not an ingest verifier and cannot reconstruct Git tree edges,
// blob content, or a ref observation from the result record alone.
function validateGitBaseManifestResultSummaryConsistency(
  value: unknown,
  request: GitBaseManifestRequestV1,
): GitBaseManifestResultV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "status", "profile", "requestDigest",
      "baseBindingDigest", "refName", "objectFormat", "commitObjectId",
      "commitRawSha256", "rootTreeObjectId", "rootTreeRawSha256",
      "refRevisionToken", "acceptedTreeDigest", "snapshotObjectClosureDigest",
      "objects", "files", "snapshotObjectCount", "fileCount", "totalFileBytes",
      "gitSnapshotClosureValidated", "acceptedTreeMatched", "protectedRef",
      "authorizing", "mayCreateDecision", "mayStage", "mayPromote", "mayExecute",
      "limitations", "resultDigest",
    ],
    "GIT_BASE_RESULT_INVALID",
    "Git-base manifest result",
  );
  const refName = validateGitBaseRefName(record.refName);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "GIT_BASE_MANIFEST_VERIFICATION" ||
    record.status !== "VERIFIED_INERT" ||
    record.profile !== GIT_BASE_MANIFEST_PROFILE ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.baseBindingDigest) ||
    record.objectFormat !== "sha1" ||
    !isGitSha1ObjectId(record.commitObjectId) ||
    !isSha256Digest(record.commitRawSha256) ||
    !isGitSha1ObjectId(record.rootTreeObjectId) ||
    !isSha256Digest(record.rootTreeRawSha256) ||
    !isSha256Digest(record.refRevisionToken) ||
    !isSha256Digest(record.acceptedTreeDigest) ||
    !isSha256Digest(record.snapshotObjectClosureDigest) ||
    typeof record.snapshotObjectCount !== "number" ||
    !Number.isSafeInteger(record.snapshotObjectCount) ||
    typeof record.fileCount !== "number" ||
    !Number.isSafeInteger(record.fileCount) ||
    typeof record.totalFileBytes !== "number" ||
    !Number.isSafeInteger(record.totalFileBytes) ||
    record.totalFileBytes < 0 ||
    record.totalFileBytes > GIT_BASE_MANIFEST_LIMITS.maxTotalFileBytes ||
    record.gitSnapshotClosureValidated !== true ||
    record.acceptedTreeMatched !== true ||
    record.protectedRef !== false ||
    record.authorizing !== false ||
    record.mayCreateDecision !== false ||
    record.mayStage !== false ||
    record.mayPromote !== false ||
    record.mayExecute !== false ||
    canonicalJson(record.limitations) !== canonicalJson(GIT_BASE_MANIFEST_LIMITATIONS) ||
    !isSha256Digest(record.resultDigest)
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result fields or zero-authority contract are invalid.");
  }
  if (
    !Array.isArray(record.objects) ||
    record.objects.length === 0 ||
    record.objects.length > GIT_BASE_MANIFEST_LIMITS.maxObjects ||
    !Array.isArray(record.files) ||
    record.files.length === 0 ||
    record.files.length > GIT_BASE_MANIFEST_LIMITS.maxFiles
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result arrays exceed their frozen bounds.");
  }
  const objects = record.objects.map(validateGitBaseManifestObject);
  const files = record.files.map(validateGitBaseManifestFile);
  const sortedObjects = [...objects].sort((left, right) => codePointCompare(left.objectId, right.objectId));
  const sortedFiles = [...files].sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  const portableFileKeys = files.map((file) =>
    file.relativePath.split("/").map(gitBasePortableNameKey).join("/"));
  if (
    canonicalJson(objects) !== canonicalJson(sortedObjects) ||
    canonicalJson(files) !== canonicalJson(sortedFiles) ||
    new Set(objects.map((object) => object.objectId)).size !== objects.length ||
    new Set(files.map((file) => file.relativePath)).size !== files.length ||
    new Set(portableFileKeys).size !== files.length
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result inventory is not sorted and unique.");
  }
  const objectsById = new Map(objects.map((object) => [object.objectId, object]));
  const commitObject = objectsById.get(record.commitObjectId);
  const rootTreeObject = objectsById.get(record.rootTreeObjectId);
  if (
    commitObject?.objectType !== "commit" ||
    commitObject.rawSha256 !== record.commitRawSha256 ||
    rootTreeObject?.objectType !== "tree" ||
    rootTreeObject.rawSha256 !== record.rootTreeRawSha256 ||
    objects.filter((object) => object.objectType === "commit").length !== 1
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result commit or root-tree binding is invalid.");
  }
  let observedTotalFileBytes = 0;
  const referencedBlobObjectIds = new Set<string>();
  for (const file of files) {
    const blobObject = objectsById.get(file.blobObjectId);
    if (
      blobObject?.objectType !== "blob" ||
      blobObject.rawSha256 !== file.blobRawSha256 ||
      blobObject.contentByteLength !== file.byteLength
    ) {
      fail("GIT_BASE_RESULT_INVALID", "Git-base manifest file does not bind one exact blob object.", {
        path: file.relativePath,
      });
    }
    referencedBlobObjectIds.add(file.blobObjectId);
    observedTotalFileBytes += file.byteLength;
  }
  if (
    objects.some(
      (object) => object.objectType === "blob" && !referencedBlobObjectIds.has(object.objectId),
    )
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result contains an unreferenced blob object.");
  }
  const expectedBaseBindingDigest = candidateStageBaseBindingDigest(request.base);
  if (
    record.requestDigest !== request.requestDigest ||
    record.baseBindingDigest !== expectedBaseBindingDigest ||
    refName !== request.refName ||
    record.commitObjectId !== request.expectedCommitObjectId ||
    record.rootTreeObjectId !== request.expectedRootTreeObjectId ||
    record.acceptedTreeDigest !== request.base.acceptedReference.objectDigest ||
    record.snapshotObjectCount !== objects.length ||
    record.fileCount !== files.length ||
    record.totalFileBytes !== observedTotalFileBytes ||
    record.snapshotObjectClosureDigest !== sha256Bytes(canonicalJson(objects))
  ) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result does not cross-bind its request and inventories.");
  }
  const body: Omit<GitBaseManifestResultV1, "resultDigest"> = {
    schemaVersion: 1,
    recordType: "GIT_BASE_MANIFEST_VERIFICATION",
    status: "VERIFIED_INERT",
    profile: GIT_BASE_MANIFEST_PROFILE,
    requestDigest: record.requestDigest,
    baseBindingDigest: record.baseBindingDigest,
    refName,
    objectFormat: "sha1",
    commitObjectId: record.commitObjectId,
    commitRawSha256: record.commitRawSha256,
    rootTreeObjectId: record.rootTreeObjectId,
    rootTreeRawSha256: record.rootTreeRawSha256,
    refRevisionToken: record.refRevisionToken,
    acceptedTreeDigest: record.acceptedTreeDigest,
    snapshotObjectClosureDigest: record.snapshotObjectClosureDigest,
    objects,
    files,
    snapshotObjectCount: record.snapshotObjectCount,
    fileCount: record.fileCount,
    totalFileBytes: record.totalFileBytes,
    gitSnapshotClosureValidated: true,
    acceptedTreeMatched: true,
    protectedRef: false,
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayExecute: false,
    limitations: GIT_BASE_MANIFEST_LIMITATIONS,
  };
  if (record.resultDigest !== sha256Bytes(canonicalJson(body))) {
    fail("GIT_BASE_RESULT_INVALID", "Git-base manifest result digest is not exact.");
  }
  return { ...body, resultDigest: record.resultDigest };
}

function isGitSha1ObjectId(value: unknown): value is string {
  return typeof value === "string" && /^[0-9a-f]{40}$/.test(value);
}

function validateGitBaseRefName(value: unknown): string {
  const hasForbiddenCharacter = typeof value === "string" && [...value].some((character) => {
    const codePoint = character.codePointAt(0);
    return (
      codePoint === undefined ||
      codePoint <= 0x20 ||
      codePoint === 0x7f ||
      "~^:?*[".includes(character)
    );
  });
  if (
    typeof value !== "string" ||
    Buffer.byteLength(value, "utf8") > GIT_BASE_MANIFEST_LIMITS.maxRefBytes ||
    !GIT_BASE_REF_ASCII_PROFILE.test(value) ||
    !value.startsWith("refs/heads/") ||
    value.endsWith("/") ||
    value.includes("\\") ||
    value.includes("\0") ||
    value.includes("..") ||
    value.includes("//") ||
    value.includes("@{") ||
    hasForbiddenCharacter
  ) {
    fail("GIT_BASE_REF_INVALID", "Git-base fixture requires one canonical direct branch ref name.");
  }
  const components = value.split("/");
  if (
    components.some((component) =>
      component.length === 0 ||
      component.startsWith(".") ||
      component.endsWith(".") ||
      component.endsWith(".lock"))
  ) {
    fail("GIT_BASE_REF_INVALID", "Git-base fixture ref components are not canonical.");
  }
  return value;
}

function gitBaseManifestRequestBody(
  request: Omit<GitBaseManifestRequestV1, "requestDigest"> | GitBaseManifestRequestV1,
): Omit<GitBaseManifestRequestV1, "requestDigest"> {
  const { requestDigest: _requestDigest, ...body } = request as GitBaseManifestRequestV1;
  return body;
}

function validateGitBaseManifestRequest(value: unknown): GitBaseManifestRequestV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "profile", "base", "refName", "objectFormat",
      "expectedCommitObjectId", "expectedRootTreeObjectId", "authorityMode",
      "authorizing", "mayCreateDecision", "mayStage", "mayPromote", "mayExecute",
      "requestDigest",
    ],
    "GIT_BASE_MANIFEST_INVALID",
    "Git-base manifest request",
  );
  if (record.objectFormat !== "sha1") {
    fail("GIT_BASE_OBJECT_FORMAT_UNSUPPORTED", "Only the exact Git SHA-1 object format is admitted by this fixture.");
  }
  const base = validateCandidateStageBaseBinding(record.base);
  const refName = validateGitBaseRefName(record.refName);
  if (
    record.schemaVersion !== 1 ||
    record.profile !== GIT_BASE_MANIFEST_PROFILE ||
    !isGitSha1ObjectId(record.expectedCommitObjectId) ||
    !isGitSha1ObjectId(record.expectedRootTreeObjectId) ||
    record.authorityMode !== "SELF_ADMINISTERED" ||
    record.authorizing !== false ||
    record.mayCreateDecision !== false ||
    record.mayStage !== false ||
    record.mayPromote !== false ||
    record.mayExecute !== false ||
    !isSha256Digest(record.requestDigest)
  ) {
    fail("GIT_BASE_MANIFEST_INVALID", "Git-base manifest fields or zero-authority contract are invalid.");
  }
  const request: GitBaseManifestRequestV1 = {
    schemaVersion: 1,
    profile: GIT_BASE_MANIFEST_PROFILE,
    base,
    refName,
    objectFormat: "sha1",
    expectedCommitObjectId: record.expectedCommitObjectId,
    expectedRootTreeObjectId: record.expectedRootTreeObjectId,
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayExecute: false,
    requestDigest: record.requestDigest,
  };
  if (request.requestDigest !== sha256Bytes(canonicalJson(gitBaseManifestRequestBody(request)))) {
    fail("GIT_BASE_MANIFEST_INVALID", "Git-base manifest request digest is not exact.");
  }
  return request;
}

function createGitBaseManifestRequest(
  base: CandidateStageBaseBindingV1,
  refName: string,
  expectedCommitObjectId: string,
  expectedRootTreeObjectId: string,
): GitBaseManifestRequestV1 {
  const body: Omit<GitBaseManifestRequestV1, "requestDigest"> = {
    schemaVersion: 1,
    profile: GIT_BASE_MANIFEST_PROFILE,
    base: validateCandidateStageBaseBinding(base),
    refName: validateGitBaseRefName(refName),
    objectFormat: "sha1",
    expectedCommitObjectId,
    expectedRootTreeObjectId,
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayExecute: false,
  };
  return validateGitBaseManifestRequest({
    ...body,
    requestDigest: sha256Bytes(canonicalJson(body)),
  });
}

function parseExactGitBaseObject(
  raw: Buffer,
  expectedObjectId: string,
): ParsedGitBaseObjectV1 {
  if (raw.byteLength > GIT_BASE_MANIFEST_LIMITS.maxObjectBytes + 64) {
    fail("GIT_BASE_LIMIT_EXCEEDED", "Git object exceeds the frozen raw-object limit.", {
      objectId: expectedObjectId,
    });
  }
  const nul = raw.indexOf(0);
  if (nul < 1 || nul > 48) {
    fail("GIT_BASE_OBJECT_CORRUPT", "Git object header is missing or exceeds the frozen bound.", {
      objectId: expectedObjectId,
    });
  }
  const headerBytes = raw.subarray(0, nul);
  const header = headerBytes.toString("ascii");
  if (!Buffer.from(header, "ascii").equals(headerBytes)) {
    fail("GIT_BASE_OBJECT_CORRUPT", "Git object header is not canonical ASCII.", {
      objectId: expectedObjectId,
    });
  }
  const match = /^([a-z]+) (0|[1-9][0-9]*)$/.exec(header);
  if (match === null) {
    fail("GIT_BASE_OBJECT_CORRUPT", "Git object header type or length is malformed.", {
      objectId: expectedObjectId,
    });
  }
  const objectType = match[1];
  if (objectType !== "blob" && objectType !== "tree" && objectType !== "commit") {
    fail("GIT_BASE_OBJECT_TYPE_UNSUPPORTED", "Git-base fixture rejects unsupported object types.", {
      objectId: expectedObjectId,
      objectType,
    });
  }
  const declaredLength = Number(match[2]);
  const content = raw.subarray(nul + 1);
  if (
    !Number.isSafeInteger(declaredLength) ||
    declaredLength !== content.byteLength ||
    content.byteLength > GIT_BASE_MANIFEST_LIMITS.maxObjectBytes
  ) {
    fail("GIT_BASE_OBJECT_CORRUPT", "Git object declared length and exact content length disagree.", {
      objectId: expectedObjectId,
    });
  }
  const observedObjectId = createHash("sha1").update(raw).digest("hex");
  if (observedObjectId !== expectedObjectId) {
    fail("GIT_BASE_OBJECT_ID_MISMATCH", "Git object bytes do not reproduce the requested object ID.", {
      expectedObjectId,
      observedObjectId,
    });
  }
  return {
    objectType,
    content: Buffer.from(content),
    rawSha256: sha256Bytes(raw),
  };
}

function parseGitBaseCommitRootTree(content: Buffer): string {
  if (content.byteLength > GIT_BASE_MANIFEST_LIMITS.maxCommitBytes) {
    fail("GIT_BASE_LIMIT_EXCEEDED", "Git commit exceeds the frozen commit-content limit.");
  }
  const separator = content.indexOf("\n\n");
  if (separator < 0) {
    fail("GIT_BASE_COMMIT_INVALID", "Git commit lacks a canonical header and message separator.");
  }
  const headerBytes = content.subarray(0, separator);
  if (headerBytes.includes(0) || headerBytes.includes(13)) {
    fail("GIT_BASE_COMMIT_INVALID", "Git commit headers contain a prohibited NUL or carriage return.");
  }
  const header = headerBytes.toString("utf8");
  if (!Buffer.from(header, "utf8").equals(headerBytes)) {
    fail("GIT_BASE_COMMIT_INVALID", "Git commit headers must use canonical UTF-8 in this fixture.");
  }
  const lines = header.split("\n");
  const treeLines = lines.filter((line) => line.startsWith("tree "));
  if (
    treeLines.length !== 1 ||
    lines[0] !== treeLines[0] ||
    !/^tree [0-9a-f]{40}$/.test(treeLines[0])
  ) {
    fail("GIT_BASE_COMMIT_INVALID", "Git commit must bind exactly one SHA-1 root tree as its first header.");
  }
  const cursor = 1;
  if ((lines[cursor] ?? "").startsWith("parent ")) {
    if (!/^parent [0-9a-f]{40}$/.test(lines[cursor] ?? "")) {
      fail("GIT_BASE_COMMIT_INVALID", "Git commit parent header is malformed.");
    }
    fail(
      "GIT_BASE_PARENT_UNSUPPORTED",
      "Git-base snapshot fixture admits only an unsigned root commit and never claims history closure.",
    );
  }
  const actorPattern = /^(author|committer) [^<>\n]+ <[^<>\n]+> (0|[1-9][0-9]*) [+-][0-9]{4}$/;
  if (
    cursor + 2 !== lines.length ||
    !actorPattern.test(lines[cursor] ?? "") ||
    !(lines[cursor] ?? "").startsWith("author ") ||
    !actorPattern.test(lines[cursor + 1] ?? "") ||
    !(lines[cursor + 1] ?? "").startsWith("committer ")
  ) {
    fail("GIT_BASE_COMMIT_INVALID", "Git commit must use the frozen root-tree/author/committer header grammar.");
  }
  return treeLines[0].slice("tree ".length);
}

function gitTreeSortKey(nameBytes: Buffer, isTree: boolean): Buffer {
  return isTree ? Buffer.concat([nameBytes, Buffer.from("/", "ascii")]) : Buffer.from(nameBytes);
}

function gitBasePortableNameKey(name: string): string {
  // Bound work before Unicode normalization or character-array allocation.
  if (name.length > 255 || Buffer.byteLength(name, "utf8") > 255) {
    fail("GIT_BASE_PATH_INVALID", "Git tree entry name violates the exact portable component profile.", {
      name,
    });
  }
  const normalized = name.normalize("NFC");
  const hasForbiddenCharacter = [...name].some((character) => {
    const codePoint = character.codePointAt(0);
    return codePoint === undefined || codePoint <= 0x1f || '<>:"|?*'.includes(character);
  });
  if (
    normalized !== name ||
    hasForbiddenCharacter ||
    name.endsWith(".") ||
    name.endsWith(" ")
  ) {
    fail("GIT_BASE_PATH_INVALID", "Git tree entry name violates the exact portable component profile.", {
      name,
    });
  }
  const key = normalized.toLocaleLowerCase("en-US");
  const stem = key.split(".")[0];
  if (
    key === ".git" ||
    key === ".veritas" ||
    /^(con|prn|aux|nul|com[1-9]|lpt[1-9])$/.test(stem)
  ) {
    fail("GIT_BASE_PATH_COLLISION", "Git tree entry collides with reserved Veritas, Git, or Windows namespace.", {
      name,
    });
  }
  return key;
}

function parseExactGitBaseTree(content: Buffer): ParsedGitTreeEntryV1[] {
  const entries: ParsedGitTreeEntryV1[] = [];
  const exactNames = new Set<string>();
  const portableNames = new Set<string>();
  let previousSortKey: Buffer | null = null;
  let offset = 0;
  while (offset < content.byteLength) {
    const space = content.indexOf(0x20, offset);
    const nul = space < 0 ? -1 : content.indexOf(0, space + 1);
    if (space <= offset || nul <= space + 1 || nul + 21 > content.byteLength) {
      fail("GIT_BASE_TREE_INVALID", "Git tree entry framing is truncated or malformed.");
    }
    const modeBytes = content.subarray(offset, space);
    const mode = modeBytes.toString("ascii");
    if (!Buffer.from(mode, "ascii").equals(modeBytes) || !/^[0-7]{5,6}$/.test(mode)) {
      fail("GIT_BASE_TREE_INVALID", "Git tree mode is not canonical octal text.");
    }
    const nameBytes = content.subarray(space + 1, nul);
    const name = nameBytes.toString("utf8");
    if (
      !Buffer.from(name, "utf8").equals(nameBytes) ||
      name.length === 0 ||
      name === "." ||
      name === ".." ||
      name.includes("/") ||
      name.includes("\\") ||
      name.includes("\0")
    ) {
      fail("GIT_BASE_PATH_INVALID", "Git tree entry name violates the bounded UTF-8 portable path profile.");
    }
    const portableName = gitBasePortableNameKey(name);
    if (
      exactNames.has(name) ||
      portableNames.has(portableName)
    ) {
      fail("GIT_BASE_PATH_COLLISION", "Git tree contains a reserved or colliding portable entry name.", {
        name,
      });
    }
    if (mode === "120000") {
      fail("GIT_BASE_SYMLINK_UNSUPPORTED", "Git-base fixture rejects symbolic-link entries.", { name });
    }
    if (mode === "160000") {
      fail("GIT_BASE_SUBMODULE_UNSUPPORTED", "Git-base fixture rejects submodule entries.", { name });
    }
    if (mode !== "40000" && mode !== "100644" && mode !== "100755") {
      fail("GIT_BASE_MODE_UNSUPPORTED", "Git-base fixture rejects unsupported tree entry modes.", {
        name,
        mode,
      });
    }
    const objectId = content.subarray(nul + 1, nul + 21).toString("hex");
    const sortKey = gitTreeSortKey(nameBytes, mode === "40000");
    if (previousSortKey !== null && Buffer.compare(previousSortKey, sortKey) >= 0) {
      fail("GIT_BASE_TREE_ORDER_INVALID", "Git tree entries are not in exact canonical Git order.", {
        name,
      });
    }
    previousSortKey = sortKey;
    exactNames.add(name);
    portableNames.add(portableName);
    entries.push({ mode, name, objectId });
    offset = nul + 21;
  }
  if (entries.length === 0) {
    fail("GIT_BASE_TREE_INVALID", "Git-base fixture requires a non-empty root tree.");
  }
  return entries;
}

async function readGitBaseRef(
  port: GitBaseObjectPortV1,
  refName: string,
  phase: string,
): Promise<GitBaseRefObservationV1> {
  let observed: GitBaseRefObservationV1 | null;
  try {
    observed = await port.readRef(refName);
  } catch {
    fail("GIT_BASE_REF_UNAVAILABLE", `Git ref could not be read during ${phase}.`);
  }
  if (observed === null) {
    fail("GIT_BASE_REF_UNAVAILABLE", `Git ref is missing or malformed during ${phase}.`);
  }
  const record = requireExactObjectKeys(
    observed,
    ["objectId", "revisionToken"],
    "GIT_BASE_REF_UNAVAILABLE",
    `Git ref observation during ${phase}`,
  );
  if (!isGitSha1ObjectId(record.objectId) || !isSha256Digest(record.revisionToken)) {
    fail("GIT_BASE_REF_UNAVAILABLE", `Git ref identity or monotonic token is malformed during ${phase}.`);
  }
  return { objectId: record.objectId, revisionToken: record.revisionToken };
}

async function listGitBaseObjectIds(port: GitBaseObjectPortV1, phase: string): Promise<string[]> {
  let objectIds: string[];
  try {
    objectIds = await port.listObjectIds();
  } catch {
    fail("GIT_BASE_OBJECT_UNAVAILABLE", `Git object bundle could not be listed during ${phase}.`);
  }
  if (Array.isArray(objectIds) && objectIds.length > GIT_BASE_MANIFEST_LIMITS.maxObjects) {
    fail("GIT_BASE_LIMIT_EXCEEDED", `Git object bundle exceeds the frozen count during ${phase}.`);
  }
  if (
    !Array.isArray(objectIds) ||
    objectIds.length === 0 ||
    objectIds.some((objectId) => !isGitSha1ObjectId(objectId)) ||
    new Set(objectIds).size !== objectIds.length ||
    canonicalJson(objectIds) !== canonicalJson([...objectIds].sort(codePointCompare))
  ) {
    fail("GIT_BASE_CLOSURE_INVALID", `Git object bundle identity list is malformed during ${phase}.`);
  }
  return [...objectIds];
}

async function readGitBaseRawObject(
  port: GitBaseObjectPortV1,
  objectId: string,
): Promise<Buffer> {
  let raw: Buffer | null;
  try {
    raw = await port.readObject(objectId);
  } catch {
    fail("GIT_BASE_OBJECT_UNAVAILABLE", "Git object port failed while reading a required object.", {
      objectId,
    });
  }
  if (!Buffer.isBuffer(raw)) {
    fail("GIT_BASE_OBJECT_MISSING", "A Git object referenced by the exact base graph is missing.", {
      objectId,
    });
  }
  return Buffer.from(raw);
}

function assertGitBaseManifestFixtureLane(active = boundedTestLaneActive()): void {
  if (!active) {
    fail("GIT_BASE_FIXTURE_ONLY", "Git-base manifest verification is non-callable outside the bounded test lane.");
  }
}

async function verifyExactGitBaseManifest(
  storePath: string,
  value: unknown,
  port: GitBaseObjectPortV1,
  hooks: GitBaseManifestHooksV1 = {},
): Promise<GitBaseManifestResultV1> {
  assertGitBaseManifestFixtureLane();
  const request = validateGitBaseManifestRequest(value);
  assertCandidateStageBaseMatches(request.base, await observeCandidateStageBaseUnlocked(storePath));
  const initialRef = await readGitBaseRef(port, request.refName, "initial observation");
  if (initialRef.objectId !== request.expectedCommitObjectId) {
    fail("GIT_BASE_REF_MISMATCH", "Git ref does not select the exact requested commit object.", {
      expected: request.expectedCommitObjectId,
      observed: initialRef.objectId,
    });
  }
  const initialObjectIds = await listGitBaseObjectIds(port, "initial observation");
  await hooks.afterInitialRefRead?.({
    refName: request.refName,
    commitObjectId: initialRef.objectId,
    revisionToken: initialRef.revisionToken,
  });

  const objectCache = new Map<string, ParsedGitBaseObjectV1>();
  let totalObjectBytes = 0;
  async function loadObject(
    objectId: string,
    expectedType: GitBaseObjectTypeV1,
  ): Promise<ParsedGitBaseObjectV1> {
    const cached = objectCache.get(objectId);
    if (cached !== undefined) {
      if (cached.objectType !== expectedType) {
        fail("GIT_BASE_OBJECT_TYPE_MISMATCH", "One Git object ID was reused under an incompatible graph type.", {
          objectId,
          expectedType,
          observedType: cached.objectType,
        });
      }
      return cached;
    }
    if (objectCache.size >= GIT_BASE_MANIFEST_LIMITS.maxObjects) {
      fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base graph exceeds the frozen reachable-object count.");
    }
    const raw = await readGitBaseRawObject(port, objectId);
    totalObjectBytes += raw.byteLength;
    if (totalObjectBytes > GIT_BASE_MANIFEST_LIMITS.maxTotalObjectBytes) {
      fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base graph exceeds the frozen aggregate object-byte limit.");
    }
    const parsed = parseExactGitBaseObject(raw, objectId);
    if (parsed.objectType !== expectedType) {
      fail("GIT_BASE_OBJECT_TYPE_MISMATCH", "Git object graph type differs from the required edge type.", {
        objectId,
        expectedType,
        observedType: parsed.objectType,
      });
    }
    objectCache.set(objectId, parsed);
    return parsed;
  }

  const commit = await loadObject(request.expectedCommitObjectId, "commit");
  const rootTreeObjectId = parseGitBaseCommitRootTree(commit.content);
  if (rootTreeObjectId !== request.expectedRootTreeObjectId) {
    fail("GIT_BASE_ROOT_TREE_MISMATCH", "Git commit selects a different root tree than the exact manifest.", {
      expected: request.expectedRootTreeObjectId,
      observed: rootTreeObjectId,
    });
  }

  const declaredFiles: CandidateStageDeclaredFileV1[] = [];
  const manifestFiles: GitBaseManifestFileV1[] = [];
  const activeTrees = new Set<string>();
  const exactPaths = new Set<string>();
  const portablePaths = new Set<string>();
  let totalFileBytes = 0;
  async function walkTree(treeObjectId: string, prefix: string, depth: number): Promise<void> {
    if (depth > GIT_BASE_MANIFEST_LIMITS.maxDepth) {
      fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base tree exceeds the frozen path-depth limit.");
    }
    if (activeTrees.has(treeObjectId)) {
      fail("GIT_BASE_TREE_CYCLE", "Git-base tree graph contains a recursive tree edge.");
    }
    activeTrees.add(treeObjectId);
    try {
      const tree = await loadObject(treeObjectId, "tree");
      for (const entry of parseExactGitBaseTree(tree.content)) {
        const relativePath = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
        if (
          normalizeRelativePath(relativePath) !== relativePath ||
          Buffer.byteLength(relativePath, "utf8") > GIT_BASE_MANIFEST_LIMITS.maxPathBytes
        ) {
          fail("GIT_BASE_PATH_INVALID", "Git-base path is not canonical or exceeds the frozen byte limit.", {
            path: relativePath,
          });
        }
        const portablePath = relativePath.normalize("NFC").toLocaleLowerCase("en-US");
        if (exactPaths.has(relativePath) || portablePaths.has(portablePath)) {
          fail("GIT_BASE_PATH_COLLISION", "Git-base graph contains a repeated or portable-colliding path.", {
            path: relativePath,
          });
        }
        exactPaths.add(relativePath);
        portablePaths.add(portablePath);
        if (entry.mode === "40000") {
          await walkTree(entry.objectId, relativePath, depth + 1);
          continue;
        }
        if (declaredFiles.length >= GIT_BASE_MANIFEST_LIMITS.maxFiles) {
          fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base graph exceeds the frozen file-count limit.");
        }
        const blob = await loadObject(entry.objectId, "blob");
        if (blob.content.byteLength > GIT_BASE_MANIFEST_LIMITS.maxFileBytes) {
          fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base blob exceeds the frozen per-file limit.", {
            path: relativePath,
          });
        }
        totalFileBytes += blob.content.byteLength;
        if (totalFileBytes > GIT_BASE_MANIFEST_LIMITS.maxTotalFileBytes) {
          fail("GIT_BASE_LIMIT_EXCEEDED", "Git-base graph exceeds the frozen aggregate file-byte limit.");
        }
        declaredFiles.push(candidateStageDeclaredFile(
          relativePath,
          blob.content,
          entry.mode,
        ));
        manifestFiles.push({
          relativePath,
          mode: entry.mode,
          blobObjectId: entry.objectId,
          blobRawSha256: blob.rawSha256,
          byteLength: blob.content.byteLength,
          contentSha256: sha256Bytes(blob.content),
        });
      }
    } finally {
      activeTrees.delete(treeObjectId);
    }
  }
  await walkTree(rootTreeObjectId, "", 1);
  declaredFiles.sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  const validatedFiles = validateCandidateStageDeclaredFiles(declaredFiles);
  const acceptedTreeDigest = candidateStageTreeDigest(validatedFiles);
  if (acceptedTreeDigest !== request.base.acceptedReference.objectDigest) {
    fail("GIT_BASE_ACCEPTED_TREE_MISMATCH", "Git commit tree bytes do not reproduce the exact active accepted artifact.", {
      expected: request.base.acceptedReference.objectDigest,
      observed: acceptedTreeDigest,
    });
  }

  const snapshotObjectIds = [...objectCache.keys()].sort(codePointCompare);
  if (canonicalJson(snapshotObjectIds) !== canonicalJson(initialObjectIds)) {
    fail("GIT_BASE_CLOSURE_INVALID", "Declared Git object bundle is not exactly the reachable snapshot closure.", {
      declaredObjectCount: initialObjectIds.length,
      snapshotObjectCount: snapshotObjectIds.length,
    });
  }
  await hooks.afterGraphRead?.({
    commitObjectId: request.expectedCommitObjectId,
    rootTreeObjectId,
    snapshotObjectIds,
  });
  for (const objectId of snapshotObjectIds) {
    const before = objectCache.get(objectId);
    assert(before !== undefined);
    const currentRaw = await readGitBaseRawObject(port, objectId);
    if (sha256Bytes(currentRaw) !== before.rawSha256) {
      fail("GIT_BASE_OBJECT_CHANGED", "A reachable Git object changed before final verification.", {
        objectId,
      });
    }
    const current = parseExactGitBaseObject(currentRaw, objectId);
    if (current.objectType !== before.objectType) {
      fail("GIT_BASE_OBJECT_CHANGED", "A reachable Git object changed type before final verification.", {
        objectId,
      });
    }
  }
  const finalObjectIds = await listGitBaseObjectIds(port, "final observation");
  if (canonicalJson(finalObjectIds) !== canonicalJson(initialObjectIds)) {
    fail("GIT_BASE_CLOSURE_CHANGED", "Declared Git object bundle changed before final verification.");
  }
  assertCandidateStageBaseMatches(request.base, await observeCandidateStageBaseUnlocked(storePath));
  const finalRef = await readGitBaseRef(port, request.refName, "final observation");
  if (
    canonicalJson(finalRef) !== canonicalJson(initialRef) ||
    finalRef.objectId !== request.expectedCommitObjectId
  ) {
    fail("GIT_BASE_REF_CHANGED", "Git ref changed before exact-base verification completed.", {
      initial: initialRef,
      final: finalRef,
    });
  }

  const manifestObjects: GitBaseManifestObjectV1[] = snapshotObjectIds.map((objectId) => {
    const object = objectCache.get(objectId);
    assert(object !== undefined);
    return {
      objectId,
      objectType: object.objectType,
      rawSha256: object.rawSha256,
      contentByteLength: object.content.byteLength,
    };
  });
  manifestFiles.sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  const snapshotObjectClosureDigest = sha256Bytes(canonicalJson(manifestObjects));

  const body: Omit<GitBaseManifestResultV1, "resultDigest"> = {
    schemaVersion: 1,
    recordType: "GIT_BASE_MANIFEST_VERIFICATION",
    status: "VERIFIED_INERT",
    profile: GIT_BASE_MANIFEST_PROFILE,
    requestDigest: request.requestDigest,
    baseBindingDigest: candidateStageBaseBindingDigest(request.base),
    refName: request.refName,
    objectFormat: "sha1",
    commitObjectId: request.expectedCommitObjectId,
    commitRawSha256: commit.rawSha256,
    rootTreeObjectId,
    rootTreeRawSha256: objectCache.get(rootTreeObjectId)?.rawSha256 ?? fail(
      "GIT_BASE_CLOSURE_INVALID",
      "Verified Git-base closure lost its root tree object.",
    ),
    refRevisionToken: initialRef.revisionToken,
    acceptedTreeDigest,
    snapshotObjectClosureDigest,
    objects: manifestObjects,
    files: manifestFiles,
    snapshotObjectCount: objectCache.size,
    fileCount: validatedFiles.length,
    totalFileBytes,
    gitSnapshotClosureValidated: true,
    acceptedTreeMatched: true,
    protectedRef: false,
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayExecute: false,
    limitations: GIT_BASE_MANIFEST_LIMITATIONS,
  };
  return validateGitBaseManifestResultSummaryConsistency(
    { ...body, resultDigest: sha256Bytes(canonicalJson(body)) },
    request,
  );
}

type GitTreeDeltaOperationKindV1 = "ADD" | "REPLACE" | "DELETE" | "CHMOD";

type GitTreeDeltaOperationV1 = {
  kind: GitTreeDeltaOperationKindV1;
  relativePath: string;
  prior: GitBaseManifestFileV1 | null;
  next: CandidateStageDeclaredFileV1 | null;
};

type GitTreeDeltaRequestV1 = {
  schemaVersion: 1;
  profile: typeof GIT_TREE_DELTA_PROFILE;
  operationId: string;
  inputMode: "STRUCTURED_REGULAR_FILE_TREE_DELTA";
  gitBaseRequest: GitBaseManifestRequestV1;
  expectedGitBaseManifestResultDigest: string;
  operations: GitTreeDeltaOperationV1[];
  operationsDigest: string;
  expectedCandidateDigest: string;
  authorityMode: "SELF_ADMINISTERED";
  authorizing: false;
  mayCreateDecision: false;
  mayStage: false;
  mayPromote: false;
  mayInstall: false;
  mayExecute: false;
  requestDigest: string;
};

type GitTreeDeltaResultFileV1 = {
  relativePath: string;
  mode: "100644" | "100755";
  byteLength: number;
  contentSha256: string;
};

type GitTreeDeltaResultV1 = {
  schemaVersion: 1;
  recordType: "GIT_TREE_DELTA_DERIVATION";
  status: "DERIVED_INERT";
  profile: typeof GIT_TREE_DELTA_PROFILE;
  operationId: string;
  requestDigest: string;
  gitBaseRequestDigest: string;
  gitBaseManifestResultDigest: string;
  baseBindingDigest: string;
  commitObjectId: string;
  rootTreeObjectId: string;
  refRevisionToken: string;
  snapshotObjectClosureDigest: string;
  operationsDigest: string;
  baseTreeDigest: string;
  baseInventoryDigest: string;
  finalInventoryDigest: string;
  candidateDigest: string;
  operationCount: number;
  addCount: number;
  replaceCount: number;
  deleteCount: number;
  chmodCount: number;
  baseFileCount: number;
  baseTotalBytes: number;
  finalFileCount: number;
  finalTotalBytes: number;
  finalFiles: GitTreeDeltaResultFileV1[];
  atomicCheckIds: typeof M37_GIT_TREE_DELTA_ATOMIC_CHECK_IDS;
  repeatedRuns: typeof M37_GIT_TREE_DELTA_REPEATED_RUNS;
  denominatorNegativeControls: typeof M37_GIT_TREE_DELTA_DENOMINATOR_NEGATIVE_CONTROL_IDS.length;
  freshBaseReverified: true;
  protectedRef: false;
  authorizing: false;
  mayCreateDecision: false;
  mayStage: false;
  mayPromote: false;
  mayInstall: false;
  mayExecute: false;
  gitSubprocessInvoked: false;
  textPatchParsed: false;
  filesystemMutated: false;
  limitations: typeof GIT_TREE_DELTA_LIMITATIONS;
  resultDigest: string;
};

type GitTreeDeltaFaultPointV1 =
  | "AFTER_VALIDATION"
  | "AFTER_DERIVATION"
  | "BEFORE_FINAL_BASE_VERIFICATION"
  | "BEFORE_RETURN";

type GitTreeDeltaHooksV1 = {
  faultAt?: GitTreeDeltaFaultPointV1;
  afterDerivation?: (context: {
    requestDigest: string;
    candidateDigest: string;
  }) => Promise<void> | void;
};

function gitTreeDeltaDomainDigest(domain: string, value: unknown): string {
  return sha256Bytes(canonicalJson({
    domain: `VERITAS_GIT_TREE_DELTA_V1:${domain}`,
    profile: GIT_TREE_DELTA_PROFILE,
    value,
  }));
}

function throwGitTreeDeltaFault(
  hooks: GitTreeDeltaHooksV1,
  point: GitTreeDeltaFaultPointV1,
): void {
  if (hooks.faultAt === point) {
    fail("GIT_TREE_DELTA_INJECTED_FAULT", `Injected inert tree-delta fault at ${point}.`);
  }
}

function assertGitTreeDeltaFixtureLane(active = boundedTestLaneActive()): void {
  if (!active) {
    fail("GIT_TREE_DELTA_FIXTURE_ONLY", "Structured tree-delta derivation is non-callable outside the bounded test lane.");
  }
}

function validateGitTreeDeltaRelativePath(value: unknown): string {
  if (
    typeof value !== "string" ||
    value.length === 0 ||
    value.startsWith("/") ||
    value.endsWith("/") ||
    value.includes("\\") ||
    value.includes("\0") ||
    Buffer.from(value, "utf8").toString("utf8") !== value ||
    [...value].some((character) => {
      const codePoint = character.codePointAt(0);
      return codePoint !== undefined && codePoint >= 0xd800 && codePoint <= 0xdfff;
    })
  ) {
    fail("GIT_TREE_DELTA_PATH_INVALID", "Tree-delta paths require exact canonical UTF-8 relative names.");
  }
  const relativePath = normalizeRelativePath(value);
  const components = relativePath.split("/");
  if (
    relativePath !== value ||
    components.some((component) => component.length === 0 || component === "." || component === "..") ||
    Buffer.byteLength(relativePath, "utf8") > GIT_TREE_DELTA_LIMITS.maxPathBytes ||
    components.length > GIT_TREE_DELTA_LIMITS.maxDepth
  ) {
    fail("GIT_TREE_DELTA_PATH_INVALID", "Tree-delta path traversal, normalization, depth, or byte limits failed.", {
      path: value,
    });
  }
  for (const component of components) gitBasePortableNameKey(component);
  return relativePath;
}

function gitTreeDeltaPortablePathKey(relativePath: string): string {
  return relativePath.split("/").map(gitBasePortableNameKey).join("/");
}

function validateGitTreeDeltaNextFile(
  value: unknown,
  relativePath: string,
): CandidateStageDeclaredFileV1 {
  const next = validateCandidateStageDeclaredFiles([value])[0];
  assert(next !== undefined);
  validateGitTreeDeltaRelativePath(next.relativePath);
  if (next.relativePath !== relativePath) {
    fail("GIT_TREE_DELTA_OPERATION_INVALID", "Tree-delta next file path does not equal its operation path.");
  }
  return next;
}

function validateGitTreeDeltaPriorFile(
  value: unknown,
  relativePath: string,
): GitBaseManifestFileV1 {
  const prior = validateGitBaseManifestFile(value);
  validateGitTreeDeltaRelativePath(prior.relativePath);
  if (prior.relativePath !== relativePath) {
    fail("GIT_TREE_DELTA_OPERATION_INVALID", "Tree-delta prior file path does not equal its operation path.");
  }
  return prior;
}

function validateGitTreeDeltaOperation(value: unknown): GitTreeDeltaOperationV1 {
  const record = requireExactObjectKeys(
    value,
    ["kind", "relativePath", "prior", "next"],
    "GIT_TREE_DELTA_OPERATION_INVALID",
    "Structured tree-delta operation",
  );
  if (
    record.kind !== "ADD" &&
    record.kind !== "REPLACE" &&
    record.kind !== "DELETE" &&
    record.kind !== "CHMOD"
  ) {
    fail("GIT_TREE_DELTA_OPERATION_INVALID", "Tree-delta operation kind is unsupported.");
  }
  const kind = record.kind as GitTreeDeltaOperationKindV1;
  const relativePath = validateGitTreeDeltaRelativePath(record.relativePath);
  if (kind === "ADD") {
    if (record.prior !== null || record.next === null) {
      fail("GIT_TREE_DELTA_OPERATION_INVALID", "ADD requires null prior and one exact next file.");
    }
    return {
      kind,
      relativePath,
      prior: null,
      next: validateGitTreeDeltaNextFile(record.next, relativePath),
    };
  }
  if (record.prior === null) {
    fail("GIT_TREE_DELTA_OPERATION_INVALID", `${kind} requires one exact prior file binding.`);
  }
  const prior = validateGitTreeDeltaPriorFile(record.prior, relativePath);
  if (kind === "DELETE") {
    if (record.next !== null) {
      fail("GIT_TREE_DELTA_OPERATION_INVALID", "DELETE requires null next.");
    }
    return { kind, relativePath, prior, next: null };
  }
  if (record.next === null) {
    fail("GIT_TREE_DELTA_OPERATION_INVALID", `${kind} requires one exact next file.`);
  }
  return {
    kind,
    relativePath,
    prior,
    next: validateGitTreeDeltaNextFile(record.next, relativePath),
  };
}

function assertGitTreeDeltaPredecodeTotals(
  declaredBytes: number,
  encodedCharacters: number,
): void {
  if (
    !Number.isSafeInteger(declaredBytes) ||
    declaredBytes < 0 ||
    declaredBytes > GIT_TREE_DELTA_LIMITS.maxTotalBytes ||
    !Number.isSafeInteger(encodedCharacters) ||
    encodedCharacters < 0 ||
    encodedCharacters > GIT_TREE_DELTA_LIMITS.maxEncodedCharacters
  ) {
    fail("GIT_TREE_DELTA_LIMIT_EXCEEDED", "Tree-delta payloads exceed the aggregate predecode byte or base64 limit.");
  }
}

function validateGitTreeDeltaOperations(value: unknown): GitTreeDeltaOperationV1[] {
  if (
    !Array.isArray(value) ||
    value.length === 0 ||
    value.length > GIT_TREE_DELTA_LIMITS.maxOperations
  ) {
    fail("GIT_TREE_DELTA_OPERATIONS_INVALID", "Tree-delta requires a bounded non-empty operation array.");
  }
  let encodedCharacters = 0;
  let declaredBytes = 0;
  for (const rawOperation of value) {
    const rawRecord = requireExactObjectKeys(
      rawOperation,
      ["kind", "relativePath", "prior", "next"],
      "GIT_TREE_DELTA_OPERATION_INVALID",
      "Structured tree-delta operation predecode envelope",
    );
    if (rawRecord.next !== null) {
      const rawNext = requireExactObjectKeys(
        rawRecord.next,
        ["relativePath", "mode", "byteLength", "bytesBase64", "bytesSha256"],
        "GIT_TREE_DELTA_OPERATION_INVALID",
        "Structured tree-delta next-file predecode envelope",
      );
      if (
        typeof rawNext.byteLength !== "number" ||
        !Number.isSafeInteger(rawNext.byteLength) ||
        rawNext.byteLength < 0 ||
        rawNext.byteLength > GIT_TREE_DELTA_LIMITS.maxFileBytes ||
        typeof rawNext.bytesBase64 !== "string" ||
        rawNext.bytesBase64.length !== candidateStageEncodedLength(rawNext.byteLength)
      ) {
        fail("GIT_TREE_DELTA_LIMIT_EXCEEDED", "Tree-delta payload declaration exceeds or disagrees with its predecode bounds.");
      }
      declaredBytes += rawNext.byteLength;
      encodedCharacters += rawNext.bytesBase64.length;
      assertGitTreeDeltaPredecodeTotals(declaredBytes, encodedCharacters);
    }
  }
  const operations = value.map(validateGitTreeDeltaOperation);
  const sorted = [...operations].sort((left, right) =>
    codePointCompare(left.relativePath, right.relativePath));
  if (canonicalJson(operations) !== canonicalJson(sorted)) {
    fail("GIT_TREE_DELTA_OPERATIONS_INVALID", "Tree-delta operations must be canonically sorted by path.");
  }
  const exactPaths = new Set<string>();
  const portablePaths = new Set<string>();
  for (const operation of operations) {
    const portablePath = gitTreeDeltaPortablePathKey(operation.relativePath);
    if (exactPaths.has(operation.relativePath) || portablePaths.has(portablePath)) {
      fail("GIT_TREE_DELTA_OPERATION_COLLISION", "Tree-delta admits exactly one operation per canonical portable path.", {
        path: operation.relativePath,
      });
    }
    exactPaths.add(operation.relativePath);
    portablePaths.add(portablePath);
  }
  return operations;
}

function gitTreeDeltaOperationsDigest(operations: GitTreeDeltaOperationV1[]): string {
  return gitTreeDeltaDomainDigest("OPERATIONS", operations);
}

function gitTreeDeltaRequestBody(
  request: Omit<GitTreeDeltaRequestV1, "requestDigest"> | GitTreeDeltaRequestV1,
): Omit<GitTreeDeltaRequestV1, "requestDigest"> {
  const { requestDigest: _requestDigest, ...body } = request as GitTreeDeltaRequestV1;
  return body;
}

function validateGitTreeDeltaRequest(value: unknown): GitTreeDeltaRequestV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "profile", "operationId", "inputMode", "gitBaseRequest",
      "expectedGitBaseManifestResultDigest", "operations", "operationsDigest",
      "expectedCandidateDigest", "authorityMode", "authorizing", "mayCreateDecision",
      "mayStage", "mayPromote", "mayInstall", "mayExecute", "requestDigest",
    ],
    "GIT_TREE_DELTA_REQUEST_INVALID",
    "Structured tree-delta request",
  );
  if (
    record.schemaVersion !== 1 ||
    record.profile !== GIT_TREE_DELTA_PROFILE ||
    typeof record.operationId !== "string" ||
    !isCanonicalUuidV4(record.operationId) ||
    record.inputMode !== "STRUCTURED_REGULAR_FILE_TREE_DELTA" ||
    !isSha256Digest(record.expectedGitBaseManifestResultDigest) ||
    !isSha256Digest(record.operationsDigest) ||
    !isSha256Digest(record.expectedCandidateDigest) ||
    record.authorityMode !== "SELF_ADMINISTERED" ||
    record.authorizing !== false ||
    record.mayCreateDecision !== false ||
    record.mayStage !== false ||
    record.mayPromote !== false ||
    record.mayInstall !== false ||
    record.mayExecute !== false ||
    !isSha256Digest(record.requestDigest)
  ) {
    fail("GIT_TREE_DELTA_REQUEST_INVALID", "Tree-delta request fields or zero-authority contract are invalid.");
  }
  const gitBaseRequest = validateGitBaseManifestRequest(record.gitBaseRequest);
  const operations = validateGitTreeDeltaOperations(record.operations);
  const request: GitTreeDeltaRequestV1 = {
    schemaVersion: 1,
    profile: GIT_TREE_DELTA_PROFILE,
    operationId: record.operationId,
    inputMode: "STRUCTURED_REGULAR_FILE_TREE_DELTA",
    gitBaseRequest,
    expectedGitBaseManifestResultDigest: record.expectedGitBaseManifestResultDigest,
    operations,
    operationsDigest: record.operationsDigest,
    expectedCandidateDigest: record.expectedCandidateDigest,
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayInstall: false,
    mayExecute: false,
    requestDigest: record.requestDigest,
  };
  if (
    request.operationsDigest !== gitTreeDeltaOperationsDigest(operations) ||
    request.requestDigest !== gitTreeDeltaDomainDigest(
      "REQUEST",
      gitTreeDeltaRequestBody(request),
    )
  ) {
    fail("GIT_TREE_DELTA_REQUEST_INVALID", "Tree-delta request or operation digest is not exact.");
  }
  return request;
}

function createGitTreeDeltaRequest(
  operationId: string,
  gitBaseRequest: GitBaseManifestRequestV1,
  expectedGitBaseManifestResultDigest: string,
  operations: GitTreeDeltaOperationV1[],
  expectedCandidateDigest: string,
): GitTreeDeltaRequestV1 {
  const validatedOperations = validateGitTreeDeltaOperations(operations);
  const body: Omit<GitTreeDeltaRequestV1, "requestDigest"> = {
    schemaVersion: 1,
    profile: GIT_TREE_DELTA_PROFILE,
    operationId,
    inputMode: "STRUCTURED_REGULAR_FILE_TREE_DELTA",
    gitBaseRequest: validateGitBaseManifestRequest(gitBaseRequest),
    expectedGitBaseManifestResultDigest,
    operations: validatedOperations,
    operationsDigest: gitTreeDeltaOperationsDigest(validatedOperations),
    expectedCandidateDigest,
    authorityMode: "SELF_ADMINISTERED",
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayInstall: false,
    mayExecute: false,
  };
  return validateGitTreeDeltaRequest({
    ...body,
    requestDigest: gitTreeDeltaDomainDigest("REQUEST", body),
  });
}

function assertGitTreeDeltaPriorMatches(
  prior: GitBaseManifestFileV1,
  observed: GitBaseManifestFileV1,
): void {
  if (canonicalJson(prior) !== canonicalJson(observed)) {
    fail("GIT_TREE_DELTA_PRIOR_MISMATCH", "Tree-delta prior state does not exactly bind the verified base file.", {
      path: prior.relativePath,
    });
  }
}

async function materializeExactGitTreeDeltaBase(
  port: GitBaseObjectPortV1,
  manifest: GitBaseManifestResultV1,
): Promise<CandidateStageDeclaredFileV1[]> {
  const declared: CandidateStageDeclaredFileV1[] = [];
  const objectsById = new Map(manifest.objects.map((object) => [object.objectId, object]));
  const contentCache = new Map<string, Buffer>();
  for (const file of manifest.files) {
    const object = objectsById.get(file.blobObjectId);
    if (object?.objectType !== "blob" || object.rawSha256 !== file.blobRawSha256) {
      fail("GIT_TREE_DELTA_BASE_INVALID", "Verified base manifest lost an exact blob-object binding.", {
        path: file.relativePath,
      });
    }
    let content = contentCache.get(file.blobObjectId);
    if (content === undefined) {
      const raw = await readGitBaseRawObject(port, file.blobObjectId);
      const parsed = parseExactGitBaseObject(raw, file.blobObjectId);
      if (parsed.rawSha256 !== file.blobRawSha256) {
        fail("GIT_TREE_DELTA_BASE_CHANGED", "A base blob changed during exact tree-delta materialization.", {
          path: file.relativePath,
        });
      }
      if (parsed.objectType !== "blob") {
        fail("GIT_TREE_DELTA_BASE_INVALID", "A verified base file no longer resolves to a blob.", {
          path: file.relativePath,
        });
      }
      content = Buffer.from(parsed.content);
      contentCache.set(file.blobObjectId, content);
    }
    if (
      content.byteLength !== file.byteLength ||
      sha256Bytes(content) !== file.contentSha256
    ) {
      fail("GIT_TREE_DELTA_BASE_CHANGED", "Base blob bytes disagree with the freshly verified manifest.", {
        path: file.relativePath,
      });
    }
    declared.push(candidateStageDeclaredFile(file.relativePath, content, file.mode));
  }
  declared.sort((left, right) => codePointCompare(left.relativePath, right.relativePath));
  return validateCandidateStageDeclaredFiles(declared);
}

function gitTreeDeltaResultFile(file: CandidateStageDeclaredFileV1): GitTreeDeltaResultFileV1 {
  return {
    relativePath: file.relativePath,
    mode: file.mode,
    byteLength: file.byteLength,
    contentSha256: file.bytesSha256,
  };
}

// Summary consistency is for a result freshly produced by deriveExactGitTreeDelta.
// It is not an ingest verifier and never substitutes for raw base verification or bytes.
function validateGitTreeDeltaResultSummaryConsistency(
  value: unknown,
  request: GitTreeDeltaRequestV1,
  manifest: GitBaseManifestResultV1,
  baseFilesWithBytes: CandidateStageDeclaredFileV1[],
  finalFilesWithBytes: CandidateStageDeclaredFileV1[],
): GitTreeDeltaResultV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "status", "profile", "operationId",
      "requestDigest", "gitBaseRequestDigest", "gitBaseManifestResultDigest",
      "baseBindingDigest", "commitObjectId", "rootTreeObjectId", "refRevisionToken",
      "snapshotObjectClosureDigest", "operationsDigest", "baseTreeDigest",
      "baseInventoryDigest", "finalInventoryDigest", "candidateDigest",
      "operationCount", "addCount", "replaceCount", "deleteCount", "chmodCount",
      "baseFileCount", "baseTotalBytes", "finalFileCount", "finalTotalBytes",
      "finalFiles", "atomicCheckIds", "repeatedRuns", "denominatorNegativeControls",
      "freshBaseReverified", "protectedRef", "authorizing", "mayCreateDecision",
      "mayStage", "mayPromote", "mayInstall", "mayExecute", "gitSubprocessInvoked",
      "textPatchParsed", "filesystemMutated", "limitations", "resultDigest",
    ],
    "GIT_TREE_DELTA_RESULT_INVALID",
    "Structured tree-delta result",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "GIT_TREE_DELTA_DERIVATION" ||
    record.status !== "DERIVED_INERT" ||
    record.profile !== GIT_TREE_DELTA_PROFILE ||
    typeof record.operationId !== "string" ||
    !isCanonicalUuidV4(record.operationId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.gitBaseRequestDigest) ||
    !isSha256Digest(record.gitBaseManifestResultDigest) ||
    !isSha256Digest(record.baseBindingDigest) ||
    !isGitSha1ObjectId(record.commitObjectId) ||
    !isGitSha1ObjectId(record.rootTreeObjectId) ||
    !isSha256Digest(record.refRevisionToken) ||
    !isSha256Digest(record.snapshotObjectClosureDigest) ||
    !isSha256Digest(record.operationsDigest) ||
    !isSha256Digest(record.baseTreeDigest) ||
    !isSha256Digest(record.baseInventoryDigest) ||
    !isSha256Digest(record.finalInventoryDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    record.freshBaseReverified !== true ||
    record.protectedRef !== false ||
    record.authorizing !== false ||
    record.mayCreateDecision !== false ||
    record.mayStage !== false ||
    record.mayPromote !== false ||
    record.mayInstall !== false ||
    record.mayExecute !== false ||
    record.gitSubprocessInvoked !== false ||
    record.textPatchParsed !== false ||
    record.filesystemMutated !== false ||
    canonicalJson(record.atomicCheckIds) !== canonicalJson(M37_GIT_TREE_DELTA_ATOMIC_CHECK_IDS) ||
    record.repeatedRuns !== M37_GIT_TREE_DELTA_REPEATED_RUNS ||
    record.denominatorNegativeControls !== M37_GIT_TREE_DELTA_DENOMINATOR_NEGATIVE_CONTROL_IDS.length ||
    canonicalJson(record.limitations) !== canonicalJson(GIT_TREE_DELTA_LIMITATIONS) ||
    !isSha256Digest(record.resultDigest)
  ) {
    fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result fields, denominator, or zero-authority contract are invalid.");
  }
  const requireResultCount = (field: unknown): number => {
    if (typeof field !== "number" || !Number.isSafeInteger(field) || field < 0) {
      fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result counts must be non-negative safe integers.");
    }
    return field;
  };
  const operationCount = requireResultCount(record.operationCount);
  const addCount = requireResultCount(record.addCount);
  const replaceCount = requireResultCount(record.replaceCount);
  const deleteCount = requireResultCount(record.deleteCount);
  const chmodCount = requireResultCount(record.chmodCount);
  const baseFileCount = requireResultCount(record.baseFileCount);
  const baseTotalBytes = requireResultCount(record.baseTotalBytes);
  const finalFileCount = requireResultCount(record.finalFileCount);
  const finalTotalBytes = requireResultCount(record.finalTotalBytes);
  if (
    !Array.isArray(record.finalFiles) ||
    record.finalFiles.length === 0 ||
    record.finalFiles.length > GIT_TREE_DELTA_LIMITS.maxFiles
  ) {
    fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result final inventory is invalid.");
  }
  const finalFiles: GitTreeDeltaResultFileV1[] = record.finalFiles.map((value: unknown) => {
    const file = requireExactObjectKeys(
      value,
      ["relativePath", "mode", "byteLength", "contentSha256"],
      "GIT_TREE_DELTA_RESULT_INVALID",
      "Tree-delta result file",
    );
    const relativePath = validateGitTreeDeltaRelativePath(file.relativePath);
    if (
      (file.mode !== "100644" && file.mode !== "100755") ||
      typeof file.byteLength !== "number" ||
      !Number.isSafeInteger(file.byteLength) ||
      file.byteLength < 0 ||
      file.byteLength > GIT_TREE_DELTA_LIMITS.maxFileBytes ||
      !isSha256Digest(file.contentSha256)
    ) {
      fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result file metadata is invalid.");
    }
    return {
      relativePath,
      mode: file.mode,
      byteLength: file.byteLength,
      contentSha256: file.contentSha256,
    } as GitTreeDeltaResultFileV1;
  });
  const sortedFiles = [...finalFiles].sort((left, right) =>
    codePointCompare(left.relativePath, right.relativePath));
  const portableKeys = finalFiles.map((file) => gitTreeDeltaPortablePathKey(file.relativePath));
  const observedFinalBytes = finalFiles.reduce((total, file) => total + file.byteLength, 0);
  const exactBaseFiles = validateCandidateStageDeclaredFiles(baseFilesWithBytes);
  const exactFinalFiles = validateCandidateStageDeclaredFiles(finalFilesWithBytes);
  const expectedFinalFiles = exactFinalFiles.map(gitTreeDeltaResultFile);
  const operationCounts = { ADD: 0, REPLACE: 0, DELETE: 0, CHMOD: 0 };
  for (const operation of request.operations) operationCounts[operation.kind] += 1;
  if (
    canonicalJson(finalFiles) !== canonicalJson(sortedFiles) ||
    new Set(finalFiles.map((file) => file.relativePath)).size !== finalFiles.length ||
    new Set(portableKeys).size !== finalFiles.length ||
    operationCount !== addCount + replaceCount + deleteCount + chmodCount ||
    finalFileCount !== finalFiles.length ||
    finalTotalBytes !== observedFinalBytes ||
    record.finalInventoryDigest !== gitTreeDeltaDomainDigest("FINAL_INVENTORY", finalFiles) ||
    canonicalJson(finalFiles) !== canonicalJson(expectedFinalFiles) ||
    record.operationId !== request.operationId ||
    record.requestDigest !== request.requestDigest ||
    record.gitBaseRequestDigest !== request.gitBaseRequest.requestDigest ||
    record.gitBaseManifestResultDigest !== manifest.resultDigest ||
    record.baseBindingDigest !== candidateStageBaseBindingDigest(request.gitBaseRequest.base) ||
    record.commitObjectId !== manifest.commitObjectId ||
    record.rootTreeObjectId !== manifest.rootTreeObjectId ||
    record.refRevisionToken !== manifest.refRevisionToken ||
    record.snapshotObjectClosureDigest !== manifest.snapshotObjectClosureDigest ||
    record.operationsDigest !== request.operationsDigest ||
    record.baseTreeDigest !== manifest.acceptedTreeDigest ||
    record.baseInventoryDigest !== gitTreeDeltaDomainDigest(
      "BASE_INVENTORY",
      exactBaseFiles.map(gitTreeDeltaResultFile),
    ) ||
    record.candidateDigest !== candidateStageTreeDigest(exactFinalFiles) ||
    record.candidateDigest !== request.expectedCandidateDigest ||
    operationCount !== request.operations.length ||
    addCount !== operationCounts.ADD ||
    replaceCount !== operationCounts.REPLACE ||
    deleteCount !== operationCounts.DELETE ||
    chmodCount !== operationCounts.CHMOD ||
    baseFileCount !== exactBaseFiles.length ||
    baseTotalBytes !== exactBaseFiles.reduce((total, file) => total + file.byteLength, 0)
  ) {
    fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result counts or exact final inventory disagree.");
  }
  const body = { ...record } as Record<string, unknown>;
  delete body.resultDigest;
  if (record.resultDigest !== gitTreeDeltaDomainDigest("RESULT", body)) {
    fail("GIT_TREE_DELTA_RESULT_INVALID", "Tree-delta result digest is not exact.");
  }
  return { ...record, finalFiles } as GitTreeDeltaResultV1;
}

async function deriveExactGitTreeDelta(
  storePath: string,
  value: unknown,
  port: GitBaseObjectPortV1,
  hooks: GitTreeDeltaHooksV1 = {},
): Promise<GitTreeDeltaResultV1> {
  assertGitTreeDeltaFixtureLane();
  const request = validateGitTreeDeltaRequest(value);
  throwGitTreeDeltaFault(hooks, "AFTER_VALIDATION");
  const initialManifest = await verifyExactGitBaseManifest(
    storePath,
    request.gitBaseRequest,
    port,
  );
  if (initialManifest.resultDigest !== request.expectedGitBaseManifestResultDigest) {
    fail("GIT_TREE_DELTA_BASE_RESULT_MISMATCH", "Fresh raw Git-base result differs from the exact request binding.");
  }
  const baseFiles = await materializeExactGitTreeDeltaBase(port, initialManifest);
  const baseByPath = new Map(baseFiles.map((file) => [file.relativePath, file]));
  const manifestByPath = new Map(initialManifest.files.map((file) => [file.relativePath, file]));

  for (const operation of request.operations) {
    const baseFile = baseByPath.get(operation.relativePath);
    const manifestFile = manifestByPath.get(operation.relativePath);
    if (operation.kind === "ADD") {
      if (baseFile !== undefined || manifestFile !== undefined) {
        fail("GIT_TREE_DELTA_ADD_EXISTS", "ADD requires proven absence from the exact base inventory.", {
          path: operation.relativePath,
        });
      }
      continue;
    }
    if (baseFile === undefined || manifestFile === undefined || operation.prior === null) {
      fail("GIT_TREE_DELTA_PRIOR_ABSENT", `${operation.kind} requires an exact existing base file.`, {
        path: operation.relativePath,
      });
    }
    assertGitTreeDeltaPriorMatches(operation.prior, manifestFile);
    if (operation.kind === "DELETE") continue;
    assert(operation.next !== null);
    if (operation.kind === "REPLACE") {
      if (operation.next.bytesSha256 === baseFile.bytesSha256) {
        fail("GIT_TREE_DELTA_REPLACE_NOOP", "REPLACE requires changed content; mode-only changes require CHMOD.", {
          path: operation.relativePath,
        });
      }
      continue;
    }
    if (
      operation.next.bytesSha256 !== baseFile.bytesSha256 ||
      operation.next.byteLength !== baseFile.byteLength ||
      operation.next.bytesBase64 !== baseFile.bytesBase64
    ) {
      fail("GIT_TREE_DELTA_CHMOD_CONTENT_CHANGED", "CHMOD must preserve exact content bytes.", {
        path: operation.relativePath,
      });
    }
    if (operation.next.mode === baseFile.mode) {
      fail("GIT_TREE_DELTA_CHMOD_NOOP", "CHMOD must toggle the admitted regular-file mode.", {
        path: operation.relativePath,
      });
    }
  }

  const finalByPath = new Map(
    baseFiles.map((file) => [file.relativePath, structuredClone(file)]),
  );
  for (const operation of request.operations) {
    if (operation.kind === "DELETE") finalByPath.delete(operation.relativePath);
    else {
      assert(operation.next !== null);
      finalByPath.set(operation.relativePath, structuredClone(operation.next));
    }
  }
  const finalFiles = [...finalByPath.values()].sort((left, right) =>
    codePointCompare(left.relativePath, right.relativePath));
  const validatedFinalFiles = validateCandidateStageDeclaredFiles(finalFiles);
  const candidateDigest = candidateStageTreeDigest(validatedFinalFiles);
  if (candidateDigest !== request.expectedCandidateDigest) {
    fail("GIT_TREE_DELTA_FINAL_DIGEST_MISMATCH", "Derived final tree does not equal the exact requested artifact digest.");
  }
  throwGitTreeDeltaFault(hooks, "AFTER_DERIVATION");
  await hooks.afterDerivation?.({ requestDigest: request.requestDigest, candidateDigest });
  throwGitTreeDeltaFault(hooks, "BEFORE_FINAL_BASE_VERIFICATION");
  const finalManifest = await verifyExactGitBaseManifest(
    storePath,
    request.gitBaseRequest,
    port,
  );
  if (
    finalManifest.resultDigest !== initialManifest.resultDigest ||
    finalManifest.resultDigest !== request.expectedGitBaseManifestResultDigest ||
    finalManifest.refRevisionToken !== initialManifest.refRevisionToken ||
    finalManifest.snapshotObjectClosureDigest !== initialManifest.snapshotObjectClosureDigest
  ) {
    fail("GIT_TREE_DELTA_BASE_CHANGED", "Exact Git base, ref token, or object closure changed during derivation.");
  }
  throwGitTreeDeltaFault(hooks, "BEFORE_RETURN");

  const finalResultFiles = validatedFinalFiles.map(gitTreeDeltaResultFile);
  const counts = { ADD: 0, REPLACE: 0, DELETE: 0, CHMOD: 0 };
  for (const operation of request.operations) counts[operation.kind] += 1;
  const body: Omit<GitTreeDeltaResultV1, "resultDigest"> = {
    schemaVersion: 1,
    recordType: "GIT_TREE_DELTA_DERIVATION",
    status: "DERIVED_INERT",
    profile: GIT_TREE_DELTA_PROFILE,
    operationId: request.operationId,
    requestDigest: request.requestDigest,
    gitBaseRequestDigest: request.gitBaseRequest.requestDigest,
    gitBaseManifestResultDigest: finalManifest.resultDigest,
    baseBindingDigest: candidateStageBaseBindingDigest(request.gitBaseRequest.base),
    commitObjectId: finalManifest.commitObjectId,
    rootTreeObjectId: finalManifest.rootTreeObjectId,
    refRevisionToken: finalManifest.refRevisionToken,
    snapshotObjectClosureDigest: finalManifest.snapshotObjectClosureDigest,
    operationsDigest: request.operationsDigest,
    baseTreeDigest: finalManifest.acceptedTreeDigest,
    baseInventoryDigest: gitTreeDeltaDomainDigest(
      "BASE_INVENTORY",
      baseFiles.map(gitTreeDeltaResultFile),
    ),
    finalInventoryDigest: gitTreeDeltaDomainDigest("FINAL_INVENTORY", finalResultFiles),
    candidateDigest,
    operationCount: request.operations.length,
    addCount: counts.ADD,
    replaceCount: counts.REPLACE,
    deleteCount: counts.DELETE,
    chmodCount: counts.CHMOD,
    baseFileCount: baseFiles.length,
    baseTotalBytes: baseFiles.reduce((total, file) => total + file.byteLength, 0),
    finalFileCount: validatedFinalFiles.length,
    finalTotalBytes: validatedFinalFiles.reduce((total, file) => total + file.byteLength, 0),
    finalFiles: finalResultFiles,
    atomicCheckIds: M37_GIT_TREE_DELTA_ATOMIC_CHECK_IDS,
    repeatedRuns: M37_GIT_TREE_DELTA_REPEATED_RUNS,
    denominatorNegativeControls: M37_GIT_TREE_DELTA_DENOMINATOR_NEGATIVE_CONTROL_IDS.length,
    freshBaseReverified: true,
    protectedRef: false,
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayInstall: false,
    mayExecute: false,
    gitSubprocessInvoked: false,
    textPatchParsed: false,
    filesystemMutated: false,
    limitations: GIT_TREE_DELTA_LIMITATIONS,
  };
  return validateGitTreeDeltaResultSummaryConsistency({
    ...body,
    resultDigest: gitTreeDeltaDomainDigest("RESULT", body),
  }, request, finalManifest, baseFiles, validatedFinalFiles);
}

// M46_INERT_DEPENDENCY_GRAPH_BEGIN
type M46DependencyNodeTypeV1 =
  | "CLOSURE_ROOT"
  | "VERIFIER"
  | "POLICY"
  | "ADAPTER"
  | "RUNTIME"
  | "EVIDENCE"
  | "DESTINATION";

type M46RequiredDependencyNodeTypeV1 = Exclude<
  M46DependencyNodeTypeV1,
  "CLOSURE_ROOT"
>;

type M46DependencyNodeV1 = {
  schemaVersion: 1;
  recordType: "M46_DEPENDENCY_NODE";
  nodeType: M46DependencyNodeTypeV1;
  nodeId: string;
  contentDigest: string;
  nodeDigest: string;
};

type M46RequiredDependencyV1 = {
  nodeType: M46RequiredDependencyNodeTypeV1;
  nodeId: string;
  nodeDigest: string;
};

type M46DependencyEdgeV1 = {
  schemaVersion: 1;
  recordType: "M46_DEPENDENCY_EDGE";
  edgeType: "DEPENDS_ON";
  fromNodeDigest: string;
  toNodeDigest: string;
  edgeDigest: string;
};

type M46DependencyClosureGraphV1 = {
  schemaVersion: 1;
  recordType: "M46_DEPENDENCY_CLOSURE_GRAPH";
  status: "DECLARED_INERT";
  profile: typeof M46_DEPENDENCY_CLOSURE_PROFILE;
  foundationOnly: true;
  subjectType: "ACCEPTED_ARTIFACT";
  subjectDigest: string;
  rootNodeDigest: string;
  requiredDependencies: M46RequiredDependencyV1[];
  nodes: M46DependencyNodeV1[];
  edges: M46DependencyEdgeV1[];
  nodeCount: number;
  edgeCount: number;
  authorityMode: "SELF_ADMINISTERED";
  externalCompletenessVerified: false;
  currentnessVerified: false;
  destinationReadbackVerified: false;
  authorizing: false;
  mayCreateDecision: false;
  mayStage: false;
  mayPromote: false;
  mayRecall: false;
  mayReplay: false;
  mayInstall: false;
  mayExecute: false;
  graphDigest: string;
};

type M46DependencyClosureExpectationsV1 = {
  expectedSubjectDigest: string;
  expectedGraphDigest: string;
};

const M46_DEPENDENCY_NODE_TYPES = Object.freeze([
  "CLOSURE_ROOT",
  "VERIFIER",
  "POLICY",
  "ADAPTER",
  "RUNTIME",
  "EVIDENCE",
  "DESTINATION",
] as const);

const M46_REQUIRED_DEPENDENCY_NODE_TYPES = Object.freeze([
  "VERIFIER",
  "POLICY",
  "ADAPTER",
  "RUNTIME",
  "EVIDENCE",
  "DESTINATION",
] as const);

function m46DependencyDomainDigest(domain: string, value: unknown): string {
  const hash = createHash("sha256");
  updateFrame(hash, 0, Buffer.from(domain, "utf8"));
  updateFrame(hash, 1, Buffer.from(canonicalJson(value), "utf8"));
  return hash.digest("hex");
}

function m46DependencyNodeId(value: unknown): string {
  if (
    typeof value !== "string" ||
    value.length > M46_DEPENDENCY_GRAPH_LIMITS.maxNodeIdBytes ||
    Buffer.byteLength(value, "utf8") > M46_DEPENDENCY_GRAPH_LIMITS.maxNodeIdBytes ||
    value.normalize("NFC") !== value ||
    !/^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*(?:\/[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*)*$/u.test(value)
  ) {
    fail(
      "M46_DEPENDENCY_NODE_ID_INVALID",
      "M4.6 dependency node IDs must be bounded NFC lowercase ASCII namespaces.",
    );
  }
  return value;
}

function compareM46DependencyNodes(
  left: M46DependencyNodeV1,
  right: M46DependencyNodeV1,
): number {
  return codePointCompare(left.nodeType, right.nodeType) ||
    codePointCompare(left.nodeId, right.nodeId) ||
    codePointCompare(left.nodeDigest, right.nodeDigest);
}

function compareM46RequiredDependencies(
  left: M46RequiredDependencyV1,
  right: M46RequiredDependencyV1,
): number {
  return codePointCompare(left.nodeType, right.nodeType) ||
    codePointCompare(left.nodeId, right.nodeId) ||
    codePointCompare(left.nodeDigest, right.nodeDigest);
}

function compareM46DependencyEdges(
  left: M46DependencyEdgeV1,
  right: M46DependencyEdgeV1,
): number {
  return codePointCompare(left.fromNodeDigest, right.fromNodeDigest) ||
    codePointCompare(left.toNodeDigest, right.toNodeDigest) ||
    codePointCompare(left.edgeType, right.edgeType) ||
    codePointCompare(left.edgeDigest, right.edgeDigest);
}

function createM46DependencyNode(
  nodeType: M46DependencyNodeTypeV1,
  nodeId: string,
  contentDigest: string,
): M46DependencyNodeV1 {
  const body = {
    schemaVersion: 1 as const,
    recordType: "M46_DEPENDENCY_NODE" as const,
    nodeType,
    nodeId,
    contentDigest,
  };
  return {
    ...body,
    nodeDigest: m46DependencyDomainDigest(M46_DEPENDENCY_NODE_DIGEST_DOMAIN, body),
  };
}

function createM46DependencyEdge(
  fromNodeDigest: string,
  toNodeDigest: string,
): M46DependencyEdgeV1 {
  const body = {
    schemaVersion: 1 as const,
    recordType: "M46_DEPENDENCY_EDGE" as const,
    edgeType: "DEPENDS_ON" as const,
    fromNodeDigest,
    toNodeDigest,
  };
  return {
    ...body,
    edgeDigest: m46DependencyDomainDigest(M46_DEPENDENCY_EDGE_DIGEST_DOMAIN, body),
  };
}

function createM46MinimumDependencyClosureGraph(
  contentSalt = "m46-fixture",
  subjectDigestOverride?: string,
): M46DependencyClosureGraphV1 {
  const subjectDigest = subjectDigestOverride ?? sha256Bytes(`${contentSalt}:accepted-artifact`);
  const nodes = [
    createM46DependencyNode("CLOSURE_ROOT", "root/accepted-artifact", subjectDigest),
    createM46DependencyNode(
      "VERIFIER",
      "verifier/deterministic-gates",
      sha256Bytes(`${contentSalt}:verifier/deterministic-gates`),
    ),
    createM46DependencyNode(
      "POLICY",
      "policy/acceptance-profile",
      sha256Bytes(`${contentSalt}:policy/acceptance-profile`),
    ),
    createM46DependencyNode(
      "ADAPTER",
      "adapter/project-test",
      sha256Bytes(`${contentSalt}:adapter/project-test`),
    ),
    createM46DependencyNode(
      "RUNTIME",
      "runtime/node",
      sha256Bytes(`${contentSalt}:runtime/node`),
    ),
    createM46DependencyNode(
      "EVIDENCE",
      "evidence/test-result",
      sha256Bytes(`${contentSalt}:evidence/test-result`),
    ),
    createM46DependencyNode(
      "DESTINATION",
      "destination/local-content-addressed",
      sha256Bytes(`${contentSalt}:destination/local-content-addressed`),
    ),
  ].sort(compareM46DependencyNodes);
  const root = nodes.find((node) => node.nodeType === "CLOSURE_ROOT");
  assert(root !== undefined);
  const dependencies = nodes.filter(
    (node): node is M46DependencyNodeV1 & { nodeType: M46RequiredDependencyNodeTypeV1 } =>
      node.nodeType !== "CLOSURE_ROOT",
  );
  const requiredDependencies = dependencies.map((node) => ({
    nodeType: node.nodeType,
    nodeId: node.nodeId,
    nodeDigest: node.nodeDigest,
  })).sort(compareM46RequiredDependencies);
  const edges = dependencies.map((node) =>
    createM46DependencyEdge(root.nodeDigest, node.nodeDigest)).sort(compareM46DependencyEdges);
  const body: Omit<M46DependencyClosureGraphV1, "graphDigest"> = {
    schemaVersion: 1,
    recordType: "M46_DEPENDENCY_CLOSURE_GRAPH",
    status: "DECLARED_INERT",
    profile: M46_DEPENDENCY_CLOSURE_PROFILE,
    foundationOnly: true,
    subjectType: "ACCEPTED_ARTIFACT",
    subjectDigest,
    rootNodeDigest: root.nodeDigest,
    requiredDependencies,
    nodes,
    edges,
    nodeCount: nodes.length,
    edgeCount: edges.length,
    authorityMode: "SELF_ADMINISTERED",
    externalCompletenessVerified: false,
    currentnessVerified: false,
    destinationReadbackVerified: false,
    authorizing: false,
    mayCreateDecision: false,
    mayStage: false,
    mayPromote: false,
    mayRecall: false,
    mayReplay: false,
    mayInstall: false,
    mayExecute: false,
  };
  return {
    ...body,
    graphDigest: m46DependencyDomainDigest(M46_DEPENDENCY_GRAPH_DIGEST_DOMAIN, body),
  };
}

function validateM46DependencyClosureGraph(
  value: unknown,
  expectations: M46DependencyClosureExpectationsV1,
): M46DependencyClosureGraphV1 {
  if (
    !isSha256Digest(expectations.expectedSubjectDigest) ||
    !isSha256Digest(expectations.expectedGraphDigest)
  ) {
    fail("M46_EXPECTATION_INVALID", "M4.6 graph validation requires external exact subject and graph digests.");
  }
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "status", "profile", "foundationOnly",
      "subjectType", "subjectDigest", "rootNodeDigest", "requiredDependencies",
      "nodes", "edges", "nodeCount", "edgeCount", "authorityMode",
      "externalCompletenessVerified", "currentnessVerified",
      "destinationReadbackVerified", "authorizing", "mayCreateDecision",
      "mayStage", "mayPromote", "mayRecall", "mayReplay", "mayInstall",
      "mayExecute", "graphDigest",
    ],
    "M46_GRAPH_INVALID",
    "M4.6 dependency closure graph",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "M46_DEPENDENCY_CLOSURE_GRAPH" ||
    record.status !== "DECLARED_INERT" ||
    record.profile !== M46_DEPENDENCY_CLOSURE_PROFILE ||
    record.foundationOnly !== true ||
    record.subjectType !== "ACCEPTED_ARTIFACT" ||
    !isSha256Digest(record.subjectDigest) ||
    !isSha256Digest(record.rootNodeDigest) ||
    !isSha256Digest(record.graphDigest) ||
    record.authorityMode !== "SELF_ADMINISTERED" ||
    record.externalCompletenessVerified !== false ||
    record.currentnessVerified !== false ||
    record.destinationReadbackVerified !== false ||
    record.authorizing !== false ||
    record.mayCreateDecision !== false ||
    record.mayStage !== false ||
    record.mayPromote !== false ||
    record.mayRecall !== false ||
    record.mayReplay !== false ||
    record.mayInstall !== false ||
    record.mayExecute !== false
  ) {
    fail("M46_GRAPH_INVALID", "M4.6 graph identity or zero-authority fields are invalid.");
  }
  if (record.subjectDigest !== expectations.expectedSubjectDigest) {
    fail("M46_SUBJECT_EXPECTATION_MISMATCH", "M4.6 graph subject differs from the external expected subject.");
  }
  if (
    !Array.isArray(record.nodes) ||
    record.nodes.length === 0 ||
    record.nodes.length > M46_DEPENDENCY_GRAPH_LIMITS.maxNodes ||
    !Array.isArray(record.requiredDependencies) ||
    record.requiredDependencies.length === 0 ||
    record.requiredDependencies.length >= M46_DEPENDENCY_GRAPH_LIMITS.maxNodes ||
    !Array.isArray(record.edges) ||
    record.edges.length === 0 ||
    record.edges.length > M46_DEPENDENCY_GRAPH_LIMITS.maxEdges ||
    !Number.isSafeInteger(record.nodeCount) ||
    record.nodeCount !== record.nodes.length ||
    !Number.isSafeInteger(record.edgeCount) ||
    record.edgeCount !== record.edges.length
  ) {
    fail("M46_GRAPH_LIMIT_OR_COUNT_INVALID", "M4.6 graph arrays or declared counts exceed the frozen bounds.");
  }

  const nodes = record.nodes.map((value: unknown) => {
    const node = requireExactObjectKeys(
      value,
      ["schemaVersion", "recordType", "nodeType", "nodeId", "contentDigest", "nodeDigest"],
      "M46_NODE_INVALID",
      "M4.6 dependency node",
    );
    if (
      node.schemaVersion !== 1 ||
      node.recordType !== "M46_DEPENDENCY_NODE" ||
      typeof node.nodeType !== "string" ||
      !(M46_DEPENDENCY_NODE_TYPES as readonly string[]).includes(node.nodeType) ||
      !isSha256Digest(node.contentDigest) ||
      !isSha256Digest(node.nodeDigest)
    ) {
      fail("M46_NODE_INVALID", "M4.6 dependency node identity fields are invalid.");
    }
    const typedNode = {
      schemaVersion: 1 as const,
      recordType: "M46_DEPENDENCY_NODE" as const,
      nodeType: node.nodeType as M46DependencyNodeTypeV1,
      nodeId: m46DependencyNodeId(node.nodeId),
      contentDigest: node.contentDigest,
      nodeDigest: node.nodeDigest,
    };
    const { nodeDigest: _nodeDigest, ...body } = typedNode;
    if (
      typedNode.nodeDigest !==
        m46DependencyDomainDigest(M46_DEPENDENCY_NODE_DIGEST_DOMAIN, body)
    ) {
      fail("M46_NODE_DIGEST_MISMATCH", "M4.6 dependency node digest is not exact.");
    }
    return typedNode;
  });
  const nodeDigests = new Set<string>();
  const logicalIdentities = new Set<string>();
  for (const node of nodes) {
    if (nodeDigests.has(node.nodeDigest)) {
      fail("M46_GRAPH_NODE_DIGEST_DUPLICATE", "M4.6 graph repeats a node digest.");
    }
    const identity = `${node.nodeType}\0${node.nodeId}`;
    if (logicalIdentities.has(identity)) {
      fail("M46_GRAPH_NODE_AMBIGUOUS", "M4.6 graph repeats a typed logical node identity.");
    }
    nodeDigests.add(node.nodeDigest);
    logicalIdentities.add(identity);
  }
  if (canonicalJson(nodes) !== canonicalJson([...nodes].sort(compareM46DependencyNodes))) {
    fail("M46_GRAPH_NODE_ORDER_INVALID", "M4.6 dependency nodes must be canonically sorted.");
  }
  const roots = nodes.filter((node) => node.nodeType === "CLOSURE_ROOT");
  if (
    roots.length !== 1 ||
    roots[0]?.nodeDigest !== record.rootNodeDigest ||
    roots[0]?.contentDigest !== record.subjectDigest
  ) {
    fail("M46_GRAPH_ROOT_INVALID", "M4.6 graph requires one exact subject-bound closure root.");
  }
  for (const nodeType of M46_REQUIRED_DEPENDENCY_NODE_TYPES) {
    if (!nodes.some((node) => node.nodeType === nodeType)) {
      fail("M46_GRAPH_REQUIRED_TYPE_MISSING", "M4.6 graph omits a required dependency type.", { nodeType });
    }
  }

  const requiredDependencies = record.requiredDependencies.map((value: unknown) => {
    const requirement = requireExactObjectKeys(
      value,
      ["nodeType", "nodeId", "nodeDigest"],
      "M46_REQUIREMENT_INVALID",
      "M4.6 required dependency",
    );
    if (
      typeof requirement.nodeType !== "string" ||
      !(M46_REQUIRED_DEPENDENCY_NODE_TYPES as readonly string[]).includes(requirement.nodeType) ||
      !isSha256Digest(requirement.nodeDigest)
    ) {
      fail("M46_REQUIREMENT_INVALID", "M4.6 required dependency identity is invalid.");
    }
    return {
      nodeType: requirement.nodeType as M46RequiredDependencyNodeTypeV1,
      nodeId: m46DependencyNodeId(requirement.nodeId),
      nodeDigest: requirement.nodeDigest,
    };
  });
  if (
    canonicalJson(requiredDependencies) !==
      canonicalJson([...requiredDependencies].sort(compareM46RequiredDependencies))
  ) {
    fail("M46_GRAPH_REQUIREMENT_ORDER_INVALID", "M4.6 required dependencies must be canonically sorted.");
  }
  const expectedRequirements = nodes
    .filter(
      (node): node is M46DependencyNodeV1 & { nodeType: M46RequiredDependencyNodeTypeV1 } =>
        node.nodeType !== "CLOSURE_ROOT",
    )
    .map((node) => ({
      nodeType: node.nodeType,
      nodeId: node.nodeId,
      nodeDigest: node.nodeDigest,
    }))
    .sort(compareM46RequiredDependencies);
  if (canonicalJson(requiredDependencies) !== canonicalJson(expectedRequirements)) {
    fail("M46_GRAPH_REQUIREMENTS_MISMATCH", "M4.6 requirements must equal every and only declared non-root node.");
  }

  const edges = record.edges.map((value: unknown) => {
    const edge = requireExactObjectKeys(
      value,
      ["schemaVersion", "recordType", "edgeType", "fromNodeDigest", "toNodeDigest", "edgeDigest"],
      "M46_EDGE_INVALID",
      "M4.6 dependency edge",
    );
    if (
      edge.schemaVersion !== 1 ||
      edge.recordType !== "M46_DEPENDENCY_EDGE" ||
      edge.edgeType !== "DEPENDS_ON" ||
      !isSha256Digest(edge.fromNodeDigest) ||
      !isSha256Digest(edge.toNodeDigest) ||
      !isSha256Digest(edge.edgeDigest)
    ) {
      fail("M46_EDGE_INVALID", "M4.6 dependency edge identity fields are invalid.");
    }
    const typedEdge = {
      schemaVersion: 1 as const,
      recordType: "M46_DEPENDENCY_EDGE" as const,
      edgeType: "DEPENDS_ON" as const,
      fromNodeDigest: edge.fromNodeDigest,
      toNodeDigest: edge.toNodeDigest,
      edgeDigest: edge.edgeDigest,
    };
    const { edgeDigest: _edgeDigest, ...body } = typedEdge;
    if (
      typedEdge.edgeDigest !==
        m46DependencyDomainDigest(M46_DEPENDENCY_EDGE_DIGEST_DOMAIN, body)
    ) {
      fail("M46_EDGE_DIGEST_MISMATCH", "M4.6 dependency edge digest is not exact.");
    }
    return typedEdge;
  });
  if (canonicalJson(edges) !== canonicalJson([...edges].sort(compareM46DependencyEdges))) {
    fail("M46_GRAPH_EDGE_ORDER_INVALID", "M4.6 dependency edges must be canonically sorted.");
  }
  if (new Set(edges.map((edge) => edge.edgeDigest)).size !== edges.length) {
    fail("M46_GRAPH_EDGE_DUPLICATE", "M4.6 graph repeats a dependency edge.");
  }
  for (const edge of edges) {
    if (!nodeDigests.has(edge.fromNodeDigest) || !nodeDigests.has(edge.toNodeDigest)) {
      fail("M46_GRAPH_EDGE_ENDPOINT_INVALID", "M4.6 dependency edge names an unknown node.");
    }
    if (edge.fromNodeDigest === edge.toNodeDigest) {
      fail("M46_GRAPH_SELF_EDGE", "M4.6 dependency graph refuses self-dependency.");
    }
    if (edge.toNodeDigest === record.rootNodeDigest) {
      fail("M46_GRAPH_ROOT_INVALID", "M4.6 closure root cannot depend on another graph node.");
    }
  }

  const inbound = new Map(nodes.map((node) => [node.nodeDigest, 0]));
  const outgoing = new Map(nodes.map((node) => [node.nodeDigest, [] as string[]]));
  for (const edge of edges) {
    inbound.set(edge.toNodeDigest, (inbound.get(edge.toNodeDigest) ?? 0) + 1);
    outgoing.get(edge.fromNodeDigest)?.push(edge.toNodeDigest);
  }
  const ready = [...inbound.entries()]
    .filter(([, count]) => count === 0)
    .map(([digest]) => digest)
    .sort(codePointCompare);
  let processed = 0;
  while (ready.length > 0) {
    const digest = ready.shift();
    assert(digest !== undefined);
    processed += 1;
    for (const dependencyDigest of outgoing.get(digest) ?? []) {
      const next = (inbound.get(dependencyDigest) ?? 0) - 1;
      inbound.set(dependencyDigest, next);
      if (next === 0) {
        ready.push(dependencyDigest);
        ready.sort(codePointCompare);
      }
    }
  }
  if (processed !== nodes.length) {
    fail("M46_GRAPH_CYCLE", "M4.6 dependency graph must be acyclic.");
  }
  const reachable = new Set<string>();
  const pending = [record.rootNodeDigest as string];
  while (pending.length > 0) {
    const digest = pending.pop();
    assert(digest !== undefined);
    if (reachable.has(digest)) continue;
    reachable.add(digest);
    for (const dependencyDigest of outgoing.get(digest) ?? []) pending.push(dependencyDigest);
  }
  if (reachable.size !== nodes.length) {
    fail("M46_GRAPH_UNREACHABLE", "Every declared dependency must be reachable from the closure root.");
  }

  const body = { ...record } as Record<string, unknown>;
  delete body.graphDigest;
  const observedGraphDigest = m46DependencyDomainDigest(
    M46_DEPENDENCY_GRAPH_DIGEST_DOMAIN,
    body,
  );
  if (record.graphDigest !== observedGraphDigest) {
    fail("M46_GRAPH_DIGEST_MISMATCH", "M4.6 dependency graph digest is not exact.");
  }
  if (record.graphDigest !== expectations.expectedGraphDigest) {
    fail("M46_GRAPH_EXPECTATION_MISMATCH", "M4.6 graph differs from the external expected graph digest.");
  }
  return structuredClone(record) as M46DependencyClosureGraphV1;
}
// M46_INERT_DEPENDENCY_GRAPH_END

// M46_INERT_SCOPED_RECALL_BEGIN
type M46RecallReceiptFixtureV1 = {
  schemaVersion: 1;
  recordType: "M46_RECALL_RECEIPT_FIXTURE";
  profile: typeof M46_RECALL_PROFILE;
  receiptId: string;
  subjectDigest: string;
  graphDigest: string;
  scopeDigest: string;
  dependencyNodeDigests: string[];
  boundLedgerRevision: number;
  boundBarrierRevision: number;
  authorizing: false;
  mayConsume: false;
  receiptDigest: string;
};

type M46RecallScopeBarrierFixtureV1 = {
  schemaVersion: 1;
  recordType: "M46_RECALL_SCOPE_BARRIER_FIXTURE";
  scopeDigest: string;
  barrierRevision: number;
  lastAffectingEventDigest: string | null;
};

type M46RecallBarrierStateFixtureV1 = {
  schemaVersion: 1;
  recordType: "M46_RECALL_BARRIER_STATE_FIXTURE";
  status: "INERT_FIXTURE";
  profile: typeof M46_RECALL_PROFILE;
  graphDigest: string;
  ledgerRevision: number;
  scopeBarriers: M46RecallScopeBarrierFixtureV1[];
  pendingEventDigest: string | null;
  lastEventId: string | null;
  lastEventDigest: string | null;
  authorizing: false;
  mayConsume: false;
  mayRecall: false;
  mayReplay: false;
  mayExecute: false;
  stateDigest: string;
};

type M46DependencyChangeEventFixtureV1 = {
  schemaVersion: 1;
  recordType: "M46_DEPENDENCY_CHANGE_EVENT_FIXTURE";
  profile: typeof M46_RECALL_PROFILE;
  eventId: string;
  graphDigest: string;
  changeType: "CONTENT_CHANGED";
  previousLedgerRevision: number;
  nextLedgerRevision: number;
  nodeType: M46DependencyNodeTypeV1;
  nodeId: string;
  priorNodeDigest: string;
  priorContentDigest: string;
  nextNodeType: M46DependencyNodeTypeV1;
  nextNodeId: string;
  nextContentDigest: string;
  nextNodeDigest: string;
  externallyObserved: false;
  authenticated: false;
  authorizing: false;
  eventDigest: string;
};

type M46RecallAdmissionDispositionV1 =
  | "MEASURED_CURRENT_NONAUTHORIZING"
  | "MEASURED_UNAFFECTED_NONAUTHORIZING"
  | "REFUSED_RECALL_REQUIRED";

type M46RecallAdmissionFixtureV1 = {
  receiptId: string;
  evaluatedStateDigest: string;
  disposition: M46RecallAdmissionDispositionV1;
};

type M46RecallTransitionResultFixtureV1 = {
  schemaVersion: 1;
  recordType: "M46_RECALL_TRANSITION_RESULT_FIXTURE";
  status: "DERIVED_INERT";
  profile: typeof M46_RECALL_PROFILE;
  graphDigest: string;
  beforeStateDigest: string;
  barrierStateDigest: string;
  afterStateDigest: string;
  receiptSetDigest: string;
  eventDigest: string;
  affectedReceiptIds: string[];
  unaffectedReceiptIds: string[];
  admissions: M46RecallAdmissionFixtureV1[];
  trace: [
    "VALIDATE_PRIOR",
    "VALIDATE_EVENT",
    "ADVANCE_AFFECTED_BARRIER",
    "EVALUATE_AFTER_STATE",
    "RETURN_INERT",
  ];
  authorizing: false;
  mayConsume: false;
  mayRecall: false;
  actualRecallPerformed: false;
  receiptConsumed: false;
  mayCreateDecision: false;
  mayPromote: false;
  mayReplay: false;
  mayInstall: false;
  mayExecute: false;
  filesystemMutated: false;
  networkRequested: false;
  subprocessStarted: false;
  dynamicLoadAttempted: false;
  coordinatorMutated: false;
  resultDigest: string;
};

type M46RecallExpectationsV1 = {
  expectedSubjectDigest: string;
  expectedGraphDigest: string;
  expectedBeforeStateDigest: string;
  expectedReceiptSetDigest: string;
  expectedEventDigest: string;
  expectedBarrierStateDigest: string;
  expectedAfterStateDigest: string;
  expectedResultDigest: string;
};

type M46RecallFixtureInputsV1 = {
  graph: M46DependencyClosureGraphV1;
  receipts: M46RecallReceiptFixtureV1[];
  beforeState: M46RecallBarrierStateFixtureV1;
  event: M46DependencyChangeEventFixtureV1;
  expectations: M46RecallExpectationsV1;
};

function m46RecallDomainDigest(domain: string, value: unknown): string {
  return m46DependencyDomainDigest(domain, value);
}

function m46RecallId(value: unknown, label: "receipt" | "event"): string {
  const maximum = label === "receipt"
    ? M46_RECALL_LIMITS.maxReceiptIdBytes
    : M46_RECALL_LIMITS.maxEventIdBytes;
  if (
    typeof value !== "string" ||
    value.length > maximum ||
    Buffer.byteLength(value, "utf8") > maximum ||
    value.normalize("NFC") !== value ||
    !/^[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*(?:\/[a-z][a-z0-9]*(?:[.-][a-z0-9]+)*)*$/u.test(value)
  ) {
    fail("M46_RECALL_ID_INVALID", `M4.6 ${label} IDs must be bounded NFC lowercase ASCII namespaces.`);
  }
  return value;
}

function compareM46RecallReceipts(
  left: M46RecallReceiptFixtureV1,
  right: M46RecallReceiptFixtureV1,
): number {
  return codePointCompare(left.receiptId, right.receiptId) ||
    codePointCompare(left.receiptDigest, right.receiptDigest);
}

function compareM46RecallScopeBarriers(
  left: M46RecallScopeBarrierFixtureV1,
  right: M46RecallScopeBarrierFixtureV1,
): number {
  return codePointCompare(left.scopeDigest, right.scopeDigest);
}

function m46RecallReceiptSetDigest(
  receipts: ReadonlyArray<M46RecallReceiptFixtureV1>,
): string {
  return m46RecallDomainDigest(M46_RECALL_RECEIPT_SET_DIGEST_DOMAIN, {
    schemaVersion: 1,
    recordType: "M46_RECALL_RECEIPT_SET_FIXTURE",
    profile: M46_RECALL_PROFILE,
    receipts,
  });
}

function createM46RecallReceiptFixture(
  graph: M46DependencyClosureGraphV1,
  receiptId: string,
  dependencyNodeDigests: string[],
  boundBarrierRevision: number,
): M46RecallReceiptFixtureV1 {
  const sortedDependencies = [...dependencyNodeDigests].sort(codePointCompare);
  const scopeBody = {
    schemaVersion: 1 as const,
    recordType: "M46_RECALL_SCOPE_FIXTURE" as const,
    profile: M46_RECALL_PROFILE,
    subjectDigest: graph.subjectDigest,
    graphDigest: graph.graphDigest,
    dependencyNodeDigests: sortedDependencies,
  };
  const body: Omit<M46RecallReceiptFixtureV1, "receiptDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_RECEIPT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    receiptId,
    subjectDigest: graph.subjectDigest,
    graphDigest: graph.graphDigest,
    scopeDigest: m46RecallDomainDigest(M46_RECALL_SCOPE_DIGEST_DOMAIN, scopeBody),
    dependencyNodeDigests: sortedDependencies,
    boundLedgerRevision: 7,
    boundBarrierRevision,
    authorizing: false,
    mayConsume: false,
  };
  return {
    ...body,
    receiptDigest: m46RecallDomainDigest(M46_RECALL_RECEIPT_DIGEST_DOMAIN, body),
  };
}

function validateM46RecallReceiptFixture(
  value: unknown,
  graph: M46DependencyClosureGraphV1,
): M46RecallReceiptFixtureV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "profile", "receiptId", "subjectDigest",
      "graphDigest", "scopeDigest", "dependencyNodeDigests", "boundLedgerRevision",
      "boundBarrierRevision", "authorizing", "mayConsume", "receiptDigest",
    ],
    "M46_RECALL_RECEIPT_INVALID",
    "M4.6 recall receipt fixture",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "M46_RECALL_RECEIPT_FIXTURE" ||
    record.profile !== M46_RECALL_PROFILE ||
    record.subjectDigest !== graph.subjectDigest ||
    record.graphDigest !== graph.graphDigest ||
    !isSha256Digest(record.scopeDigest) ||
    !Array.isArray(record.dependencyNodeDigests) ||
    record.dependencyNodeDigests.length === 0 ||
    record.dependencyNodeDigests.length > M46_RECALL_LIMITS.maxDependenciesPerReceipt ||
    !Number.isSafeInteger(record.boundLedgerRevision) ||
    (record.boundLedgerRevision as number) < 0 ||
    !Number.isSafeInteger(record.boundBarrierRevision) ||
    (record.boundBarrierRevision as number) < 0 ||
    record.authorizing !== false ||
    record.mayConsume !== false ||
    !isSha256Digest(record.receiptDigest)
  ) {
    fail("M46_RECALL_RECEIPT_INVALID", "M4.6 recall receipt identity or zero-authority fields are invalid.");
  }
  const dependencyNodeDigests = (record.dependencyNodeDigests as unknown[]).map((digest) => {
    if (!isSha256Digest(digest)) {
      fail("M46_RECALL_RECEIPT_DEPENDENCY_INVALID", "M4.6 recall receipt dependencies must be SHA-256 digests.");
    }
    return digest;
  });
  if (
    canonicalJson(dependencyNodeDigests) !==
      canonicalJson([...dependencyNodeDigests].sort(codePointCompare))
  ) {
    fail("M46_RECALL_RECEIPT_DEPENDENCY_ORDER_INVALID", "M4.6 recall receipt dependencies must be canonically sorted.");
  }
  if (new Set(dependencyNodeDigests).size !== dependencyNodeDigests.length) {
    fail("M46_RECALL_RECEIPT_DEPENDENCY_DUPLICATE", "M4.6 recall receipt repeats a dependency.");
  }
  const graphDependencyDigests = new Set(
    graph.nodes.filter((node) => node.nodeType !== "CLOSURE_ROOT").map((node) => node.nodeDigest),
  );
  if (!dependencyNodeDigests.every((digest) => graphDependencyDigests.has(digest))) {
    fail("M46_RECALL_RECEIPT_DEPENDENCY_UNKNOWN", "M4.6 recall receipt names a dependency outside the frozen graph.");
  }
  const receiptId = m46RecallId(record.receiptId, "receipt");
  const scopeBody = {
    schemaVersion: 1 as const,
    recordType: "M46_RECALL_SCOPE_FIXTURE" as const,
    profile: M46_RECALL_PROFILE,
    subjectDigest: graph.subjectDigest,
    graphDigest: graph.graphDigest,
    dependencyNodeDigests,
  };
  if (
    record.scopeDigest !==
      m46RecallDomainDigest(M46_RECALL_SCOPE_DIGEST_DOMAIN, scopeBody)
  ) {
    fail("M46_RECALL_SCOPE_DIGEST_MISMATCH", "M4.6 recall receipt scope digest is not exact.");
  }
  const body: Omit<M46RecallReceiptFixtureV1, "receiptDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_RECEIPT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    receiptId,
    subjectDigest: record.subjectDigest,
    graphDigest: record.graphDigest,
    scopeDigest: record.scopeDigest,
    dependencyNodeDigests,
    boundLedgerRevision: record.boundLedgerRevision as number,
    boundBarrierRevision: record.boundBarrierRevision as number,
    authorizing: false,
    mayConsume: false,
  };
  if (
    record.receiptDigest !==
      m46RecallDomainDigest(M46_RECALL_RECEIPT_DIGEST_DOMAIN, body)
  ) {
    fail("M46_RECALL_RECEIPT_DIGEST_MISMATCH", "M4.6 recall receipt digest is not exact.");
  }
  return { ...body, receiptDigest: record.receiptDigest };
}

function validateM46RecallReceiptSet(
  values: unknown,
  graph: M46DependencyClosureGraphV1,
  expectedReceiptSetDigest: string,
): M46RecallReceiptFixtureV1[] {
  if (!isSha256Digest(expectedReceiptSetDigest) || !Array.isArray(values)) {
    fail("M46_RECALL_RECEIPT_SET_INVALID", "M4.6 recall requires an externally expected bounded receipt set.");
  }
  if (values.length < 2 || values.length > M46_RECALL_LIMITS.maxReceipts) {
    fail("M46_RECALL_RECEIPT_SET_INVALID", "M4.6 recall receipt count is outside the frozen bounds.");
  }
  const receipts = values.map((value) => validateM46RecallReceiptFixture(value, graph));
  if (canonicalJson(receipts) !== canonicalJson([...receipts].sort(compareM46RecallReceipts))) {
    fail("M46_RECALL_RECEIPT_ORDER_INVALID", "M4.6 recall receipts must be canonically sorted.");
  }
  if (
    new Set(receipts.map((receipt) => receipt.receiptId)).size !== receipts.length ||
    new Set(receipts.map((receipt) => receipt.receiptDigest)).size !== receipts.length ||
    new Set(receipts.map((receipt) => receipt.scopeDigest)).size !== receipts.length
  ) {
    fail("M46_RECALL_RECEIPT_SET_AMBIGUOUS", "M4.6 recall receipt or scope identity is duplicated.");
  }
  if (m46RecallReceiptSetDigest(receipts) !== expectedReceiptSetDigest) {
    fail("M46_RECALL_RECEIPT_SET_EXPECTATION_MISMATCH", "M4.6 recall receipt set differs from its external expectation.");
  }
  return receipts;
}

function createM46RecallBarrierStateFixture(
  graph: M46DependencyClosureGraphV1,
  receipts: ReadonlyArray<M46RecallReceiptFixtureV1>,
): M46RecallBarrierStateFixtureV1 {
  const body: Omit<M46RecallBarrierStateFixtureV1, "stateDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_BARRIER_STATE_FIXTURE",
    status: "INERT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    graphDigest: graph.graphDigest,
    ledgerRevision: 7,
    scopeBarriers: receipts.map((receipt) => ({
      schemaVersion: 1 as const,
      recordType: "M46_RECALL_SCOPE_BARRIER_FIXTURE" as const,
      scopeDigest: receipt.scopeDigest,
      barrierRevision: receipt.boundBarrierRevision,
      lastAffectingEventDigest: null,
    })).sort(compareM46RecallScopeBarriers),
    pendingEventDigest: null,
    lastEventId: null,
    lastEventDigest: null,
    authorizing: false,
    mayConsume: false,
    mayRecall: false,
    mayReplay: false,
    mayExecute: false,
  };
  return {
    ...body,
    stateDigest: m46RecallDomainDigest(M46_RECALL_STATE_DIGEST_DOMAIN, body),
  };
}

function validateM46RecallBarrierStateFixture(
  value: unknown,
  graph: M46DependencyClosureGraphV1,
  receipts: ReadonlyArray<M46RecallReceiptFixtureV1>,
  expectedStateDigest?: string,
): M46RecallBarrierStateFixtureV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "status", "profile", "graphDigest",
      "ledgerRevision", "scopeBarriers", "pendingEventDigest", "lastEventId",
      "lastEventDigest", "authorizing", "mayConsume", "mayRecall", "mayReplay",
      "mayExecute", "stateDigest",
    ],
    "M46_RECALL_STATE_INVALID",
    "M4.6 recall barrier state fixture",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "M46_RECALL_BARRIER_STATE_FIXTURE" ||
    record.status !== "INERT_FIXTURE" ||
    record.profile !== M46_RECALL_PROFILE ||
    record.graphDigest !== graph.graphDigest ||
    !Number.isSafeInteger(record.ledgerRevision) ||
    (record.ledgerRevision as number) < 0 ||
    !Array.isArray(record.scopeBarriers) ||
    record.scopeBarriers.length !== receipts.length ||
    record.authorizing !== false ||
    record.mayConsume !== false ||
    record.mayRecall !== false ||
    record.mayReplay !== false ||
    record.mayExecute !== false ||
    !isSha256Digest(record.stateDigest)
  ) {
    fail("M46_RECALL_STATE_INVALID", "M4.6 recall state identity or zero-authority fields are invalid.");
  }
  const scopeBarriers = (record.scopeBarriers as unknown[]).map((value) => {
    const barrier = requireExactObjectKeys(
      value,
      [
        "schemaVersion", "recordType", "scopeDigest", "barrierRevision",
        "lastAffectingEventDigest",
      ],
      "M46_RECALL_SCOPE_BARRIER_INVALID",
      "M4.6 recall scope barrier",
    );
    if (
      barrier.schemaVersion !== 1 ||
      barrier.recordType !== "M46_RECALL_SCOPE_BARRIER_FIXTURE" ||
      !isSha256Digest(barrier.scopeDigest) ||
      !Number.isSafeInteger(barrier.barrierRevision) ||
      (barrier.barrierRevision as number) < 0 ||
      !(barrier.lastAffectingEventDigest === null ||
        isSha256Digest(barrier.lastAffectingEventDigest))
    ) {
      fail("M46_RECALL_SCOPE_BARRIER_INVALID", "M4.6 recall scope barrier fields are invalid.");
    }
    return {
      schemaVersion: 1 as const,
      recordType: "M46_RECALL_SCOPE_BARRIER_FIXTURE" as const,
      scopeDigest: barrier.scopeDigest,
      barrierRevision: barrier.barrierRevision as number,
      lastAffectingEventDigest: barrier.lastAffectingEventDigest as string | null,
    };
  });
  if (
    canonicalJson(scopeBarriers) !==
      canonicalJson([...scopeBarriers].sort(compareM46RecallScopeBarriers))
  ) {
    fail("M46_RECALL_SCOPE_BARRIER_ORDER_INVALID", "M4.6 recall scope barriers must be canonically sorted.");
  }
  const expectedScopes = [...receipts].map((receipt) => receipt.scopeDigest).sort(codePointCompare);
  if (
    new Set(scopeBarriers.map((barrier) => barrier.scopeDigest)).size !== scopeBarriers.length ||
    canonicalJson(scopeBarriers.map((barrier) => barrier.scopeDigest)) !==
      canonicalJson(expectedScopes)
  ) {
    fail("M46_RECALL_SCOPE_BARRIER_SET_INVALID", "M4.6 recall barriers must equal every and only receipt scope.");
  }
  const pendingEventDigest = record.pendingEventDigest;
  const lastEventId = record.lastEventId;
  const lastEventDigest = record.lastEventDigest;
  if (
    !(pendingEventDigest === null || isSha256Digest(pendingEventDigest)) ||
    !((lastEventId === null && lastEventDigest === null) ||
      (typeof lastEventId === "string" && isSha256Digest(lastEventDigest))) ||
    (pendingEventDigest !== null && pendingEventDigest !== lastEventDigest)
  ) {
    fail("M46_RECALL_STATE_EVENT_BINDING_INVALID", "M4.6 recall state event bindings are invalid.");
  }
  const typedLastEventId = lastEventId === null ? null : m46RecallId(lastEventId, "event");
  const body: Omit<M46RecallBarrierStateFixtureV1, "stateDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_BARRIER_STATE_FIXTURE",
    status: "INERT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    graphDigest: record.graphDigest,
    ledgerRevision: record.ledgerRevision as number,
    scopeBarriers,
    pendingEventDigest: pendingEventDigest as string | null,
    lastEventId: typedLastEventId,
    lastEventDigest: lastEventDigest as string | null,
    authorizing: false,
    mayConsume: false,
    mayRecall: false,
    mayReplay: false,
    mayExecute: false,
  };
  const computed = m46RecallDomainDigest(M46_RECALL_STATE_DIGEST_DOMAIN, body);
  if (record.stateDigest !== computed) {
    fail("M46_RECALL_STATE_DIGEST_MISMATCH", "M4.6 recall state digest is not exact.");
  }
  if (expectedStateDigest !== undefined) {
    if (!isSha256Digest(expectedStateDigest) || record.stateDigest !== expectedStateDigest) {
      fail("M46_RECALL_STATE_EXPECTATION_MISMATCH", "M4.6 recall state differs from its external expectation.");
    }
  }
  return { ...body, stateDigest: record.stateDigest };
}

function createM46DependencyChangeEventFixture(
  graph: M46DependencyClosureGraphV1,
): M46DependencyChangeEventFixtureV1 {
  const priorNode = graph.nodes.find((node) => node.nodeType === "POLICY");
  assert(priorNode !== undefined);
  const nextContentDigest = sha256Bytes("m46-recall:policy/changed");
  const nextNode = createM46DependencyNode(
    priorNode.nodeType,
    priorNode.nodeId,
    nextContentDigest,
  );
  const body: Omit<M46DependencyChangeEventFixtureV1, "eventDigest"> = {
    schemaVersion: 1,
    recordType: "M46_DEPENDENCY_CHANGE_EVENT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    eventId: "event/policy-content-change",
    graphDigest: graph.graphDigest,
    changeType: "CONTENT_CHANGED",
    previousLedgerRevision: 7,
    nextLedgerRevision: 8,
    nodeType: priorNode.nodeType,
    nodeId: priorNode.nodeId,
    priorNodeDigest: priorNode.nodeDigest,
    priorContentDigest: priorNode.contentDigest,
    nextNodeType: priorNode.nodeType,
    nextNodeId: priorNode.nodeId,
    nextContentDigest,
    nextNodeDigest: nextNode.nodeDigest,
    externallyObserved: false,
    authenticated: false,
    authorizing: false,
  };
  return {
    ...body,
    eventDigest: m46RecallDomainDigest(M46_RECALL_EVENT_DIGEST_DOMAIN, body),
  };
}

function validateM46DependencyChangeEventFixture(
  value: unknown,
  graph: M46DependencyClosureGraphV1,
  expectedEventDigest?: string,
): M46DependencyChangeEventFixtureV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "profile", "eventId", "graphDigest",
      "changeType", "previousLedgerRevision", "nextLedgerRevision", "nodeType",
      "nodeId", "priorNodeDigest", "priorContentDigest", "nextNodeType",
      "nextNodeId", "nextContentDigest", "nextNodeDigest", "externallyObserved",
      "authenticated", "authorizing", "eventDigest",
    ],
    "M46_RECALL_EVENT_INVALID",
    "M4.6 dependency change event fixture",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "M46_DEPENDENCY_CHANGE_EVENT_FIXTURE" ||
    record.profile !== M46_RECALL_PROFILE ||
    record.graphDigest !== graph.graphDigest ||
    record.changeType !== "CONTENT_CHANGED" ||
    !Number.isSafeInteger(record.previousLedgerRevision) ||
    (record.previousLedgerRevision as number) < 0 ||
    !Number.isSafeInteger(record.nextLedgerRevision) ||
    (record.nextLedgerRevision as number) < 0 ||
    typeof record.nodeType !== "string" ||
    !(M46_DEPENDENCY_NODE_TYPES as readonly string[]).includes(record.nodeType) ||
    typeof record.nextNodeType !== "string" ||
    !(M46_DEPENDENCY_NODE_TYPES as readonly string[]).includes(record.nextNodeType) ||
    !isSha256Digest(record.priorNodeDigest) ||
    !isSha256Digest(record.priorContentDigest) ||
    !isSha256Digest(record.nextContentDigest) ||
    !isSha256Digest(record.nextNodeDigest) ||
    record.externallyObserved !== false ||
    record.authenticated !== false ||
    record.authorizing !== false ||
    !isSha256Digest(record.eventDigest)
  ) {
    fail("M46_RECALL_EVENT_INVALID", "M4.6 dependency change event identity or zero-authority fields are invalid.");
  }
  const eventId = m46RecallId(record.eventId, "event");
  const nodeId = m46DependencyNodeId(record.nodeId);
  const nextNodeId = m46DependencyNodeId(record.nextNodeId);
  const priorNode = graph.nodes.find((node) => node.nodeDigest === record.priorNodeDigest);
  if (priorNode === undefined) {
    fail("M46_RECALL_EVENT_NODE_UNKNOWN", "M4.6 recall event prior node is absent from the frozen graph.");
  }
  if (priorNode.nodeType !== record.nodeType || priorNode.nodeId !== nodeId) {
    fail("M46_RECALL_EVENT_PRIOR_NODE_MISMATCH", "M4.6 recall event prior node identity differs from the graph.");
  }
  if (priorNode.contentDigest !== record.priorContentDigest) {
    fail("M46_RECALL_EVENT_PRIOR_CONTENT_MISMATCH", "M4.6 recall event prior content differs from the graph.");
  }
  if (record.nextContentDigest === record.priorContentDigest) {
    fail("M46_RECALL_EVENT_NOOP", "M4.6 recall event must change exact content bytes.");
  }
  if (record.nextNodeType !== record.nodeType || nextNodeId !== nodeId) {
    fail("M46_RECALL_EVENT_NEXT_IDENTITY_MISMATCH", "M4.6 recall event cannot substitute the changed node identity.");
  }
  const nextNodeBody = {
    schemaVersion: 1 as const,
    recordType: "M46_DEPENDENCY_NODE" as const,
    nodeType: record.nextNodeType as M46DependencyNodeTypeV1,
    nodeId: nextNodeId,
    contentDigest: record.nextContentDigest,
  };
  if (
    record.nextNodeDigest !==
      m46DependencyDomainDigest(M46_DEPENDENCY_NODE_DIGEST_DOMAIN, nextNodeBody)
  ) {
    fail("M46_RECALL_EVENT_NEXT_NODE_DIGEST_MISMATCH", "M4.6 recall event next-node digest is not exact.");
  }
  const body: Omit<M46DependencyChangeEventFixtureV1, "eventDigest"> = {
    schemaVersion: 1,
    recordType: "M46_DEPENDENCY_CHANGE_EVENT_FIXTURE",
    profile: M46_RECALL_PROFILE,
    eventId,
    graphDigest: record.graphDigest,
    changeType: "CONTENT_CHANGED",
    previousLedgerRevision: record.previousLedgerRevision as number,
    nextLedgerRevision: record.nextLedgerRevision as number,
    nodeType: record.nodeType as M46DependencyNodeTypeV1,
    nodeId,
    priorNodeDigest: record.priorNodeDigest,
    priorContentDigest: record.priorContentDigest,
    nextNodeType: record.nextNodeType as M46DependencyNodeTypeV1,
    nextNodeId,
    nextContentDigest: record.nextContentDigest,
    nextNodeDigest: record.nextNodeDigest,
    externallyObserved: false,
    authenticated: false,
    authorizing: false,
  };
  if (
    record.eventDigest !==
      m46RecallDomainDigest(M46_RECALL_EVENT_DIGEST_DOMAIN, body)
  ) {
    fail("M46_RECALL_EVENT_DIGEST_MISMATCH", "M4.6 recall event digest is not exact.");
  }
  if (expectedEventDigest !== undefined) {
    if (!isSha256Digest(expectedEventDigest) || record.eventDigest !== expectedEventDigest) {
      fail("M46_RECALL_EVENT_EXPECTATION_MISMATCH", "M4.6 recall event differs from its external expectation.");
    }
  }
  return { ...body, eventDigest: record.eventDigest };
}

function assertM46RecallFixtureLane(active = boundedTestLaneActive()): void {
  if (!active) {
    fail("M46_RECALL_FIXTURE_LANE_REQUIRED", "M4.6 scoped recall derivation is available only inside the bounded private test lane.");
  }
}

function m46RecallStateBody(
  state: M46RecallBarrierStateFixtureV1,
): Omit<M46RecallBarrierStateFixtureV1, "stateDigest"> {
  const { stateDigest: _stateDigest, ...body } = state;
  return body;
}

function redigestM46RecallReceipt(receipt: M46RecallReceiptFixtureV1): void {
  const { receiptDigest: _receiptDigest, ...body } = receipt;
  receipt.receiptDigest = m46RecallDomainDigest(M46_RECALL_RECEIPT_DIGEST_DOMAIN, body);
}

function redigestM46RecallEvent(event: M46DependencyChangeEventFixtureV1): void {
  const { eventDigest: _eventDigest, ...body } = event;
  event.eventDigest = m46RecallDomainDigest(M46_RECALL_EVENT_DIGEST_DOMAIN, body);
}

function redigestM46RecallState(state: M46RecallBarrierStateFixtureV1): void {
  state.stateDigest = m46RecallDomainDigest(
    M46_RECALL_STATE_DIGEST_DOMAIN,
    m46RecallStateBody(state),
  );
}

function redigestM46RecallResult(result: M46RecallTransitionResultFixtureV1): void {
  const { resultDigest: _resultDigest, ...body } = result;
  result.resultDigest = m46RecallDomainDigest(M46_RECALL_RESULT_DIGEST_DOMAIN, body);
}

function classifyM46RecallEventReplay(
  state: M46RecallBarrierStateFixtureV1,
  event: M46DependencyChangeEventFixtureV1,
): "NEW_EVENT" | "IDEMPOTENT_DUPLICATE_NO_CHANGE" {
  if (state.lastEventId === event.eventId) {
    if (
      state.lastEventDigest === event.eventDigest &&
      state.ledgerRevision === event.nextLedgerRevision
    ) {
      return "IDEMPOTENT_DUPLICATE_NO_CHANGE";
    }
    fail("M46_RECALL_EVENT_ID_REUSE_DIVERGENT", "M4.6 recall event ID was reused with divergent bytes or sequence.");
  }
  if (event.previousLedgerRevision < state.ledgerRevision) {
    fail("M46_RECALL_EVENT_SEQUENCE_ROLLBACK", "M4.6 recall event sequence would roll back the ledger.");
  }
  if (event.previousLedgerRevision > state.ledgerRevision) {
    fail("M46_RECALL_EVENT_SEQUENCE_GAP", "M4.6 recall event sequence skips the current ledger revision.");
  }
  if (
    event.nextLedgerRevision <= event.previousLedgerRevision ||
    event.previousLedgerRevision === Number.MAX_SAFE_INTEGER
  ) {
    fail("M46_RECALL_EVENT_SEQUENCE_ROLLBACK", "M4.6 recall event sequence must advance without overflow.");
  }
  if (event.nextLedgerRevision !== event.previousLedgerRevision + 1) {
    fail("M46_RECALL_EVENT_SEQUENCE_GAP", "M4.6 recall event sequence must advance by exactly one.");
  }
  return "NEW_EVENT";
}

function evaluateM46RecallFixtureAdmission(
  receipt: M46RecallReceiptFixtureV1,
  state: M46RecallBarrierStateFixtureV1,
): M46RecallAdmissionDispositionV1 {
  const scope = state.scopeBarriers.find(
    (barrier) => barrier.scopeDigest === receipt.scopeDigest,
  );
  if (scope === undefined) {
    fail("M46_RECALL_SCOPE_BARRIER_SET_INVALID", "M4.6 recall admission cannot find the receipt scope barrier.");
  }
  if (
    receipt.boundLedgerRevision > state.ledgerRevision ||
    receipt.boundBarrierRevision > scope.barrierRevision
  ) {
    fail("M46_RECALL_RECEIPT_FUTURE_BOUND", "M4.6 recall receipt claims a future ledger or barrier.");
  }
  if (receipt.boundBarrierRevision < scope.barrierRevision) {
    return "REFUSED_RECALL_REQUIRED";
  }
  if (state.lastEventDigest !== null && scope.lastAffectingEventDigest !== state.lastEventDigest) {
    return "MEASURED_UNAFFECTED_NONAUTHORIZING";
  }
  return "MEASURED_CURRENT_NONAUTHORIZING";
}

function validateM46RecallTransitionResultFixture(
  value: unknown,
  beforeState: M46RecallBarrierStateFixtureV1,
  barrierState: M46RecallBarrierStateFixtureV1,
  afterState: M46RecallBarrierStateFixtureV1,
  receipts: ReadonlyArray<M46RecallReceiptFixtureV1>,
  event: M46DependencyChangeEventFixtureV1,
  expectedResultDigest: string,
): M46RecallTransitionResultFixtureV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "status", "profile", "graphDigest",
      "beforeStateDigest", "barrierStateDigest", "afterStateDigest",
      "receiptSetDigest", "eventDigest", "affectedReceiptIds",
      "unaffectedReceiptIds", "admissions", "trace", "authorizing", "mayConsume",
      "mayRecall", "actualRecallPerformed", "receiptConsumed", "mayCreateDecision",
      "mayPromote", "mayReplay", "mayInstall", "mayExecute", "filesystemMutated",
      "networkRequested", "subprocessStarted", "dynamicLoadAttempted", "coordinatorMutated",
      "resultDigest",
    ],
    "M46_RECALL_RESULT_INVALID",
    "M4.6 recall transition result fixture",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "M46_RECALL_TRANSITION_RESULT_FIXTURE" ||
    record.status !== "DERIVED_INERT" ||
    record.profile !== M46_RECALL_PROFILE ||
    record.graphDigest !== beforeState.graphDigest ||
    record.beforeStateDigest !== beforeState.stateDigest ||
    record.barrierStateDigest !== barrierState.stateDigest ||
    record.afterStateDigest !== afterState.stateDigest ||
    !isSha256Digest(record.receiptSetDigest) ||
    record.eventDigest !== event.eventDigest ||
    !Array.isArray(record.affectedReceiptIds) ||
    !Array.isArray(record.unaffectedReceiptIds) ||
    !Array.isArray(record.admissions) ||
    !Array.isArray(record.trace) ||
    record.authorizing !== false ||
    record.mayConsume !== false ||
    record.mayRecall !== false ||
    record.actualRecallPerformed !== false ||
    record.receiptConsumed !== false ||
    record.mayCreateDecision !== false ||
    record.mayPromote !== false ||
    record.mayReplay !== false ||
    record.mayInstall !== false ||
    record.mayExecute !== false ||
    record.filesystemMutated !== false ||
    record.networkRequested !== false ||
    record.subprocessStarted !== false ||
    record.dynamicLoadAttempted !== false ||
    record.coordinatorMutated !== false ||
    !isSha256Digest(record.resultDigest)
  ) {
    fail("M46_RECALL_RESULT_INVALID", "M4.6 recall result identity or zero-authority fields are invalid.");
  }
  if (
    record.affectedReceiptIds.length === 0 ||
    record.unaffectedReceiptIds.length === 0 ||
    record.affectedReceiptIds.length > receipts.length ||
    record.unaffectedReceiptIds.length > receipts.length ||
    record.affectedReceiptIds.length + record.unaffectedReceiptIds.length !== receipts.length
  ) {
    fail("M46_RECALL_RESULT_SCOPE_PARTITION_INVALID", "M4.6 recall result partitions exceed or differ from the bounded receipt set.");
  }
  if (record.admissions.length !== receipts.length) {
    fail("M46_RECALL_ADMISSION_INVALID", "M4.6 recall admission count must equal the bounded receipt set before parsing.");
  }
  if (record.trace.length !== 5) {
    fail("M46_RECALL_RESULT_TRACE_INVALID", "M4.6 recall trace length differs from the frozen bounded ordering.");
  }
  if (record.receiptSetDigest !== m46RecallReceiptSetDigest(receipts)) {
    fail("M46_RECALL_RESULT_RECEIPT_SET_MISMATCH", "M4.6 recall result receipt-set digest differs from the exact receipt argument.");
  }
  if (
    barrierState.ledgerRevision !== beforeState.ledgerRevision + 1 ||
    afterState.ledgerRevision !== barrierState.ledgerRevision ||
    barrierState.pendingEventDigest !== event.eventDigest ||
    afterState.pendingEventDigest !== null ||
    barrierState.lastEventId !== event.eventId ||
    afterState.lastEventId !== event.eventId ||
    barrierState.lastEventDigest !== event.eventDigest ||
    afterState.lastEventDigest !== event.eventDigest
  ) {
    fail("M46_RECALL_RESULT_SEQUENCE_INVALID", "M4.6 recall result state sequence is invalid.");
  }
  const affected = receipts.filter((receipt) =>
    receipt.dependencyNodeDigests.includes(event.priorNodeDigest));
  const unaffected = receipts.filter((receipt) =>
    !receipt.dependencyNodeDigests.includes(event.priorNodeDigest));
  if (affected.length === 0 || unaffected.length === 0) {
    fail("M46_RECALL_RESULT_SCOPE_PARTITION_INVALID", "M4.6 recall fixture requires nonempty affected and unrelated complements.");
  }
  const affectedReceiptIds = (record.affectedReceiptIds as unknown[]).map((id) =>
    m46RecallId(id, "receipt"));
  const unaffectedReceiptIds = (record.unaffectedReceiptIds as unknown[]).map((id) =>
    m46RecallId(id, "receipt"));
  const expectedAffected = affected.map((receipt) => receipt.receiptId).sort(codePointCompare);
  const expectedUnaffected = unaffected.map((receipt) => receipt.receiptId).sort(codePointCompare);
  if (
    canonicalJson(affectedReceiptIds) !== canonicalJson(expectedAffected) ||
    canonicalJson(unaffectedReceiptIds) !== canonicalJson(expectedUnaffected) ||
    new Set([...affectedReceiptIds, ...unaffectedReceiptIds]).size !== receipts.length
  ) {
    fail("M46_RECALL_RESULT_SCOPE_PARTITION_INVALID", "M4.6 recall result affected and unrelated complements are not exact.");
  }
  const beforeBarriers = new Map(beforeState.scopeBarriers.map((barrier) => [barrier.scopeDigest, barrier]));
  const barrierBarriers = new Map(barrierState.scopeBarriers.map((barrier) => [barrier.scopeDigest, barrier]));
  const afterBarriers = new Map(afterState.scopeBarriers.map((barrier) => [barrier.scopeDigest, barrier]));
  for (const receipt of receipts) {
    const before = beforeBarriers.get(receipt.scopeDigest);
    const barrier = barrierBarriers.get(receipt.scopeDigest);
    const after = afterBarriers.get(receipt.scopeDigest);
    assert(before !== undefined && barrier !== undefined && after !== undefined);
    if (affectedReceiptIds.includes(receipt.receiptId)) {
      if (
        before.barrierRevision === Number.MAX_SAFE_INTEGER ||
        barrier.barrierRevision !== before.barrierRevision + 1 ||
        after.barrierRevision !== barrier.barrierRevision ||
        barrier.lastAffectingEventDigest !== event.eventDigest ||
        after.lastAffectingEventDigest !== event.eventDigest
      ) {
        fail("M46_RECALL_AFFECTED_BARRIER_INVALID", "M4.6 affecting scope barrier did not advance exactly once.");
      }
    } else if (canonicalJson(barrier) !== canonicalJson(before) || canonicalJson(after) !== canonicalJson(before)) {
      fail("M46_RECALL_UNRELATED_BARRIER_CHANGED", "M4.6 unrelated scope barrier changed.");
    }
  }
  const admissions = (record.admissions as unknown[]).map((value) => {
    const admission = requireExactObjectKeys(
      value,
      ["receiptId", "evaluatedStateDigest", "disposition"],
      "M46_RECALL_ADMISSION_INVALID",
      "M4.6 recall admission result",
    );
    const receiptId = m46RecallId(admission.receiptId, "receipt");
    const receipt = receipts.find((entry) => entry.receiptId === receiptId);
    if (
      receipt === undefined ||
      admission.evaluatedStateDigest !== afterState.stateDigest ||
      admission.disposition !== evaluateM46RecallFixtureAdmission(receipt, afterState)
    ) {
      fail("M46_RECALL_ADMISSION_INVALID", "M4.6 recall admission is not bound to the exact after-state disposition.");
    }
    return {
      receiptId,
      evaluatedStateDigest: admission.evaluatedStateDigest,
      disposition: admission.disposition as M46RecallAdmissionDispositionV1,
    };
  });
  if (
    admissions.length !== receipts.length ||
    new Set(admissions.map((admission) => admission.receiptId)).size !== admissions.length ||
    canonicalJson(admissions.map((admission) => admission.receiptId)) !==
      canonicalJson(receipts.map((receipt) => receipt.receiptId))
  ) {
    fail("M46_RECALL_ADMISSION_INVALID", "M4.6 recall admissions must cover every receipt exactly once in canonical order.");
  }
  const trace = [
    "VALIDATE_PRIOR",
    "VALIDATE_EVENT",
    "ADVANCE_AFFECTED_BARRIER",
    "EVALUATE_AFTER_STATE",
    "RETURN_INERT",
  ] as const;
  if (canonicalJson(record.trace) !== canonicalJson(trace)) {
    fail("M46_RECALL_RESULT_TRACE_INVALID", "M4.6 recall result trace differs from the frozen ordering.");
  }
  const body: Omit<M46RecallTransitionResultFixtureV1, "resultDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_TRANSITION_RESULT_FIXTURE",
    status: "DERIVED_INERT",
    profile: M46_RECALL_PROFILE,
    graphDigest: record.graphDigest,
    beforeStateDigest: record.beforeStateDigest,
    barrierStateDigest: record.barrierStateDigest,
    afterStateDigest: record.afterStateDigest,
    receiptSetDigest: record.receiptSetDigest,
    eventDigest: record.eventDigest,
    affectedReceiptIds,
    unaffectedReceiptIds,
    admissions,
    trace: [...trace],
    authorizing: false,
    mayConsume: false,
    mayRecall: false,
    actualRecallPerformed: false,
    receiptConsumed: false,
    mayCreateDecision: false,
    mayPromote: false,
    mayReplay: false,
    mayInstall: false,
    mayExecute: false,
    filesystemMutated: false,
    networkRequested: false,
    subprocessStarted: false,
    dynamicLoadAttempted: false,
    coordinatorMutated: false,
  };
  const computed = m46RecallDomainDigest(M46_RECALL_RESULT_DIGEST_DOMAIN, body);
  if (record.resultDigest !== computed) {
    fail("M46_RECALL_RESULT_DIGEST_MISMATCH", "M4.6 recall transition result digest is not exact.");
  }
  if (!isSha256Digest(expectedResultDigest) || record.resultDigest !== expectedResultDigest) {
    fail("M46_RECALL_RESULT_EXPECTATION_MISMATCH", "M4.6 recall transition result differs from its external expectation.");
  }
  return { ...body, resultDigest: record.resultDigest };
}

function createM46RecallFixtureInputs(): M46RecallFixtureInputsV1 {
  const graph = createM46MinimumDependencyClosureGraph();
  const policy = graph.nodes.find((node) => node.nodeType === "POLICY");
  const adapter = graph.nodes.find((node) => node.nodeType === "ADAPTER");
  assert(policy !== undefined && adapter !== undefined);
  const receipts = [
    createM46RecallReceiptFixture(graph, "receipt/affected", [policy.nodeDigest], 2),
    createM46RecallReceiptFixture(graph, "receipt/unrelated", [adapter.nodeDigest], 4),
  ].sort(compareM46RecallReceipts);
  const beforeState = createM46RecallBarrierStateFixture(graph, receipts);
  const event = createM46DependencyChangeEventFixture(graph);
  return {
    graph,
    receipts,
    beforeState,
    event,
    expectations: {
      expectedSubjectDigest: M46_MINIMUM_FIXTURE_SUBJECT_DIGEST,
      expectedGraphDigest: M46_MINIMUM_FIXTURE_GRAPH_DIGEST,
      expectedBeforeStateDigest: M46_RECALL_EXPECTED_BEFORE_STATE_DIGEST,
      expectedReceiptSetDigest: M46_RECALL_EXPECTED_RECEIPT_SET_DIGEST,
      expectedEventDigest: M46_RECALL_EXPECTED_EVENT_DIGEST,
      expectedBarrierStateDigest: M46_RECALL_EXPECTED_BARRIER_STATE_DIGEST,
      expectedAfterStateDigest: M46_RECALL_EXPECTED_AFTER_STATE_DIGEST,
      expectedResultDigest: M46_RECALL_EXPECTED_RESULT_DIGEST,
    },
  };
}

function deriveM46RecallTransitionFixture(
  inputs: M46RecallFixtureInputsV1,
  laneActive = boundedTestLaneActive(),
): {
  barrierState: M46RecallBarrierStateFixtureV1;
  afterState: M46RecallBarrierStateFixtureV1;
  result: M46RecallTransitionResultFixtureV1;
} {
  assertM46RecallFixtureLane(laneActive);
  for (const digest of Object.values(inputs.expectations)) {
    if (!isSha256Digest(digest)) {
      fail("M46_RECALL_EXPECTATION_INVALID", "M4.6 scoped recall requires source-external exact digests.");
    }
  }
  const graph = validateM46DependencyClosureGraph(inputs.graph, {
    expectedSubjectDigest: inputs.expectations.expectedSubjectDigest,
    expectedGraphDigest: inputs.expectations.expectedGraphDigest,
  });
  const receipts = validateM46RecallReceiptSet(
    inputs.receipts,
    graph,
    inputs.expectations.expectedReceiptSetDigest,
  );
  const beforeState = validateM46RecallBarrierStateFixture(
    inputs.beforeState,
    graph,
    receipts,
    inputs.expectations.expectedBeforeStateDigest,
  );
  const event = validateM46DependencyChangeEventFixture(
    inputs.event,
    graph,
    inputs.expectations.expectedEventDigest,
  );
  if (classifyM46RecallEventReplay(beforeState, event) !== "NEW_EVENT") {
    fail("M46_RECALL_EVENT_DUPLICATE_STATE_INVALID", "M4.6 recall transition requires a new event.");
  }
  const affectedReceipts = receipts.filter((receipt) =>
    receipt.dependencyNodeDigests.includes(event.priorNodeDigest));
  const unaffectedReceipts = receipts.filter((receipt) =>
    !receipt.dependencyNodeDigests.includes(event.priorNodeDigest));
  if (affectedReceipts.length === 0 || unaffectedReceipts.length === 0) {
    fail("M46_RECALL_RESULT_SCOPE_PARTITION_INVALID", "M4.6 recall fixture requires affected and unrelated receipt scopes.");
  }
  for (const receipt of receipts) {
    const barrier = beforeState.scopeBarriers.find(
      (entry) => entry.scopeDigest === receipt.scopeDigest,
    );
    assert(barrier !== undefined);
    if (
      receipt.boundLedgerRevision > beforeState.ledgerRevision ||
      receipt.boundBarrierRevision > barrier.barrierRevision
    ) {
      fail("M46_RECALL_RECEIPT_FUTURE_BOUND", "M4.6 recall receipt claims a future pre-event state.");
    }
    if (
      receipt.boundLedgerRevision !== beforeState.ledgerRevision ||
      receipt.boundBarrierRevision !== barrier.barrierRevision ||
      evaluateM46RecallFixtureAdmission(receipt, beforeState) !==
        "MEASURED_CURRENT_NONAUTHORIZING"
    ) {
      fail("M46_RECALL_RECEIPT_PRESTATE_NOT_CURRENT", "M4.6 recall positive fixture requires exact pre-event receipt bindings.");
    }
  }
  const barrierState = structuredClone(beforeState) as M46RecallBarrierStateFixtureV1;
  barrierState.ledgerRevision = event.nextLedgerRevision;
  barrierState.pendingEventDigest = event.eventDigest;
  barrierState.lastEventId = event.eventId;
  barrierState.lastEventDigest = event.eventDigest;
  for (const receipt of affectedReceipts) {
    const barrier = barrierState.scopeBarriers.find(
      (entry) => entry.scopeDigest === receipt.scopeDigest,
    );
    assert(barrier !== undefined);
    if (barrier.barrierRevision === Number.MAX_SAFE_INTEGER) {
      fail("M46_RECALL_BARRIER_OVERFLOW", "M4.6 recall barrier cannot advance without exact monotonic space.");
    }
    barrier.barrierRevision += 1;
    barrier.lastAffectingEventDigest = event.eventDigest;
  }
  redigestM46RecallState(barrierState);
  validateM46RecallBarrierStateFixture(
    barrierState,
    graph,
    receipts,
    inputs.expectations.expectedBarrierStateDigest,
  );
  for (const receipt of affectedReceipts) {
    if (evaluateM46RecallFixtureAdmission(receipt, barrierState) !== "REFUSED_RECALL_REQUIRED") {
      fail("M46_RECALL_BARRIER_ADMISSION_INVALID", "M4.6 recall barrier failed to withhold an affected receipt before completion.");
    }
  }
  const afterState = structuredClone(barrierState) as M46RecallBarrierStateFixtureV1;
  afterState.pendingEventDigest = null;
  redigestM46RecallState(afterState);
  validateM46RecallBarrierStateFixture(
    afterState,
    graph,
    receipts,
    inputs.expectations.expectedAfterStateDigest,
  );
  const admissions = receipts.map((receipt) => ({
    receiptId: receipt.receiptId,
    evaluatedStateDigest: afterState.stateDigest,
    disposition: evaluateM46RecallFixtureAdmission(receipt, afterState),
  }));
  const body: Omit<M46RecallTransitionResultFixtureV1, "resultDigest"> = {
    schemaVersion: 1,
    recordType: "M46_RECALL_TRANSITION_RESULT_FIXTURE",
    status: "DERIVED_INERT",
    profile: M46_RECALL_PROFILE,
    graphDigest: graph.graphDigest,
    beforeStateDigest: beforeState.stateDigest,
    barrierStateDigest: barrierState.stateDigest,
    afterStateDigest: afterState.stateDigest,
    receiptSetDigest: m46RecallReceiptSetDigest(receipts),
    eventDigest: event.eventDigest,
    affectedReceiptIds: affectedReceipts.map((receipt) => receipt.receiptId).sort(codePointCompare),
    unaffectedReceiptIds: unaffectedReceipts.map((receipt) => receipt.receiptId).sort(codePointCompare),
    admissions,
    trace: [
      "VALIDATE_PRIOR",
      "VALIDATE_EVENT",
      "ADVANCE_AFFECTED_BARRIER",
      "EVALUATE_AFTER_STATE",
      "RETURN_INERT",
    ],
    authorizing: false,
    mayConsume: false,
    mayRecall: false,
    actualRecallPerformed: false,
    receiptConsumed: false,
    mayCreateDecision: false,
    mayPromote: false,
    mayReplay: false,
    mayInstall: false,
    mayExecute: false,
    filesystemMutated: false,
    networkRequested: false,
    subprocessStarted: false,
    dynamicLoadAttempted: false,
    coordinatorMutated: false,
  };
  const result: M46RecallTransitionResultFixtureV1 = {
    ...body,
    resultDigest: m46RecallDomainDigest(M46_RECALL_RESULT_DIGEST_DOMAIN, body),
  };
  return {
    barrierState,
    afterState,
    result: validateM46RecallTransitionResultFixture(
      result,
      beforeState,
      barrierState,
      afterState,
      receipts,
      event,
      inputs.expectations.expectedResultDigest,
    ),
  };
}
// M46_INERT_SCOPED_RECALL_END

// M47_INERT_FROZEN_SET_ORACLE_BEGIN
const M47_ORACLE_RECORD_KINDS = Object.freeze([
  "SUBJECT",
  "TRANSFORMATION",
  "EVIDENCE",
  "VERIFIER",
  "POLICY",
  "AUTHORITY_REFERENCE",
  "APPROVAL",
  "DECISION",
  "RECEIPT",
  "DESTINATION",
  "DEPENDENCY_CONTINUITY",
  "CROSS_INVARIANT_REGRESSION_CANARY",
] as const);

type M47OracleRecordKindV1 = (typeof M47_ORACLE_RECORD_KINDS)[number];
type M47ChangeVectorKindV1 = "KNOWN_CHANGE" | "UNRESOLVED_DEPENDENCY";
type M47ReasonKindV1 = "DIRECT_GRAPH_INTERSECTION" | "UNRESOLVED_DEPENDENCY_FALLBACK";
type M47PlanModeV1 = "FROZEN_SET_FALLBACK";

const M47_CHANGE_VECTOR_KINDS = Object.freeze([
  "KNOWN_CHANGE",
  "UNRESOLVED_DEPENDENCY",
] as const satisfies readonly M47ChangeVectorKindV1[]);

const M47_REASON_KINDS = Object.freeze([
  "DIRECT_GRAPH_INTERSECTION",
  "UNRESOLVED_DEPENDENCY_FALLBACK",
] as const satisfies readonly M47ReasonKindV1[]);

const M47_RESULT_TRACE = Object.freeze([
  "VALIDATE_FROZEN_ORACLE",
  "VALIDATE_REGISTERED_CHECKS",
  "VALIDATE_PRE_PLANNER_FREEZE",
  "VALIDATE_CHANGE_VECTORS",
  "DERIVE_FROZEN_SET_PLANS",
  "COMPARE_ORACLE_AND_PLANS",
  "RETURN_INERT",
] as const);

type M47OracleRecordFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_ORACLE_RECORD_FIXTURE";
  profile: typeof M47_ORACLE_PROFILE;
  recordId: string;
  kind: M47OracleRecordKindV1;
  checkId: string;
  graphDigest: string;
  dependencyNodeDigests: string[];
  authorizing: false;
  recordDigest: string;
};

type M47OracleUniverseFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_ORACLE_UNIVERSE_FIXTURE";
  status: "FROZEN_INERT";
  profile: typeof M47_ORACLE_PROFILE;
  graphDigest: string;
  records: M47OracleRecordFixtureV1[];
  recordCount: number;
  authorizing: false;
  universeDigest: string;
};

type M47RegisteredCheckFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_REGISTERED_CHECK_FIXTURE";
  profile: typeof M47_ORACLE_PROFILE;
  checkId: string;
  graphDigest: string;
  dependencyNodeDigests: string[];
  authorizing: false;
  mayExecute: false;
  checkDigest: string;
};

type M47RegisteredCheckSetFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_REGISTERED_CHECK_SET_FIXTURE";
  profile: typeof M47_ORACLE_PROFILE;
  graphDigest: string;
  checks: M47RegisteredCheckFixtureV1[];
  checkCount: number;
  authorizing: false;
  checkSetDigest: string;
};

type M47PrePlannerFreezeFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_PRE_PLANNER_FREEZE_FIXTURE";
  status: "FROZEN_BEFORE_PLANNER";
  profile: typeof M47_ORACLE_PROFILE;
  graphDigest: string;
  universeDigest: string;
  canonicalOracleByteLength: number;
  canonicalOracleDigest: string;
  oracleVersion: 1;
  owner: string;
  frozenAt: string;
  plannerSourceDigest: null;
  authorizing: false;
  freezeDigest: string;
};

type M47UnresolvedDependencyRefFixtureV1 = {
  refId: string;
  candidateNodeDigests: string[];
};

type M47ChangeVectorFixtureV1 = {
  schemaVersion: 1;
  recordType: "M47_CHANGE_VECTOR_FIXTURE";
  profile: typeof M47_ORACLE_PROFILE;
  vectorId: string;
  vectorKind: M47ChangeVectorKindV1;
  graphDigest: string;
  changedNodeDigests: string[];
  unresolvedDependencyRefs: M47UnresolvedDependencyRefFixtureV1[];
  externallyObserved: false;
  authorizing: false;
  changeDigest: string;
};

