  profile: typeof M47_ORACLE_PROFILE;
  graphDigest: string;
  universeDigest: string;
  checkSetDigest: string;
  freezeDigest: string;
  mode: M47PlanModeV1;
  includedCheckIds: string[];
  knownChange: M47OracleArmAgreementFixtureV1;
  unresolvedDependency: M47OracleArmAgreementFixtureV1;
  trace: [
    "VALIDATE_FROZEN_ORACLE",
    "VALIDATE_REGISTERED_CHECKS",
    "VALIDATE_PRE_PLANNER_FREEZE",
    "VALIDATE_CHANGE_VECTORS",
    "DERIVE_FROZEN_SET_PLANS",
    "COMPARE_ORACLE_AND_PLANS",
    "RETURN_INERT",
  ];
  authorizing: false;
  protectedAuthorityVerified: false;
  generatedArtifactExecuted: false;
  runtimeDependencyObserved: false;
  realEventObserved: false;
  mayRecall: false;
  mayReplay: false;
  mayExecute: false;
  mayPromote: false;
  mayInstall: false;
  filesystemMutated: false;
  networkRequested: false;
  subprocessStarted: false;
  dynamicLoadAttempted: false;
  coordinatorMutated: false;
  officialE15Credit: false;
  officialE16Credit: false;
  m4Credit: false;
