function classifyFi0ObservationReplay(
  existing: FailureIncidentV1,
  observed: FailureIncidentV1,
): "IDEMPOTENT_DUPLICATE_NO_COUNT_CHANGE" | "NEW_OBSERVATION" {
  if (existing.observationKey !== observed.observationKey) return "NEW_OBSERVATION";
  if (existing.incidentDigest !== observed.incidentDigest) {
    fail("FI0_OBSERVATION_KEY_CONFLICT", "FI-0 observation identity was reused for divergent incident bytes.");
  }
  if (existing.occurrenceCount !== 1 || observed.occurrenceCount !== 1) {
    fail("FI0_OBSERVATION_COUNT_INVALID", "FI-0 fixture duplicates may not inflate occurrence counts.");
  }
  return "IDEMPOTENT_DUPLICATE_NO_COUNT_CHANGE";
}

function createFi0IncidentEventFixtures(
  incident: FailureIncidentV1,
  externalGenesisDigest: string,
): Fi0IncidentEventV1[] {
  const actorPrincipalDigest = fi0ContextDigest("SELF_ADMIN_PRINCIPAL", {
    principalId: "fixture-owner",
  });
  const actorSessionDigest = fi0ContextDigest("SELF_ADMIN_SESSION", {
    sessionId: "fixture-session-001",
  });
  const reasons: Fi0IncidentEventV1["reasonCode"][] = [
    "INSUFFICIENT_INDEPENDENT_AUTHORITY",
    "EVIDENCE_COMPLETENESS_FIXTURE_ONLY",
    "NO_PROTECTED_ADJUDICATION_STATE",
  ];
  const events: Fi0IncidentEventV1[] = [];
  for (let index = 0; index < reasons.length; index += 1) {
    const ordinal = index + 1;
    const body: Omit<Fi0IncidentEventV1, "eventDigest"> = {
      schemaVersion: 1,
      recordType: "FI0_INCIDENT_ADJUDICATION_EVENT",
      profile: FI0_INCIDENT_PROFILE,
      eventId: `event/fi0-teaching-${String(ordinal).padStart(3, "0")}`,
      incidentId: incident.incidentId,
      incidentDigest: incident.incidentDigest,
      ordinal,
      predecessorDigest: index === 0 ? externalGenesisDigest : events[index - 1].eventDigest,
      sourceStreamId: incident.sourceStreamId,
      sourceStreamHeadDigest: incident.sourceStreamHeadDigest,
      actorPrincipalDigest,
      actorSessionDigest,
      actorRole: "SELF_ADMIN_FIXTURE",
      decision: "MARK_INCONCLUSIVE",
      priorState: index === 0 ? "CANDIDATE" : "INCONCLUSIVE",
      nextState: "INCONCLUSIVE",
      reasonCode: reasons[index],
      protectedAuthorityVerified: false,
      authorizing: false,
    };
    events.push({
      ...body,
      eventDigest: fi0DomainDigest(FI0_EVENT_DIGEST_DOMAIN, body),
    });
  }
  return events;
}

function validateFi0IncidentEvent(
  value: unknown,
  incident: FailureIncidentV1,
): Fi0IncidentEventV1 {
  assertFi0NoProhibitedRawLocatorOrCredentialText(value, "FI-0 incident event");
  if (
    value !== null &&
    typeof value === "object" &&
    !Array.isArray(value) &&
    Object.hasOwn(value, "checkpointDigest")
  ) {
    fail("FI0_EVENT_CHECKPOINT_FORBIDDEN", "FI-0 fixture has no protected checkpoint authority.");
  }
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "profile", "eventId", "incidentId",
      "incidentDigest", "ordinal", "predecessorDigest", "sourceStreamId",
      "sourceStreamHeadDigest", "actorPrincipalDigest", "actorSessionDigest",
      "actorRole", "decision", "priorState", "nextState", "reasonCode",
      "protectedAuthorityVerified", "authorizing", "eventDigest",
    ],
    "FI0_EVENT_INVALID",
    "FI-0 incident event",
  );
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "FI0_INCIDENT_ADJUDICATION_EVENT" ||
    record.profile !== FI0_INCIDENT_PROFILE ||
    !Number.isSafeInteger(record.ordinal) ||
    (record.ordinal as number) < 1 ||
    !isSha256Digest(record.predecessorDigest) ||
    record.sourceStreamId !== incident.sourceStreamId ||
    record.sourceStreamHeadDigest !== incident.sourceStreamHeadDigest ||
    !isSha256Digest(record.actorPrincipalDigest) ||
    !isSha256Digest(record.actorSessionDigest) ||
    record.actorRole !== "SELF_ADMIN_FIXTURE" ||
    !["CANDIDATE", "INCONCLUSIVE"].includes(record.priorState as string) ||
    !isSha256Digest(record.eventDigest)
  ) {
    fail("FI0_EVENT_INVALID", "FI-0 event identity, lineage, or actor fields are invalid.");
  }
  if (
    record.incidentId !== incident.incidentId ||
    record.incidentDigest !== incident.incidentDigest
  ) {
    fail("FI0_EVENT_INCIDENT_BINDING_MISMATCH", "FI-0 event names a different incident identity or digest.");
  }
  if (
    record.decision !== "MARK_INCONCLUSIVE" ||
    record.nextState !== "INCONCLUSIVE" ||
    record.protectedAuthorityVerified !== false ||
    record.authorizing !== false
  ) {
    fail("FI0_EVENT_TRANSITION_UNAUTHORIZED", "Self-administered FI-0 events may only preserve an inconclusive state.");
  }
  const reasonCode = fi0Code(record.reasonCode, "event reason") as Fi0IncidentEventV1["reasonCode"];
  if (![
    "INSUFFICIENT_INDEPENDENT_AUTHORITY",
    "EVIDENCE_COMPLETENESS_FIXTURE_ONLY",
    "NO_PROTECTED_ADJUDICATION_STATE",
  ].includes(reasonCode)) {
    fail("FI0_EVENT_INVALID", "FI-0 event reason is outside the frozen fixture vocabulary.");
  }
  const body: Omit<Fi0IncidentEventV1, "eventDigest"> = {
    schemaVersion: 1,
    recordType: "FI0_INCIDENT_ADJUDICATION_EVENT",
    profile: FI0_INCIDENT_PROFILE,
    eventId: fi0Identifier(record.eventId, "event ID"),
    incidentId: fi0Identifier(record.incidentId, "incident ID"),
    incidentDigest: record.incidentDigest,
    ordinal: record.ordinal as number,
    predecessorDigest: record.predecessorDigest,
    sourceStreamId: fi0Identifier(record.sourceStreamId, "source stream ID"),
    sourceStreamHeadDigest: record.sourceStreamHeadDigest,
    actorPrincipalDigest: record.actorPrincipalDigest,
    actorSessionDigest: record.actorSessionDigest,
    actorRole: "SELF_ADMIN_FIXTURE",
    decision: "MARK_INCONCLUSIVE",
    priorState: record.priorState as Fi0AdjudicationStateV1,
    nextState: "INCONCLUSIVE",
    reasonCode,
    protectedAuthorityVerified: false,
    authorizing: false,
  };
  if (record.eventDigest !== fi0DomainDigest(FI0_EVENT_DIGEST_DOMAIN, body)) {
    fail("FI0_EVENT_DIGEST_MISMATCH", "FI-0 incident event digest is not exact.");
  }
  return { ...body, eventDigest: record.eventDigest };
}

function fi0EventChainHeadDigest(
  incident: FailureIncidentV1,
  externalGenesisDigest: string,
  events: ReadonlyArray<Fi0IncidentEventV1>,
): string {
  return fi0DomainDigest(FI0_CHAIN_HEAD_DIGEST_DOMAIN, {
    schemaVersion: 1,
    recordType: "FI0_EVENT_CHAIN_HEAD",
    profile: FI0_INCIDENT_PROFILE,
    incidentDigest: incident.incidentDigest,
    externalGenesisDigest,
    sourceStreamHeadDigest: incident.sourceStreamHeadDigest,
    orderedEventDigests: events.map((event) => event.eventDigest),
    finalOrdinal: events.at(-1)?.ordinal ?? 0,
  });
}

function validateFi0IncidentEventChain(
  values: unknown,
  incident: FailureIncidentV1,
  expectedExternalGenesisDigest: string,
  expectedEventChainHeadDigest: string,
): { events: Fi0IncidentEventV1[]; eventChainHeadDigest: string } {
  if (
    !Array.isArray(values) ||
    values.length < FI0_LIMITS.minEventCount ||
    values.length > FI0_LIMITS.maxEventCount
  ) {
    fail("FI0_EVENT_COUNT_INVALID", "FI-0 fixture requires the frozen bounded minimum event chain.");
  }
  if (!isSha256Digest(expectedExternalGenesisDigest) || !isSha256Digest(expectedEventChainHeadDigest)) {
    fail("FI0_EVENT_EXPECTATION_INVALID", "FI-0 event-chain expectations must equal the source-frozen self-administered digests.");
  }
  const events = values.map((value) => validateFi0IncidentEvent(value, incident));
  if (
    new Set(events.map((event) => event.eventId)).size !== events.length ||
    new Set(events.map((event) => event.eventDigest)).size !== events.length
  ) {
    fail("FI0_EVENT_DUPLICATE", "FI-0 incident event IDs and digests must be unique.");
  }
  if (
    canonicalJson(events.map((event) => event.ordinal)) !==
      canonicalJson([...events].sort((left, right) => left.ordinal - right.ordinal).map((event) => event.ordinal))
  ) {
    fail("FI0_EVENT_ORDER_INVALID", "FI-0 incident events must be supplied in ordinal order.");
  }
  const predecessorUse = new Set<string>();
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index];
    if (event.ordinal !== index + 1) {
      fail("FI0_EVENT_ORDINAL_GAP", "FI-0 incident event ordinals must be contiguous from one.");
    }
    if (predecessorUse.has(event.predecessorDigest)) {
      fail("FI0_EVENT_FORK_REFUSED", "FI-0 fixture refuses multiple children for one predecessor.");
    }
    predecessorUse.add(event.predecessorDigest);
    const expectedPredecessor = index === 0
      ? expectedExternalGenesisDigest
      : events[index - 1].eventDigest;
    if (event.predecessorDigest !== expectedPredecessor) {
      fail(
        index === 0 ? "FI0_EXTERNAL_GENESIS_MISMATCH" : "FI0_EVENT_PREDECESSOR_MISMATCH",
        "FI-0 event predecessor does not match the source-frozen self-administered linear chain.",
      );
    }
    const expectedPriorState: Fi0AdjudicationStateV1 = index === 0
      ? "CANDIDATE"
      : "INCONCLUSIVE";
    if (event.priorState !== expectedPriorState || event.nextState !== "INCONCLUSIVE") {
      fail("FI0_EVENT_TRANSITION_UNAUTHORIZED", "FI-0 event state transition is not the frozen self-administered inconclusive path.");
    }
  }
  const eventChainHeadDigest = fi0EventChainHeadDigest(
    incident,
    expectedExternalGenesisDigest,
    events,
  );
  if (eventChainHeadDigest !== expectedEventChainHeadDigest) {
    fail("FI0_EVENT_CHAIN_EXPECTATION_MISMATCH", "FI-0 event chain differs from its source-frozen self-administered expected head.");
  }
  return { events, eventChainHeadDigest };
}

