function validateFi0HistoricalImportEnvelope(
  value: unknown,
  context: Fi0AccessContextV1,
  incident: FailureIncidentV1,
  eventChainHeadDigest: string,
  expectedEnvelopeDigest: string,
): Fi0HistoricalImportEnvelopeV1 {
  assertFi0NoProhibitedRawLocatorOrCredentialText(value, "FI-0 historical import envelope");
  const record = requireExactObjectKeys(
    value,
    [
      "schemaVersion", "recordType", "profile", "envelopeId", "scopeId",
      "projectIdDigest", "batchId", "sourceRecordDigest", "sourceRowOrdinal",
      "parserVersionDigest", "canonicalizerVersionDigest", "provenanceDigest",
      "expectedRecordCount", "incidentDigest", "eventChainHeadDigest", "inert",
      "importPerformed", "historicalFactsVerified", "mayImport", "envelopeDigest",
    ],
    "FI0_IMPORT_ENVELOPE_INVALID",
    "FI-0 historical import envelope",
  );
  if (
    !isSha256Digest(expectedEnvelopeDigest) ||
    record.schemaVersion !== 1 ||
    record.recordType !== "FI0_HISTORICAL_IMPORT_ENVELOPE" ||
    record.profile !== FI0_INCIDENT_PROFILE ||
    record.scopeId !== context.scopeId ||
    record.projectIdDigest !== context.projectIdDigest ||
    !isSha256Digest(record.sourceRecordDigest) ||
    record.sourceRowOrdinal !== 17 ||
    !isSha256Digest(record.parserVersionDigest) ||
    !isSha256Digest(record.canonicalizerVersionDigest) ||
    !isSha256Digest(record.provenanceDigest) ||
    record.expectedRecordCount !== 1 ||
    record.incidentDigest !== incident.incidentDigest ||
    record.eventChainHeadDigest !== eventChainHeadDigest ||
    record.inert !== true ||
    record.importPerformed !== false ||
    record.historicalFactsVerified !== false ||
    record.mayImport !== false ||
    !isSha256Digest(record.envelopeDigest)
  ) {
    fail("FI0_IMPORT_PROVENANCE_INVALID", "FI-0 historical envelope provenance or inert fields are invalid.");
  }
  const provenanceBody = {
    schemaVersion: 1,
    recordType: "FI0_HISTORICAL_PROVENANCE",
    batchId: fi0Identifier(record.batchId, "historical batch ID"),
    sourceRecordDigest: record.sourceRecordDigest,
    sourceRowOrdinal: 17,
    parserVersionDigest: record.parserVersionDigest,
    canonicalizerVersionDigest: record.canonicalizerVersionDigest,
  };
  if (record.provenanceDigest !== fi0DomainDigest(FI0_PROVENANCE_DIGEST_DOMAIN, provenanceBody)) {
    fail("FI0_IMPORT_PROVENANCE_INVALID", "FI-0 historical envelope provenance digest is not exact.");
  }
  const body: Omit<Fi0HistoricalImportEnvelopeV1, "envelopeDigest"> = {
    schemaVersion: 1,
    recordType: "FI0_HISTORICAL_IMPORT_ENVELOPE",
    profile: FI0_INCIDENT_PROFILE,
    envelopeId: fi0Identifier(record.envelopeId, "historical envelope ID"),
    scopeId: context.scopeId,
    projectIdDigest: context.projectIdDigest,
    batchId: provenanceBody.batchId,
    sourceRecordDigest: record.sourceRecordDigest,
    sourceRowOrdinal: 17,
    parserVersionDigest: record.parserVersionDigest,
    canonicalizerVersionDigest: record.canonicalizerVersionDigest,
    provenanceDigest: record.provenanceDigest,
    expectedRecordCount: 1,
    incidentDigest: incident.incidentDigest,
    eventChainHeadDigest,
    inert: true,
    importPerformed: false,
    historicalFactsVerified: false,
    mayImport: false,
  };
  const computed = fi0DomainDigest(FI0_IMPORT_ENVELOPE_DIGEST_DOMAIN, body);
  if (record.envelopeDigest !== computed) {
    fail("FI0_IMPORT_ENVELOPE_DIGEST_MISMATCH", "FI-0 historical envelope digest is not exact.");
  }
  if (record.envelopeDigest !== expectedEnvelopeDigest) {
    fail("FI0_IMPORT_ENVELOPE_EXPECTATION_MISMATCH", "FI-0 historical envelope differs from its source-frozen self-administered expectation.");
  }
  assertFi0NoProhibitedRawLocatorOrCredentialText(body, "FI-0 historical envelope");
  return { ...body, envelopeDigest: record.envelopeDigest };
}

function createFi0BaselineBundleFixture(): Fi0BaselineBundleV1 {
  const artifactBytes = fi0CanonicalRecordBytes({
    schemaVersion: 1,
    recordType: "FI0_BASELINE_ARTIFACT_FIXTURE",
    outputCode: "BASELINE_OUTPUT_UNCHANGED",
  });
  const verdictBytes = fi0CanonicalRecordBytes({
    schemaVersion: 1,
    recordType: "FI0_BASELINE_VERDICT_FIXTURE",
    result: "PASS_BASELINE_FIXTURE_ONLY",
    fi0Used: false,
  });
  const certificateBytes = fi0CanonicalRecordBytes({
    schemaVersion: 1,
    recordType: "FI0_BASELINE_CERTIFICATE_FIXTURE",
    status: "UNCERTIFIED",
    fi0Used: false,
  });
  const digestBody = {
    schemaVersion: 1,
    recordType: "FI0_BASELINE_BUNDLE",
    artifactBytesDigest: sha256Bytes(artifactBytes),
    verdictBytesDigest: sha256Bytes(verdictBytes),
    certificateBytesDigest: sha256Bytes(certificateBytes),
  };
  return {
    artifactBytes,
    verdictBytes,
    certificateBytes,
    bundleDigest: fi0DomainDigest(FI0_BASELINE_BUNDLE_DIGEST_DOMAIN, digestBody),
  };
}

function exerciseFi0ShadowAdapterScenario(
  mode: (typeof FI0_BASELINE_FAILURE_MODES)[number],
): (typeof FI0_EXPECTED_SHADOW_DISPOSITIONS)[keyof typeof FI0_EXPECTED_SHADOW_DISPOSITIONS] {
  switch (mode) {
    case "DISABLED":
      return FI0_EXPECTED_SHADOW_DISPOSITIONS.DISABLED;
    case "MISSING": {
      const candidate: Buffer | undefined = undefined;
      assert.equal(candidate, undefined);
      return FI0_EXPECTED_SHADOW_DISPOSITIONS.MISSING;
    }
    case "MALFORMED":
      try {
        parseCanonicalFi0RecordBytes(Buffer.from("{\n", "utf8"), "FI-0 malformed shadow record");
      } catch (error) {
        if (error instanceof VeritasError && error.code === "FI0_RECORD_NONCANONICAL") {
          return FI0_EXPECTED_SHADOW_DISPOSITIONS.MALFORMED;
        }
        throw error;
      }
      break;
    case "CORRUPT":
      try {
        if (sha256Bytes("fi0-shadow-corrupt") !== sha256Bytes("fi0-shadow-expected")) {
          fail("FI0_SHADOW_CORRUPT_INJECTED", "FI-0 injected corrupt shadow record differs from its expected digest.");
        }
      } catch (error) {
        if (error instanceof VeritasError && error.code === "FI0_SHADOW_CORRUPT_INJECTED") {
          return FI0_EXPECTED_SHADOW_DISPOSITIONS.CORRUPT;
        }
        throw error;
      }
      break;
    case "SLOW_BUDGET_EXCEEDED": {
      const budgetUnits = 1;
      const observedUnits = 2;
      assert.equal(observedUnits > budgetUnits, true);
      return FI0_EXPECTED_SHADOW_DISPOSITIONS.SLOW_BUDGET_EXCEEDED;
    }
    case "STORE_FULL":
      try {
        fail("FI0_SHADOW_STORE_FULL_INJECTED", "FI-0 injected shadow store-full condition.");
      } catch (error) {
        if (error instanceof VeritasError && error.code === "FI0_SHADOW_STORE_FULL_INJECTED") {
          return FI0_EXPECTED_SHADOW_DISPOSITIONS.STORE_FULL;
        }
        throw error;
      }
      break;
    case "THREW":
      try {
        throw new Error("FI0_SHADOW_ADAPTER_THROW_INJECTED");
      } catch (error) {
        if (error instanceof Error && error.message === "FI0_SHADOW_ADAPTER_THROW_INJECTED") {
          return FI0_EXPECTED_SHADOW_DISPOSITIONS.THREW;
        }
        throw error;
      }
  }
  fail("FI0_BASELINE_MODE_INVALID", "FI-0 shadow adapter scenario did not reach its frozen disposition.");
}

function exerciseFi0BaselineFailureModeFixture(
  baseline: Fi0BaselineBundleV1,
  mode: (typeof FI0_BASELINE_FAILURE_MODES)[number],
  expectedBundleDigest: string,
): Fi0BaselineInvariantResultV1 {
  if (!FI0_BASELINE_FAILURE_MODES.includes(mode) || !isSha256Digest(expectedBundleDigest)) {
    fail("FI0_BASELINE_MODE_INVALID", "FI-0 baseline fixture mode or expectation is invalid.");
  }
  const result: Fi0BaselineInvariantResultV1 = {
    mode,
    shadowDisposition: exerciseFi0ShadowAdapterScenario(mode),
    artifactBytes: Buffer.from(baseline.artifactBytes),
    verdictBytes: Buffer.from(baseline.verdictBytes),
    certificateBytes: Buffer.from(baseline.certificateBytes),
    bundleDigest: baseline.bundleDigest,
  };
  const recomputedBundleDigest = fi0DomainDigest(FI0_BASELINE_BUNDLE_DIGEST_DOMAIN, {
    schemaVersion: 1,
    recordType: "FI0_BASELINE_BUNDLE",
    artifactBytesDigest: sha256Bytes(result.artifactBytes),
    verdictBytesDigest: sha256Bytes(result.verdictBytes),
    certificateBytesDigest: sha256Bytes(result.certificateBytes),
  });
  if (
    result.bundleDigest !== expectedBundleDigest ||
    recomputedBundleDigest !== expectedBundleDigest ||
    !result.artifactBytes.equals(baseline.artifactBytes) ||
    !result.verdictBytes.equals(baseline.verdictBytes) ||
    !result.certificateBytes.equals(baseline.certificateBytes)
  ) {
    fail("FI0_BASELINE_MUTATION_DETECTED", "FI-0 shadow failure changed frozen baseline bytes or their bundle digest.");
  }
  return result;
}

