function validateFi0IncidentView(
  value: unknown,
  incident: FailureIncidentV1,
  events: ReadonlyArray<Fi0IncidentEventV1>,
  eventChainHeadDigest: string,
  importEnvelope: Fi0HistoricalImportEnvelopeV1,
  baselineBundleDigest: string,
  expectedViewDigest: string,
): Fi0IncidentViewV1 {
  assertFi0NoProhibitedRawLocatorOrCredentialText(value, "FI-0 incident view");
  const keys = [
    "schemaVersion", "recordType", "profile", "incidentId", "incidentDigest",
    "observationKey", "evidenceManifestDigest", "eventChainHeadDigest",
    "adjudicationState", "occurrenceCount", "historyEventCount",
    "sourceStreamHeadDigest", "historicalImportEnvelopeDigest", "baselineBundleDigest",
    "foundationOnly", "authorizing", "protectedAuthorityVerified", "mayCapture",
    "mayImport", "mayAdjudicate", "mayConfirm", "mayPromote", "mayRetrieve",
    "mayInjectContext", "mayRepair", "mayChangePolicy", "mayCertify", "mayRecall",
    "mayReplay", "mayInstall", "mayExecute", "filesystemMutated", "networkRequested",
    "subprocessStarted", "dynamicLoadAttempted", "coordinatorMutated",
    "generatedArtifactExecuted", "crossProjectRead", "baselineMutated", "viewDigest",
  ] as const;
  const record = requireExactObjectKeys(
    value,
    keys,
    "FI0_VIEW_INVALID",
    "FI-0 incident view",
  );
  const falseFields = [
    "authorizing", "protectedAuthorityVerified", "mayCapture", "mayImport",
    "mayAdjudicate", "mayConfirm", "mayPromote", "mayRetrieve", "mayInjectContext",
    "mayRepair", "mayChangePolicy", "mayCertify", "mayRecall", "mayReplay",
    "mayInstall", "mayExecute", "filesystemMutated", "networkRequested",
    "subprocessStarted", "dynamicLoadAttempted", "coordinatorMutated",
    "generatedArtifactExecuted", "crossProjectRead", "baselineMutated",
  ] as const;
  if (
    !isSha256Digest(expectedViewDigest) ||
    record.schemaVersion !== 1 ||
    record.recordType !== "FI0_INCIDENT_VIEW" ||
    record.profile !== FI0_INCIDENT_PROFILE ||
    record.incidentId !== incident.incidentId ||
    record.incidentDigest !== incident.incidentDigest ||
    record.observationKey !== incident.observationKey ||
    record.evidenceManifestDigest !== incident.evidenceManifestDigest ||
    record.eventChainHeadDigest !== eventChainHeadDigest ||
    record.adjudicationState !== "INCONCLUSIVE" ||
    record.occurrenceCount !== 1 ||
    record.historyEventCount !== events.length ||
    record.historyEventCount !== 3 ||
    record.sourceStreamHeadDigest !== incident.sourceStreamHeadDigest ||
    record.historicalImportEnvelopeDigest !== importEnvelope.envelopeDigest ||
    record.baselineBundleDigest !== baselineBundleDigest ||
    record.foundationOnly !== true ||
    falseFields.some((field) => record[field] !== false) ||
    !isSha256Digest(record.viewDigest)
  ) {
    fail("FI0_VIEW_INVALID", "FI-0 incident view binding or zero-authority fields are invalid.");
  }
  const body = { ...record } as Record<string, unknown>;
  delete body.viewDigest;
  const computed = fi0DomainDigest(FI0_VIEW_DIGEST_DOMAIN, body);
  if (record.viewDigest !== computed) {
    fail("FI0_VIEW_DIGEST_MISMATCH", "FI-0 incident view digest is not exact.");
  }
  if (record.viewDigest !== expectedViewDigest) {
    fail("FI0_VIEW_EXPECTATION_MISMATCH", "FI-0 incident view differs from its source-frozen self-administered expectation.");
  }
  return structuredClone(record) as Fi0IncidentViewV1;
}

function assertFi0FixtureLane(active = boundedTestLaneActive()): void {
  if (!active || ALPHA_EXECUTION_ENABLED !== false) {
    fail("FI0_FIXTURE_LANE_REQUIRED", "FI-0 incident-contract fixture is callable only in the bounded private test lane.");
  }
}

function createFi0ExternalGenesisDigest(context: Fi0AccessContextV1): string {
  return fi0DomainDigest(FI0_EXTERNAL_GENESIS_DIGEST_DOMAIN, {
    schemaVersion: 1,
    recordType: "FI0_EXTERNAL_EVENT_GENESIS",
    profile: FI0_INCIDENT_PROFILE,
    scopeId: context.scopeId,
    projectIdDigest: context.projectIdDigest,
    sourceStreamId: context.sourceStreamId,
    sourceStreamHeadDigest: context.sourceStreamHeadDigest,
    genesisOrdinal: 0,
  });
}

type Fi0PositiveObjectsV1 = {
  context: Fi0AccessContextV1;
  evidenceRefs: Fi0EvidenceRefV1[];
  evidenceManifest: Fi0EvidenceManifestV1;
  incident: FailureIncidentV1;
  externalGenesisDigest: string;
  events: Fi0IncidentEventV1[];
  eventChainHeadDigest: string;
  importEnvelope: Fi0HistoricalImportEnvelopeV1;
  baseline: Fi0BaselineBundleV1;
  view: Fi0IncidentViewV1;
};

function createFi0PositiveObjects(): Fi0PositiveObjectsV1 {
  const context = createFi0AccessContextFixture();
  const evidenceRefs = [
    createFi0EvidenceRefFixture(
      "evidence/analysis-001",
      "ANALYSIS",
      context.scopeId,
      context.projectIdDigest,
      "issuer/self-administered-analysis-fixture",
      context.subjectIdDigest,
      context.subjectContentDigest,
      "analysis-event-17",
      "analysis-digest-token-v1",
    ),
    createFi0EvidenceRefFixture(
      "evidence/gate-001",
      "DETERMINISTIC_GATE",
      context.scopeId,
      context.projectIdDigest,
      "issuer/self-administered-gate-fixture",
      context.subjectIdDigest,
      context.subjectContentDigest,
      "gate-event-17",
      "gate-digest-token-v1",
    ),
  ].sort(compareFi0EvidenceRefs);
  const evidenceManifest = createFi0EvidenceManifestFixture(
    evidenceRefs,
    context.scopeId,
    context.projectIdDigest,
    context.sourceStreamId,
    context.sourceStreamHeadDigest,
  );
  const incident = createFi0IncidentFixture(
    evidenceManifest,
    context.subjectIdDigest,
    context.subjectContentDigest,
    context,
  );
  const externalGenesisDigest = createFi0ExternalGenesisDigest(context);
  const events = createFi0IncidentEventFixtures(incident, externalGenesisDigest);
  const eventChainHeadDigest = fi0EventChainHeadDigest(incident, externalGenesisDigest, events);
  const importEnvelope = createFi0HistoricalImportEnvelopeFixture(
    context,
    incident,
    eventChainHeadDigest,
  );
  const baseline = createFi0BaselineBundleFixture();
  const view = createFi0IncidentViewFixture(
    incident,
    events,
    eventChainHeadDigest,
    importEnvelope,
    baseline.bundleDigest,
  );
  return {
    context,
    evidenceRefs,
    evidenceManifest,
    incident,
    externalGenesisDigest,
    events,
    eventChainHeadDigest,
    importEnvelope,
    baseline,
    view,
  };
}

function createFi0RawFixtureInputs(): Fi0RawFixtureInputsV1 {
  const fixture = createFi0PositiveObjects();
  return {
    evidenceRefBytes: fixture.evidenceRefs.map(fi0CanonicalRecordBytes),
    evidenceManifestBytes: fi0CanonicalRecordBytes(fixture.evidenceManifest),
    incidentBytes: fi0CanonicalRecordBytes(fixture.incident),
    eventBytes: fixture.events.map(fi0CanonicalRecordBytes),
    importEnvelopeBytes: fi0CanonicalRecordBytes(fixture.importEnvelope),
    expectations: {
      expectedExternalGenesisDigest: FI0_EXPECTED_EXTERNAL_GENESIS_DIGEST,
      expectedEvidenceManifestDigest: FI0_EXPECTED_EVIDENCE_MANIFEST_DIGEST,
      expectedIncidentDigest: FI0_EXPECTED_INCIDENT_DIGEST,
      expectedEventChainHeadDigest: FI0_EXPECTED_EVENT_ROOT_DIGEST,
      expectedImportEnvelopeDigest: FI0_EXPECTED_IMPORT_ENVELOPE_DIGEST,
      expectedViewDigest: FI0_EXPECTED_VIEW_DIGEST,
      expectedBaselineBundleDigest: FI0_EXPECTED_BASELINE_BUNDLE_DIGEST,
    },
  };
}

function validateFi0ExternalExpectations(
  value: unknown,
  context: Fi0AccessContextV1,
): Fi0ExternalExpectationsV1 {
  const record = requireExactObjectKeys(
    value,
    [
      "expectedExternalGenesisDigest", "expectedEvidenceManifestDigest",
      "expectedIncidentDigest", "expectedEventChainHeadDigest",
      "expectedImportEnvelopeDigest", "expectedViewDigest", "expectedBaselineBundleDigest",
    ],
    "FI0_EXPECTATION_INVALID",
    "FI-0 source-frozen self-administered expectations",
  );
  const expected: Fi0ExternalExpectationsV1 = {
    expectedExternalGenesisDigest: FI0_EXPECTED_EXTERNAL_GENESIS_DIGEST,
    expectedEvidenceManifestDigest: FI0_EXPECTED_EVIDENCE_MANIFEST_DIGEST,
    expectedIncidentDigest: FI0_EXPECTED_INCIDENT_DIGEST,
    expectedEventChainHeadDigest: FI0_EXPECTED_EVENT_ROOT_DIGEST,
    expectedImportEnvelopeDigest: FI0_EXPECTED_IMPORT_ENVELOPE_DIGEST,
    expectedViewDigest: FI0_EXPECTED_VIEW_DIGEST,
    expectedBaselineBundleDigest: FI0_EXPECTED_BASELINE_BUNDLE_DIGEST,
  };
  if (
    Object.values(expected).some((digest) => !isSha256Digest(digest)) ||
    canonicalJson(record) !== canonicalJson(expected) ||
    expected.expectedExternalGenesisDigest !== createFi0ExternalGenesisDigest(context)
  ) {
    fail("FI0_EXPECTATION_INVALID", "FI-0 expectations must equal the source-frozen self-administered constants.");
  }
  return expected;
}

function preflightFi0EvidenceRefExternalBindings(
  value: unknown,
  context: Fi0AccessContextV1,
): void {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as Record<string, unknown>;
  if (
    record.scopeId !== context.scopeId ||
    record.projectIdDigest !== context.projectIdDigest ||
    record.subjectType !== "LLM_ARTIFACT" ||
    record.subjectIdDigest !== context.subjectIdDigest ||
    record.subjectContentDigest !== context.subjectContentDigest
  ) {
    fail("FI0_EVIDENCE_SUBJECT_BINDING_MISMATCH", "FI-0 evidence reference differs from the frozen scope, project, or typed subject identity/content.");
  }
}

function preflightFi0ManifestExternalBindings(
  value: unknown,
  context: Fi0AccessContextV1,
): void {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as Record<string, unknown>;
  if (
    record.scopeId !== context.scopeId ||
    record.projectIdDigest !== context.projectIdDigest ||
    record.sourceStreamId !== context.sourceStreamId ||
    record.sourceStreamHeadDigest !== context.sourceStreamHeadDigest
  ) {
    fail("FI0_SCOPE_ACCESS_REFUSED", "FI-0 evidence manifest differs from the frozen scope, project, or source stream.");
  }
}

function preflightFi0IncidentExternalBindings(
  value: unknown,
  context: Fi0AccessContextV1,
  manifest: Fi0EvidenceManifestV1,
): void {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return;
  const record = value as Record<string, unknown>;
  if (
    record.scopeId !== context.scopeId ||
    record.projectIdDigest !== context.projectIdDigest ||
    record.accessPolicyDigest !== context.accessPolicyDigest ||
    record.retentionPolicyDigest !== context.retentionPolicyDigest
  ) {
    fail("FI0_SCOPE_ACCESS_REFUSED", "FI-0 incident differs from the frozen scope, project, access, or retention context.");
  }
  if (
    record.subjectIdDigest !== context.subjectIdDigest ||
    record.subjectContentDigest !== context.subjectContentDigest
  ) {
    fail("FI0_SUBJECT_BINDING_INVALID", "FI-0 incident subject identity/content differs from the frozen typed subject.");
  }
  if (record.subjectLineageRootDigest !== context.subjectLineageRootDigest) {
    fail("FI0_SUBJECT_LINEAGE_MISMATCH", "FI-0 incident subject lineage differs from the frozen lineage root.");
  }
  if (
    record.evidenceManifestDigest !== manifest.manifestDigest ||
    record.evidenceSetDigest !== manifest.evidenceSetDigest
  ) {
    fail("FI0_EVIDENCE_ROOT_BINDING_MISMATCH", "FI-0 incident evidence bindings differ from the validated external manifest.");
  }
  if (
    record.architectureVersionDigest !== context.architectureVersionDigest ||
    record.policyVersionDigest !== context.policyVersionDigest ||
    record.dependencyGraphDigest !== context.dependencyGraphDigest ||
    record.sourceStreamId !== context.sourceStreamId ||
    record.sourceStreamHeadDigest !== context.sourceStreamHeadDigest
  ) {
    fail("FI0_INCIDENT_EXTERNAL_BINDING_MISMATCH", "FI-0 incident architecture, policy, dependency, or stream binding differs from its source fixture.");
  }
}

function deriveFi0IncidentContractFixture(
  inputs: Fi0RawFixtureInputsV1,
): Fi0DerivedFixtureV1 {
  assertFi0FixtureLane();
  requireExactObjectKeys(
    inputs,
    [
      "evidenceRefBytes", "evidenceManifestBytes", "incidentBytes", "eventBytes",
      "importEnvelopeBytes", "expectations",
    ],
    "FI0_CONTRACT_INVALID",
    "FI-0 raw fixture inputs",
  );
  const context = createFi0AccessContextFixture();
  const expectations = validateFi0ExternalExpectations(inputs.expectations, context);
  if (
    !Array.isArray(inputs.evidenceRefBytes) ||
    inputs.evidenceRefBytes.length === 0 ||
    inputs.evidenceRefBytes.length > FI0_LIMITS.maxEvidenceRefs ||
    !Array.isArray(inputs.eventBytes) ||
    inputs.eventBytes.length < FI0_LIMITS.minEventCount ||
    inputs.eventBytes.length > FI0_LIMITS.maxEventCount
  ) {
    fail("FI0_AGGREGATE_LIMIT_INVALID", "FI-0 raw array counts exceed frozen pre-parse bounds.");
  }
  const allBytes = [
    ...inputs.evidenceRefBytes,
    inputs.evidenceManifestBytes,
    inputs.incidentBytes,
    ...inputs.eventBytes,
    inputs.importEnvelopeBytes,
  ];
  if (
    allBytes.some((bytes) => !Buffer.isBuffer(bytes)) ||
    allBytes.reduce((total, bytes) => total + bytes.length, 0) > FI0_LIMITS.maxAggregateFixtureBytes
  ) {
    fail("FI0_AGGREGATE_LIMIT_INVALID", "FI-0 aggregate canonical bytes exceed the frozen pre-parse bound.");
  }
  const evidenceRefs = inputs.evidenceRefBytes.map((bytes, index) => {
    const parsed = parseCanonicalFi0RecordBytes(bytes, `FI-0 evidence reference ${index}`);
    preflightFi0EvidenceRefExternalBindings(parsed, context);
    return validateFi0EvidenceRef(
      parsed,
      context.scopeId,
      context.projectIdDigest,
      context.subjectIdDigest,
      context.subjectContentDigest,
    );
  });
  if (
    new Set(evidenceRefs.map((ref) => ref.refId)).size !== evidenceRefs.length ||
    new Set(evidenceRefs.map((ref) => ref.refDigest)).size !== evidenceRefs.length ||
    new Set(evidenceRefs.map((ref) => canonicalJson({
      evidenceKind: ref.evidenceKind,
      evidenceOutcome: ref.evidenceOutcome,
      scopeId: ref.scopeId,
      projectIdDigest: ref.projectIdDigest,
      issuerIdDigest: ref.issuerIdDigest,
      subjectIdDigest: ref.subjectIdDigest,
      subjectType: ref.subjectType,
      subjectContentDigest: ref.subjectContentDigest,
      locatorDigest: ref.locatorDigest,
      contentDigest: ref.contentDigest,
    }))).size !== evidenceRefs.length
  ) {
    fail("FI0_EVIDENCE_SET_AMBIGUOUS", "FI-0 evidence reference or semantic evidence identity is duplicated.");
  }
  if (canonicalJson(evidenceRefs) !== canonicalJson([...evidenceRefs].sort(compareFi0EvidenceRefs))) {
    fail("FI0_EVIDENCE_SET_ORDER_INVALID", "FI-0 evidence references must be canonically ordered.");
  }
  const parsedManifest = parseCanonicalFi0RecordBytes(
    inputs.evidenceManifestBytes,
    "FI-0 evidence manifest",
  );
  preflightFi0ManifestExternalBindings(parsedManifest, context);
  const evidenceManifest = validateFi0EvidenceManifest(
    parsedManifest,
    evidenceRefs,
    expectations.expectedEvidenceManifestDigest,
  );
  if (
    evidenceManifest.scopeId !== context.scopeId ||
    evidenceManifest.projectIdDigest !== context.projectIdDigest ||
    evidenceManifest.sourceStreamId !== context.sourceStreamId ||
    evidenceManifest.sourceStreamHeadDigest !== context.sourceStreamHeadDigest
  ) {
    fail("FI0_SCOPE_ACCESS_REFUSED", "FI-0 evidence manifest lies outside the frozen scope and access context.");
  }
  const parsedIncident = parseCanonicalFi0RecordBytes(
    inputs.incidentBytes,
    "FI-0 failure incident",
  );
  preflightFi0IncidentExternalBindings(parsedIncident, context, evidenceManifest);
  const incident = validateFi0Incident(
    parsedIncident,
    evidenceManifest,
    expectations.expectedIncidentDigest,
  );
  if (
    incident.scopeId !== context.scopeId ||
    incident.projectIdDigest !== context.projectIdDigest ||
    incident.accessPolicyDigest !== context.accessPolicyDigest ||
    incident.retentionPolicyDigest !== context.retentionPolicyDigest
  ) {
    fail("FI0_SCOPE_ACCESS_REFUSED", "FI-0 incident lies outside the frozen scope, project, access, or retention context.");
  }
  if (
    incident.subjectIdDigest !== context.subjectIdDigest ||
    incident.subjectContentDigest !== context.subjectContentDigest
  ) {
    fail("FI0_SUBJECT_BINDING_INVALID", "FI-0 incident subject identity/content domains differ from the frozen subject.");
  }
  if (incident.subjectLineageRootDigest !== context.subjectLineageRootDigest) {
    fail("FI0_SUBJECT_LINEAGE_MISMATCH", "FI-0 incident subject lineage differs from the frozen root.");
  }
  if (
    incident.architectureVersionDigest !== context.architectureVersionDigest ||
    incident.policyVersionDigest !== context.policyVersionDigest ||
    incident.dependencyGraphDigest !== context.dependencyGraphDigest ||
    incident.sourceStreamId !== context.sourceStreamId ||
    incident.sourceStreamHeadDigest !== context.sourceStreamHeadDigest
  ) {
    fail("FI0_INCIDENT_EXTERNAL_BINDING_MISMATCH", "FI-0 incident policy, architecture, dependency, or stream binding differs from its source-frozen self-administered fixture.");
  }
  const parsedEvents = inputs.eventBytes.map((bytes, index) => parseCanonicalFi0RecordBytes(
    bytes,
    `FI-0 incident event ${index}`,
    "EVENT",
  ));
  const chain = validateFi0IncidentEventChain(
    parsedEvents,
    incident,
    expectations.expectedExternalGenesisDigest,
    expectations.expectedEventChainHeadDigest,
  );
  const importEnvelope = validateFi0HistoricalImportEnvelope(
    parseCanonicalFi0RecordBytes(inputs.importEnvelopeBytes, "FI-0 historical import envelope"),
    context,
    incident,
    chain.eventChainHeadDigest,
    expectations.expectedImportEnvelopeDigest,
  );
  const baseline = createFi0BaselineBundleFixture();
  if (baseline.bundleDigest !== expectations.expectedBaselineBundleDigest) {
    fail("FI0_BASELINE_MUTATION_DETECTED", "FI-0 baseline bundle differs from its frozen pre-FI expectation.");
  }
  const baselineFailureModes = FI0_BASELINE_FAILURE_MODES.map((mode) =>
    exerciseFi0BaselineFailureModeFixture(
      baseline,
      mode,
      expectations.expectedBaselineBundleDigest,
    ));
  const view = validateFi0IncidentView(
    createFi0IncidentViewFixture(
      incident,
      chain.events,
      chain.eventChainHeadDigest,
      importEnvelope,
      baseline.bundleDigest,
    ),
    incident,
    chain.events,
    chain.eventChainHeadDigest,
    importEnvelope,
    baseline.bundleDigest,
    expectations.expectedViewDigest,
  );
  return {
    evidenceRefs,
    evidenceManifest,
    incident,
    events: chain.events,
    eventChainHeadDigest: chain.eventChainHeadDigest,
    importEnvelope,
    view,
    baseline,
    baselineFailureModes,
  };
}
