class AuthorityCeremonyFixture {
  #generation = 0;
  #state: "UNENROLLED" | "ACTIVE" | "WITHDRAWN" | "RETIRED" = "UNENROLLED";
  enroll(authority: string, generation: number): void {
    if (authority !== "ADMIN") fail("CEREMONY_AUTHORITY_REQUIRED", "Only the ceremony authority may enroll.");
    if (this.#state !== "UNENROLLED") fail("CEREMONY_REENROLL_BLOCKED", "Implicit re-enrollment is forbidden.");
    if (generation !== 1) fail("CEREMONY_GENERATION_INVALID", "Initial enrollment must start at generation one.");
    this.#generation = generation; this.#state = "ACTIVE";
  }
  withdraw(authority: string): void { if (authority !== "ADMIN" || this.#state !== "ACTIVE") fail("CEREMONY_WITHDRAWAL_INVALID", "Only active authority may be withdrawn."); this.#state = "WITHDRAWN"; }
  rotate(authority: string, generation: number): void { if (authority !== "ADMIN" || this.#state !== "ACTIVE" || generation <= this.#generation) fail("CEREMONY_ROTATION_INVALID", "Rotation must be authorized and strictly monotonic."); this.#generation = generation; }
  retire(authority: string): void { if (authority !== "ADMIN" || this.#state !== "ACTIVE") fail("CEREMONY_RETIREMENT_INVALID", "Only active authority may be retired."); this.#state = "RETIRED"; }
  snapshot(): { state: string; generation: number } { return { state: this.#state, generation: this.#generation }; }
}

const kernelContextStatesByHandle = new WeakMap<KernelContextV1, KernelContextStateV1>();
const kernelContextHandlesByCanonicalRoot = new Map<string, KernelContextV1>();

function persistentWitnessEnrollmentIntentPath(storePath: string): string {
  return join(storePath, "coordinator", "persistent-witness-enrollment.json");
}

function sqliteText(row: Record<string, unknown>, key: string): string {
  const value = row[key];
  if (typeof value !== "string") {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not text.`);
  }
  return value;
}

function sqliteInteger(row: Record<string, unknown>, key: string): number {
  const value = row[key];
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not an integer.`);
  }
  return value;
}

function sqliteBoundedText(
  row: Record<string, unknown>,
  key: string,
  maximumLength = 4096,
): string {
  const value = sqliteText(row, key);
  if (value.length === 0 || value.length > maximumLength) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} has an invalid length.`);
  }
  return value;
}

function sqliteSha256(row: Record<string, unknown>, key: string): string {
  const value = sqliteText(row, key);
  if (!isSha256Digest(value)) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not a SHA-256 digest.`);
  }
  return value;
}

function isCanonicalUuidV4(value: unknown): value is string {
  return (
    typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(value)
  );
}

function sqliteUuidV4(row: Record<string, unknown>, key: string): string {
  const value = sqliteText(row, key);
  if (!isCanonicalUuidV4(value)) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not a canonical UUIDv4.`);
  }
  return value;
}

function sqliteDecimalIdentity(row: Record<string, unknown>, key: string): string {
  const value = sqliteText(row, key);
  if (!/^(0|[1-9][0-9]*)$/.test(value)) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not a decimal identity.`);
  }
  return value;
}

function sqliteIsoInstant(row: Record<string, unknown>, key: string): string {
  const value = sqliteText(row, key);
  if (!isCanonicalIsoInstant(value)) {
    fail("WITNESS_REGISTRY_CORRUPT", `Registry column ${key} is not a canonical UTC instant.`);
  }
  return value;
}

function isCanonicalIsoInstant(value: unknown): value is string {
  if (typeof value !== "string") return false;
  const parsed = new Date(value);
  return Number.isFinite(parsed.valueOf()) && parsed.toISOString() === value;
}

function rethrowPersistentRegistryError(error: unknown): never {
  if (error instanceof VeritasError) throw error;
  const code = (error as { code?: unknown } | null)?.code;
  if (typeof code !== "string" || !code.startsWith("ERR_SQLITE")) throw error;
  const message = error instanceof Error ? error.message : "SQLite registry operation failed.";
  const details = { sqliteCode: code, sqliteMessage: message } satisfies JsonValue;
  if (/busy|locked/i.test(message)) {
    fail(
      "WITNESS_REGISTRY_BUSY",
      "Persistent witness registry is busy; authorization is withheld.",
      details,
    );
  }
  if (/malformed|corrupt|not a database|disk image/i.test(message)) {
    fail(
      "WITNESS_REGISTRY_CORRUPT",
      "Persistent witness registry integrity is invalid.",
      details,
    );
  }
  fail(
    "WITNESS_REGISTRY_IO_FAILED",
    "Persistent witness registry operation failed closed.",
    details,
  );
}

function persistentRegistryPragmaScalar(
  database: DatabaseSync,
  pragma: "journal_mode" | "synchronous" | "fullfsync" | "checkpoint_fullfsync" |
    "trusted_schema" | "foreign_keys",
): string | number {
  const row = database.prepare(`PRAGMA ${pragma}`).get() as Record<string, unknown> | undefined;
  const values = row === undefined ? [] : Object.values(row);
  if (values.length !== 1 || (typeof values[0] !== "string" && typeof values[0] !== "number")) {
    fail("WITNESS_REGISTRY_CORRUPT", `Persistent registry PRAGMA ${pragma} is unavailable.`);
  }
  return values[0];
}

const PERSISTENT_REGISTRY_TABLE_SQL = {
  registry_meta: `
    CREATE TABLE registry_meta (
      key TEXT PRIMARY KEY,
      value TEXT NOT NULL
    ) STRICT
  `,
  witness_enrollments: `
    CREATE TABLE witness_enrollments (
      store_id TEXT PRIMARY KEY,
      enrollment_id TEXT NOT NULL UNIQUE,
      generation INTEGER NOT NULL CHECK (generation >= 1),
      canonical_store_path TEXT NOT NULL,
      store_device_id TEXT NOT NULL,
      store_inode_id TEXT NOT NULL,
      migration_digest TEXT NOT NULL,
      storage_admission_digest TEXT NOT NULL,
      witness_id TEXT NOT NULL UNIQUE,
      binding_digest TEXT NOT NULL,
      state TEXT NOT NULL CHECK (state IN ('ACTIVE', 'WITHDRAWN')),
      current_record_digest TEXT NOT NULL,
      created_at TEXT NOT NULL
    ) STRICT
  `,
  witness_records: `
    CREATE TABLE witness_records (
      witness_id TEXT NOT NULL,
      witness_version INTEGER NOT NULL CHECK (witness_version >= 0),
      record_digest TEXT NOT NULL UNIQUE,
      previous_record_digest TEXT,
      operation_id TEXT NOT NULL UNIQUE,
      request_digest TEXT NOT NULL,
      record_json TEXT NOT NULL,
      PRIMARY KEY (witness_id, witness_version)
    ) STRICT
  `,
  witness_recovery_resolutions: `
    CREATE TABLE witness_recovery_resolutions (
      witness_id TEXT NOT NULL,
      withdrawn_record_digest TEXT PRIMARY KEY,
      operation_id TEXT NOT NULL UNIQUE,
      request_digest TEXT NOT NULL,
      resolution_digest TEXT NOT NULL,
      selection_record_digest TEXT NOT NULL UNIQUE,
      selection_record_json TEXT NOT NULL
    ) STRICT
  `,
} as const;

type RegistryTableName = keyof typeof PERSISTENT_REGISTRY_TABLE_SQL;
type RegistryColumnExpectation = readonly [name: string, type: "TEXT" | "INTEGER", notNull: 0 | 1, primaryKey: number];

const PERSISTENT_REGISTRY_COLUMNS: Record<RegistryTableName, readonly RegistryColumnExpectation[]> = {
  registry_meta: [
    ["key", "TEXT", 1, 1],
    ["value", "TEXT", 1, 0],
  ],
  witness_enrollments: [
    ["store_id", "TEXT", 1, 1],
    ["enrollment_id", "TEXT", 1, 0],
    ["generation", "INTEGER", 1, 0],
    ["canonical_store_path", "TEXT", 1, 0],
    ["store_device_id", "TEXT", 1, 0],
    ["store_inode_id", "TEXT", 1, 0],
    ["migration_digest", "TEXT", 1, 0],
    ["storage_admission_digest", "TEXT", 1, 0],
    ["witness_id", "TEXT", 1, 0],
    ["binding_digest", "TEXT", 1, 0],
    ["state", "TEXT", 1, 0],
    ["current_record_digest", "TEXT", 1, 0],
    ["created_at", "TEXT", 1, 0],
  ],
  witness_records: [
    ["witness_id", "TEXT", 1, 1],
    ["witness_version", "INTEGER", 1, 2],
    ["record_digest", "TEXT", 1, 0],
    ["previous_record_digest", "TEXT", 0, 0],
    ["operation_id", "TEXT", 1, 0],
    ["request_digest", "TEXT", 1, 0],
    ["record_json", "TEXT", 1, 0],
  ],
  witness_recovery_resolutions: [
    ["witness_id", "TEXT", 1, 0],
    ["withdrawn_record_digest", "TEXT", 1, 1],
    ["operation_id", "TEXT", 1, 0],
    ["request_digest", "TEXT", 1, 0],
    ["resolution_digest", "TEXT", 1, 0],
    ["selection_record_digest", "TEXT", 1, 0],
    ["selection_record_json", "TEXT", 1, 0],
  ],
};

const PERSISTENT_REGISTRY_INDEXES = [
  { name: "sqlite_autoindex_registry_meta_1", table: "registry_meta", origin: "pk", columns: ["key"] },
  { name: "sqlite_autoindex_witness_enrollments_1", table: "witness_enrollments", origin: "pk", columns: ["store_id"] },
  { name: "sqlite_autoindex_witness_enrollments_2", table: "witness_enrollments", origin: "u", columns: ["enrollment_id"] },
  { name: "sqlite_autoindex_witness_enrollments_3", table: "witness_enrollments", origin: "u", columns: ["witness_id"] },
  { name: "sqlite_autoindex_witness_records_1", table: "witness_records", origin: "u", columns: ["record_digest"] },
  { name: "sqlite_autoindex_witness_records_2", table: "witness_records", origin: "u", columns: ["operation_id"] },
  { name: "sqlite_autoindex_witness_records_3", table: "witness_records", origin: "pk", columns: ["witness_id", "witness_version"] },
  { name: "sqlite_autoindex_witness_recovery_resolutions_1", table: "witness_recovery_resolutions", origin: "pk", columns: ["withdrawn_record_digest"] },
  { name: "sqlite_autoindex_witness_recovery_resolutions_2", table: "witness_recovery_resolutions", origin: "u", columns: ["operation_id"] },
  { name: "sqlite_autoindex_witness_recovery_resolutions_3", table: "witness_recovery_resolutions", origin: "u", columns: ["selection_record_digest"] },
] as const;

function normalizeSql(sql: string): string {
  return sql.replace(/\s+/g, " ").trim().replace(/;$/, "");
}

function attestPersistentRegistrySchema(database: DatabaseSync): void {
  const observedSchema = database.prepare(
    `SELECT type, name, tbl_name, rootpage, sql
       FROM main.sqlite_schema
      ORDER BY type COLLATE BINARY, name COLLATE BINARY`,
  ).all() as Record<string, unknown>[];
  const expectedSchema = [
    ...PERSISTENT_REGISTRY_INDEXES.map((index) => ({
      type: "index",
      name: index.name,
      tbl_name: index.table,
      sql: null,
    })),
    ...Object.entries(PERSISTENT_REGISTRY_TABLE_SQL).map(([name, sql]) => ({
      type: "table",
      name,
      tbl_name: name,
      sql: normalizeSql(sql),
    })),
  ].sort((left, right) =>
    codePointCompare(left.type, right.type) || codePointCompare(left.name, right.name));
  const rootPages = new Set<number>();
  const projectedSchema = observedSchema.map((row) => {
    const rootPage = sqliteInteger(row, "rootpage");
    if (rootPage <= 0 || rootPages.has(rootPage)) {
      fail("WITNESS_REGISTRY_SCHEMA_WEAK", "Persistent registry root-page allocation is invalid.");
    }
    rootPages.add(rootPage);
    const sql = row.sql;
    if (sql !== null && typeof sql !== "string") {
      fail("WITNESS_REGISTRY_SCHEMA_WEAK", "Persistent registry schema SQL is malformed.");
    }
    return {
      type: sqliteText(row, "type"),
      name: sqliteText(row, "name"),
      tbl_name: sqliteText(row, "tbl_name"),
      sql: sql === null ? null : normalizeSql(sql),
    };
  });
  if (canonicalJson(projectedSchema) !== canonicalJson(expectedSchema)) {
    fail("WITNESS_REGISTRY_SCHEMA_WEAK", "Persistent registry schema, indexes, views, or triggers differ.");
  }

  for (const table of Object.keys(PERSISTENT_REGISTRY_TABLE_SQL) as RegistryTableName[]) {
    const observedColumns = database.prepare(
      `SELECT cid, name, type, "notnull", dflt_value, pk, hidden
         FROM pragma_table_xinfo(?) ORDER BY cid`,
    ).all(table) as Record<string, unknown>[];
    const expectedColumns = PERSISTENT_REGISTRY_COLUMNS[table].map(
      ([name, type, notnull, pk], cid) => ({
        cid,
        name,
        type,
        notnull,
        dflt_value: null,
        pk,
        hidden: 0,
      }),
    );
    if (canonicalJson(observedColumns) !== canonicalJson(expectedColumns)) {
      fail("WITNESS_REGISTRY_SCHEMA_WEAK", `Persistent registry table ${table} columns differ.`);
    }
    const observedIndexes = database.prepare(
      `SELECT name, "unique", origin, partial
         FROM pragma_index_list(?) ORDER BY name COLLATE BINARY`,
    ).all(table) as Record<string, unknown>[];
    const expectedIndexes = PERSISTENT_REGISTRY_INDEXES
      .filter((index) => index.table === table)
      .map((index) => ({ name: index.name, unique: 1, origin: index.origin, partial: 0 }))
      .sort((left, right) => codePointCompare(left.name, right.name));
    if (canonicalJson(observedIndexes) !== canonicalJson(expectedIndexes)) {
      fail("WITNESS_REGISTRY_SCHEMA_WEAK", `Persistent registry table ${table} indexes differ.`);
    }
  }

  for (const index of PERSISTENT_REGISTRY_INDEXES) {
    const tableColumns = PERSISTENT_REGISTRY_COLUMNS[index.table];
    const expectedIndexRows = [
      ...index.columns.map((name, seqno) => ({
        seqno,
        cid: tableColumns.findIndex((column) => column[0] === name),
        name,
        desc: 0,
        coll: "BINARY",
        key: 1,
      })),
      {
        seqno: index.columns.length,
        cid: -1,
        name: null,
        desc: 0,
        coll: "BINARY",
        key: 0,
      },
    ];
    const observedIndexRows = database.prepare(
      `SELECT seqno, cid, name, "desc", coll, "key"
         FROM pragma_index_xinfo(?) ORDER BY seqno`,
    ).all(index.name) as Record<string, unknown>[];
    if (canonicalJson(observedIndexRows) !== canonicalJson(expectedIndexRows)) {
      fail("WITNESS_REGISTRY_SCHEMA_WEAK", `Persistent registry index ${index.name} differs.`);
    }
  }

  const databases = database.prepare(`PRAGMA database_list`).all() as Record<string, unknown>[];
  const databaseNames = databases.map((row) => sqliteText(row, "name")).sort(codePointCompare);
  if (
    databaseNames.length < 1 ||
    databaseNames[0] !== "main" ||
    databaseNames.some((name) => !["main", "temp"].includes(name))
  ) {
    fail("WITNESS_REGISTRY_SCHEMA_WEAK", "Persistent registry has an attached database.");
  }
  const temporaryObjects = database.prepare(`SELECT name FROM temp.sqlite_schema`).all();
  if (temporaryObjects.length !== 0) {
    fail("WITNESS_REGISTRY_SCHEMA_WEAK", "Persistent registry temporary schema is not empty.");
  }
  const integrityRows = database.prepare(`PRAGMA integrity_check`).all() as Record<string, unknown>[];
  if (
    integrityRows.length !== 1 ||
    Object.values(integrityRows[0]).length !== 1 ||
    Object.values(integrityRows[0])[0] !== "ok"
  ) {
    fail("WITNESS_REGISTRY_CORRUPT", "Persistent registry full integrity check failed.");
  }
}

function initializePersistentRegistry(database: DatabaseSync, created: boolean): string {
  try {
    database.enableLoadExtension(false);
    database.enableDefensive(true);
    if (created) database.exec(`PRAGMA journal_mode = DELETE;`);
    database.exec(`
      PRAGMA synchronous = EXTRA;
      PRAGMA fullfsync = ON;
      PRAGMA checkpoint_fullfsync = ON;
      PRAGMA trusted_schema = OFF;
      PRAGMA foreign_keys = ON;
    `);
    if (created) {
      const existingSchema = database.prepare(`SELECT name FROM main.sqlite_schema`).all();
      if (existingSchema.length !== 0) {
        fail("WITNESS_REGISTRY_SCHEMA_WEAK", "New persistent registry was not empty.");
      }
      database.exec("BEGIN IMMEDIATE");
      database.exec(`${Object.values(PERSISTENT_REGISTRY_TABLE_SQL).join(";\n")};`);
      const schemaInsert = database.prepare(
        `INSERT INTO registry_meta (key, value) VALUES ('schema', '2')`,
      ).run();
      const identityInsert = database.prepare(
        `INSERT INTO registry_meta (key, value) VALUES ('registry_id', ?)`,
      ).run(randomUUID());
      if (schemaInsert.changes !== 1 || identityInsert.changes !== 1) {
        fail("WITNESS_REGISTRY_CORRUPT", "Persistent registry metadata was not created exactly once.");
      }
      database.exec("COMMIT");
    }
    attestPersistentRegistrySchema(database);
    const metadataRows = database.prepare(
      `SELECT key, value FROM registry_meta ORDER BY key COLLATE BINARY`,
    ).all() as Record<string, unknown>[];
    if (
      metadataRows.length !== 2 ||
      sqliteText(metadataRows[0], "key") !== "registry_id" ||
      sqliteText(metadataRows[1], "key") !== "schema" ||
      sqliteText(metadataRows[1], "value") !== "2"
    ) {
      fail("WITNESS_REGISTRY_SCHEMA_UNSUPPORTED", "Persistent registry metadata is unsupported.");
    }
    const registryId = sqliteUuidV4(metadataRows[0], "value");
    if (
      persistentRegistryPragmaScalar(database, "journal_mode") !== "delete" ||
      persistentRegistryPragmaScalar(database, "synchronous") !== 3 ||
      persistentRegistryPragmaScalar(database, "fullfsync") !== 1 ||
      persistentRegistryPragmaScalar(database, "checkpoint_fullfsync") !== 1 ||
      persistentRegistryPragmaScalar(database, "trusted_schema") !== 0 ||
      persistentRegistryPragmaScalar(database, "foreign_keys") !== 1
    ) {
      fail("WITNESS_REGISTRY_DURABILITY_INCONCLUSIVE", "Persistent registry safety settings are not active.");
    }
    return registryId;
  } catch (error) {
    try { database.exec("ROLLBACK"); } catch { /* transaction may already be closed */ }
    rethrowPersistentRegistryError(error);
  }
}

function readPersistentEnrollmentByStoreId(
  context: KernelContextStateV1,
  storeId: string,
): PersistentWitnessEnrollmentV1 | null {
  const row = context.database.prepare(
    `SELECT store_id, enrollment_id, generation, canonical_store_path,
            store_device_id, store_inode_id, migration_digest,
            storage_admission_digest, witness_id, binding_digest, state,
            current_record_digest, created_at
       FROM witness_enrollments WHERE store_id = ?`,
  ).get(storeId) as Record<string, unknown> | undefined;
  if (row === undefined) return null;
  const state = sqliteText(row, "state");
  if (!["ACTIVE", "WITHDRAWN"].includes(state)) {
    fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness enrollment state is invalid.");
  }
  const observedStoreId = sqliteUuidV4(row, "store_id");
  const canonicalStorePath = sqliteBoundedText(row, "canonical_store_path");
  const generation = sqliteInteger(row, "generation");
  if (
    observedStoreId !== storeId ||
    generation !== 1 ||
    !isAbsolute(canonicalStorePath) ||
    resolve(canonicalStorePath) !== canonicalStorePath
  ) {
    fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness enrollment identity is invalid.");
  }
  return {
    storeId: observedStoreId,
    enrollmentId: sqliteUuidV4(row, "enrollment_id"),
    generation,
    canonicalStorePath,
    storeDeviceId: sqliteDecimalIdentity(row, "store_device_id"),
    storeInodeId: sqliteDecimalIdentity(row, "store_inode_id"),
    migrationRecordDigest: sqliteSha256(row, "migration_digest"),
    storageAdmissionRecordDigest: sqliteSha256(row, "storage_admission_digest"),
    witnessId: sqliteUuidV4(row, "witness_id"),
    bindingDigest: sqliteSha256(row, "binding_digest"),
    state: state as PersistentWitnessEnrollmentV1["state"],
    currentRecordDigest: sqliteSha256(row, "current_record_digest"),
    createdAt: sqliteIsoInstant(row, "created_at"),
  };
}

function persistentEnrollmentMatchesPending(
  enrollment: PersistentWitnessEnrollmentV1,
  pending: Omit<PersistentWitnessEnrollmentV1, "state" | "currentRecordDigest">,
  currentRecordDigest: string,
): boolean {
  return canonicalJson(enrollment) === canonicalJson({
    ...pending,
    state: "ACTIVE",
    currentRecordDigest,
  });
}

class PrivatePersistentMonotonicWitnessFixture implements MonotonicWitnessV1 {
  readonly protocol = WITNESS_PROTOCOL;
  readonly implementationClass = "PRIVATE_PERSISTENT_FIXTURE" as const;
  readonly witnessId: string;
  readonly #context: KernelContextStateV1;
  readonly #bindingDigest: string;
  readonly #pendingEnrollment: Omit<
    PersistentWitnessEnrollmentV1,
    "state" | "currentRecordDigest"
  > | null;
  #available = true;
  #unknownAfterCommitOnce = false;

  constructor(
    context: KernelContextStateV1,
    witnessId: string,
    bindingDigest: string,
    pendingEnrollment: Omit<
      PersistentWitnessEnrollmentV1,
      "state" | "currentRecordDigest"
    > | null = null,
  ) {
    this.#context = context;
    this.witnessId = witnessId;
    if (!isSha256Digest(bindingDigest)) {
      fail("WITNESS_BINDING_MISMATCH", "Persistent witness binding digest is malformed.");
    }
    this.#bindingDigest = bindingDigest;
    this.#pendingEnrollment = pendingEnrollment;
    Object.freeze(this);
  }

  setAvailableForSelfTest(available: boolean): void {
    this.#available = available;
  }

  simulateUnknownAfterCommitOnceForSelfTest(): void {
    this.#unknownAfterCommitOnce = true;
  }

  #requireAvailable(): void {
    if (!this.#available) {
      fail("WITNESS_REGISTRY_UNAVAILABLE", "Persistent witness registry is unavailable.");
    }
  }

  #readHistory(): VerifiedWitnessRecord[] {
    const enrollment = this.#context.database.prepare(
      `SELECT store_id, enrollment_id, binding_digest, created_at
         FROM witness_enrollments WHERE witness_id = ?`,
    ).get(this.witnessId) as Record<string, unknown> | undefined;
    if (enrollment === undefined) {
      fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness history has no enrollment row.");
    }
    const enrollmentStoreId = sqliteUuidV4(enrollment, "store_id");
    const enrollmentId = sqliteUuidV4(enrollment, "enrollment_id");
    const enrollmentBindingDigest = sqliteSha256(enrollment, "binding_digest");
    const enrollmentCreatedAt = sqliteIsoInstant(enrollment, "created_at");
    const rows = this.#context.database.prepare(
      `SELECT witness_version, record_digest, previous_record_digest,
              operation_id, request_digest, record_json
         FROM witness_records WHERE witness_id = ? ORDER BY witness_version`,
    ).all(this.witnessId) as Record<string, unknown>[];
    const history: VerifiedWitnessRecord[] = [];
    for (let index = 0; index < rows.length; index += 1) {
      const row = rows[index];
      const version = sqliteInteger(row, "witness_version");
      const recordDigest = sqliteSha256(row, "record_digest");
      const operationId = sqliteBoundedText(row, "operation_id", 256);
      const requestDigest = sqliteSha256(row, "request_digest");
      const previousDigestValue = row.previous_record_digest;
      if (
        previousDigestValue !== null &&
        (typeof previousDigestValue !== "string" || !isSha256Digest(previousDigestValue))
      ) {
        fail("WITNESS_REGISTRY_CORRUPT", "Witness predecessor digest is invalid.");
      }
      let parsed: unknown;
      try {
        parsed = JSON.parse(sqliteText(row, "record_json"));
      } catch {
        fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness record JSON is invalid.");
      }
      const record = validateWitnessRecord(parsed);
      const previous = history.at(-1);
      const expectedPrevious = previous?.recordDigest ?? null;
      if (
        version !== index ||
        record.witnessVersion !== index ||
        record.witnessId !== this.witnessId ||
        record.bindingDigest !== enrollmentBindingDigest ||
        !isCanonicalIsoInstant(record.recordedAt) ||
        record.previousWitnessRecordDigest !== expectedPrevious ||
        previousDigestValue !== expectedPrevious ||
        recordDigest !== sha256Bytes(canonicalJson(record))
      ) {
        fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness history is incomplete or divergent.");
      }

      let expectedOperationId: string;
      let expectedRequest: JsonValue;
      if (previous === undefined) {
        expectedOperationId = `enroll:${enrollmentId}`;
        expectedRequest = {
          operationId: expectedOperationId,
          bindingDigest: enrollmentBindingDigest,
          tip: record.highWatermark,
        };
        if (
          record.state !== "SELECTED" ||
          record.highWatermark.storeId !== enrollmentStoreId ||
          record.recordedAt !== enrollmentCreatedAt
        ) {
          fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness genesis is not enrollment-bound.");
        }
      } else if (record.state === "SELECTED") {
        expectedRequest = witnessSelectOperationKey(
          this.witnessId,
          enrollmentBindingDigest,
          previous.recordDigest,
          record.highWatermark,
        );
        expectedOperationId = witnessSelectOperationId(
          this.witnessId,
          enrollmentBindingDigest,
          previous.recordDigest,
          record.highWatermark,
        );
        if (
          previous.record.state !== "SELECTED" ||
          record.highWatermark.storeId !== previous.record.highWatermark.storeId ||
          record.highWatermark.revision !== previous.record.highWatermark.revision + 1 ||
          record.highWatermark.previousCommitRecordDigest !==
            previous.record.highWatermark.commitRecordDigest
        ) {
          fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness SELECT transition is non-monotonic.");
        }
      } else {
        const withdrawal = validateWitnessWithdrawal(record.withdrawal);
        const withdrawalRequest = validateWitnessWithdrawalRequest({
          recoveryIntent: withdrawal.recoveryIntent,
          recoveryIntentDigest: withdrawal.recoveryIntentDigest,
        });
        expectedRequest = witnessWithdrawalOperationKey(
          this.witnessId,
          enrollmentBindingDigest,
          previous.recordDigest,
          withdrawalRequest,
        );
        expectedOperationId = witnessWithdrawalOperationId(
          this.witnessId,
          enrollmentBindingDigest,
          previous.recordDigest,
          withdrawalRequest,
        );
        if (
          previous.record.state !== "SELECTED" ||
          canonicalJson(record.highWatermark) !== canonicalJson(previous.record.highWatermark) ||
          !witnessWithdrawalRequestMatchesTip(withdrawalRequest, previous.record.highWatermark) ||
          record.recordedAt !== withdrawal.withdrawnAt
        ) {
          fail("WITNESS_REGISTRY_CORRUPT", "Persistent witness WITHDRAW transition is not tip-bound.");
        }
      }
      if (
        operationId !== expectedOperationId ||
        requestDigest !== sha256Bytes(canonicalJson(expectedRequest))
      ) {
        fail(
          "WITNESS_REGISTRY_CORRUPT",
          "Persistent witness operation identity or request digest is not transition-bound.",
        );
      }
      history.push({ record, recordDigest });
    }
    return history;
  }

  #readCurrent(bindingDigest: string): VerifiedWitnessRecord {
    const enrollment = this.#context.database.prepare(
      `SELECT binding_digest, state, current_record_digest
         FROM witness_enrollments WHERE witness_id = ?`,
    ).get(this.witnessId) as Record<string, unknown> | undefined;
    if (enrollment === undefined) {
      fail("WITNESS_ENROLLMENT_MISSING", "Persistent witness enrollment is missing.");
    }
    if (sqliteText(enrollment, "binding_digest") !== bindingDigest) {
      fail("WITNESS_BINDING_MISMATCH", "Persistent witness is bound to another coordinator.");
    }
    const history = this.#readHistory();
    const current = history.at(-1);
    const expectedEnrollmentState = current?.record.state === "WITHDRAWN"
      ? "WITHDRAWN"
      : "ACTIVE";
    if (
      current === undefined ||
      current.recordDigest !== sqliteText(enrollment, "current_record_digest") ||
      sqliteText(enrollment, "state") !== expectedEnrollmentState
    ) {
      fail(
        "WITNESS_REGISTRY_CORRUPT",
        "Enrollment state and digest do not select the exact witness tail.",
      );
    }
    return current;
  }

  #readRecoveryResolutionSelections(): VerifiedWitnessRecoveryResolutionSelectionV1[] {
    const history = this.#readHistory();
    const historyByDigest = new Map(history.map((item) => [item.recordDigest, item]));
    const rows = this.#context.database.prepare(
      `SELECT witness_id, withdrawn_record_digest, operation_id, request_digest,
              resolution_digest, selection_record_digest, selection_record_json
         FROM witness_recovery_resolutions
        WHERE witness_id = ?
        ORDER BY withdrawn_record_digest COLLATE BINARY`,
    ).all(this.witnessId) as Record<string, unknown>[];
    const selections: VerifiedWitnessRecoveryResolutionSelectionV1[] = [];
    for (const row of rows) {
      const witnessId = sqliteUuidV4(row, "witness_id");
      const withdrawnRecordDigest = sqliteSha256(row, "withdrawn_record_digest");
      const operationId = sqliteBoundedText(row, "operation_id", 256);
      const requestDigest = sqliteSha256(row, "request_digest");
      const resolutionDigestValue = sqliteSha256(row, "resolution_digest");
      const selectionRecordDigest = sqliteSha256(row, "selection_record_digest");
      let parsed: unknown;
      try {
        parsed = JSON.parse(sqliteText(row, "selection_record_json"));
      } catch {
        fail("WITNESS_REGISTRY_CORRUPT", "Recovery resolution selection JSON is invalid.");
      }
      let selection: WitnessRecoveryResolutionSelectionV1;
      try {
        selection = validateWitnessRecoveryResolutionSelection(parsed);
      } catch {
        fail("WITNESS_REGISTRY_CORRUPT", "Recovery resolution selection record is invalid.");
      }
      const withdrawn = historyByDigest.get(withdrawnRecordDigest);
      const expectedRequest = witnessRecoveryResolutionOperationKey(
        selection.witnessId,
        selection.bindingDigest,
        selection.withdrawnRecordDigest,
        selection.resolution.barrierRecordDigest,
        selection.resolutionDigest,
      );
      if (
        witnessId !== this.witnessId ||
        selection.witnessId !== witnessId ||
        selection.withdrawnRecordDigest !== withdrawnRecordDigest ||
        selection.operationId !== operationId ||
        requestDigest !== sha256Bytes(canonicalJson(expectedRequest)) ||
        selection.resolutionDigest !== resolutionDigestValue ||
        selectionRecordDigest !== sha256Bytes(canonicalJson(selection)) ||
        withdrawn === undefined ||
        withdrawn.record.state !== "WITHDRAWN" ||
        canonicalJson(withdrawn.record.highWatermark) !==
          canonicalJson(selection.resolution.highWatermark)
      ) {
        fail(
          "WITNESS_REGISTRY_CORRUPT",
          "Recovery resolution selection is not bound to one exact withdrawn witness record.",
        );
      }
      selections.push({ record: selection, recordDigest: selectionRecordDigest });
    }
    return selections;
  }

  async observe(bindingDigest: string): Promise<VerifiedWitnessRecord> {
    this.#requireAvailable();
    await verifyKernelContextLive(this.#context);
    const observed = cloneWitnessRecord(this.#readCurrent(bindingDigest));
    await verifyKernelContextLive(this.#context);
    return observed;
  }

  async observeRecoveryResolution(
    withdrawnRecordDigest: string,
  ): Promise<VerifiedWitnessRecoveryResolutionSelectionV1 | null> {
    this.#requireAvailable();
    if (!isSha256Digest(withdrawnRecordDigest)) {
      fail("RECOVERY_RESOLUTION_INVALID", "Withdrawn record digest is malformed.");
    }
    await verifyKernelContextLive(this.#context);
    const selection = this.#readRecoveryResolutionSelections().find(
      (item) => item.record.withdrawnRecordDigest === withdrawnRecordDigest,
    ) ?? null;
    await verifyKernelContextLive(this.#context);
    return selection === null
      ? null
      : JSON.parse(JSON.stringify(selection)) as VerifiedWitnessRecoveryResolutionSelectionV1;
  }

  async enroll(bindingDigest: string, tipValue: WitnessTipV1): Promise<VerifiedWitnessRecord> {
    this.#requireAvailable();
    const pending = this.#pendingEnrollment;
    if (pending === null || pending.bindingDigest !== bindingDigest) {
      fail("WITNESS_ENROLLMENT_INVALID", "Persistent enrollment intent is missing or mismatched.");
    }
    const tip = validateWitnessTip(tipValue);
    if (tip.storeId !== pending.storeId) {
      fail("WITNESS_BINDING_MISMATCH", "Persistent enrollment tip belongs to another store.");
    }
    const recordedAt = pending.createdAt;
    const record = validateWitnessRecord({
      schemaVersion: 1,
      recordType: "MONOTONIC_WITNESS",
      protocol: WITNESS_PROTOCOL,
      witnessId: this.witnessId,
      bindingDigest,
      witnessVersion: 0,
      previousWitnessRecordDigest: null,
      state: "SELECTED",
      highWatermark: tip,
      selectedTip: tip,
      withdrawal: null,
      recordedAt,
    });
    const recordDigest = sha256Bytes(canonicalJson(record));
    const operationId = `enroll:${pending.enrollmentId}`;
    const requestDigest = sha256Bytes(canonicalJson({ operationId, bindingDigest, tip }));
    const database = this.#context.database;
    await verifyKernelContextLive(this.#context);
    let committed = false;
    try {
      database.exec("BEGIN IMMEDIATE");
      verifyKernelContextPathIdentitySync(this.#context);
      attestPersistentRegistrySchema(database);
      const existingEnrollment = readPersistentEnrollmentByStoreId(this.#context, pending.storeId);
      const existingOperation = database.prepare(
        `SELECT request_digest, record_digest, record_json
           FROM witness_records WHERE operation_id = ?`,
      ).get(operationId) as Record<string, unknown> | undefined;
      if (existingEnrollment !== null || existingOperation !== undefined) {
        if (
          existingEnrollment === null ||
          existingOperation === undefined ||
          sqliteSha256(existingOperation, "request_digest") !== requestDigest ||
          sqliteSha256(existingOperation, "record_digest") !== recordDigest ||
          sqliteText(existingOperation, "record_json") !== canonicalJson(record) ||
          !persistentEnrollmentMatchesPending(existingEnrollment, pending, recordDigest)
        ) {
          fail(
            "WITNESS_ENROLLMENT_CONFLICT",
            "Existing persistent enrollment differs from the immutable enrollment intent.",
          );
        }
        database.exec("COMMIT");
        await verifyKernelContextLive(this.#context);
        return cloneWitnessRecord({ record, recordDigest });
      }
      const recordInsert = database.prepare(
        `INSERT INTO witness_records
           (witness_id, witness_version, record_digest, previous_record_digest,
            operation_id, request_digest, record_json)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      ).run(
        this.witnessId,
        0,
        recordDigest,
        null,
        operationId,
        requestDigest,
        canonicalJson(record),
      );
      if (recordInsert.changes !== 1) {
        fail("WITNESS_REGISTRY_CORRUPT", "Persistent enrollment did not append one witness record.");
      }
      const enrollmentInsert = database.prepare(
        `INSERT INTO witness_enrollments
           (store_id, enrollment_id, generation, canonical_store_path,
            store_device_id, store_inode_id, migration_digest,
            storage_admission_digest, witness_id, binding_digest, state,
            current_record_digest, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ACTIVE', ?, ?)`,
      ).run(
        pending.storeId,
        pending.enrollmentId,
        pending.generation,
        pending.canonicalStorePath,
        pending.storeDeviceId,
        pending.storeInodeId,
        pending.migrationRecordDigest,
        pending.storageAdmissionRecordDigest,
        pending.witnessId,
        pending.bindingDigest,
        recordDigest,
        pending.createdAt,
      );
      if (enrollmentInsert.changes !== 1) {
        fail("WITNESS_REGISTRY_CORRUPT", "Persistent enrollment did not create one registry row.");
      }
      database.exec("COMMIT");
      committed = true;
      simulateCrash({}, "AFTER_ENROLLMENT_REGISTRY_COMMIT_BEFORE_SESSION");
    } catch (error) {
      try { database.exec("ROLLBACK"); } catch { /* transaction may already be closed */ }
      rethrowPersistentRegistryError(error);
    }
    try {
      await verifyKernelContextLive(this.#context);
    } catch (error) {
      if (committed) {
        invalidateKernelContext(this.#context);
        fail(
          "WITNESS_RESULT_UNKNOWN",
          "Persistent enrollment committed but registry identity changed before confirmation.",
        );
      }
      throw error;
    }
    return cloneWitnessRecord({ record, recordDigest });
  }

  async #compareAndAppend(
    expectedRecordDigest: string,
    operationId: string,
    request: JsonValue,
    build: (current: VerifiedWitnessRecord) => WitnessRecordV1,
  ): Promise<VerifiedWitnessRecord> {
    this.#requireAvailable();
    if (operationId.length === 0 || operationId.length > 256) {
      fail("WITNESS_OPERATION_ID_INVALID", "Persistent witness operation ID length is invalid.");
    }
    if (!isSha256Digest(expectedRecordDigest)) {
      fail("WITNESS_RECORD_INVALID", "Persistent witness expected digest is malformed.");
    }
    const requestDigest = sha256Bytes(canonicalJson(request));
    const database = this.#context.database;
    let result: VerifiedWitnessRecord;
    let committedHere = false;
    await verifyKernelContextLive(this.#context);
    try {
      database.exec("BEGIN IMMEDIATE");
      verifyKernelContextPathIdentitySync(this.#context);
      attestPersistentRegistrySchema(database);
      const prior = database.prepare(
        `SELECT request_digest, record_digest FROM witness_records WHERE operation_id = ?`,
      ).get(operationId) as Record<string, unknown> | undefined;
      if (prior !== undefined) {
        if (sqliteText(prior, "request_digest") !== requestDigest) {
          fail(
            "WITNESS_OPERATION_ID_CONFLICT",
            "Persistent witness operation ID was reused with different bytes.",
          );
        }
        const recordDigest = sqliteText(prior, "record_digest");
        const current = this.#readHistory().find((item) => item.recordDigest === recordDigest);
        if (current === undefined) {
          fail("WITNESS_REGISTRY_CORRUPT", "Idempotent operation result is missing.");
        }
        result = current;
        database.exec("COMMIT");
      } else {
        const bindingRow = database.prepare(
          `SELECT binding_digest FROM witness_enrollments WHERE witness_id = ?`,
        ).get(this.witnessId) as Record<string, unknown> | undefined;
        if (bindingRow === undefined) {
          fail("WITNESS_ENROLLMENT_MISSING", "Persistent witness enrollment is missing.");
        }
        const current = this.#readCurrent(sqliteSha256(bindingRow, "binding_digest"));
        if (current.recordDigest !== expectedRecordDigest) {
          fail("WITNESS_CAS_CONFLICT", "Persistent witness changed before compare-and-swap.", {
            expectedRecordDigest,
            observedRecordDigest: current.recordDigest,
          });
        }
        const record = validateWitnessRecord(build(current));
        const recordDigest = sha256Bytes(canonicalJson(record));
        const recordInsert = database.prepare(
          `INSERT INTO witness_records
             (witness_id, witness_version, record_digest, previous_record_digest,
              operation_id, request_digest, record_json)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        ).run(
          this.witnessId,
          record.witnessVersion,
          recordDigest,
          current.recordDigest,
          operationId,
          requestDigest,
          canonicalJson(record),
        );
        if (recordInsert.changes !== 1) {
          fail("WITNESS_REGISTRY_CORRUPT", "Persistent CAS did not append one witness record.");
        }
        const enrollmentUpdate = database.prepare(
          `UPDATE witness_enrollments
              SET current_record_digest = ?, state = ?
            WHERE witness_id = ? AND current_record_digest = ?`,
        ).run(
          recordDigest,
          record.state === "WITHDRAWN" ? "WITHDRAWN" : "ACTIVE",
          this.witnessId,
          current.recordDigest,
        );
        if (enrollmentUpdate.changes !== 1) {
          fail("WITNESS_CAS_CONFLICT", "Persistent witness enrollment changed during compare-and-swap.");
        }
        result = { record, recordDigest };
        database.exec("COMMIT");
        committedHere = true;
      }
    } catch (error) {
      try { database.exec("ROLLBACK"); } catch { /* transaction may already be closed */ }
      rethrowPersistentRegistryError(error);
    }
    try {
      await verifyKernelContextLive(this.#context);
    } catch (error) {
      if (committedHere) {
        invalidateKernelContext(this.#context);
        fail(
          "WITNESS_RESULT_UNKNOWN",
          "Persistent witness may have committed before registry identity changed.",
          { operationId },
        );
      }
      throw error;
    }
    if (committedHere && this.#unknownAfterCommitOnce) {
      this.#unknownAfterCommitOnce = false;
      fail(
        "WITNESS_RESULT_UNKNOWN",
        "Persistent witness committed but the response was intentionally dropped.",
        { operationId },
      );
    }
    return cloneWitnessRecord(result);
  }

  async compareAndSelect(
    expectedRecordDigest: string,
    nextTipValue: WitnessTipV1,
    operationId: string,
  ): Promise<VerifiedWitnessRecord> {
    const nextTip = validateWitnessTip(nextTipValue);
    const request = witnessSelectOperationKey(
      this.witnessId,
      this.#bindingDigest,
      expectedRecordDigest,
      nextTip,
    );
    if (
      operationId !== witnessSelectOperationId(
        this.witnessId,
        this.#bindingDigest,
        expectedRecordDigest,
        nextTip,
      )
    ) {
      fail(
        operationId.startsWith("select:v1:")
          ? "WITNESS_OPERATION_ID_CONFLICT"
          : "WITNESS_OPERATION_ID_INVALID",
        "Persistent selection operation ID is not transition-bound.",
      );
    }
    return this.#compareAndAppend(expectedRecordDigest, operationId, request, (current) => {
      if (current.record.state !== "SELECTED") {
        fail("WITNESS_WITHDRAWN", "A withdrawn witness cannot select another tip.");
      }
      const previousTip = current.record.highWatermark;
      if (
        nextTip.storeId !== previousTip.storeId ||
        nextTip.revision !== previousTip.revision + 1 ||
        nextTip.previousCommitRecordDigest !== previousTip.commitRecordDigest
      ) {
        fail("WITNESS_MONOTONICITY_VIOLATION", "Persistent selection is not the exact successor.");
      }
      return {
        ...current.record,
        witnessVersion: current.record.witnessVersion + 1,
        previousWitnessRecordDigest: current.recordDigest,
        state: "SELECTED",
        highWatermark: nextTip,
        selectedTip: nextTip,
        withdrawal: null,
        recordedAt: new Date().toISOString(),
      };
    });
  }

  async compareAndWithdraw(
    expectedRecordDigest: string,
    requestValue: WitnessWithdrawalRequestV1,
    operationId: string,
  ): Promise<VerifiedWitnessRecord> {
    const withdrawalRequest = validateWitnessWithdrawalRequest(requestValue);
    const request = witnessWithdrawalOperationKey(
      this.witnessId,
      this.#bindingDigest,
      expectedRecordDigest,
      withdrawalRequest,
    );
    if (
      operationId !== witnessWithdrawalOperationId(
        this.witnessId,
        this.#bindingDigest,
        expectedRecordDigest,
        withdrawalRequest,
      )
    ) {
      fail(
        operationId.startsWith("withdraw:v1:")
          ? "WITNESS_OPERATION_ID_CONFLICT"
          : "WITNESS_OPERATION_ID_INVALID",
        "Persistent withdrawal operation ID is not transition-bound.",
      );
    }
    return this.#compareAndAppend(expectedRecordDigest, operationId, request, (current) => {
      if (current.record.state !== "SELECTED") {
        fail("WITNESS_WITHDRAWAL_CONFLICT", "Persistent witness is already withdrawn.");
      }
      if (!witnessWithdrawalRequestMatchesTip(withdrawalRequest, current.record.highWatermark)) {
        fail(
          "WITNESS_WITHDRAWAL_CONFLICT",
          "Persistent withdrawal does not describe the exact selected high-watermark.",
        );
      }
      const withdrawal = validateWitnessWithdrawal({
        ...withdrawalRequest,
        withdrawnAt: new Date().toISOString(),
      });
      return {
        ...current.record,
        witnessVersion: current.record.witnessVersion + 1,
        previousWitnessRecordDigest: current.recordDigest,
        state: "WITHDRAWN",
        selectedTip: null,
        withdrawal,
        recordedAt: withdrawal.withdrawnAt,
      };
    });
  }

  async selectRecoveryResolution(
    resolutionValue: CoordinatorRecoveryResolutionV1,
  ): Promise<VerifiedWitnessRecoveryResolutionSelectionV1> {
    this.#requireAvailable();
    const resolution = validateCoordinatorRecoveryResolution(resolutionValue);
    if (
      resolution.witnessId !== this.witnessId ||
      resolution.witnessBindingDigest !== this.#bindingDigest
    ) {
      fail("WITNESS_BINDING_MISMATCH", "Recovery resolution belongs to another witness binding.");
    }
    const resolutionDigestValue = recoveryResolutionDigest(resolution);
    const operationId = witnessRecoveryResolutionOperationId(
      this.witnessId,
      this.#bindingDigest,
      resolution.withdrawnRecordDigest,
      resolution.barrierRecordDigest,
      resolutionDigestValue,
    );
    const request = witnessRecoveryResolutionOperationKey(
      this.witnessId,
      this.#bindingDigest,
      resolution.withdrawnRecordDigest,
      resolution.barrierRecordDigest,
      resolutionDigestValue,
    );
    const requestDigest = sha256Bytes(canonicalJson(request));
    const selection = validateWitnessRecoveryResolutionSelection({
      schemaVersion: 1,
      recordType: "WITNESS_RECOVERY_RESOLUTION_SELECTION",
      protocol: RECOVERY_RESOLUTION_SELECTION_PROTOCOL,
      witnessId: this.witnessId,
      bindingDigest: this.#bindingDigest,
      withdrawnRecordDigest: resolution.withdrawnRecordDigest,
      resolutionDigest: resolutionDigestValue,
      resolution,
      operationId,
    });
    const selectionRecordDigest = sha256Bytes(canonicalJson(selection));
    const database = this.#context.database;
    let committedHere = false;
    await verifyKernelContextLive(this.#context);
    try {
      database.exec("BEGIN IMMEDIATE");
      verifyKernelContextPathIdentitySync(this.#context);
      attestPersistentRegistrySchema(database);
      const current = this.#readCurrent(this.#bindingDigest);
      if (
        current.record.state !== "WITHDRAWN" ||
        current.recordDigest !== resolution.withdrawnRecordDigest ||
        canonicalJson(current.record.highWatermark) !== canonicalJson(resolution.highWatermark)
      ) {
        fail(
          "RECOVERY_WITHDRAWAL_REQUIRED",
          "Recovery resolution requires the exact terminal withdrawn witness record.",
        );
      }
      if (current.record.previousWitnessRecordDigest === null) {
        fail("WITNESS_REGISTRY_CORRUPT", "Withdrawn witness lacks its selected predecessor.");
      }
      const currentWithdrawal = validateWitnessWithdrawal(current.record.withdrawal);
      const currentWithdrawalRequest = validateWitnessWithdrawalRequest({
        recoveryIntent: currentWithdrawal.recoveryIntent,
        recoveryIntentDigest: currentWithdrawal.recoveryIntentDigest,
      });
      const expectedWithdrawalOperationId = witnessWithdrawalOperationId(
        this.witnessId,
        this.#bindingDigest,
        current.record.previousWitnessRecordDigest,
        currentWithdrawalRequest,
      );
      if (
        resolution.storeId !== current.record.highWatermark.storeId ||
        resolution.recoveryIntentDigest !== currentWithdrawal.recoveryIntentDigest ||
        resolution.withdrawalOperationId !== expectedWithdrawalOperationId ||
        resolution.recoveryRevision !== currentWithdrawal.recoveryIntent.toRevision ||
        resolution.observedReferenceDigest !==
          currentWithdrawal.recoveryIntent.observedReferenceDigest ||
        resolution.observedReferenceTransactionId !==
          currentWithdrawal.recoveryIntent.observedReferenceTransactionId
      ) {
        fail(
          "RECOVERY_RESOLUTION_INVALID",
          "Recovery resolution is not semantically bound to the exact witness withdrawal.",
        );
      }
      const rows = database.prepare(
        `SELECT withdrawn_record_digest, operation_id, request_digest,
                resolution_digest, selection_record_digest, selection_record_json
           FROM witness_recovery_resolutions
          WHERE withdrawn_record_digest = ? OR operation_id = ?`,
      ).all(resolution.withdrawnRecordDigest, operationId) as Record<string, unknown>[];
      if (rows.length > 1) {
        fail("WITNESS_REGISTRY_CORRUPT", "Recovery resolution identities select multiple rows.");
      }
      const existing = rows[0];
      if (existing !== undefined) {
        if (
          sqliteSha256(existing, "withdrawn_record_digest") !== resolution.withdrawnRecordDigest ||
          sqliteBoundedText(existing, "operation_id", 256) !== operationId ||
          sqliteSha256(existing, "request_digest") !== requestDigest ||
          sqliteSha256(existing, "resolution_digest") !== resolutionDigestValue ||
          sqliteSha256(existing, "selection_record_digest") !== selectionRecordDigest ||
          sqliteText(existing, "selection_record_json") !== canonicalJson(selection)
        ) {
          fail(
            "RECOVERY_RESOLUTION_CONFLICT",
            "A different recovery resolution already selects this withdrawal or operation.",
          );
        }
      } else {
        const inserted = database.prepare(
          `INSERT INTO witness_recovery_resolutions
             (witness_id, withdrawn_record_digest, operation_id, request_digest,
              resolution_digest, selection_record_digest, selection_record_json)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        ).run(
          this.witnessId,
          resolution.withdrawnRecordDigest,
          operationId,
          requestDigest,
          resolutionDigestValue,
          selectionRecordDigest,
          canonicalJson(selection),
        );
        if (inserted.changes !== 1) {
          fail("WITNESS_REGISTRY_CORRUPT", "Recovery resolution did not append exactly once.");
        }
        committedHere = true;
      }
      database.exec("COMMIT");
    } catch (error) {
      try { database.exec("ROLLBACK"); } catch { /* transaction may already be closed */ }
      rethrowPersistentRegistryError(error);
    }
    try {
      await verifyKernelContextLive(this.#context);
    } catch (error) {
      if (committedHere) {
        invalidateKernelContext(this.#context);
        fail(
          "WITNESS_RESULT_UNKNOWN",
          "Recovery resolution may have committed before registry identity changed.",
          { operationId },
        );
      }
      throw error;
    }
    if (committedHere && this.#unknownAfterCommitOnce) {
      this.#unknownAfterCommitOnce = false;
      fail(
        "WITNESS_RESULT_UNKNOWN",
        "Recovery resolution committed but the response was intentionally dropped.",
        { operationId },
      );
    }
    const observed = await this.observeRecoveryResolution(resolution.withdrawnRecordDigest);
    if (
      observed === null ||
      observed.recordDigest !== selectionRecordDigest ||
      canonicalJson(observed.record) !== canonicalJson(selection)
    ) {
      fail("RECOVERY_RESOLUTION_INCONCLUSIVE", "Recovery resolution readback is not exact.");
    }
    return observed;
  }
}

async function openPrivatePersistentKernelContext(
  registryRootPath: string,
  allowCreate: boolean,
): Promise<KernelContextV1> {
  const requestedRoot = resolve(registryRootPath);
  let canonicalParent: string;
  try {
    canonicalParent = await realpath(dirname(requestedRoot));
  } catch {
    fail("WITNESS_REGISTRY_UNAVAILABLE", "Persistent witness registry parent is unavailable.");
  }
  if (canonicalParent !== dirname(requestedRoot)) {
    fail("WITNESS_REGISTRY_REBIND_REQUIRED", "Registry parent must be canonical.");
  }
  const parent = await lstat(canonicalParent);
  const effectiveUid = typeof process.getuid === "function" ? process.getuid() : null;
  if (
    effectiveUid === null ||
    parent.uid !== effectiveUid ||
    (parent.mode & 0o022) !== 0
  ) {
    fail("WITNESS_REGISTRY_PERMISSIONS_INVALID", "Registry parent is not private to the current user.");
  }
  const parentFilesystem = await statfs(canonicalParent);
  requireAdmittedStorageFacts(platform(), String(parentFilesystem.type));
  await observeDarwinApfsBackend(canonicalParent, String(parent.dev));
  if (!(await pathExists(requestedRoot))) {
    if (!allowCreate) {
      fail("WITNESS_REGISTRY_UNAVAILABLE", "Fixed persistent witness registry is unavailable.");
    }
    await mkdir(requestedRoot, { recursive: false, mode: 0o700 });
    await syncDirectory(canonicalParent);
  }
  const canonicalRegistryRoot = await realpath(requestedRoot);
  const registry = await lstat(canonicalRegistryRoot);
  if (
    canonicalRegistryRoot !== requestedRoot ||
    !registry.isDirectory() ||
    registry.isSymbolicLink() ||
    registry.uid !== effectiveUid ||
    (registry.mode & 0o7777) !== 0o700
  ) {
    fail("WITNESS_REGISTRY_PERMISSIONS_INVALID", "Registry root identity or mode is invalid.");
  }
  const databasePath = join(canonicalRegistryRoot, "registry.sqlite");
  let created = false;
  if (!(await pathExists(databasePath))) {
    if (!allowCreate) {
      fail("WITNESS_REGISTRY_UNAVAILABLE", "Fixed persistent witness registry database is unavailable.");
    }
    const handle = await open(databasePath, "wx", 0o600);
    await handle.sync();
    await handle.close();
    await syncDirectory(canonicalRegistryRoot);
    created = true;
  }
  const databaseInfo = await lstat(databasePath);
  if (
    !databaseInfo.isFile() ||
    databaseInfo.isSymbolicLink() ||
    databaseInfo.uid !== effectiveUid ||
    databaseInfo.dev !== registry.dev ||
    databaseInfo.nlink !== 1 ||
    (databaseInfo.mode & 0o7777) !== 0o600
  ) {
    fail("WITNESS_REGISTRY_PERMISSIONS_INVALID", "Registry database identity or mode is invalid.");
  }
  let database: DatabaseSync;
  try {
    database = new DatabaseSync(databasePath);
  } catch (error) {
    rethrowPersistentRegistryError(error);
  }
  let registryId: string;
  try {
    registryId = initializePersistentRegistry(database, created);
  } catch (error) {
    database.close();
    throw error;
  }
  const handle = Object.freeze<KernelContextV1>({
    capability: KERNEL_CONTEXT_CAPABILITY,
    contextId: randomUUID(),
  });
  const state: KernelContextStateV1 = {
    handle,
    canonicalRegistryRoot,
    registryDeviceId: String(registry.dev),
    registryInodeId: String(registry.ino),
    registryId,
    databasePath,
    databaseDeviceId: String(databaseInfo.dev),
    databaseInodeId: String(databaseInfo.ino),
    database,
    invalidated: false,
  };
  kernelContextStatesByHandle.set(handle, state);
  kernelContextHandlesByCanonicalRoot.set(canonicalRegistryRoot, handle);
  return handle;
}

async function openPrivatePersistentKernelContextForSelfTest(
  registryRootPath: string,
): Promise<KernelContextV1> {
  if (!boundedTestLaneActive()) {
    fail(
      "TEST_ONLY_KERNEL_CONTEXT_REJECTED",
      "The private persistent context fixture is available only to the embedded test lane.",
    );
  }
  return openPrivatePersistentKernelContext(registryRootPath, true);
}

function requireKernelContextState(context: KernelContextV1): KernelContextStateV1 {
  const state = kernelContextStatesByHandle.get(context);
  if (
    state === undefined ||
    state.invalidated ||
    !Object.isFrozen(context) ||
    context.capability !== KERNEL_CONTEXT_CAPABILITY
  ) {
    fail("KERNEL_CONTEXT_INVALID", "Kernel context is not registry-issued in this process.");
  }
  return state;
}

function closePrivatePersistentKernelContextForSelfTest(context: KernelContextV1): void {
  const state = kernelContextStatesByHandle.get(context);
  if (state === undefined) return;
  state.database.close();
  kernelContextStatesByHandle.delete(context);
  if (kernelContextHandlesByCanonicalRoot.get(state.canonicalRegistryRoot) === context) {
    kernelContextHandlesByCanonicalRoot.delete(state.canonicalRegistryRoot);
  }
}

const witnessStatesByCanonicalStorePath = new Map<string, WitnessSessionStateV1>();
const witnessStatesByPhysicalStoreIdentity = new Map<string, WitnessSessionStateV1>();
const witnessStatesByStoreId = new Map<string, WitnessSessionStateV1>();
let witnessStatesByHandle = new WeakMap<WitnessSessionV1, WitnessSessionStateV1>();

type ObservedStoreIdentity = {
  canonicalStorePath: string;
  storeDeviceId: string;
  storeInodeId: string;
};

function physicalStoreIdentityKey(identity: ObservedStoreIdentity): string {
  return `${identity.storeDeviceId}:${identity.storeInodeId}`;
}

async function observeStoreIdentity(storePath: string): Promise<ObservedStoreIdentity> {
  const canonicalStorePath = await realpath(resolve(storePath));
  const information = await lstat(canonicalStorePath);
  if (!information.isDirectory()) {
    fail("STORE_NOT_DIRECTORY", "Veritas store root must be a directory.");
  }
  return {
    canonicalStorePath,
    storeDeviceId: String(information.dev),
    storeInodeId: String(information.ino),
  };
}

type DurableCoordinatorIdentity = {
  storeId: string;
  migrationRecordDigest: string | null;
  storageAdmissionRecordDigest: string | null;
  source: "COMMIT_SPINE" | "HEAD_ONLY";
};

async function readDurableCoordinatorIdentityForWitnessLookup(
  storePath: string,
): Promise<DurableCoordinatorIdentity | null> {
  const commitDirectory = join(storePath, "coordinator", "commits");
  const commitNames = (await pathExists(commitDirectory))
    ? (await readdir(commitDirectory)).filter((name) => name.endsWith(".json"))
    : [];
  if (commitNames.length !== 0) {
    const chain = await readCoordinatorCommitChainUnlocked(storePath);
    const latest = chain.at(-1);
    if (latest === undefined) {
      fail("COORDINATOR_COMMIT_MISSING", "Coordinator commit spine disappeared during admission.");
    }
    await verifyCoordinatorMigrationUnlocked(storePath, latest.state);
    return {
      storeId: latest.state.storeId,
      migrationRecordDigest: latest.state.migrationRecordDigest,
      storageAdmissionRecordDigest: latest.state.storageAdmissionRecordDigest,
      source: "COMMIT_SPINE",
    };
  }
  if (!(await pathExists(coordinatorHeadPath(storePath)))) return null;
  return {
    storeId: (await readCoordinatorHeadUnlocked(storePath)).head.storeId,
    migrationRecordDigest: null,
    storageAdmissionRecordDigest: null,
    source: "HEAD_ONLY",
  };
}

function fixedPersistentRegistryConfiguration(): { path: string; requiredWhenAbsent: boolean } {
  const testAccountHome = process.env.VERITAS_TEST_OS_ACCOUNT_HOME;
  if (testAccountHome !== undefined) {
    if (!boundedTestLaneActive()) {
      fail(
        "WITNESS_REGISTRY_CONFIG_INVALID",
        "OS-account home substitution is available only to the bounded test harness.",
      );
    }
    if (testAccountHome.length === 0 || !isAbsolute(testAccountHome)) {
      fail("WITNESS_REGISTRY_CONFIG_INVALID", "Test OS-account home must be absolute.");
    }
    return {
      path: join(
        resolve(testAccountHome),
        "Library",
        "Application Support",
        "Veritas",
        "private-witness-v1",
      ),
      requiredWhenAbsent: true,
    };
  }
  const override = process.env.VERITAS_PRIVATE_REGISTRY_ROOT;
  if (override !== undefined) {
    if (!boundedTestLaneActive()) {
      fail(
        "WITNESS_REGISTRY_CONFIG_INVALID",
        "Persistent registry path override is accepted only in the test lane.",
      );
    }
    if (override.length === 0 || !isAbsolute(override)) {
      fail("WITNESS_REGISTRY_CONFIG_INVALID", "Persistent registry path override must be absolute.");
    }
    return { path: resolve(override), requiredWhenAbsent: true };
  }
  if (boundedTestLaneActive()) {
    return {
      path: join(tmpdir(), `veritas-self-test-unconfigured-registry-${process.pid}`),
      requiredWhenAbsent: false,
    };
  }
  let accountHome: string;
  try {
    accountHome = userInfo().homedir;
  } catch {
    fail("WITNESS_REGISTRY_CONFIG_INVALID", "OS account home cannot be resolved.");
  }
  if (!isAbsolute(accountHome) || resolve(accountHome) !== accountHome) {
    fail("WITNESS_REGISTRY_CONFIG_INVALID", "OS account home is not an absolute canonical path.");
  }
  return {
    path: join(accountHome, "Library", "Application Support", "Veritas", "private-witness-v1"),
    requiredWhenAbsent: true,
  };
}

async function openExistingFixedPersistentKernelContext(
  enrollmentIntentPresent: boolean,
  configuration = fixedPersistentRegistryConfiguration(),
): Promise<KernelContextV1 | null> {
  if (!(await pathExists(configuration.path))) {
    if (configuration.requiredWhenAbsent || enrollmentIntentPresent) {
      fail("WITNESS_REGISTRY_UNAVAILABLE", "Fixed persistent witness registry is unavailable.");
    }
    return null;
  }
  let canonicalRoot: string;
  try {
    canonicalRoot = await realpath(configuration.path);
  } catch {
    fail("WITNESS_REGISTRY_UNAVAILABLE", "Fixed persistent witness registry cannot be resolved.");
  }
  const existing = kernelContextHandlesByCanonicalRoot.get(canonicalRoot);
  if (existing !== undefined) {
    await verifyKernelContextLive(requireKernelContextState(existing));
    return existing;
  }
  return openPrivatePersistentKernelContext(configuration.path, false);
}

async function findRegisteredWitnessState(
  storePath: string,
): Promise<WitnessSessionStateV1 | undefined> {
  const identity = await observeStoreIdentity(storePath);
  const candidates = new Set<WitnessSessionStateV1>();
  const byPath = witnessStatesByCanonicalStorePath.get(identity.canonicalStorePath);
  const byPhysical = witnessStatesByPhysicalStoreIdentity.get(
    physicalStoreIdentityKey(identity),
  );
  if (byPath !== undefined) candidates.add(byPath);
  if (byPhysical !== undefined) candidates.add(byPhysical);

  const durableIdentity = await readDurableCoordinatorIdentityForWitnessLookup(
    identity.canonicalStorePath,
  );
  if (durableIdentity !== null) {
    const byStoreId = witnessStatesByStoreId.get(durableIdentity.storeId);
    if (byStoreId !== undefined) candidates.add(byStoreId);
  }
  if (candidates.size === 0) {
    const intent = await readPersistentEnrollmentIntent(identity.canonicalStorePath);
    const fixedConfiguration = fixedPersistentRegistryConfiguration();
    const fixedContext = await openExistingFixedPersistentKernelContext(
      intent !== null,
      fixedConfiguration,
    );
    if (fixedContext !== null && durableIdentity !== null) {
      const context = requireKernelContextState(fixedContext);
      const enrollment = readPersistentEnrollmentByStoreId(context, durableIdentity.storeId);
      if (enrollment !== null) {
        const session = await loadPersistentSessionFromEnrollment(
          context,
          identity.canonicalStorePath,
          identity,
          durableIdentity,
          enrollment,
          intent,
        );
        const state = witnessStatesByHandle.get(session);
        if (state === undefined) {
          fail("WITNESS_SESSION_NOT_ENROLLED", "Fixed persistent witness session was not registered.");
        }
        candidates.add(state);
      } else if (intent !== null) {
        if (intent.registryId !== context.registryId || intent.storeId !== durableIdentity.storeId) {
          fail("WITNESS_ENROLLMENT_CONFLICT", "Enrollment intent targets another fixed registry or store.");
        }
        fail(
          "WITNESS_ENROLLMENT_PENDING",
          "Persistent enrollment intent exists but its registry row is not committed.",
        );
      } else if (fixedConfiguration.requiredWhenAbsent) {
        fail(
          "WITNESS_ENROLLMENT_MISSING",
          "The required fixed registry has no enrollment for this initialized coordinator.",
        );
      }
    } else if (intent !== null) {
      fail("WITNESS_REGISTRY_UNAVAILABLE", "Enrollment intent exists but its fixed registry is unavailable.");
    }
    if (candidates.size === 0) return undefined;
  }
  if (candidates.size !== 1) {
    fail("WITNESS_ADMISSION_CONFLICT", "Witness registries disagree about store identity.");
  }
  const state = [...candidates][0];
  if (
    state.canonicalStorePath !== identity.canonicalStorePath ||
    state.storeDeviceId !== identity.storeDeviceId ||
    state.storeInodeId !== identity.storeInodeId ||
    (durableIdentity !== null && durableIdentity.storeId !== state.storeId) ||
    (durableIdentity !== null &&
      durableIdentity.migrationRecordDigest !== null &&
      durableIdentity.migrationRecordDigest !== state.migrationRecordDigest) ||
    (durableIdentity !== null &&
      durableIdentity.storageAdmissionRecordDigest !== null &&
      durableIdentity.storageAdmissionRecordDigest !== state.storageAdmissionRecordDigest)
  ) {
    fail(
      "WITNESS_REBIND_REQUIRED",
      "Witness-enrolled store path or physical identity changed without an explicit rebind.",
    );
  }
  return state;
}

async function requireRegisteredWitnessSession(
  storePath: string,
  provided?: WitnessSessionV1,
): Promise<WitnessSessionStateV1 | undefined> {
  const registered = await findRegisteredWitnessState(storePath);
  if (registered === undefined) {
    if (provided !== undefined) {
      fail("WITNESS_SESSION_NOT_ENROLLED", "Witness session is not enrolled for this store.");
    }
    return undefined;
  }
  if (
    (provided === undefined && registered.admissionSource !== "FIXED_PERSISTENT") ||
    (provided !== undefined && provided !== registered.handle) ||
    (provided !== undefined && !Object.isFrozen(provided)) ||
    (provided !== undefined && provided.capability !== WITNESS_SESSION_CAPABILITY) ||
    (provided !== undefined && witnessStatesByHandle.get(provided) !== registered) ||
    registered.witness.witnessId !== registered.witnessId
  ) {
    fail("WITNESS_CONTEXT_REQUIRED", "This witness-enrolled store requires its exact admitted session.");
  }
  return registered;
}

function admitWitnessForProfile(
  witness: MonotonicWitnessV1,
  profile: "TEACHING_PROTOCOL" | "PRODUCTION",
): void {
  if (witness.protocol !== WITNESS_PROTOCOL) {
    fail("WITNESS_PROTOCOL_UNSUPPORTED", "Witness protocol version is unsupported.");
  }
  if (profile === "PRODUCTION") {
    if (witness.implementationClass === "TEST_ONLY_ORACLE") {
      fail(
        "TEST_ONLY_WITNESS_REJECTED",
        "The in-memory test oracle is mechanically ineligible for production admission.",
      );
    }
    if (witness.implementationClass === "PRIVATE_PERSISTENT_FIXTURE") {
      fail(
        "PRIVATE_PERSISTENT_WITNESS_REJECTED",
        "The same-user SQLite witness fixture is mechanically ineligible for production admission.",
      );
    }
    if (witness.implementationClass === "AUTHENTICATED_TRANSPORT_PROTOCOL_FIXTURE") {
      fail(
        "AUTHENTICATED_TRANSPORT_FIXTURE_REJECTED",
        "The same-UID authenticated transport protocol fixture is mechanically ineligible for protected admission.",
      );
    }
    fail(
      "PRODUCTION_WITNESS_BACKEND_NOT_IMPLEMENTED",
      "No registry-issued protected witness backend exists in the teaching kernel.",
    );
  }
}

function storageAdmissionDirectory(storePath: string): string {
  return join(storePath, "coordinator", "storage-admissions");
}

function storageAdmissionPath(storePath: string, digest: string): string {
  return join(storageAdmissionDirectory(storePath), `${digest}.json`);
}

async function runBoundedHostCommand(command: string, args: string[]): Promise<string> {
  return new Promise<string>((resolvePromise, rejectPromise) => {
    const child = spawn(command, args, {
      stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env, LANG: "C", LC_ALL: "C" },
    });
    let stdout = "";
    let stderr = "";
    let outputBytes = 0;
    let settled = false;
    const finishReject = (error: unknown): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      rejectPromise(error);
    };
    const timeout = setTimeout(() => {
      if (!settled) {
        child.kill("SIGKILL");
        finishReject(new VeritasError(
          "STORAGE_HOST_ATTESTATION_TIMEOUT",
          "Host storage command exceeded its five-second time bound.",
          { command },
        ));
      }
    }, 5_000);
    const append = (current: string, chunk: Buffer): string => {
      if (settled) return current;
      outputBytes += chunk.byteLength;
      if (outputBytes > 256 * 1024) {
        child.kill("SIGKILL");
        finishReject(new VeritasError(
          "STORAGE_HOST_ATTESTATION_FAILED",
          "Host storage command exceeded its output bound.",
          { command },
        ));
        return current;
      }
      return current + chunk.toString("utf8");
    };
    child.stdout.on("data", (chunk: Buffer) => {
      stdout = append(stdout, chunk);
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr = append(stderr, chunk);
    });
    child.once("error", finishReject);
    child.once("close", (code, signal) => {
      if (settled) return;
      if (code !== 0 || signal !== null) {
        finishReject(
          new VeritasError(
            "STORAGE_HOST_ATTESTATION_FAILED",
            "Host storage command failed.",
            { command, code, signal, stderr: stderr.slice(0, 4096) },
          ),
        );
        return;
      }
      settled = true;
      clearTimeout(timeout);
      resolvePromise(stdout);
    });
  });
}

