async function readAlphaProfile(profilePath: string): Promise<AlphaProfileV1> {
  const { bytes } = await readStableRegularFile(profilePath, "ALPHA_PROFILE_INVALID", "Alpha profile");
  let parsed: unknown;
  try {
    parsed = JSON.parse(bytes.toString("utf8")) as unknown;
  } catch {
    fail("ALPHA_PROFILE_INVALID", "Alpha profile must be canonical JSON.");
  }
  requireExactObjectKeys(parsed, ALPHA_PROFILE_KEYS, "ALPHA_PROFILE_INVALID", "Alpha profile");
  const profile = readAlphaProfileShape(parsed);
  const canonicalBytes = `${canonicalJson(profile)}\n`;
  if (bytes.toString("utf8") !== canonicalBytes) {
    fail("ALPHA_PROFILE_NONCANONICAL", "Alpha profile bytes must equal canonical JSON followed by one newline.");
  }
  return profile;
}

function computeAlphaProfileDigest(profile: AlphaProfileV1, binding: AlphaProfileProposalBindingV1): string {
  return sha256Bytes(canonicalJson({ recordType: "ALPHA_PROFILE_PROPOSAL", binding, profile }));
}

function validateAlphaProfileProposal(value: unknown): AlphaProfileProposalV1 {
  requireExactObjectKeys(value, ALPHA_PROFILE_PROPOSAL_KEYS, "ALPHA_PROFILE_RECORD_INVALID", "Alpha profile proposal");
  const record = value as Partial<AlphaProfileProposalV1>;
  const profile = readAlphaProfileShape(record);
  const binding: AlphaProfileProposalBindingV1 = { authorityDigest: record.authorityDigest ?? "", decisionId: record.decisionId ?? "", decisionDigest: record.decisionDigest ?? "", candidateDigest: record.candidateDigest ?? "", dependencyEpoch: record.dependencyEpoch ?? -1, targetId: record.targetId as "local-content-addressed-alpha" };
  if (record.recordType !== "ALPHA_PROFILE_PROPOSAL" || !isSha256Digest(binding.authorityDigest) || typeof binding.decisionId !== "string" || binding.decisionId.length === 0 || !isSha256Digest(binding.decisionDigest) || !isSha256Digest(binding.candidateDigest) || profile.expectedProjectDigest !== binding.candidateDigest || !Number.isSafeInteger(binding.dependencyEpoch) || binding.dependencyEpoch < 0 || binding.targetId !== "local-content-addressed-alpha" || !isSha256Digest(record.profileDigest) || record.profileDigest !== computeAlphaProfileDigest(profile, binding)) {
    fail("ALPHA_PROFILE_RECORD_INVALID", "Alpha profile proposal integrity or authority reference is invalid.");
  }
  return { ...profile, ...binding, recordType: "ALPHA_PROFILE_PROPOSAL", profileDigest: record.profileDigest };
}

function readAlphaProfileShape(value: unknown): AlphaProfileV1 {
  const profile = value as Partial<AlphaProfileV1>;
  if (profile.schemaVersion !== 1 || typeof profile.profileId !== "string" || profile.profileId.length === 0 || typeof profile.projectRoot !== "string" || profile.projectRoot.length === 0 || typeof profile.executablePath !== "string" || !isAbsolute(profile.executablePath) || !isSha256Digest(profile.executableDigest ?? "") || !isSha256Digest(profile.expectedProjectDigest ?? "") || !Array.isArray(profile.args) || profile.args.some((arg) => typeof arg !== "string") || !Number.isSafeInteger(profile.timeoutMs) || (profile.timeoutMs ?? 0) < 100 || (profile.timeoutMs ?? 0) > 60_000) {
    fail("ALPHA_PROFILE_INVALID", "Alpha profile must bind one absolute executable, exact digests, arguments, project root, and bounded timeout.");
  }
  return { schemaVersion: 1, profileId: profile.profileId, projectRoot: profile.projectRoot, executablePath: profile.executablePath, executableDigest: profile.executableDigest, expectedProjectDigest: profile.expectedProjectDigest, args: [...profile.args], timeoutMs: profile.timeoutMs } as AlphaProfileV1;
}

function assertAlphaExecutableSingleLink(identity: FileIdentityStamp): void {
  if (identity.linkCount !== "1") {
    fail(
      "ALPHA_EXECUTABLE_HARDLINK_ALIAS",
      "Alpha executable admission requires one filesystem link so candidate or store aliases cannot share its inode.",
      { linkCount: identity.linkCount },
    );
  }
}

async function proposeAlphaProfile(storePath: string, decisionPath: string, profilePath: string): Promise<AlphaProfileProposalV1> {
  const store = await ensureStore(storePath);
  const profile = await readAlphaProfile(profilePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    if (ready.state.phase !== "READY") fail("COORDINATOR_NOT_READY", "Alpha profile proposal requires a READY coordinator state.");
    const decision = await loadDecision(store, decisionPath);
    const observedBase = ready.state.destination?.objectDigest ?? null;
    if (observedBase !== decision.expectedBaseDigest) {
      fail("BASE_DIGEST_MISMATCH", "Accepted target changed after the alpha profile decision was created.", {
        expected: decision.expectedBaseDigest,
        observed: observedBase,
      });
    }
    const projectRoot = await realpath(profile.projectRoot);
    if (projectRoot !== decision.candidateSourcePath || profile.expectedProjectDigest !== decision.candidate.digest) {
      fail("ALPHA_DECISION_SUBJECT_MISMATCH", "Profile proposal must bind the exact decision candidate path and digest.");
    }
    const executablePath = await realpath(profile.executablePath);
    if (isWithin(projectRoot, executablePath) || isWithin(store, executablePath)) fail("ALPHA_EXECUTABLE_NOT_SEPARATED", "Alpha executable must be outside candidate and state-store content.");
    const executable = await readStableRegularFile(executablePath, "ALPHA_EXECUTABLE_INVALID", "Alpha executable");
    assertAlphaExecutableSingleLink(executable.identity);
    if (sha256Bytes(executable.bytes) !== profile.executableDigest) fail("ALPHA_EXECUTABLE_DIGEST_MISMATCH", "Alpha executable differs from the proposed profile.");
    const enrolledAuthority = validateAuthority(await readEnvelope<unknown>(join(store, "authorities", `${decision.authorityDigest}.json`)));
    if (sha256Bytes(`${AUTHORITY_PROFILE}\0${canonicalJson(enrolledAuthority)}`) !== decision.authorityDigest) fail("ALPHA_AUTHORITY_MISMATCH", "Decision authority snapshot is invalid.");
    const { objectFingerprint } = await validateDecisionInputsUnlocked(store, decision);
    if (objectFingerprint.digest !== profile.expectedProjectDigest) fail("ALPHA_PREPARED_OBJECT_MISMATCH", "Decision prepared candidate object differs from the profile subject.");
    const canonicalProfile: AlphaProfileV1 = { ...profile, projectRoot, executablePath };
    const binding: AlphaProfileProposalBindingV1 = { authorityDigest: decision.authorityDigest, decisionId: decision.decisionId, decisionDigest: sha256Bytes(canonicalJson(decision)), candidateDigest: decision.candidate.digest, dependencyEpoch: decision.dependencyEpoch, targetId: decision.targetId };
    const profileDigest = computeAlphaProfileDigest(canonicalProfile, binding);
    const record: AlphaProfileProposalV1 = { ...canonicalProfile, ...binding, recordType: "ALPHA_PROFILE_PROPOSAL", profileDigest };
    await writeImmutableRecord(join(store, "alpha-profile-proposals", `${profileDigest}.json`), record);
    return record;
  });
}

async function loadAlphaProfileClosureUnlocked(
  store: string,
  profileDigest: string,
  ready: CoordinatorSnapshot,
): Promise<LoadedAlphaProfileClosureV1> {
  if (!isSha256Digest(profileDigest)) fail("ALPHA_PROFILE_DIGEST_INVALID", "Alpha profile lookup requires an exact SHA-256 digest.");
  if (ready.state.phase !== "READY") fail("COORDINATOR_NOT_READY", "Alpha profile loading requires a READY coordinator state.");
  const verifiedProposal = await readVerifiedEnvelope<unknown>(join(store, "alpha-profile-proposals", `${profileDigest}.json`));
  const record = validateAlphaProfileProposal(verifiedProposal.record);
  if (record.profileDigest !== profileDigest) fail("ALPHA_PROFILE_DIGEST_MISMATCH", "Alpha profile pathname and record digest disagree.");
  const authority = validateAuthority(await readEnvelope<unknown>(join(store, "authorities", `${record.authorityDigest}.json`)));
  if (sha256Bytes(`${AUTHORITY_PROFILE}\0${canonicalJson(authority)}`) !== record.authorityDigest) fail("ALPHA_AUTHORITY_MISMATCH", "Profile proposal authority record is invalid.");
  const decision = await loadDecision(
    store,
    await uuidRecordPath(store, "decisions", record.decisionId, "INVALID_DECISION", true),
  );
  const decisionDigest = sha256Bytes(canonicalJson(decision));
  if (decisionDigest !== record.decisionDigest || decision.authorityDigest !== record.authorityDigest || decision.candidate.digest !== record.candidateDigest || decision.candidateSourcePath !== record.projectRoot || decision.dependencyEpoch !== record.dependencyEpoch || decision.targetId !== record.targetId) fail("ALPHA_DECISION_BINDING_MISMATCH", "Profile proposal decision binding is invalid.");
  const observedBase = ready.state.destination?.objectDigest ?? null;
  if (observedBase !== decision.expectedBaseDigest) fail("BASE_DIGEST_MISMATCH", "Accepted target changed after the loaded alpha profile decision was created.");
  const { objectFingerprint } = await validateDecisionInputsUnlocked(store, decision);
  if (objectFingerprint.digest !== record.candidateDigest) fail("ALPHA_PREPARED_OBJECT_MISMATCH", "Loaded alpha profile prepared object differs from its candidate binding.");
  const executablePath = await realpath(record.executablePath);
  if (executablePath !== record.executablePath || isWithin(record.projectRoot, executablePath) || isWithin(store, executablePath)) fail("ALPHA_EXECUTABLE_NOT_SEPARATED", "Loaded alpha executable path is no longer canonical and separated.");
  const executable = await readStableRegularFile(executablePath, "ALPHA_EXECUTABLE_INVALID", "Alpha executable");
  assertAlphaExecutableSingleLink(executable.identity);
  if (sha256Bytes(executable.bytes) !== record.executableDigest) fail("ALPHA_EXECUTABLE_DIGEST_MISMATCH", "Loaded alpha executable differs from the proposal.");
  return {
    proposal: record,
    proposalRecordDigest: verifiedProposal.recordDigest,
    decision,
    decisionDigest,
  };
}

async function loadAlphaProfileProposal(storePath: string, profileDigest: string): Promise<AlphaProfileProposalV1> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    return (await loadAlphaProfileClosureUnlocked(store, profileDigest, ready)).proposal;
  });
}

function alphaExecutionArgsDigest(args: string[]): string {
  return sha256Bytes(`veritas-alpha-argv-v1\0${canonicalJson(args)}`);
}

function computeAlphaExecutionApprovalDigest(
  body: Omit<AlphaExecutionApprovalV1, "approvalDigest">,
): string {
  return sha256Bytes(`${ALPHA_EXECUTION_APPROVAL_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaExecutionApproval(value: unknown): AlphaExecutionApprovalV1 {
  requireExactObjectKeys(value, ALPHA_EXECUTION_APPROVAL_KEYS, "ALPHA_APPROVAL_INVALID", "Alpha execution approval");
  const record = value as Partial<AlphaExecutionApprovalV1>;
  requireExactObjectKeys(record.proposal, ALPHA_EXECUTION_APPROVAL_PROPOSAL_KEYS, "ALPHA_APPROVAL_INVALID", "Alpha approval proposal binding");
  requireExactObjectKeys(record.decision, ALPHA_EXECUTION_APPROVAL_DECISION_KEYS, "ALPHA_APPROVAL_INVALID", "Alpha approval decision binding");
  requireExactObjectKeys(record.commandPolicy, ALPHA_EXECUTION_COMMAND_POLICY_KEYS, "ALPHA_APPROVAL_INVALID", "Alpha approval command policy");
  requireExactObjectKeys(record.validity, ALPHA_EXECUTION_VALIDITY_KEYS, "ALPHA_APPROVAL_INVALID", "Alpha approval validity");
  const proposal = record.proposal as AlphaExecutionApprovalV1["proposal"];
  const decision = record.decision as AlphaExecutionApprovalV1["decision"];
  const policy = record.commandPolicy as AlphaExecutionApprovalV1["commandPolicy"];
  const validity = record.validity as AlphaExecutionApprovalV1["validity"];
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_APPROVAL" ||
    record.approvalProfile !== ALPHA_EXECUTION_APPROVAL_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "RECORDED_NOT_AUTHORIZED" ||
    record.executionAuthority !== "NONE" ||
    record.maySpawnProcess !== false ||
    record.executionUseLimit !== 0 ||
    record.authorityMode !== "SELF_ADMINISTERED" ||
    !isSha256Digest(proposal.profileDigest) ||
    !isSha256Digest(proposal.proposalRecordDigest) ||
    typeof proposal.profileId !== "string" || proposal.profileId.length === 0 ||
    !isSha256Digest(proposal.executableDigest) ||
    !isSha256Digest(proposal.argsDigest) ||
    !Number.isSafeInteger(proposal.timeoutMs) || proposal.timeoutMs < 100 || proposal.timeoutMs > 60_000 ||
    typeof decision.decisionId !== "string" || decision.decisionId.length === 0 ||
    !isSha256Digest(decision.decisionDigest) ||
    !isSha256Digest(decision.candidateDigest) ||
    !isSha256Digest(decision.authorityDigest) ||
    (decision.expectedBaseDigest !== null && !isSha256Digest(decision.expectedBaseDigest)) ||
    !Number.isSafeInteger(decision.dependencyEpoch) || decision.dependencyEpoch < 0 ||
    decision.targetId !== "local-content-addressed-alpha" ||
    policy.executableSource !== "PROPOSAL_UNTRUSTED_REQUEST" ||
    policy.cwd !== "OBJECT_DERIVED_WORKSPACE_REQUIRED_NOT_EXECUTION_ADMISSION" ||
    policy.inheritEnvironment !== false ||
    !Array.isArray(policy.environmentAllowlist) ||
    canonicalJson(policy.environmentAllowlist) !== canonicalJson(["LANG", "LC_ALL"]) ||
    policy.stdin !== "NONE" ||
    policy.network !== "DENY_ALL_REQUIRED_NOT_IMPLEMENTED" ||
    policy.sandbox !== "REQUIRED_NOT_IMPLEMENTED" ||
    policy.stdoutLimitBytes !== 262144 ||
    policy.stderrLimitBytes !== 262144 ||
    policy.descendantPolicy !== "TERMINATE_TREE_REQUIRED_NOT_IMPLEMENTED" ||
    validity.basis !== "EXACT_PROPOSAL_AND_DECISION" ||
    validity.revocationMode !== "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION" ||
    validity.wallClockExpiry !== "NOT_ESTABLISHED" ||
    !isSha256Digest(record.approvalDigest)
  ) {
    fail("ALPHA_APPROVAL_INVALID", "Alpha execution approval is not the exact inert self-administered profile.");
  }
  const body = { ...record } as Partial<AlphaExecutionApprovalV1>;
  delete body.approvalDigest;
  if (record.approvalDigest !== computeAlphaExecutionApprovalDigest(body as Omit<AlphaExecutionApprovalV1, "approvalDigest">)) {
    fail("ALPHA_APPROVAL_INVALID", "Alpha execution approval digest does not bind the exact record body.");
  }
  return record as AlphaExecutionApprovalV1;
}

function buildAlphaExecutionApproval(closure: LoadedAlphaProfileClosureV1): AlphaExecutionApprovalV1 {
  const body: Omit<AlphaExecutionApprovalV1, "approvalDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_APPROVAL",
    approvalProfile: ALPHA_EXECUTION_APPROVAL_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "RECORDED_NOT_AUTHORIZED",
    executionAuthority: "NONE",
    maySpawnProcess: false,
    executionUseLimit: 0,
    authorityMode: "SELF_ADMINISTERED",
    proposal: {
      profileDigest: closure.proposal.profileDigest,
      proposalRecordDigest: closure.proposalRecordDigest,
      profileId: closure.proposal.profileId,
      executableDigest: closure.proposal.executableDigest,
      argsDigest: alphaExecutionArgsDigest(closure.proposal.args),
      timeoutMs: closure.proposal.timeoutMs,
    },
    decision: {
      decisionId: closure.decision.decisionId,
      decisionDigest: closure.decisionDigest,
      candidateDigest: closure.decision.candidate.digest,
      authorityDigest: closure.decision.authorityDigest,
      expectedBaseDigest: closure.decision.expectedBaseDigest,
      dependencyEpoch: closure.decision.dependencyEpoch,
      targetId: closure.decision.targetId,
    },
    commandPolicy: {
      executableSource: "PROPOSAL_UNTRUSTED_REQUEST",
      cwd: "OBJECT_DERIVED_WORKSPACE_REQUIRED_NOT_EXECUTION_ADMISSION",
      inheritEnvironment: false,
      environmentAllowlist: ["LANG", "LC_ALL"],
      stdin: "NONE",
      network: "DENY_ALL_REQUIRED_NOT_IMPLEMENTED",
      sandbox: "REQUIRED_NOT_IMPLEMENTED",
      stdoutLimitBytes: 262144,
      stderrLimitBytes: 262144,
      descendantPolicy: "TERMINATE_TREE_REQUIRED_NOT_IMPLEMENTED",
    },
    validity: {
      basis: "EXACT_PROPOSAL_AND_DECISION",
      revocationMode: "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION",
      wallClockExpiry: "NOT_ESTABLISHED",
    },
  };
  return validateAlphaExecutionApproval({ ...body, approvalDigest: computeAlphaExecutionApprovalDigest(body) });
}

function assertAlphaApprovalMatchesClosure(
  approval: AlphaExecutionApprovalV1,
  closure: LoadedAlphaProfileClosureV1,
): void {
  if (
    approval.proposal.profileDigest !== closure.proposal.profileDigest ||
    approval.proposal.proposalRecordDigest !== closure.proposalRecordDigest ||
    approval.proposal.profileId !== closure.proposal.profileId ||
    approval.proposal.executableDigest !== closure.proposal.executableDigest ||
    approval.proposal.argsDigest !== alphaExecutionArgsDigest(closure.proposal.args) ||
    approval.proposal.timeoutMs !== closure.proposal.timeoutMs ||
    approval.decision.decisionId !== closure.decision.decisionId ||
    approval.decision.decisionDigest !== closure.decisionDigest ||
    approval.decision.candidateDigest !== closure.decision.candidate.digest ||
    approval.decision.authorityDigest !== closure.decision.authorityDigest ||
    approval.decision.expectedBaseDigest !== closure.decision.expectedBaseDigest ||
    approval.decision.dependencyEpoch !== closure.decision.dependencyEpoch ||
    approval.decision.targetId !== closure.decision.targetId
  ) {
    fail("ALPHA_APPROVAL_CLOSURE_MISMATCH", "Alpha approval does not close over the exact proposal and decision records.");
  }
}

async function readAlphaExecutionApprovalUnlocked(
  store: string,
  approvalDigest: string,
): Promise<{ approval: AlphaExecutionApprovalV1; approvalRecordDigest: string }> {
  if (!isSha256Digest(approvalDigest)) fail("ALPHA_APPROVAL_DIGEST_INVALID", "Alpha approval lookup requires an exact SHA-256 digest.");
  const verified = await readVerifiedEnvelope<unknown>(join(store, "alpha-execution-approvals", `${approvalDigest}.json`));
  const approval = validateAlphaExecutionApproval(verified.record);
  if (approval.approvalDigest !== approvalDigest) fail("ALPHA_APPROVAL_DIGEST_MISMATCH", "Alpha approval pathname and record digest disagree.");
  return { approval, approvalRecordDigest: verified.recordDigest };
}

async function recordAlphaExecutionApproval(
  storePath: string,
  profileDigest: string,
): Promise<AlphaExecutionApprovalV1> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    const closure = await loadAlphaProfileClosureUnlocked(store, profileDigest, ready);
    const approval = buildAlphaExecutionApproval(closure);
    const approvalPath = join(store, "alpha-execution-approvals", `${approval.approvalDigest}.json`);
    await writeImmutableRecord(approvalPath, approval);
    const readback = await readAlphaExecutionApprovalUnlocked(store, approval.approvalDigest);
    if (canonicalJson(readback.approval) !== canonicalJson(approval)) fail("ALPHA_APPROVAL_READBACK_MISMATCH", "Alpha approval readback differs from the exact inert record.");
    return approval;
  });
}

function computeAlphaExecutionActivationDigest(
  body: Omit<AlphaExecutionActivationV1, "activationDigest">,
): string {
  return sha256Bytes(`${ALPHA_EXECUTION_ACTIVATION_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaExecutionActivation(value: unknown): AlphaExecutionActivationV1 {
  requireExactObjectKeys(value, ALPHA_EXECUTION_ACTIVATION_KEYS, "ALPHA_ACTIVATION_INVALID", "Alpha execution activation");
  const record = value as Partial<AlphaExecutionActivationV1>;
  requireExactObjectKeys(record.coordinator, ALPHA_EXECUTION_COORDINATOR_KEYS, "ALPHA_ACTIVATION_INVALID", "Alpha activation coordinator binding");
  requireExactObjectKeys(record.validity, ALPHA_EXECUTION_VALIDITY_KEYS, "ALPHA_ACTIVATION_INVALID", "Alpha activation validity");
  const coordinator = record.coordinator as AlphaExecutionActivationV1["coordinator"];
  const validity = record.validity as AlphaExecutionActivationV1["validity"];
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_ACTIVATION" ||
    record.activationProfile !== ALPHA_EXECUTION_ACTIVATION_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "RECORDED_NOT_AUTHORIZED" ||
    record.executionAuthority !== "NONE" ||
    record.maySpawnProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(record.approvalDigest) ||
    !isSha256Digest(record.approvalRecordDigest) ||
    !isSha256Digest(record.profileDigest) ||
    !isSha256Digest(record.proposalRecordDigest) ||
    !isSha256Digest(record.decisionDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    !isSha256Digest(record.authorityDigest) ||
    !Number.isSafeInteger(record.dependencyEpoch) || (record.dependencyEpoch ?? -1) < 0 ||
    !isCanonicalUuidV4(coordinator.storeId) ||
    !Number.isSafeInteger(coordinator.revision) || coordinator.revision < 0 ||
    !isSha256Digest(coordinator.stateDigest) ||
    !isSha256Digest(coordinator.headRecordDigest) ||
    !isSha256Digest(coordinator.commitRecordDigest) ||
    !isSha256Digest(coordinator.migrationRecordDigest) ||
    !isSha256Digest(coordinator.storageAdmissionRecordDigest) ||
    !Number.isSafeInteger(coordinator.dependencyEpoch) || coordinator.dependencyEpoch < 0 ||
    coordinator.dependencyEpoch !== record.dependencyEpoch ||
    coordinator.phase !== "READY" ||
    validity.basis !== "EXACT_COORDINATOR_SNAPSHOT" ||
    validity.revocationMode !== "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION" ||
    validity.wallClockExpiry !== "NOT_ESTABLISHED" ||
    !isSha256Digest(record.activationDigest)
  ) {
    fail("ALPHA_ACTIVATION_INVALID", "Alpha execution activation is not the exact inert coordinator-snapshot profile.");
  }
  const body = { ...record } as Partial<AlphaExecutionActivationV1>;
  delete body.activationDigest;
  if (record.activationDigest !== computeAlphaExecutionActivationDigest(body as Omit<AlphaExecutionActivationV1, "activationDigest">)) {
    fail("ALPHA_ACTIVATION_INVALID", "Alpha execution activation digest does not bind the exact record body.");
  }
  return record as AlphaExecutionActivationV1;
}

function buildAlphaExecutionActivation(
  approval: AlphaExecutionApprovalV1,
  approvalRecordDigest: string,
  ready: CoordinatorSnapshot,
): AlphaExecutionActivationV1 {
  const body: Omit<AlphaExecutionActivationV1, "activationDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_ACTIVATION",
    activationProfile: ALPHA_EXECUTION_ACTIVATION_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "RECORDED_NOT_AUTHORIZED",
    executionAuthority: "NONE",
    maySpawnProcess: false,
    executionUseLimit: 0,
    approvalDigest: approval.approvalDigest,
    approvalRecordDigest,
    profileDigest: approval.proposal.profileDigest,
    proposalRecordDigest: approval.proposal.proposalRecordDigest,
    decisionDigest: approval.decision.decisionDigest,
    candidateDigest: approval.decision.candidateDigest,
    authorityDigest: approval.decision.authorityDigest,
    dependencyEpoch: approval.decision.dependencyEpoch,
    coordinator: {
      storeId: ready.state.storeId,
      revision: ready.state.revision,
      stateDigest: ready.head.stateDigest,
      headRecordDigest: ready.headRecordDigest,
      commitRecordDigest: ready.commitRecordDigest,
      migrationRecordDigest: ready.state.migrationRecordDigest,
      storageAdmissionRecordDigest: ready.state.storageAdmissionRecordDigest,
      dependencyEpoch: ready.state.dependencyEpoch,
      phase: "READY",
    },
    validity: {
      basis: "EXACT_COORDINATOR_SNAPSHOT",
      revocationMode: "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION",
      wallClockExpiry: "NOT_ESTABLISHED",
    },
  };
  return validateAlphaExecutionActivation({ ...body, activationDigest: computeAlphaExecutionActivationDigest(body) });
}

function assertAlphaActivationMatchesApproval(
  activation: AlphaExecutionActivationV1,
  approval: AlphaExecutionApprovalV1,
  approvalRecordDigest: string,
): void {
  if (
    activation.approvalDigest !== approval.approvalDigest ||
    activation.approvalRecordDigest !== approvalRecordDigest ||
    activation.profileDigest !== approval.proposal.profileDigest ||
    activation.proposalRecordDigest !== approval.proposal.proposalRecordDigest ||
    activation.decisionDigest !== approval.decision.decisionDigest ||
    activation.candidateDigest !== approval.decision.candidateDigest ||
    activation.authorityDigest !== approval.decision.authorityDigest ||
    activation.dependencyEpoch !== approval.decision.dependencyEpoch
  ) {
    fail("ALPHA_ACTIVATION_CLOSURE_MISMATCH", "Alpha activation does not close over the exact inert approval.");
  }
}

async function readAlphaExecutionActivationUnlocked(
  store: string,
  activationDigest: string,
): Promise<{ activation: AlphaExecutionActivationV1; activationRecordDigest: string }> {
  if (!isSha256Digest(activationDigest)) fail("ALPHA_ACTIVATION_DIGEST_INVALID", "Alpha activation lookup requires an exact SHA-256 digest.");
  const verified = await readVerifiedEnvelope<unknown>(join(store, "alpha-execution-activations", `${activationDigest}.json`));
  const activation = validateAlphaExecutionActivation(verified.record);
  if (activation.activationDigest !== activationDigest) fail("ALPHA_ACTIVATION_DIGEST_MISMATCH", "Alpha activation pathname and record digest disagree.");
  return { activation, activationRecordDigest: verified.recordDigest };
}

async function recordAlphaExecutionActivation(
  storePath: string,
  approvalDigest: string,
): Promise<AlphaExecutionActivationV1> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    if (ready.state.phase !== "READY") fail("COORDINATOR_NOT_READY", "Alpha activation requires a READY coordinator state.");
    const { approval, approvalRecordDigest } = await readAlphaExecutionApprovalUnlocked(store, approvalDigest);
    const closure = await loadAlphaProfileClosureUnlocked(store, approval.proposal.profileDigest, ready);
    assertAlphaApprovalMatchesClosure(approval, closure);
    if (approval.decision.dependencyEpoch !== ready.state.dependencyEpoch) fail("DECISION_STALE", "Alpha approval decision epoch is no longer current.");
    const activation = buildAlphaExecutionActivation(approval, approvalRecordDigest, ready);
    const activationPath = join(store, "alpha-execution-activations", `${activation.activationDigest}.json`);
    await writeImmutableRecord(activationPath, activation);
    const readback = await readAlphaExecutionActivationUnlocked(store, activation.activationDigest);
    if (canonicalJson(readback.activation) !== canonicalJson(activation)) fail("ALPHA_ACTIVATION_READBACK_MISMATCH", "Alpha activation readback differs from the exact inert record.");
    return activation;
  });
}

function alphaActivationMatchesCoordinatorSnapshot(
  activation: AlphaExecutionActivationV1,
  ready: CoordinatorSnapshot,
): boolean {
  return canonicalJson(activation.coordinator) === canonicalJson({
    storeId: ready.state.storeId,
    revision: ready.state.revision,
    stateDigest: ready.head.stateDigest,
    headRecordDigest: ready.headRecordDigest,
    commitRecordDigest: ready.commitRecordDigest,
    migrationRecordDigest: ready.state.migrationRecordDigest,
    storageAdmissionRecordDigest: ready.state.storageAdmissionRecordDigest,
    dependencyEpoch: ready.state.dependencyEpoch,
    phase: "READY",
  });
}

async function inspectAlphaExecutionActivationUnlocked(
  store: string,
  activationDigest: string,
  ready: CoordinatorSnapshot,
): Promise<{
  activation: AlphaExecutionActivationV1;
  activationRecordDigest: string;
  approval: AlphaExecutionApprovalV1;
  approvalRecordDigest: string;
  closure: LoadedAlphaProfileClosureV1 | null;
  status: AlphaExecutionActivationStatusV1;
}> {
  if (ready.state.phase !== "READY") fail("COORDINATOR_NOT_READY", "Alpha activation inspection requires a READY coordinator state.");
  const { activation, activationRecordDigest } = await readAlphaExecutionActivationUnlocked(store, activationDigest);
  const { approval, approvalRecordDigest } = await readAlphaExecutionApprovalUnlocked(store, activation.approvalDigest);
  assertAlphaActivationMatchesApproval(activation, approval, approvalRecordDigest);
  if (ready.state.dependencyEpoch < activation.dependencyEpoch) {
    fail("ALPHA_ACTIVATION_EPOCH_ROLLBACK", "Current coordinator epoch is older than the recorded activation epoch.");
  }
  if (ready.state.dependencyEpoch > activation.dependencyEpoch) {
    return { activation, activationRecordDigest, approval, approvalRecordDigest, closure: null, status: "RECALLED_BY_DEPENDENCY_EPOCH" };
  }
  if (!alphaActivationMatchesCoordinatorSnapshot(activation, ready)) {
    return { activation, activationRecordDigest, approval, approvalRecordDigest, closure: null, status: "SUPERSEDED_COORDINATOR_SNAPSHOT" };
  }
  const closure = await loadAlphaProfileClosureUnlocked(store, approval.proposal.profileDigest, ready);
  assertAlphaApprovalMatchesClosure(approval, closure);
  return { activation, activationRecordDigest, approval, approvalRecordDigest, closure, status: "CURRENT_INERT" };
}

async function inspectAlphaExecutionActivation(
  storePath: string,
  activationDigest: string,
): Promise<{ activation: AlphaExecutionActivationV1; status: AlphaExecutionActivationStatusV1 }> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    const inspection = await inspectAlphaExecutionActivationUnlocked(store, activationDigest, ready);
    return { activation: inspection.activation, status: inspection.status };
  });
}

function alphaWorkspaceId(
  activationDigest: string,
  activationRecordDigest: string,
  candidateDigest: string,
): string {
  return sha256Bytes(
    `veritas-alpha-workspace-id-v1\0${canonicalJson({
      activationDigest,
      activationRecordDigest,
      candidateDigest,
      treeProfile: TREE_PROFILE,
    })}`,
  );
}

function alphaWorkspaceRelativePaths(workspaceId: string, candidateDigest: string): {
  parentRelativePath: "alpha-execution-workspaces";
  stagingRelativePath: string;
  finalRelativePath: string;
  sourceObjectRelativePath: string;
} {
  if (!isSha256Digest(workspaceId) || !isSha256Digest(candidateDigest)) {
    fail("ALPHA_WORKSPACE_ID_INVALID", "Alpha workspace paths require exact SHA-256 identities.");
  }
  return {
    parentRelativePath: "alpha-execution-workspaces",
    stagingRelativePath: `alpha-execution-workspaces/.materialize-${workspaceId}`,
    finalRelativePath: `alpha-execution-workspaces/${workspaceId}`,
    sourceObjectRelativePath: `objects/${candidateDigest}`,
  };
}

function computeAlphaWorkspaceIntentDigest(
  body: Omit<AlphaWorkspaceIntentV1, "intentDigest">,
): string {
  return sha256Bytes(`${ALPHA_WORKSPACE_INTENT_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaWorkspaceIntent(value: unknown): AlphaWorkspaceIntentV1 {
  requireExactObjectKeys(value, ALPHA_WORKSPACE_INTENT_KEYS, "ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent");
  const record = value as Partial<AlphaWorkspaceIntentV1>;
  requireExactObjectKeys(record.workspace, ALPHA_WORKSPACE_INTENT_WORKSPACE_KEYS, "ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent path binding");
  requireExactObjectKeys(record.limits, ALPHA_WORKSPACE_LIMIT_KEYS, "ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent limits");
  requireExactObjectKeys(record.validity, ALPHA_EXECUTION_VALIDITY_KEYS, "ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent validity");
  const workspace = record.workspace as AlphaWorkspaceIntentV1["workspace"];
  const limits = record.limits as AlphaWorkspaceLimitsV1;
  const validity = record.validity as AlphaWorkspaceIntentV1["validity"];
  if (
    !isSha256Digest(record.activationDigest) ||
    !isSha256Digest(record.activationRecordDigest) ||
    !isSha256Digest(record.candidateDigest)
  ) {
    fail("ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent lacks exact lineage digests.");
  }
  const expectedWorkspaceId = alphaWorkspaceId(
    record.activationDigest,
    record.activationRecordDigest,
    record.candidateDigest,
  );
  const expectedPaths = alphaWorkspaceRelativePaths(expectedWorkspaceId, record.candidateDigest);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_WORKSPACE_INTENT" ||
    record.intentProfile !== ALPHA_WORKSPACE_INTENT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "INTENDED_NOT_MATERIALIZED_NOT_AUTHORIZED" ||
    record.candidateExecutionAuthority !== "NONE" ||
    record.maySpawnCandidateProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(record.activationDigest) ||
    !isSha256Digest(record.activationRecordDigest) ||
    !isSha256Digest(record.approvalDigest) ||
    !isSha256Digest(record.profileDigest) ||
    !isSha256Digest(record.decisionDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    !isSha256Digest(record.authorityDigest) ||
    !Number.isSafeInteger(record.dependencyEpoch) || (record.dependencyEpoch ?? -1) < 0 ||
    workspace.workspaceId !== expectedWorkspaceId ||
    workspace.parentRelativePath !== expectedPaths.parentRelativePath ||
    workspace.stagingRelativePath !== expectedPaths.stagingRelativePath ||
    workspace.finalRelativePath !== expectedPaths.finalRelativePath ||
    workspace.sourceObjectRelativePath !== expectedPaths.sourceObjectRelativePath ||
    workspace.treeProfile !== TREE_PROFILE ||
    workspace.copyMode !== "INDEPENDENT_REGULAR_FILE_BYTES" ||
    workspace.emptyDirectoryPolicy !== "OMIT" ||
    workspace.metadataPolicy !== "DIRECTORIES_0700_FILES_0600_PLUS_EXECUTABLE_BITS" ||
    canonicalJson(limits) !== canonicalJson(ALPHA_WORKSPACE_LIMITS) ||
    validity.basis !== "CURRENT_INERT_ACTIVATION_AND_EXACT_OBJECT_AT_INTENT" ||
    validity.revocationMode !== "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_DRIFT" ||
    validity.wallClockExpiry !== "NOT_ESTABLISHED" ||
    !isSha256Digest(record.intentDigest)
  ) {
    fail("ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent is outside the exact non-executing byte-copy profile.");
  }
  const body = { ...record } as Partial<AlphaWorkspaceIntentV1>;
  delete body.intentDigest;
  if (record.intentDigest !== computeAlphaWorkspaceIntentDigest(body as Omit<AlphaWorkspaceIntentV1, "intentDigest">)) {
    fail("ALPHA_WORKSPACE_INTENT_INVALID", "Alpha workspace intent digest does not bind the exact record body.");
  }
  return record as AlphaWorkspaceIntentV1;
}

function buildAlphaWorkspaceIntent(
  inspection: Awaited<ReturnType<typeof inspectAlphaExecutionActivationUnlocked>>,
): AlphaWorkspaceIntentV1 {
  const workspaceId = alphaWorkspaceId(
    inspection.activation.activationDigest,
    inspection.activationRecordDigest,
    inspection.activation.candidateDigest,
  );
  const paths = alphaWorkspaceRelativePaths(workspaceId, inspection.activation.candidateDigest);
  const body: Omit<AlphaWorkspaceIntentV1, "intentDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_WORKSPACE_INTENT",
    intentProfile: ALPHA_WORKSPACE_INTENT_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "INTENDED_NOT_MATERIALIZED_NOT_AUTHORIZED",
    candidateExecutionAuthority: "NONE",
    maySpawnCandidateProcess: false,
    executionUseLimit: 0,
    activationDigest: inspection.activation.activationDigest,
    activationRecordDigest: inspection.activationRecordDigest,
    approvalDigest: inspection.activation.approvalDigest,
    profileDigest: inspection.activation.profileDigest,
    decisionDigest: inspection.activation.decisionDigest,
    candidateDigest: inspection.activation.candidateDigest,
    authorityDigest: inspection.activation.authorityDigest,
    dependencyEpoch: inspection.activation.dependencyEpoch,
    workspace: {
      workspaceId,
      ...paths,
      treeProfile: TREE_PROFILE,
      copyMode: "INDEPENDENT_REGULAR_FILE_BYTES",
      emptyDirectoryPolicy: "OMIT",
      metadataPolicy: "DIRECTORIES_0700_FILES_0600_PLUS_EXECUTABLE_BITS",
    },
    limits: { ...ALPHA_WORKSPACE_LIMITS },
    validity: {
      basis: "CURRENT_INERT_ACTIVATION_AND_EXACT_OBJECT_AT_INTENT",
      revocationMode: "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_DRIFT",
      wallClockExpiry: "NOT_ESTABLISHED",
    },
  };
  return validateAlphaWorkspaceIntent({ ...body, intentDigest: computeAlphaWorkspaceIntentDigest(body) });
}

function computeAlphaWorkspaceReceiptDigest(
  body: Omit<AlphaWorkspaceReceiptV1, "receiptDigest">,
): string {
  return sha256Bytes(`${ALPHA_WORKSPACE_RECEIPT_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaWorkspaceReceipt(value: unknown): AlphaWorkspaceReceiptV1 {
  requireExactObjectKeys(value, ALPHA_WORKSPACE_RECEIPT_KEYS, "ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt");
  const record = value as Partial<AlphaWorkspaceReceiptV1>;
  requireExactObjectKeys(record.workspace, ALPHA_WORKSPACE_RECEIPT_WORKSPACE_KEYS, "ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt binding");
  requireExactObjectKeys(record.validity, ALPHA_EXECUTION_VALIDITY_KEYS, "ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt validity");
  const workspace = record.workspace as AlphaWorkspaceReceiptV1["workspace"];
  requireExactObjectKeys(workspace.rootIdentity, DIRECTORY_IDENTITY_KEYS, "ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace root identity");
  const validity = record.validity as AlphaWorkspaceReceiptV1["validity"];
  if (!isSha256Digest(workspace.workspaceId) || !isSha256Digest(record.candidateDigest)) {
    fail("ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt lacks exact path-binding digests.");
  }
  const expectedPaths = alphaWorkspaceRelativePaths(workspace.workspaceId, record.candidateDigest);
  const rootIdentity = workspace.rootIdentity;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_WORKSPACE_RECEIPT" ||
    record.receiptProfile !== ALPHA_WORKSPACE_RECEIPT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "MATERIALIZED_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED" ||
    record.candidateExecutionAuthority !== "NONE" ||
    record.maySpawnCandidateProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(record.intentDigest) ||
    !isSha256Digest(record.activationDigest) ||
    !isSha256Digest(record.activationRecordDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    !Number.isSafeInteger(record.dependencyEpoch) || (record.dependencyEpoch ?? -1) < 0 ||
    !isSha256Digest(workspace.workspaceId) ||
    workspace.relativePath !== expectedPaths.finalRelativePath ||
    workspace.sourceObjectRelativePath !== expectedPaths.sourceObjectRelativePath ||
    workspace.treeProfile !== TREE_PROFILE ||
    workspace.sourceDigest !== record.candidateDigest ||
    workspace.finalDigest !== record.candidateDigest ||
    !(
      (workspace.publicationMode === "STAGE_RENAME_WITH_PRE_AND_POST_READBACK" &&
        workspace.stagingReadbackDigest === record.candidateDigest) ||
      (workspace.publicationMode === "RECOVERED_FINAL_WITH_PREEXISTING_INTENT" &&
        workspace.stagingReadbackDigest === null)
    ) ||
    !isSha256Digest(workspace.directorySetDigest) ||
    !Number.isSafeInteger(workspace.fileCount) || workspace.fileCount < 0 || workspace.fileCount > ALPHA_WORKSPACE_LIMITS.maxFiles ||
    !Number.isSafeInteger(workspace.totalBytes) || workspace.totalBytes < 0 || workspace.totalBytes > ALPHA_WORKSPACE_LIMITS.maxTotalBytes ||
    workspace.copyMode !== "INDEPENDENT_REGULAR_FILE_BYTES" ||
    workspace.emptyDirectoryPolicy !== "OMIT" ||
    workspace.metadataPolicy !== "DIRECTORIES_0700_FILES_0600_PLUS_EXECUTABLE_BITS" ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.deviceId) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.inodeId) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.ownerUid) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.ownerGid) ||
    rootIdentity.mode !== "0700" ||
    validity.basis !== "POINT_IN_TIME_EXACT_OBJECT_TO_WORKSPACE_READBACK" ||
    validity.revocationMode !== "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_DRIFT" ||
    validity.wallClockExpiry !== "NOT_ESTABLISHED" ||
    !isSha256Digest(record.receiptDigest)
  ) {
    fail("ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt is outside the exact non-executing readback profile.");
  }
  const body = { ...record } as Partial<AlphaWorkspaceReceiptV1>;
  delete body.receiptDigest;
  if (record.receiptDigest !== computeAlphaWorkspaceReceiptDigest(body as Omit<AlphaWorkspaceReceiptV1, "receiptDigest">)) {
    fail("ALPHA_WORKSPACE_RECEIPT_INVALID", "Alpha workspace receipt digest does not bind the exact record body.");
  }
  return record as AlphaWorkspaceReceiptV1;
}

function computeAlphaWorkspaceCleanupDigest(
  body: Omit<AlphaWorkspaceCleanupV1, "cleanupDigest">,
): string {
  return sha256Bytes(`${ALPHA_WORKSPACE_CLEANUP_PROFILE}\0${canonicalJson(body)}`);
}

function computeAlphaWorkspaceCleanupIntentDigest(
  body: Omit<AlphaWorkspaceCleanupIntentV1, "cleanupIntentDigest">,
): string {
  return sha256Bytes(`${ALPHA_WORKSPACE_CLEANUP_INTENT_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaWorkspaceCleanupIntent(value: unknown): AlphaWorkspaceCleanupIntentV1 {
  requireExactObjectKeys(
    value,
    ALPHA_WORKSPACE_CLEANUP_INTENT_KEYS,
    "ALPHA_WORKSPACE_CLEANUP_INTENT_INVALID",
    "Alpha workspace cleanup intent",
  );
  const record = value as Partial<AlphaWorkspaceCleanupIntentV1>;
  requireExactObjectKeys(
    record.rootIdentity,
    DIRECTORY_IDENTITY_KEYS,
    "ALPHA_WORKSPACE_CLEANUP_INTENT_INVALID",
    "Alpha workspace cleanup-intent root identity",
  );
  const rootIdentity = record.rootIdentity as DirectoryIdentityStamp;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_WORKSPACE_CLEANUP_INTENT" ||
    record.cleanupIntentProfile !== ALPHA_WORKSPACE_CLEANUP_INTENT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "CLEANUP_PENDING_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED" ||
    record.candidateExecutionAuthority !== "NONE" ||
    record.maySpawnCandidateProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(record.receiptDigest) ||
    !isSha256Digest(record.intentDigest) ||
    !isSha256Digest(record.activationDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    !isSha256Digest(record.workspaceId) ||
    record.workspaceRelativePath !== `alpha-execution-workspaces/${record.workspaceId ?? ""}` ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.deviceId) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.inodeId) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.ownerUid) ||
    !/^(0|[1-9][0-9]*)$/.test(rootIdentity.ownerGid) ||
    rootIdentity.mode !== "0700" ||
    !isSha256Digest(record.cleanupIntentDigest)
  ) {
    fail("ALPHA_WORKSPACE_CLEANUP_INTENT_INVALID", "Alpha workspace cleanup intent is outside the exact pending-barrier profile.");
  }
  const body = { ...record } as Partial<AlphaWorkspaceCleanupIntentV1>;
  delete body.cleanupIntentDigest;
  if (
    record.cleanupIntentDigest !==
    computeAlphaWorkspaceCleanupIntentDigest(
      body as Omit<AlphaWorkspaceCleanupIntentV1, "cleanupIntentDigest">,
    )
  ) {
    fail("ALPHA_WORKSPACE_CLEANUP_INTENT_INVALID", "Alpha workspace cleanup-intent digest does not bind the exact record body.");
  }
  return record as AlphaWorkspaceCleanupIntentV1;
}

function validateAlphaWorkspaceCleanup(value: unknown): AlphaWorkspaceCleanupV1 {
  requireExactObjectKeys(value, ALPHA_WORKSPACE_CLEANUP_KEYS, "ALPHA_WORKSPACE_CLEANUP_INVALID", "Alpha workspace cleanup");
  const record = value as Partial<AlphaWorkspaceCleanupV1>;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_EXECUTION_WORKSPACE_CLEANUP" ||
    record.cleanupProfile !== ALPHA_WORKSPACE_CLEANUP_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "ABSENT_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED" ||
    record.candidateExecutionAuthority !== "NONE" ||
    record.maySpawnCandidateProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(record.receiptDigest) ||
    !isSha256Digest(record.intentDigest) ||
    !isSha256Digest(record.activationDigest) ||
    !isSha256Digest(record.candidateDigest) ||
    !isSha256Digest(record.workspaceId) ||
    record.workspaceRelativePath !== `alpha-execution-workspaces/${record.workspaceId ?? ""}` ||
    !isSha256Digest(record.cleanupIntentDigest) ||
    !isSha256Digest(record.cleanupDigest)
  ) {
    fail("ALPHA_WORKSPACE_CLEANUP_INVALID", "Alpha workspace cleanup is outside the exact digest-targeted absence profile.");
  }
  const body = { ...record } as Partial<AlphaWorkspaceCleanupV1>;
  delete body.cleanupDigest;
  if (record.cleanupDigest !== computeAlphaWorkspaceCleanupDigest(body as Omit<AlphaWorkspaceCleanupV1, "cleanupDigest">)) {
    fail("ALPHA_WORKSPACE_CLEANUP_INVALID", "Alpha workspace cleanup digest does not bind the exact record body.");
  }
  return record as AlphaWorkspaceCleanupV1;
}

async function readAlphaWorkspaceIntentUnlocked(
  store: string,
  intentDigest: string,
): Promise<{ intent: AlphaWorkspaceIntentV1; intentRecordDigest: string }> {
  if (!isSha256Digest(intentDigest)) fail("ALPHA_WORKSPACE_INTENT_DIGEST_INVALID", "Alpha workspace intent lookup requires an exact SHA-256 digest.");
  const verified = await readVerifiedEnvelope<unknown>(join(store, "alpha-workspace-intents", `${intentDigest}.json`));
  const intent = validateAlphaWorkspaceIntent(verified.record);
  if (intent.intentDigest !== intentDigest) fail("ALPHA_WORKSPACE_INTENT_DIGEST_MISMATCH", "Alpha workspace intent pathname and content digest disagree.");
  return { intent, intentRecordDigest: verified.recordDigest };
}

async function readAlphaWorkspaceReceiptUnlocked(
  store: string,
  receiptDigest: string,
): Promise<{
  receipt: AlphaWorkspaceReceiptV1;
  receiptRecordDigest: string;
  intent: AlphaWorkspaceIntentV1;
  intentRecordDigest: string;
}> {
  if (!isSha256Digest(receiptDigest)) fail("ALPHA_WORKSPACE_RECEIPT_DIGEST_INVALID", "Alpha workspace receipt lookup requires an exact SHA-256 digest.");
  const verified = await readVerifiedEnvelope<unknown>(join(store, "alpha-workspace-receipts", `${receiptDigest}.json`));
  const receipt = validateAlphaWorkspaceReceipt(verified.record);
  if (receipt.receiptDigest !== receiptDigest) fail("ALPHA_WORKSPACE_RECEIPT_DIGEST_MISMATCH", "Alpha workspace receipt pathname and content digest disagree.");
  const { intent, intentRecordDigest } = await readAlphaWorkspaceIntentUnlocked(store, receipt.intentDigest);
  if (
    receipt.activationDigest !== intent.activationDigest ||
    receipt.activationRecordDigest !== intent.activationRecordDigest ||
    receipt.candidateDigest !== intent.candidateDigest ||
    receipt.dependencyEpoch !== intent.dependencyEpoch ||
    receipt.workspace.workspaceId !== intent.workspace.workspaceId ||
    receipt.workspace.relativePath !== intent.workspace.finalRelativePath ||
    receipt.workspace.sourceObjectRelativePath !== intent.workspace.sourceObjectRelativePath
  ) {
    fail("ALPHA_WORKSPACE_RECEIPT_CLOSURE_MISMATCH", "Alpha workspace receipt does not close over its exact intent.");
  }
  return { receipt, receiptRecordDigest: verified.recordDigest, intent, intentRecordDigest };
}

async function readSoleAlphaWorkspaceReceiptForIntentUnlocked(
  store: string,
  intent: AlphaWorkspaceIntentV1,
): Promise<AlphaWorkspaceReceiptV1 | null> {
  let match: AlphaWorkspaceReceiptV1 | null = null;
  const names = (await readdir(join(store, "alpha-workspace-receipts")))
    .filter((name) => name.endsWith(".json"))
    .sort(codePointCompare);
  for (const name of names) {
    const receiptDigest = name.slice(0, -".json".length);
    const { receipt } = await readAlphaWorkspaceReceiptUnlocked(store, receiptDigest);
    const sameGeneration =
      receipt.intentDigest === intent.intentDigest ||
      receipt.workspace.workspaceId === intent.workspace.workspaceId;
    if (!sameGeneration) continue;
    if (
      receipt.intentDigest !== intent.intentDigest ||
      receipt.workspace.workspaceId !== intent.workspace.workspaceId
    ) {
      fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "Workspace identity and intent identify different receipt generations.");
    }
    if (match !== null) {
      fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "One workspace generation has multiple materialization receipts.");
    }
    match = receipt;
  }
  return match;
}

function assertAlphaWorkspaceIntentMatchesInspection(
  intent: AlphaWorkspaceIntentV1,
  inspection: Awaited<ReturnType<typeof inspectAlphaExecutionActivationUnlocked>>,
): void {
  if (
    intent.activationDigest !== inspection.activation.activationDigest ||
    intent.activationRecordDigest !== inspection.activationRecordDigest ||
    intent.approvalDigest !== inspection.activation.approvalDigest ||
    intent.profileDigest !== inspection.activation.profileDigest ||
    intent.decisionDigest !== inspection.activation.decisionDigest ||
    intent.candidateDigest !== inspection.activation.candidateDigest ||
    intent.authorityDigest !== inspection.activation.authorityDigest ||
    intent.dependencyEpoch !== inspection.activation.dependencyEpoch
  ) {
    fail("ALPHA_WORKSPACE_INTENT_CLOSURE_MISMATCH", "Alpha workspace intent does not close over the exact current inert activation.");
  }
}

function alphaWorkspaceAbsolutePaths(
  store: string,
  intent: AlphaWorkspaceIntentV1,
): {
  parentPath: string;
  stagingPath: string;
  finalPath: string;
  sourceObjectPath: string;
  cleanupPath: string;
} {
  const parentPath = resolve(store, intent.workspace.parentRelativePath);
  const stagingPath = resolve(store, intent.workspace.stagingRelativePath);
  const finalPath = resolve(store, intent.workspace.finalRelativePath);
  const sourceObjectPath = resolve(store, intent.workspace.sourceObjectRelativePath);
  const cleanupPath = join(parentPath, `.cleanup-${intent.workspace.workspaceId}`);
  for (const candidate of [parentPath, stagingPath, finalPath, sourceObjectPath, cleanupPath]) {
    if (!isWithin(store, candidate)) {
      fail("ALPHA_WORKSPACE_PATH_INVALID", "Alpha workspace path escaped the exact state store.", { path: candidate });
    }
  }
  return { parentPath, stagingPath, finalPath, sourceObjectPath, cleanupPath };
}

async function assertDirectoryIdentityStable(
  directoryPath: string,
  expected: DirectoryIdentityStamp,
  errorCode: string,
  label: string,
  exactMode?: "0700",
): Promise<void> {
  const observed = await readPrivateDirectoryIdentity(directoryPath, errorCode, label, exactMode);
  if (!directoryIdentityStampsEqual(observed, expected)) {
    fail(errorCode, `${label} identity changed during the operation.`, { expected, observed });
  }
}

async function assertAlphaWorkspaceFreeSpace(
  workspaceParent: string,
  totalBytes: number,
): Promise<void> {
  const filesystem = await statfs(workspaceParent);
  const availableBytes = Number(filesystem.bavail) * Number(filesystem.bsize);
  const requiredBytes = totalBytes + ALPHA_WORKSPACE_LIMITS.minFreeReserveBytes;
  if (!Number.isFinite(availableBytes) || availableBytes < requiredBytes) {
    fail("ALPHA_WORKSPACE_SPACE_INSUFFICIENT", "Alpha workspace materialization would violate the frozen free-space reserve.", {
      availableBytes: Number.isFinite(availableBytes) ? availableBytes : -1,
      requiredBytes,
    });
  }
}

async function validateAlphaWorkspaceTree(
  rootPath: string,
  source: TreeFingerprint,
  parentIdentity: DirectoryIdentityStamp,
): Promise<{
  fingerprint: TreeFingerprint;
  directorySetDigest: string;
  rootIdentity: DirectoryIdentityStamp;
}> {
  const rootIdentity = await readPrivateDirectoryIdentity(rootPath, "ALPHA_WORKSPACE_ROOT_INVALID", "Alpha workspace root", "0700");
  if (rootIdentity.deviceId !== parentIdentity.deviceId) {
    fail("ALPHA_WORKSPACE_DEVICE_MISMATCH", "Alpha workspace and its admitted parent must remain on one device.");
  }
  const fingerprint = await fingerprintTree(rootPath);
  assertAlphaWorkspaceFingerprintOnDevice(
    fingerprint,
    rootIdentity.deviceId,
    "ALPHA_WORKSPACE_DEVICE_MISMATCH",
    "Alpha workspace",
  );
  if (fingerprint.digest !== source.digest) {
    fail("ALPHA_WORKSPACE_COPY_MISMATCH", "Alpha workspace digest differs from the prepared object.", {
      expected: source.digest,
      observed: fingerprint.digest,
    });
  }
  assertAlphaWorkspaceIndependentCopy(source, fingerprint);
  const expectedDirectories = derivedWorkspaceDirectorySet(source.entries);
  const observedDirectories = await listWorkspaceDirectorySet(rootPath, rootIdentity.deviceId);
  if (canonicalJson(observedDirectories) !== canonicalJson(expectedDirectories)) {
    fail("ALPHA_WORKSPACE_DIRECTORY_SET_MISMATCH", "Alpha workspace directory set differs from the regular-file byte-copy profile.", {
      expected: expectedDirectories,
      observed: observedDirectories,
    });
  }
  return {
    fingerprint,
    directorySetDigest: alphaWorkspaceDirectorySetDigest(observedDirectories),
    rootIdentity,
  };
}

function buildAlphaWorkspaceReceipt(
  intent: AlphaWorkspaceIntentV1,
  source: TreeFingerprint,
  staged: TreeFingerprint | null,
  final: TreeFingerprint,
  directorySetDigest: string,
  rootIdentity: DirectoryIdentityStamp,
): AlphaWorkspaceReceiptV1 {
  const totals = assertAlphaWorkspaceLimits(source);
  const body: Omit<AlphaWorkspaceReceiptV1, "receiptDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_WORKSPACE_RECEIPT",
    receiptProfile: ALPHA_WORKSPACE_RECEIPT_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "MATERIALIZED_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED",
    candidateExecutionAuthority: "NONE",
    maySpawnCandidateProcess: false,
    executionUseLimit: 0,
    intentDigest: intent.intentDigest,
    activationDigest: intent.activationDigest,
    activationRecordDigest: intent.activationRecordDigest,
    candidateDigest: intent.candidateDigest,
    dependencyEpoch: intent.dependencyEpoch,
    workspace: {
      workspaceId: intent.workspace.workspaceId,
      relativePath: intent.workspace.finalRelativePath,
      sourceObjectRelativePath: intent.workspace.sourceObjectRelativePath,
      treeProfile: TREE_PROFILE,
      sourceDigest: source.digest,
      stagingReadbackDigest: staged?.digest ?? null,
      finalDigest: final.digest,
      publicationMode: staged === null
        ? "RECOVERED_FINAL_WITH_PREEXISTING_INTENT"
        : "STAGE_RENAME_WITH_PRE_AND_POST_READBACK",
      directorySetDigest,
      fileCount: totals.fileCount,
      totalBytes: totals.totalBytes,
      copyMode: "INDEPENDENT_REGULAR_FILE_BYTES",
      emptyDirectoryPolicy: "OMIT",
      metadataPolicy: "DIRECTORIES_0700_FILES_0600_PLUS_EXECUTABLE_BITS",
      rootIdentity,
    },
    validity: {
      basis: "POINT_IN_TIME_EXACT_OBJECT_TO_WORKSPACE_READBACK",
      revocationMode: "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_DRIFT",
      wallClockExpiry: "NOT_ESTABLISHED",
    },
  };
  return validateAlphaWorkspaceReceipt({ ...body, receiptDigest: computeAlphaWorkspaceReceiptDigest(body) });
}

async function removeExactAlphaWorkspaceDirectory(
  parentPath: string,
  targetPath: string,
  quarantinePath: string,
  expectedIdentity: DirectoryIdentityStamp,
  parentIdentity: DirectoryIdentityStamp,
  hooks: { simulateCrashAt?: SimulatedCrashPoint } = {},
  crashPointAfterRename?: SimulatedCrashPoint,
): Promise<void> {
  await assertDirectoryIdentityStable(parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
  const targetIdentity = await readPrivateDirectoryIdentity(targetPath, "ALPHA_WORKSPACE_ROOT_INVALID", "Alpha workspace removal target", "0700");
  if (!directoryIdentityStampsEqual(targetIdentity, expectedIdentity)) {
    fail("ALPHA_WORKSPACE_ROOT_REBOUND", "Alpha workspace removal target differs from the recorded root identity.", {
      expected: expectedIdentity,
      observed: targetIdentity,
    });
  }
  await assertAlphaWorkspaceDirectoryTreeOnDevice(
    targetPath,
    expectedIdentity.deviceId,
    "ALPHA_WORKSPACE_ROOT_INVALID",
    "Alpha workspace removal target",
  );
  if (await pathExists(quarantinePath)) {
    fail("ALPHA_WORKSPACE_QUARANTINE_CONFLICT", "Alpha workspace quarantine path already exists.");
  }
  await rename(targetPath, quarantinePath);
  await syncDirectory(parentPath);
  if (crashPointAfterRename !== undefined) simulateCrash(hooks, crashPointAfterRename);
  await assertDirectoryIdentityStable(quarantinePath, expectedIdentity, "ALPHA_WORKSPACE_ROOT_REBOUND", "Quarantined alpha workspace", "0700");
  await assertAlphaWorkspaceDirectoryTreeOnDevice(
    quarantinePath,
    expectedIdentity.deviceId,
    "ALPHA_WORKSPACE_ROOT_INVALID",
    "Quarantined alpha workspace",
  );
  await rm(quarantinePath, { recursive: true, force: false });
  await syncDirectory(parentPath);
  await assertDirectoryIdentityStable(parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
}

async function materializeAlphaExecutionWorkspace(
  storePath: string,
  activationDigest: string,
  hooks: AlphaWorkspaceHooks = {},
): Promise<{ intent: AlphaWorkspaceIntentV1; receipt: AlphaWorkspaceReceiptV1 }> {
  if (
    (hooks.afterWorkspaceParentCaptured !== undefined ||
      hooks.afterCopiedFile !== undefined ||
      hooks.simulateCrashAt !== undefined) &&
    !boundedTestLaneActive()
  ) {
    fail("TEST_ONLY_ALPHA_WORKSPACE_HOOK_REJECTED", "Alpha workspace hooks require the bounded test lane.");
  }
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    const inspection = await inspectAlphaExecutionActivationUnlocked(store, activationDigest, ready);
    if (inspection.status !== "CURRENT_INERT" || inspection.closure === null) {
      fail(
        inspection.status === "RECALLED_BY_DEPENDENCY_EPOCH"
          ? "ALPHA_WORKSPACE_ACTIVATION_RECALLED"
          : "ALPHA_WORKSPACE_ACTIVATION_SUPERSEDED",
        "Alpha workspace materialization requires one exact CURRENT_INERT activation.",
      );
    }
    const intent = buildAlphaWorkspaceIntent(inspection);
    assertAlphaWorkspaceIntentMatchesInspection(intent, inspection);
    const paths = alphaWorkspaceAbsolutePaths(store, intent);
    const parentIdentity = await readPrivateDirectoryIdentity(paths.parentPath, "ALPHA_WORKSPACE_PARENT_INVALID", "Alpha workspace parent");
    await hooks.afterWorkspaceParentCaptured?.({ workspaceParentPath: paths.parentPath });
    await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");

    const intentPath = join(store, "alpha-workspace-intents", `${intent.intentDigest}.json`);
    const intentExisted = await pathExists(intentPath);
    if (intentExisted) {
      const existingIntent = await readAlphaWorkspaceIntentUnlocked(store, intent.intentDigest);
      if (canonicalJson(existingIntent.intent) !== canonicalJson(intent)) {
        fail("ALPHA_WORKSPACE_INTENT_CONFLICT", "Existing workspace intent differs from the exact activation-derived intent.");
      }
    }
    await assertAlphaWorkspaceNotTerminallyCleanedUnlocked(store, intent);
    const existingReceipt = intentExisted
      ? await readSoleAlphaWorkspaceReceiptForIntentUnlocked(store, intent)
      : null;
    const stagingExists = await pathExists(paths.stagingPath);
    const finalExists = await pathExists(paths.finalPath);
    const cleanupPathExists = await pathExists(paths.cleanupPath);
    if (cleanupPathExists) {
      fail("ALPHA_WORKSPACE_ORPHAN_CLEANUP_QUARANTINE", "Materialization refuses a cleanup quarantine without first completing cleanup recovery.");
    }
    if ((stagingExists || finalExists) && !intentExisted) {
      fail(
        stagingExists ? "ALPHA_WORKSPACE_ORPHAN_STAGING" : "ALPHA_WORKSPACE_ORPHAN_FINAL",
        "Workspace recovery requires an exact intent that predated the observed materialization path.",
      );
    }
    if (stagingExists && finalExists) {
      fail("ALPHA_WORKSPACE_PUBLICATION_CONFLICT", "Alpha workspace staging and final paths cannot coexist.");
    }
    if (existingReceipt !== null && !finalExists) {
      fail("ALPHA_WORKSPACE_RECEIPT_WITHOUT_FINAL", "A materialization receipt exists without its exact final workspace.");
    }
    if (stagingExists) {
      const stagingIdentity = await readPrivateDirectoryIdentity(paths.stagingPath, "ALPHA_WORKSPACE_STAGING_INVALID", "Interrupted alpha workspace staging root", "0700");
      if (stagingIdentity.deviceId !== parentIdentity.deviceId) fail("ALPHA_WORKSPACE_DEVICE_MISMATCH", "Interrupted staging root is on a foreign device.");
      await assertAlphaWorkspaceDirectoryTreeOnDevice(
        paths.stagingPath,
        stagingIdentity.deviceId,
        "ALPHA_WORKSPACE_STAGING_INVALID",
        "Interrupted alpha workspace staging root",
      );
      await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
      await assertDirectoryIdentityStable(paths.stagingPath, stagingIdentity, "ALPHA_WORKSPACE_STAGING_INVALID", "Interrupted alpha workspace staging root", "0700");
      await rm(paths.stagingPath, { recursive: true, force: false });
      simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_STAGING_CLEANUP");
      await syncDirectory(paths.parentPath);
      await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
    }

    const sourceRootIdentity = await readPrivateDirectoryIdentity(paths.sourceObjectPath, "ALPHA_WORKSPACE_SOURCE_INVALID", "Prepared-object source root");
    if (sourceRootIdentity.deviceId !== parentIdentity.deviceId) {
      fail("ALPHA_WORKSPACE_DEVICE_MISMATCH", "Prepared object and workspace parent must remain on one admitted device.");
    }
    const sourceBefore = await fingerprintTree(paths.sourceObjectPath);
    if (sourceBefore.digest !== intent.candidateDigest) {
      fail("ALPHA_WORKSPACE_SOURCE_INVALID", "Prepared-object source digest differs from the activation candidate.");
    }
    assertAlphaWorkspaceFingerprintOnDevice(
      sourceBefore,
      sourceRootIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    await assertAlphaWorkspaceDirectoryTreeOnDevice(
      paths.sourceObjectPath,
      sourceRootIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    assertAlphaWorkspaceSourceSingleLinks(sourceBefore);
    const totals = assertAlphaWorkspaceLimits(sourceBefore);
    await assertAlphaWorkspaceFreeSpace(paths.parentPath, totals.totalBytes);

    await writeImmutableRecord(intentPath, intent);
    const intentReadback = await readAlphaWorkspaceIntentUnlocked(store, intent.intentDigest);
    if (canonicalJson(intentReadback.intent) !== canonicalJson(intent)) {
      fail("ALPHA_WORKSPACE_INTENT_READBACK_MISMATCH", "Alpha workspace intent readback differs from the exact record.");
    }
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_INTENT");

    if (finalExists) {
      const validatedFinal = await validateAlphaWorkspaceTree(paths.finalPath, sourceBefore, parentIdentity);
      const sourceAfter = await fingerprintTree(paths.sourceObjectPath);
      assertAlphaWorkspaceSourceStable(sourceBefore, sourceAfter);
      await assertAlphaWorkspaceDirectoryTreeOnDevice(
        paths.sourceObjectPath,
        sourceRootIdentity.deviceId,
        "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
        "Prepared-object source",
      );
      await assertDirectoryIdentityStable(paths.sourceObjectPath, sourceRootIdentity, "ALPHA_WORKSPACE_SOURCE_CHANGED", "Prepared-object source root");
      await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
      await syncDirectory(paths.parentPath);
      const finalTotals = assertAlphaWorkspaceLimits(validatedFinal.fingerprint);
      if (existingReceipt !== null) {
        if (
          !directoryIdentityStampsEqual(existingReceipt.workspace.rootIdentity, validatedFinal.rootIdentity) ||
          existingReceipt.workspace.finalDigest !== validatedFinal.fingerprint.digest ||
          existingReceipt.workspace.directorySetDigest !== validatedFinal.directorySetDigest ||
          existingReceipt.workspace.fileCount !== finalTotals.fileCount ||
          existingReceipt.workspace.totalBytes !== finalTotals.totalBytes
        ) {
          fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "Existing receipt does not describe the exact current final workspace.");
        }
        return { intent, receipt: existingReceipt };
      }
      const prospectiveReceipt = buildAlphaWorkspaceReceipt(
        intent,
        sourceBefore,
        null,
        validatedFinal.fingerprint,
        validatedFinal.directorySetDigest,
        validatedFinal.rootIdentity,
      );
      const receiptPath = join(store, "alpha-workspace-receipts", `${prospectiveReceipt.receiptDigest}.json`);
      await writeImmutableRecord(receiptPath, prospectiveReceipt);
      const existing = await readAlphaWorkspaceReceiptUnlocked(store, prospectiveReceipt.receiptDigest);
      if (canonicalJson(existing.receipt) !== canonicalJson(prospectiveReceipt)) {
        fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "Existing alpha workspace receipt differs from exact readback.");
      }
      simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_RECEIPT");
      return { intent, receipt: existing.receipt };
    }

    await mkdir(paths.stagingPath, { recursive: false, mode: 0o700 });
    await chmod(paths.stagingPath, 0o700);
    await copyFingerprintEntriesToNewTree(
      sourceBefore,
      paths.stagingPath,
      "ALPHA_WORKSPACE_SOURCE_CHANGED",
      async ({ fileIndex, relativePath, sourcePath, destinationPath }) => {
        await hooks.afterCopiedFile?.({
          fileIndex,
          relativePath,
          sourcePath,
          destinationPath,
          stagingPath: paths.stagingPath,
        });
        simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_FILE_COPY");
      },
    );
    const validatedStage = await validateAlphaWorkspaceTree(paths.stagingPath, sourceBefore, parentIdentity);
    const sourceAfterStage = await fingerprintTree(paths.sourceObjectPath);
    assertAlphaWorkspaceSourceStable(sourceBefore, sourceAfterStage);
    await assertAlphaWorkspaceDirectoryTreeOnDevice(
      paths.sourceObjectPath,
      sourceRootIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    await assertDirectoryIdentityStable(paths.sourceObjectPath, sourceRootIdentity, "ALPHA_WORKSPACE_SOURCE_CHANGED", "Prepared-object source root");
    await syncDirectoryTree(paths.stagingPath);
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_STAGE_SYNC");
    await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
    await rename(paths.stagingPath, paths.finalPath);
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_RENAME_BEFORE_PARENT_SYNC");
    await syncDirectory(paths.parentPath);
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_PARENT_SYNC");

    const validatedFinal = await validateAlphaWorkspaceTree(paths.finalPath, sourceBefore, parentIdentity);
    if (validatedFinal.directorySetDigest !== validatedStage.directorySetDigest) {
      fail("ALPHA_WORKSPACE_DIRECTORY_SET_MISMATCH", "Published workspace directory set differs from staging readback.");
    }
    const sourceAfterFinal = await fingerprintTree(paths.sourceObjectPath);
    assertAlphaWorkspaceSourceStable(sourceBefore, sourceAfterFinal);
    await assertAlphaWorkspaceDirectoryTreeOnDevice(
      paths.sourceObjectPath,
      sourceRootIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    await assertDirectoryIdentityStable(paths.sourceObjectPath, sourceRootIdentity, "ALPHA_WORKSPACE_SOURCE_CHANGED", "Prepared-object source root");
    await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");

    const receipt = buildAlphaWorkspaceReceipt(
      intent,
      sourceBefore,
      validatedStage.fingerprint,
      validatedFinal.fingerprint,
      validatedFinal.directorySetDigest,
      validatedFinal.rootIdentity,
    );
    const receiptPath = join(store, "alpha-workspace-receipts", `${receipt.receiptDigest}.json`);
    await writeImmutableRecord(receiptPath, receipt);
    const receiptReadback = await readAlphaWorkspaceReceiptUnlocked(store, receipt.receiptDigest);
    if (canonicalJson(receiptReadback.receipt) !== canonicalJson(receipt)) {
      fail("ALPHA_WORKSPACE_RECEIPT_READBACK_MISMATCH", "Alpha workspace receipt readback differs from the exact record.");
    }
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_RECEIPT");
    return { intent, receipt };
  });
}

type AlphaWorkspaceInspectionUnlockedV1 = {
  receipt: AlphaWorkspaceReceiptV1;
  receiptRecordDigest: string;
  intent: AlphaWorkspaceIntentV1;
  intentRecordDigest: string;
  activationInspection: Awaited<ReturnType<typeof inspectAlphaExecutionActivationUnlocked>>;
  status: AlphaWorkspaceInspectionStatusV1;
};

async function inspectAlphaExecutionWorkspaceUnlocked(
  store: string,
  receiptDigest: string,
  ready: CoordinatorSnapshot,
): Promise<AlphaWorkspaceInspectionUnlockedV1> {
  const { receipt, receiptRecordDigest, intent, intentRecordDigest } =
    await readAlphaWorkspaceReceiptUnlocked(store, receiptDigest);
  const soleReceipt = await readSoleAlphaWorkspaceReceiptForIntentUnlocked(store, intent);
  if (soleReceipt === null || soleReceipt.receiptDigest !== receipt.receiptDigest) {
    fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "Workspace inspection requires the sole exact receipt for this generation.");
  }
  const activationInspection = await inspectAlphaExecutionActivationUnlocked(
    store,
    receipt.activationDigest,
    ready,
  );
  assertAlphaWorkspaceIntentMatchesInspection(intent, activationInspection);
  const base = {
    receipt,
    receiptRecordDigest,
    intent,
    intentRecordDigest,
    activationInspection,
  };
  if (activationInspection.status !== "CURRENT_INERT") {
    return { ...base, status: activationInspection.status };
  }
  const paths = alphaWorkspaceAbsolutePaths(store, intent);
  const cleanupState = await readAlphaWorkspaceCleanupStateUnlocked(store, receipt, intent);
  const stagingExists = await pathExists(paths.stagingPath);
  const finalExists = await pathExists(paths.finalPath);
  const cleanupPathExists = await pathExists(paths.cleanupPath);
  if (cleanupState.status === "TERMINAL") {
    if (stagingExists || finalExists || cleanupPathExists) {
      return { ...base, status: "WORKSPACE_DRIFT" };
    }
    return { ...base, status: "ABSENT" };
  }
  if (cleanupState.status === "PENDING") return { ...base, status: "CLEANUP_PENDING" };
  if (stagingExists || cleanupPathExists || !finalExists) {
    return { ...base, status: "WORKSPACE_DRIFT" };
  }
  try {
    const parentIdentity = await readPrivateDirectoryIdentity(paths.parentPath, "ALPHA_WORKSPACE_PARENT_INVALID", "Alpha workspace parent");
    const sourceIdentity = await readPrivateDirectoryIdentity(paths.sourceObjectPath, "ALPHA_WORKSPACE_SOURCE_INVALID", "Prepared-object source root");
    if (sourceIdentity.deviceId !== parentIdentity.deviceId) return { ...base, status: "WORKSPACE_DRIFT" };
    const source = await fingerprintTree(paths.sourceObjectPath);
    assertAlphaWorkspaceFingerprintOnDevice(
      source,
      sourceIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    await assertAlphaWorkspaceDirectoryTreeOnDevice(
      paths.sourceObjectPath,
      sourceIdentity.deviceId,
      "ALPHA_WORKSPACE_SOURCE_DEVICE_MISMATCH",
      "Prepared-object source",
    );
    const validated = await validateAlphaWorkspaceTree(paths.finalPath, source, parentIdentity);
    const totals = assertAlphaWorkspaceLimits(validated.fingerprint);
    if (
      !directoryIdentityStampsEqual(validated.rootIdentity, receipt.workspace.rootIdentity) ||
      validated.fingerprint.digest !== receipt.workspace.finalDigest ||
      validated.directorySetDigest !== receipt.workspace.directorySetDigest ||
      totals.fileCount !== receipt.workspace.fileCount ||
      totals.totalBytes !== receipt.workspace.totalBytes
    ) {
      return { ...base, status: "WORKSPACE_DRIFT" };
    }
    return { ...base, status: "CURRENT_INERT" };
  } catch (error) {
    if (error instanceof VeritasError) return { ...base, status: "WORKSPACE_DRIFT" };
    throw error;
  }
}

async function inspectAlphaExecutionWorkspace(
  storePath: string,
  receiptDigest: string,
): Promise<{ receipt: AlphaWorkspaceReceiptV1; status: AlphaWorkspaceInspectionStatusV1 }> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    const inspection = await inspectAlphaExecutionWorkspaceUnlocked(store, receiptDigest, ready);
    return { receipt: inspection.receipt, status: inspection.status };
  });
}

function buildAlphaWorkspaceCleanupIntent(
  receipt: AlphaWorkspaceReceiptV1,
): AlphaWorkspaceCleanupIntentV1 {
  const body: Omit<AlphaWorkspaceCleanupIntentV1, "cleanupIntentDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_WORKSPACE_CLEANUP_INTENT",
    cleanupIntentProfile: ALPHA_WORKSPACE_CLEANUP_INTENT_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "CLEANUP_PENDING_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED",
    candidateExecutionAuthority: "NONE",
    maySpawnCandidateProcess: false,
    executionUseLimit: 0,
    receiptDigest: receipt.receiptDigest,
    intentDigest: receipt.intentDigest,
    activationDigest: receipt.activationDigest,
    candidateDigest: receipt.candidateDigest,
    workspaceId: receipt.workspace.workspaceId,
    workspaceRelativePath: receipt.workspace.relativePath,
    rootIdentity: receipt.workspace.rootIdentity,
  };
  return validateAlphaWorkspaceCleanupIntent({
    ...body,
    cleanupIntentDigest: computeAlphaWorkspaceCleanupIntentDigest(body),
  });
}

async function readAlphaWorkspaceCleanupIntentUnlocked(
  store: string,
  cleanupIntentDigest: string,
): Promise<AlphaWorkspaceCleanupIntentV1> {
  if (!isSha256Digest(cleanupIntentDigest)) {
    fail("ALPHA_WORKSPACE_CLEANUP_INTENT_DIGEST_INVALID", "Alpha workspace cleanup-intent lookup requires an exact SHA-256 digest.");
  }
  const verified = await readVerifiedEnvelope<unknown>(
    join(store, "alpha-workspace-cleanup-intents", `${cleanupIntentDigest}.json`),
  );
  const cleanupIntent = validateAlphaWorkspaceCleanupIntent(verified.record);
  if (cleanupIntent.cleanupIntentDigest !== cleanupIntentDigest) {
    fail("ALPHA_WORKSPACE_CLEANUP_INTENT_DIGEST_MISMATCH", "Alpha workspace cleanup-intent pathname and content digest disagree.");
  }
  const { receipt, intent } = await readAlphaWorkspaceReceiptUnlocked(
    store,
    cleanupIntent.receiptDigest,
  );
  if (
    cleanupIntent.intentDigest !== receipt.intentDigest ||
    cleanupIntent.activationDigest !== receipt.activationDigest ||
    cleanupIntent.candidateDigest !== receipt.candidateDigest ||
    cleanupIntent.workspaceId !== receipt.workspace.workspaceId ||
    cleanupIntent.workspaceRelativePath !== receipt.workspace.relativePath ||
    !directoryIdentityStampsEqual(cleanupIntent.rootIdentity, receipt.workspace.rootIdentity) ||
    cleanupIntent.intentDigest !== intent.intentDigest
  ) {
    fail("ALPHA_WORKSPACE_CLEANUP_INTENT_CLOSURE_MISMATCH", "Alpha workspace cleanup intent does not close over its exact receipt and workspace root.");
  }
  return cleanupIntent;
}

function buildAlphaWorkspaceCleanup(
  receipt: AlphaWorkspaceReceiptV1,
  cleanupIntent: AlphaWorkspaceCleanupIntentV1,
): AlphaWorkspaceCleanupV1 {
  const body: Omit<AlphaWorkspaceCleanupV1, "cleanupDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_EXECUTION_WORKSPACE_CLEANUP",
    cleanupProfile: ALPHA_WORKSPACE_CLEANUP_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "ABSENT_NO_CANDIDATE_PROCESS_SPAWNED_BY_THIS_OPERATION_NOT_AUTHORIZED",
    candidateExecutionAuthority: "NONE",
    maySpawnCandidateProcess: false,
    executionUseLimit: 0,
    receiptDigest: receipt.receiptDigest,
    intentDigest: receipt.intentDigest,
    activationDigest: receipt.activationDigest,
    candidateDigest: receipt.candidateDigest,
    workspaceId: receipt.workspace.workspaceId,
    workspaceRelativePath: receipt.workspace.relativePath,
    cleanupIntentDigest: cleanupIntent.cleanupIntentDigest,
  };
  return validateAlphaWorkspaceCleanup({ ...body, cleanupDigest: computeAlphaWorkspaceCleanupDigest(body) });
}

async function readAlphaWorkspaceCleanupUnlocked(
  store: string,
  cleanupDigest: string,
): Promise<AlphaWorkspaceCleanupV1> {
  if (!isSha256Digest(cleanupDigest)) fail("ALPHA_WORKSPACE_CLEANUP_DIGEST_INVALID", "Alpha workspace cleanup lookup requires an exact SHA-256 digest.");
  const verified = await readVerifiedEnvelope<unknown>(join(store, "alpha-workspace-cleanups", `${cleanupDigest}.json`));
  const cleanup = validateAlphaWorkspaceCleanup(verified.record);
  if (cleanup.cleanupDigest !== cleanupDigest) fail("ALPHA_WORKSPACE_CLEANUP_DIGEST_MISMATCH", "Alpha workspace cleanup pathname and content digest disagree.");
  const cleanupIntent = await readAlphaWorkspaceCleanupIntentUnlocked(
    store,
    cleanup.cleanupIntentDigest,
  );
  const { receipt, intent } = await readAlphaWorkspaceReceiptUnlocked(store, cleanup.receiptDigest);
  if (
    cleanup.cleanupIntentDigest !== cleanupIntent.cleanupIntentDigest ||
    cleanup.receiptDigest !== cleanupIntent.receiptDigest ||
    cleanup.intentDigest !== receipt.intentDigest ||
    cleanup.activationDigest !== receipt.activationDigest ||
    cleanup.candidateDigest !== receipt.candidateDigest ||
    cleanup.workspaceId !== receipt.workspace.workspaceId ||
    cleanup.workspaceRelativePath !== receipt.workspace.relativePath ||
    cleanup.intentDigest !== intent.intentDigest
  ) {
    fail("ALPHA_WORKSPACE_CLEANUP_CLOSURE_MISMATCH", "Alpha workspace cleanup does not close over its exact receipt and intent.");
  }
  return cleanup;
}

type AlphaWorkspaceCleanupStateV1 =
  | { status: "NONE" }
  | { status: "PENDING"; cleanupIntent: AlphaWorkspaceCleanupIntentV1 }
  | {
      status: "TERMINAL";
      cleanupIntent: AlphaWorkspaceCleanupIntentV1;
      cleanup: AlphaWorkspaceCleanupV1;
    };

async function readAlphaWorkspaceCleanupStateUnlocked(
  store: string,
  receipt: AlphaWorkspaceReceiptV1,
  intent: AlphaWorkspaceIntentV1,
): Promise<AlphaWorkspaceCleanupStateV1> {
  let terminal: AlphaWorkspaceCleanupV1 | null = null;
  const cleanupNames = (await readdir(join(store, "alpha-workspace-cleanups")))
    .filter((name) => name.endsWith(".json"))
    .sort(codePointCompare);
  for (const name of cleanupNames) {
    const cleanup = await readAlphaWorkspaceCleanupUnlocked(
      store,
      name.slice(0, -".json".length),
    );
    const sameGeneration =
      cleanup.intentDigest === intent.intentDigest ||
      cleanup.workspaceId === intent.workspace.workspaceId;
    if (!sameGeneration) continue;
    if (
      cleanup.receiptDigest !== receipt.receiptDigest ||
      cleanup.intentDigest !== intent.intentDigest ||
      cleanup.workspaceId !== intent.workspace.workspaceId
    ) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Cleanup identity and workspace generation disagree.");
    }
    if (terminal !== null) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "One workspace generation has multiple terminal cleanup records.");
    }
    terminal = cleanup;
  }

  let pending: AlphaWorkspaceCleanupIntentV1 | null = null;
  const pendingNames = (await readdir(join(store, "alpha-workspace-cleanup-intents")))
    .filter((name) => name.endsWith(".json"))
    .sort(codePointCompare);
  for (const name of pendingNames) {
    const cleanupIntent = await readAlphaWorkspaceCleanupIntentUnlocked(
      store,
      name.slice(0, -".json".length),
    );
    const sameGeneration =
      cleanupIntent.intentDigest === intent.intentDigest ||
      cleanupIntent.workspaceId === intent.workspace.workspaceId;
    if (!sameGeneration) continue;
    if (
      cleanupIntent.receiptDigest !== receipt.receiptDigest ||
      cleanupIntent.intentDigest !== intent.intentDigest ||
      cleanupIntent.workspaceId !== intent.workspace.workspaceId
    ) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Cleanup intent identity and workspace generation disagree.");
    }
    if (pending !== null) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "One workspace generation has multiple cleanup intents.");
    }
    pending = cleanupIntent;
  }

  if (terminal !== null) {
    if (
      pending === null ||
      terminal.cleanupIntentDigest !== pending.cleanupIntentDigest
    ) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Terminal cleanup lacks its one exact cleanup-intent barrier.");
    }
    return { status: "TERMINAL", cleanupIntent: pending, cleanup: terminal };
  }
  if (pending !== null) return { status: "PENDING", cleanupIntent: pending };
  return { status: "NONE" };
}

async function assertAlphaWorkspaceNotTerminallyCleanedUnlocked(
  store: string,
  intent: AlphaWorkspaceIntentV1,
): Promise<void> {
  const names = (await readdir(join(store, "alpha-workspace-cleanups")))
    .filter((name) => name.endsWith(".json"))
    .sort(codePointCompare);
  for (const name of names) {
    const cleanupDigest = name.slice(0, -".json".length);
    const cleanup = await readAlphaWorkspaceCleanupUnlocked(store, cleanupDigest);
    if (
      cleanup.intentDigest === intent.intentDigest ||
      cleanup.workspaceId === intent.workspace.workspaceId
    ) {
      fail("ALPHA_WORKSPACE_CLEANUP_TERMINAL", "A terminal cleanup record prevents recreation of this exact workspace generation.", {
        cleanupDigest: cleanup.cleanupDigest,
        workspaceId: cleanup.workspaceId,
      });
    }
  }
  const pendingNames = (await readdir(join(store, "alpha-workspace-cleanup-intents")))
    .filter((name) => name.endsWith(".json"))
    .sort(codePointCompare);
  for (const name of pendingNames) {
    const cleanupIntentDigest = name.slice(0, -".json".length);
    const cleanupIntent = await readAlphaWorkspaceCleanupIntentUnlocked(
      store,
      cleanupIntentDigest,
    );
    if (
      cleanupIntent.intentDigest === intent.intentDigest ||
      cleanupIntent.workspaceId === intent.workspace.workspaceId
    ) {
      fail("ALPHA_WORKSPACE_CLEANUP_PENDING", "A durable cleanup barrier prevents recreation of this workspace generation.", {
        cleanupIntentDigest: cleanupIntent.cleanupIntentDigest,
        workspaceId: cleanupIntent.workspaceId,
      });
    }
  }
}

async function cleanupAlphaExecutionWorkspace(
  storePath: string,
  receiptDigest: string,
  hooks: { simulateCrashAt?: SimulatedCrashPoint } = {},
): Promise<{ cleanup: AlphaWorkspaceCleanupV1; status: "ABSENT" }> {
  if (hooks.simulateCrashAt !== undefined && !boundedTestLaneActive()) {
    fail("TEST_ONLY_ALPHA_WORKSPACE_HOOK_REJECTED", "Alpha workspace cleanup hooks require the bounded test lane.");
  }
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const { receipt, intent } = await readAlphaWorkspaceReceiptUnlocked(store, receiptDigest);
    const soleReceipt = await readSoleAlphaWorkspaceReceiptForIntentUnlocked(store, intent);
    if (soleReceipt === null || soleReceipt.receiptDigest !== receipt.receiptDigest) {
      fail("ALPHA_WORKSPACE_RECEIPT_CONFLICT", "Workspace cleanup requires the sole exact receipt for this generation.");
    }
    const cleanupIntent = buildAlphaWorkspaceCleanupIntent(receipt);
    const cleanupIntentPath = join(
      store,
      "alpha-workspace-cleanup-intents",
      `${cleanupIntent.cleanupIntentDigest}.json`,
    );
    await writeImmutableRecord(cleanupIntentPath, cleanupIntent);
    const cleanupIntentReadback = await readAlphaWorkspaceCleanupIntentUnlocked(
      store,
      cleanupIntent.cleanupIntentDigest,
    );
    if (canonicalJson(cleanupIntentReadback) !== canonicalJson(cleanupIntent)) {
      fail("ALPHA_WORKSPACE_CLEANUP_INTENT_READBACK_MISMATCH", "Alpha workspace cleanup-intent readback differs from the exact pending barrier.");
    }
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_CLEANUP_INTENT");
    const cleanup = buildAlphaWorkspaceCleanup(receipt, cleanupIntent);
    const cleanupRecordPath = join(store, "alpha-workspace-cleanups", `${cleanup.cleanupDigest}.json`);
    const paths = alphaWorkspaceAbsolutePaths(store, intent);
    const parentIdentity = await readPrivateDirectoryIdentity(paths.parentPath, "ALPHA_WORKSPACE_PARENT_INVALID", "Alpha workspace parent");
    if (await pathExists(cleanupRecordPath)) {
      const existing = await readAlphaWorkspaceCleanupUnlocked(store, cleanup.cleanupDigest);
      if (canonicalJson(existing) !== canonicalJson(cleanup)) {
        fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Existing alpha workspace cleanup differs from the exact absence record.");
      }
      if (
        (await pathExists(paths.stagingPath)) ||
        (await pathExists(paths.finalPath)) ||
        (await pathExists(paths.cleanupPath))
      ) {
        fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Cleanup record exists while workspace content remains.");
      }
      return { cleanup: existing, status: "ABSENT" };
    }

    if (await pathExists(paths.stagingPath)) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "A receipt-bound workspace cannot retain a materialization staging path.");
    }
    const finalExists = await pathExists(paths.finalPath);
    const cleanupPathExists = await pathExists(paths.cleanupPath);
    if (finalExists && cleanupPathExists) {
      fail("ALPHA_WORKSPACE_CLEANUP_CONFLICT", "Final and cleanup-quarantine paths cannot coexist.");
    }
    if (cleanupPathExists) {
      await assertDirectoryIdentityStable(
        paths.cleanupPath,
        receipt.workspace.rootIdentity,
        "ALPHA_WORKSPACE_ROOT_REBOUND",
        "Quarantined alpha workspace",
        "0700",
      );
      await assertAlphaWorkspaceDirectoryTreeOnDevice(
        paths.cleanupPath,
        receipt.workspace.rootIdentity.deviceId,
        "ALPHA_WORKSPACE_ROOT_INVALID",
        "Quarantined alpha workspace",
      );
      await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
      await assertDirectoryIdentityStable(
        paths.cleanupPath,
        receipt.workspace.rootIdentity,
        "ALPHA_WORKSPACE_ROOT_REBOUND",
        "Quarantined alpha workspace",
        "0700",
      );
      await rm(paths.cleanupPath, { recursive: true, force: false });
      await syncDirectory(paths.parentPath);
    } else if (finalExists) {
      await removeExactAlphaWorkspaceDirectory(
        paths.parentPath,
        paths.finalPath,
        paths.cleanupPath,
        receipt.workspace.rootIdentity,
        parentIdentity,
        hooks,
        "AFTER_ALPHA_WORKSPACE_CLEANUP_RENAME",
      );
    }
    simulateCrash(hooks, "AFTER_ALPHA_WORKSPACE_CLEANUP_DELETE");
    if ((await pathExists(paths.finalPath)) || (await pathExists(paths.cleanupPath))) {
      fail("ALPHA_WORKSPACE_CLEANUP_INCOMPLETE", "Alpha workspace cleanup did not reach exact absence.");
    }
    await assertDirectoryIdentityStable(paths.parentPath, parentIdentity, "ALPHA_WORKSPACE_PARENT_REBOUND", "Alpha workspace parent");
    await writeImmutableRecord(cleanupRecordPath, cleanup);
    const readback = await readAlphaWorkspaceCleanupUnlocked(store, cleanup.cleanupDigest);
    if (canonicalJson(readback) !== canonicalJson(cleanup)) {
      fail("ALPHA_WORKSPACE_CLEANUP_READBACK_MISMATCH", "Alpha workspace cleanup readback differs from the exact record.");
    }
    return { cleanup, status: "ABSENT" };
  });
}

function computeAlphaRunnerArgvDigest(argv: string[]): string {
  return sha256Bytes(`veritas-alpha-runner-argv-v1\0${canonicalJson(argv)}`);
}

function computeAlphaRunnerEnvironmentDigest(environment: { LANG: "C"; LC_ALL: "C" }): string {
  return sha256Bytes(`veritas-alpha-runner-environment-v1\0${canonicalJson(environment)}`);
}

function computeAlphaRunnerBoundaryCapsuleDigest(
  body: Omit<AlphaRunnerBoundaryCapsuleV1, "capsuleDigest">,
): string {
  return sha256Bytes(`${ALPHA_RUNNER_BOUNDARY_CAPSULE_PROFILE}\0${canonicalJson(body)}`);
}

function isUnsignedDecimalString(value: unknown): value is string {
  return typeof value === "string" && /^(0|[1-9][0-9]*)$/.test(value);
}

function validateAlphaRunnerBoundaryCapsule(value: unknown): AlphaRunnerBoundaryCapsuleV1 {
  requireExactObjectKeys(value, ALPHA_RUNNER_CAPSULE_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner boundary capsule");
  const record = value as Partial<AlphaRunnerBoundaryCapsuleV1>;
  requireExactObjectKeys(record.activation, ALPHA_RUNNER_CAPSULE_ACTIVATION_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule activation binding");
  requireExactObjectKeys(record.coordinator, ALPHA_EXECUTION_COORDINATOR_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule coordinator binding");
  requireExactObjectKeys(record.workspace, ALPHA_RUNNER_CAPSULE_WORKSPACE_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule workspace binding");
  requireExactObjectKeys(record.runner, ALPHA_RUNNER_CAPSULE_RUNNER_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule runner binding");
  requireExactObjectKeys(record.command, ALPHA_RUNNER_CAPSULE_COMMAND_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule command binding");
  requireExactObjectKeys(record.limits, ALPHA_RUNNER_CAPSULE_LIMIT_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule limits");
  requireExactObjectKeys(record.containment, ALPHA_RUNNER_CAPSULE_CONTAINMENT_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule containment requirements");
  requireExactObjectKeys(record.validity, ALPHA_RUNNER_CAPSULE_VALIDITY_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule validity");

  const activation = record.activation as AlphaRunnerBoundaryCapsuleV1["activation"];
  const coordinator = record.coordinator as AlphaRunnerBoundaryCapsuleV1["coordinator"];
  const workspace = record.workspace as AlphaRunnerBoundaryCapsuleV1["workspace"];
  const runner = record.runner as AlphaRunnerBoundaryCapsuleV1["runner"];
  const command = record.command as AlphaRunnerBoundaryCapsuleV1["command"];
  const limits = record.limits as AlphaRunnerBoundaryCapsuleV1["limits"];
  const containment = record.containment as AlphaRunnerBoundaryCapsuleV1["containment"];
  const validity = record.validity as AlphaRunnerBoundaryCapsuleV1["validity"];
  requireExactObjectKeys(workspace.rootIdentity, DIRECTORY_IDENTITY_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule workspace root identity");
  requireExactObjectKeys(runner.fileIdentity, FILE_IDENTITY_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule file identity");
  requireExactObjectKeys(command.environment, ALPHA_RUNNER_CAPSULE_ENVIRONMENT_KEYS, "ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner capsule environment");

  const rootIdentity = workspace.rootIdentity;
  const fileIdentity = runner.fileIdentity;
  const argvBytes = Array.isArray(command.argv)
    ? Buffer.byteLength(canonicalJson(command.argv), "utf8")
    : Number.POSITIVE_INFINITY;
  const digestFields = [
    activation.activationDigest,
    activation.activationRecordDigest,
    activation.approvalDigest,
    activation.approvalRecordDigest,
    activation.profileDigest,
    activation.proposalRecordDigest,
    activation.decisionDigest,
    activation.candidateDigest,
    activation.authorityDigest,
    coordinator.stateDigest,
    coordinator.headRecordDigest,
    coordinator.commitRecordDigest,
    coordinator.migrationRecordDigest,
    coordinator.storageAdmissionRecordDigest,
    workspace.receiptDigest,
    workspace.receiptRecordDigest,
    workspace.intentDigest,
    workspace.intentRecordDigest,
    workspace.workspaceId,
    workspace.finalDigest,
    workspace.directorySetDigest,
    runner.binaryDigest,
    command.argvDigest,
    command.environmentDigest,
    record.capsuleDigest,
  ];
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_RUNNER_BOUNDARY_CAPSULE" ||
    record.capsuleProfile !== ALPHA_RUNNER_BOUNDARY_CAPSULE_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "BOUND_POINT_IN_TIME_NOT_AUTHORIZED_NOT_EXECUTABLE" ||
    record.executionAuthority !== "NONE" ||
    record.maySpawnProcess !== false ||
    record.executionUseLimit !== 0 ||
    digestFields.some((field) => !isSha256Digest(field)) ||
    !Number.isSafeInteger(activation.dependencyEpoch) || activation.dependencyEpoch < 0 ||
    !isCanonicalUuidV4(coordinator.storeId) ||
    !Number.isSafeInteger(coordinator.revision) || coordinator.revision < 0 ||
    !Number.isSafeInteger(coordinator.dependencyEpoch) ||
    coordinator.dependencyEpoch !== activation.dependencyEpoch ||
    coordinator.phase !== "READY" ||
    workspace.relativePath !== `alpha-execution-workspaces/${workspace.workspaceId}` ||
    workspace.sourceObjectRelativePath !== `objects/${activation.candidateDigest}` ||
    workspace.finalDigest !== activation.candidateDigest ||
    workspace.observedStatus !== "CURRENT_INERT" ||
    !isUnsignedDecimalString(rootIdentity.deviceId) ||
    !isUnsignedDecimalString(rootIdentity.inodeId) ||
    !isUnsignedDecimalString(rootIdentity.ownerUid) ||
    !isUnsignedDecimalString(rootIdentity.ownerGid) ||
    rootIdentity.mode !== "0700" ||
    typeof runner.profileId !== "string" || runner.profileId.length === 0 ||
    typeof runner.canonicalPath !== "string" || !isAbsolute(runner.canonicalPath) ||
    runner.identityBasis !== "POINT_IN_TIME_STABLE_READBACK_NOT_SPAWN_PINNING" ||
    !isUnsignedDecimalString(fileIdentity.deviceId) ||
    !isUnsignedDecimalString(fileIdentity.inodeId) ||
    !isUnsignedDecimalString(fileIdentity.ctimeNs) ||
    !isUnsignedDecimalString(fileIdentity.mtimeNs) ||
    fileIdentity.linkCount !== "1" ||
    !isUnsignedDecimalString(fileIdentity.size) ||
    !isUnsignedDecimalString(fileIdentity.mode) ||
    !Array.isArray(command.argv) ||
    command.argv.length === 0 || command.argv.length > 128 ||
    command.argv.some((argument) => typeof argument !== "string" || argument.includes("\0")) ||
    argvBytes > 65_536 ||
    command.argv[0] !== runner.canonicalPath ||
    command.argvDigest !== computeAlphaRunnerArgvDigest(command.argv) ||
    command.cwdRelativePath !== workspace.relativePath ||
    command.environment.LANG !== "C" || command.environment.LC_ALL !== "C" ||
    command.environmentDigest !== computeAlphaRunnerEnvironmentDigest(command.environment) ||
    command.inheritEnvironment !== false ||
    command.stdin !== "NONE" ||
    !Number.isSafeInteger(limits.timeoutMs) || limits.timeoutMs < 100 || limits.timeoutMs > 60_000 ||
    limits.stdoutLimitBytes !== 262144 ||
    limits.stderrLimitBytes !== 262144 ||
    containment.descriptorRelativeWorkspace !== "REQUIRED_NOT_IMPLEMENTED" ||
    containment.spawnFromVerifiedRunnerObject !== "REQUIRED_NOT_IMPLEMENTED" ||
    containment.network !== "DENY_ALL_REQUIRED_NOT_IMPLEMENTED" ||
    containment.sandbox !== "NATIVE_BACKEND_REQUIRED_NOT_IMPLEMENTED" ||
    containment.descendants !== "TERMINATE_TREE_REQUIRED_NOT_IMPLEMENTED" ||
    containment.resourceLimits !== "NATIVE_ENFORCEMENT_REQUIRED_NOT_IMPLEMENTED" ||
    containment.satisfied !== false ||
    validity.basis !== "POINT_IN_TIME_EXACT_ACTIVATION_COORDINATOR_WORKSPACE_RUNNER_AND_COMMAND" ||
    validity.revocationMode !== "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_OR_RUNNER_DRIFT" ||
    validity.wallClockExpiry !== "NOT_ESTABLISHED"
  ) {
    fail("ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner boundary capsule is outside the exact zero-authority point-in-time profile.");
  }
  const body = { ...record } as Partial<AlphaRunnerBoundaryCapsuleV1>;
  delete body.capsuleDigest;
  if (
    record.capsuleDigest !==
    computeAlphaRunnerBoundaryCapsuleDigest(
      body as Omit<AlphaRunnerBoundaryCapsuleV1, "capsuleDigest">,
    )
  ) {
    fail("ALPHA_RUNNER_CAPSULE_INVALID", "Alpha runner boundary capsule digest does not bind the exact record body.");
  }
  return record as AlphaRunnerBoundaryCapsuleV1;
}

function buildAlphaRunnerBoundaryCapsule(
  inspection: AlphaWorkspaceInspectionUnlockedV1,
  runnerReadback: { bytes: Buffer; identity: FileIdentityStamp },
): AlphaRunnerBoundaryCapsuleV1 {
  if (
    inspection.status !== "CURRENT_INERT" ||
    inspection.activationInspection.status !== "CURRENT_INERT" ||
    inspection.activationInspection.closure === null
  ) {
    fail("ALPHA_RUNNER_CAPSULE_WORKSPACE_NOT_CURRENT", "Runner capsule construction requires one current inert workspace closure.");
  }
  const activationInspection = inspection.activationInspection;
  const closure = activationInspection.closure;
  if (closure === null) {
    fail(
      "ALPHA_RUNNER_CAPSULE_WORKSPACE_NOT_CURRENT",
      "Runner capsule construction requires one current inert workspace closure.",
    );
  }
  const activation = activationInspection.activation;
  const proposal = closure.proposal;
  const environment = { LANG: "C", LC_ALL: "C" } as const;
  const argv = [proposal.executablePath, ...proposal.args];
  const body: Omit<AlphaRunnerBoundaryCapsuleV1, "capsuleDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_RUNNER_BOUNDARY_CAPSULE",
    capsuleProfile: ALPHA_RUNNER_BOUNDARY_CAPSULE_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "BOUND_POINT_IN_TIME_NOT_AUTHORIZED_NOT_EXECUTABLE",
    executionAuthority: "NONE",
    maySpawnProcess: false,
    executionUseLimit: 0,
    activation: {
      activationDigest: activation.activationDigest,
      activationRecordDigest: activationInspection.activationRecordDigest,
      approvalDigest: activation.approvalDigest,
      approvalRecordDigest: activationInspection.approvalRecordDigest,
      profileDigest: activation.profileDigest,
      proposalRecordDigest: activation.proposalRecordDigest,
      decisionDigest: activation.decisionDigest,
      candidateDigest: activation.candidateDigest,
      authorityDigest: activation.authorityDigest,
      dependencyEpoch: activation.dependencyEpoch,
    },
    coordinator: { ...activation.coordinator },
    workspace: {
      receiptDigest: inspection.receipt.receiptDigest,
      receiptRecordDigest: inspection.receiptRecordDigest,
      intentDigest: inspection.intent.intentDigest,
      intentRecordDigest: inspection.intentRecordDigest,
      workspaceId: inspection.receipt.workspace.workspaceId,
      relativePath: inspection.receipt.workspace.relativePath,
      sourceObjectRelativePath: inspection.receipt.workspace.sourceObjectRelativePath,
      finalDigest: inspection.receipt.workspace.finalDigest,
      directorySetDigest: inspection.receipt.workspace.directorySetDigest,
      rootIdentity: { ...inspection.receipt.workspace.rootIdentity },
      observedStatus: "CURRENT_INERT",
    },
    runner: {
      profileId: proposal.profileId,
      canonicalPath: proposal.executablePath,
      binaryDigest: sha256Bytes(runnerReadback.bytes),
      fileIdentity: { ...runnerReadback.identity },
      identityBasis: "POINT_IN_TIME_STABLE_READBACK_NOT_SPAWN_PINNING",
    },
    command: {
      argv,
      argvDigest: computeAlphaRunnerArgvDigest(argv),
      cwdRelativePath: inspection.receipt.workspace.relativePath,
      environment,
      environmentDigest: computeAlphaRunnerEnvironmentDigest(environment),
      inheritEnvironment: false,
      stdin: "NONE",
    },
    limits: {
      timeoutMs: proposal.timeoutMs,
      stdoutLimitBytes: activationInspection.approval.commandPolicy.stdoutLimitBytes,
      stderrLimitBytes: activationInspection.approval.commandPolicy.stderrLimitBytes,
    },
    containment: {
      descriptorRelativeWorkspace: "REQUIRED_NOT_IMPLEMENTED",
      spawnFromVerifiedRunnerObject: "REQUIRED_NOT_IMPLEMENTED",
      network: "DENY_ALL_REQUIRED_NOT_IMPLEMENTED",
      sandbox: "NATIVE_BACKEND_REQUIRED_NOT_IMPLEMENTED",
      descendants: "TERMINATE_TREE_REQUIRED_NOT_IMPLEMENTED",
      resourceLimits: "NATIVE_ENFORCEMENT_REQUIRED_NOT_IMPLEMENTED",
      satisfied: false,
    },
    validity: {
      basis: "POINT_IN_TIME_EXACT_ACTIVATION_COORDINATOR_WORKSPACE_RUNNER_AND_COMMAND",
      revocationMode: "DEPENDENCY_EPOCH_OR_SNAPSHOT_SUPERSESSION_OR_WORKSPACE_OR_RUNNER_DRIFT",
      wallClockExpiry: "NOT_ESTABLISHED",
    },
  };
  return validateAlphaRunnerBoundaryCapsule({
    ...body,
    capsuleDigest: computeAlphaRunnerBoundaryCapsuleDigest(body),
  });
}

async function readAlphaRunnerBoundaryCapsuleUnlocked(
  store: string,
  capsuleDigest: string,
): Promise<{ capsule: AlphaRunnerBoundaryCapsuleV1; capsuleRecordDigest: string }> {
  if (!isSha256Digest(capsuleDigest)) {
    fail("ALPHA_RUNNER_CAPSULE_DIGEST_INVALID", "Alpha runner capsule lookup requires an exact SHA-256 digest.");
  }
  const verified = await readVerifiedEnvelope<unknown>(
    join(store, "alpha-runner-boundary-capsules", `${capsuleDigest}.json`),
  );
  const capsule = validateAlphaRunnerBoundaryCapsule(verified.record);
  if (capsule.capsuleDigest !== capsuleDigest) {
    fail("ALPHA_RUNNER_CAPSULE_DIGEST_MISMATCH", "Alpha runner capsule pathname and content digest disagree.");
  }
  return { capsule, capsuleRecordDigest: verified.recordDigest };
}

function assertAlphaRunnerCapsuleLineage(
  capsule: AlphaRunnerBoundaryCapsuleV1,
  inspection: AlphaWorkspaceInspectionUnlockedV1,
): void {
  const activationInspection = inspection.activationInspection;
  const activation = activationInspection.activation;
  if (
    capsule.activation.activationDigest !== activation.activationDigest ||
    capsule.activation.activationRecordDigest !== activationInspection.activationRecordDigest ||
    capsule.activation.approvalDigest !== activation.approvalDigest ||
    capsule.activation.approvalRecordDigest !== activationInspection.approvalRecordDigest ||
    capsule.activation.profileDigest !== activation.profileDigest ||
    capsule.activation.proposalRecordDigest !== activation.proposalRecordDigest ||
    capsule.activation.decisionDigest !== activation.decisionDigest ||
    capsule.activation.candidateDigest !== activation.candidateDigest ||
    capsule.activation.authorityDigest !== activation.authorityDigest ||
    capsule.activation.dependencyEpoch !== activation.dependencyEpoch ||
    canonicalJson(capsule.coordinator) !== canonicalJson(activation.coordinator) ||
    capsule.workspace.receiptDigest !== inspection.receipt.receiptDigest ||
    capsule.workspace.receiptRecordDigest !== inspection.receiptRecordDigest ||
    capsule.workspace.intentDigest !== inspection.intent.intentDigest ||
    capsule.workspace.intentRecordDigest !== inspection.intentRecordDigest ||
    capsule.workspace.workspaceId !== inspection.receipt.workspace.workspaceId ||
    capsule.workspace.relativePath !== inspection.receipt.workspace.relativePath ||
    capsule.workspace.sourceObjectRelativePath !== inspection.receipt.workspace.sourceObjectRelativePath ||
    capsule.workspace.finalDigest !== inspection.receipt.workspace.finalDigest ||
    capsule.workspace.directorySetDigest !== inspection.receipt.workspace.directorySetDigest ||
    !directoryIdentityStampsEqual(
      capsule.workspace.rootIdentity,
      inspection.receipt.workspace.rootIdentity,
    )
  ) {
    fail("ALPHA_RUNNER_CAPSULE_CLOSURE_MISMATCH", "Alpha runner capsule does not close over its exact activation and workspace lineage.");
  }
}

async function assertAlphaRunnerCapsuleHistoricalCommandClosure(
  store: string,
  capsule: AlphaRunnerBoundaryCapsuleV1,
  activationInspection: Awaited<ReturnType<typeof inspectAlphaExecutionActivationUnlocked>>,
): Promise<void> {
  const verifiedProposal = await readVerifiedEnvelope<unknown>(
    join(
      store,
      "alpha-profile-proposals",
      `${capsule.activation.profileDigest}.json`,
    ),
  );
  const proposal = validateAlphaProfileProposal(verifiedProposal.record);
  const approvalProposal = activationInspection.approval.proposal;
  const expectedArgv = [proposal.executablePath, ...proposal.args];
  if (
    proposal.profileDigest !== capsule.activation.profileDigest ||
    verifiedProposal.recordDigest !== capsule.activation.proposalRecordDigest ||
    approvalProposal.profileDigest !== proposal.profileDigest ||
    approvalProposal.proposalRecordDigest !== verifiedProposal.recordDigest ||
    approvalProposal.profileId !== proposal.profileId ||
    approvalProposal.executableDigest !== proposal.executableDigest ||
    approvalProposal.argsDigest !== alphaExecutionArgsDigest(proposal.args) ||
    approvalProposal.timeoutMs !== proposal.timeoutMs ||
    capsule.runner.profileId !== proposal.profileId ||
    capsule.runner.canonicalPath !== proposal.executablePath ||
    capsule.runner.binaryDigest !== proposal.executableDigest ||
    canonicalJson(capsule.command.argv) !== canonicalJson(expectedArgv) ||
    capsule.command.argvDigest !== computeAlphaRunnerArgvDigest(expectedArgv) ||
    capsule.limits.timeoutMs !== proposal.timeoutMs ||
    capsule.limits.stdoutLimitBytes !== activationInspection.approval.commandPolicy.stdoutLimitBytes ||
    capsule.limits.stderrLimitBytes !== activationInspection.approval.commandPolicy.stderrLimitBytes
  ) {
    fail("ALPHA_RUNNER_CAPSULE_CLOSURE_MISMATCH", "Alpha runner capsule differs from its exact immutable proposal-derived command closure.");
  }
}

async function readCurrentAlphaRunner(
  store: string,
  proposal: AlphaProfileProposalV1,
): Promise<{ bytes: Buffer; identity: FileIdentityStamp }> {
  let runnerPath: string;
  try {
    runnerPath = await realpath(proposal.executablePath);
  } catch {
    fail("ALPHA_RUNNER_CAPSULE_RUNNER_INVALID", "Alpha runner path is not currently readable as the proposed canonical path.");
  }
  if (
    runnerPath !== proposal.executablePath ||
    isWithin(proposal.projectRoot, runnerPath) ||
    isWithin(store, runnerPath)
  ) {
    fail("ALPHA_RUNNER_CAPSULE_RUNNER_INVALID", "Alpha runner path is no longer canonical and separated from candidate and store content.");
  }
  const runner = await readStableRegularFile(
    runnerPath,
    "ALPHA_RUNNER_CAPSULE_RUNNER_INVALID",
    "Alpha runner capsule binary",
  );
  assertAlphaExecutableSingleLink(runner.identity);
  if (sha256Bytes(runner.bytes) !== proposal.executableDigest) {
    fail("ALPHA_RUNNER_CAPSULE_RUNNER_INVALID", "Alpha runner bytes differ from the exact profile proposal.");
  }
  return runner;
}

async function recordAlphaRunnerBoundaryCapsule(
  storePath: string,
  receiptDigest: string,
  hooks: { simulateCrashAt?: SimulatedCrashPoint } = {},
): Promise<AlphaRunnerBoundaryCapsuleV1> {
  if (hooks.simulateCrashAt !== undefined && !boundedTestLaneActive()) {
    fail("TEST_ONLY_ALPHA_RUNNER_CAPSULE_HOOK_REJECTED", "Alpha runner capsule hooks require the bounded test lane.");
  }
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    const inspection = await inspectAlphaExecutionWorkspaceUnlocked(store, receiptDigest, ready);
    if (
      inspection.status === "RECALLED_BY_DEPENDENCY_EPOCH" ||
      inspection.status === "SUPERSEDED_COORDINATOR_SNAPSHOT"
    ) {
      fail("ALPHA_RUNNER_CAPSULE_ACTIVATION_NOT_CURRENT", "Runner capsule construction requires a current inert activation.", {
        status: inspection.status,
      });
    }
    if (inspection.status !== "CURRENT_INERT" || inspection.activationInspection.closure === null) {
      fail("ALPHA_RUNNER_CAPSULE_WORKSPACE_NOT_CURRENT", "Runner capsule construction requires a current inert workspace.", {
        status: inspection.status,
      });
    }
    const runner = await readCurrentAlphaRunner(store, inspection.activationInspection.closure.proposal);
    const capsule = buildAlphaRunnerBoundaryCapsule(inspection, runner);
    const capsulePath = join(
      store,
      "alpha-runner-boundary-capsules",
      `${capsule.capsuleDigest}.json`,
    );
    await writeImmutableRecord(capsulePath, capsule);
    simulateCrash(hooks, "AFTER_ALPHA_RUNNER_BOUNDARY_CAPSULE");
    const readback = await readAlphaRunnerBoundaryCapsuleUnlocked(store, capsule.capsuleDigest);
    if (canonicalJson(readback.capsule) !== canonicalJson(capsule)) {
      fail("ALPHA_RUNNER_CAPSULE_READBACK_MISMATCH", "Alpha runner capsule readback differs from the exact immutable record.");
    }
    return capsule;
  });
}

async function inspectAlphaRunnerBoundaryCapsuleUnlocked(
  store: string,
  capsuleDigest: string,
  ready: CoordinatorSnapshot,
): Promise<{ capsule: AlphaRunnerBoundaryCapsuleV1; status: AlphaRunnerBoundaryInspectionStatusV1 }> {
  const { capsule } = await readAlphaRunnerBoundaryCapsuleUnlocked(store, capsuleDigest);
  const inspection = await inspectAlphaExecutionWorkspaceUnlocked(
    store,
    capsule.workspace.receiptDigest,
    ready,
  );
  assertAlphaRunnerCapsuleLineage(capsule, inspection);
  await assertAlphaRunnerCapsuleHistoricalCommandClosure(
    store,
    capsule,
    inspection.activationInspection,
  );
  if (inspection.status !== "CURRENT_INERT") {
    return { capsule, status: inspection.status };
  }
  const closure = inspection.activationInspection.closure;
  if (closure === null) {
    fail("ALPHA_RUNNER_CAPSULE_CLOSURE_MISMATCH", "Current runner capsule inspection lacks its profile closure.");
  }
  try {
    const runner = await readCurrentAlphaRunner(store, closure.proposal);
    if (
      capsule.runner.canonicalPath !== closure.proposal.executablePath ||
      capsule.runner.profileId !== closure.proposal.profileId ||
      capsule.runner.binaryDigest !== closure.proposal.executableDigest ||
      !fileIdentityStampsEqual(capsule.runner.fileIdentity, runner.identity)
    ) {
      return { capsule, status: "RUNNER_DRIFT" };
    }
    const expected = buildAlphaRunnerBoundaryCapsule(inspection, runner);
    if (canonicalJson(expected) !== canonicalJson(capsule)) {
      fail("ALPHA_RUNNER_CAPSULE_CLOSURE_MISMATCH", "Alpha runner capsule command or policy differs from the exact current proposal closure.");
    }
    return { capsule, status: "CURRENT_INERT" };
  } catch (error) {
    if (
      error instanceof VeritasError &&
      (error.code === "ALPHA_RUNNER_CAPSULE_RUNNER_INVALID" ||
        error.code === "ALPHA_EXECUTABLE_HARDLINK_ALIAS")
    ) {
      return { capsule, status: "RUNNER_DRIFT" };
    }
    throw error;
  }
}

async function inspectAlphaRunnerBoundaryCapsule(
  storePath: string,
  capsuleDigest: string,
): Promise<{ capsule: AlphaRunnerBoundaryCapsuleV1; status: AlphaRunnerBoundaryInspectionStatusV1 }> {
  const store = await ensureStore(storePath);
  return withStoreLock(store, async () => {
    await reconcileUnlocked(store);
    const ready = await readCoordinatorSnapshotUnlocked(store);
    return inspectAlphaRunnerBoundaryCapsuleUnlocked(store, capsuleDigest, ready);
  });
}

async function inspectAlphaRunnerBoundaryCapsuleForFinalHandleUnlocked(
  store: string,
  capsuleDigest: string,
  ready: CoordinatorSnapshot,
): Promise<{ capsule: AlphaRunnerBoundaryCapsuleV1; status: AlphaRunnerBoundaryInspectionStatusV1 }> {
  try {
    return await inspectAlphaRunnerBoundaryCapsuleUnlocked(store, capsuleDigest, ready);
  } catch (error) {
    if (
      error instanceof VeritasError &&
      (error.code === "ALPHA_EXECUTABLE_HARDLINK_ALIAS" ||
        error.code === "ALPHA_EXECUTABLE_INVALID" ||
        error.code === "ALPHA_EXECUTABLE_DIGEST_MISMATCH" ||
        error.code === "ALPHA_RUNNER_CAPSULE_RUNNER_INVALID")
    ) {
      const { capsule } = await readAlphaRunnerBoundaryCapsuleUnlocked(
        store,
        capsuleDigest,
      );
      return { capsule, status: "RUNNER_DRIFT" };
    }
    throw error;
  }
}

function directoryIdentityStampFromStat(
  information: Awaited<ReturnType<Awaited<ReturnType<typeof open>>["stat"]>>,
): DirectoryIdentityStamp {
  const value = information as unknown as {
    dev: bigint;
    ino: bigint;
    uid: bigint;
    gid: bigint;
    mode: bigint;
  };
  return {
    deviceId: String(value.dev),
    inodeId: String(value.ino),
    ownerUid: String(value.uid),
    ownerGid: String(value.gid),
    mode: (value.mode & 0o7777n).toString(8).padStart(4, "0"),
  };
}

function requireAlphaFinalHandlePlatform(): void {
  if (
    typeof fsConstants.O_NOFOLLOW !== "number" ||
    typeof fsConstants.O_DIRECTORY !== "number"
  ) {
    fail(
      "ALPHA_FINAL_HANDLE_PLATFORM_UNSUPPORTED",
      "Final-handle observation requires O_NOFOLLOW and O_DIRECTORY with no fallback path walk.",
    );
  }
}

function assertAlphaFinalWorkspaceDirectory(
  information: Awaited<ReturnType<Awaited<ReturnType<typeof open>>["stat"]>>,
  identity: DirectoryIdentityStamp,
  expected: DirectoryIdentityStamp,
): void {
  const effectiveUid = typeof process.getuid === "function" ? String(process.getuid()) : null;
  if (
    !information.isDirectory() ||
    effectiveUid === null ||
    identity.ownerUid !== effectiveUid ||
    identity.mode !== "0700" ||
    !directoryIdentityStampsEqual(identity, expected)
  ) {
    fail(
      "ALPHA_FINAL_HANDLE_WORKSPACE_OPEN_FAILED",
      "Workspace final-object handle identity is outside the exact receipt-bound private profile.",
      { expected, observed: identity },
    );
  }
}

async function hashAlphaFinalRunnerHandle(
  handle: Awaited<ReturnType<typeof open>>,
  expectedIdentity: FileIdentityStamp,
): Promise<string> {
  const before = await handle.stat({ bigint: true });
  const beforeIdentity = fileIdentityStamp(before);
  if (!before.isFile() || !fileIdentityStampsEqual(beforeIdentity, expectedIdentity)) {
    fail("ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH", "Held runner identity changed before positional readback.");
  }
  const size = before.size;
  if (size < 0n || size > BigInt(Number.MAX_SAFE_INTEGER)) {
    fail("ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH", "Held runner size is outside the exact positional-read profile.");
  }
  const expectedBytes = Number(size);
  const hash = createHash("sha256");
  let position = 0;
  while (position < expectedBytes) {
    const length = Math.min(65_536, expectedBytes - position);
    const buffer = Buffer.allocUnsafe(length);
    const { bytesRead } = await handle.read(buffer, 0, length, position);
    if (bytesRead <= 0) {
      fail("ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH", "Held runner ended before its observed size.");
    }
    hash.update(buffer.subarray(0, bytesRead));
    position += bytesRead;
  }
  const extra = Buffer.alloc(1);
  const { bytesRead: extraBytes } = await handle.read(extra, 0, 1, expectedBytes);
  const after = await handle.stat({ bigint: true });
  const afterIdentity = fileIdentityStamp(after);
  if (
    extraBytes !== 0 ||
    position !== expectedBytes ||
    !fileIdentityStampsEqual(beforeIdentity, afterIdentity)
  ) {
    fail("ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH", "Held runner identity or length changed during positional readback.");
  }
  return hash.digest("hex");
}

async function openAlphaFinalWorkspaceHandle(
  workspacePath: string,
  expectedIdentity: DirectoryIdentityStamp,
  hooks: AlphaFinalHandleHooks,
  transferOwnership: (handle: AlphaFinalHandleFile) => void,
): Promise<{
  handle: AlphaFinalHandleFile;
  pathIdentity: DirectoryIdentityStamp;
  handleIdentity: DirectoryIdentityStamp;
}> {
  requireAlphaFinalHandlePlatform();
  try {
    const pathBefore = await lstat(workspacePath, { bigint: true });
    if (!pathBefore.isDirectory() || pathBefore.isSymbolicLink()) {
      fail("ALPHA_FINAL_HANDLE_WORKSPACE_OPEN_FAILED", "Workspace final component must be a real directory.");
    }
    const pathBeforeIdentity = directoryIdentityStampFromStat(pathBefore);
    assertAlphaFinalWorkspaceDirectory(pathBefore, pathBeforeIdentity, expectedIdentity);
    await hooks.afterWorkspacePathStat?.({ workspacePath });
    const handle = await open(
      workspacePath,
      fsConstants.O_RDONLY | fsConstants.O_DIRECTORY | fsConstants.O_NOFOLLOW,
    );
    transferOwnership(handle);
    const handleInformation = await handle.stat({ bigint: true });
    const pathAfter = await lstat(workspacePath, { bigint: true });
    if (!pathAfter.isDirectory() || pathAfter.isSymbolicLink()) {
      fail("ALPHA_FINAL_HANDLE_FINAL_COMPONENT_REBOUND", "Workspace final component changed during no-follow open.");
    }
    const handleIdentity = directoryIdentityStampFromStat(handleInformation);
    const pathAfterIdentity = directoryIdentityStampFromStat(pathAfter);
    assertAlphaFinalWorkspaceDirectory(handleInformation, handleIdentity, expectedIdentity);
    if (
      !directoryIdentityStampsEqual(pathBeforeIdentity, handleIdentity) ||
      !directoryIdentityStampsEqual(handleIdentity, pathAfterIdentity)
    ) {
      fail("ALPHA_FINAL_HANDLE_FINAL_COMPONENT_REBOUND", "Workspace pathname and held final object disagree.");
    }
    return { handle, pathIdentity: pathAfterIdentity, handleIdentity };
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail(
      "ALPHA_FINAL_HANDLE_WORKSPACE_OPEN_FAILED",
      "Workspace final component could not be opened through a no-follow directory handle.",
      { sourceCode: (error as NodeJS.ErrnoException).code ?? null },
    );
  }
}

async function openAlphaFinalRunnerHandle(
  runnerPath: string,
  expectedDigest: string,
  expectedIdentity: FileIdentityStamp,
  hooks: AlphaFinalHandleHooks,
  transferOwnership: (handle: AlphaFinalHandleFile) => void,
): Promise<{
  handle: AlphaFinalHandleFile;
  pathIdentity: FileIdentityStamp;
  handleIdentity: FileIdentityStamp;
}> {
  requireAlphaFinalHandlePlatform();
  try {
    const pathBefore = await lstat(runnerPath, { bigint: true });
    if (!pathBefore.isFile() || pathBefore.isSymbolicLink()) {
      fail("ALPHA_FINAL_HANDLE_RUNNER_OPEN_FAILED", "Runner final component must be a regular non-symlink file.");
    }
    const pathBeforeIdentity = fileIdentityStamp(pathBefore);
    assertAlphaExecutableSingleLink(pathBeforeIdentity);
    await hooks.afterRunnerPathStat?.({ runnerPath });
    const handle = await open(runnerPath, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
    transferOwnership(handle);
    const handleInformation = await handle.stat({ bigint: true });
    const pathAfter = await lstat(runnerPath, { bigint: true });
    if (!handleInformation.isFile() || !pathAfter.isFile() || pathAfter.isSymbolicLink()) {
      fail("ALPHA_FINAL_HANDLE_FINAL_COMPONENT_REBOUND", "Runner final component changed during no-follow open.");
    }
    const handleIdentity = fileIdentityStamp(handleInformation);
    const pathAfterIdentity = fileIdentityStamp(pathAfter);
    assertAlphaExecutableSingleLink(handleIdentity);
    if (
      !fileIdentityStampsEqual(pathBeforeIdentity, handleIdentity) ||
      !fileIdentityStampsEqual(handleIdentity, pathAfterIdentity) ||
      !fileIdentityStampsEqual(handleIdentity, expectedIdentity)
    ) {
      fail("ALPHA_FINAL_HANDLE_FINAL_COMPONENT_REBOUND", "Runner pathname, capsule identity, and held final object disagree.");
    }
    const observedDigest = await hashAlphaFinalRunnerHandle(handle, handleIdentity);
    if (observedDigest !== expectedDigest) {
      fail("ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH", "Held runner bytes differ from the exact capsule digest.");
    }
    return { handle, pathIdentity: pathAfterIdentity, handleIdentity };
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail(
      "ALPHA_FINAL_HANDLE_RUNNER_OPEN_FAILED",
      "Runner final component could not be opened through a stable no-follow handle.",
      { sourceCode: (error as NodeJS.ErrnoException).code ?? null },
    );
  }
}

function computeAlphaFinalHandleObservationDigest(
  body: Omit<AlphaFinalHandleObservationV1, "observationDigest">,
): string {
  return sha256Bytes(`${ALPHA_FINAL_HANDLE_OBSERVATION_PROFILE}\0${canonicalJson(body)}`);
}

function validateAlphaFinalHandleObservation(value: unknown): AlphaFinalHandleObservationV1 {
  requireExactObjectKeys(value, ALPHA_FINAL_HANDLE_OBSERVATION_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle observation");
  const record = value as Partial<AlphaFinalHandleObservationV1>;
  requireExactObjectKeys(record.capsule, ALPHA_FINAL_HANDLE_CAPSULE_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle capsule binding");
  requireExactObjectKeys(record.workspace, ALPHA_FINAL_HANDLE_WORKSPACE_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle workspace binding");
  requireExactObjectKeys(record.runner, ALPHA_FINAL_HANDLE_RUNNER_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle runner binding");
  requireExactObjectKeys(record.lease, ALPHA_FINAL_HANDLE_LEASE_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle lease limits");
  requireExactObjectKeys(record.guarantees, ALPHA_FINAL_HANDLE_GUARANTEE_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle guarantees");
  requireExactObjectKeys(record.requirements, ALPHA_FINAL_HANDLE_REQUIREMENT_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle native requirements");
  const capsule = record.capsule as AlphaFinalHandleObservationV1["capsule"];
  const workspace = record.workspace as AlphaFinalHandleObservationV1["workspace"];
  const runner = record.runner as AlphaFinalHandleObservationV1["runner"];
  const lease = record.lease as AlphaFinalHandleObservationV1["lease"];
  const guarantees = record.guarantees as AlphaFinalHandleObservationV1["guarantees"];
  const requirements = record.requirements as AlphaFinalHandleObservationV1["requirements"];
  requireExactObjectKeys(workspace.expectedRootIdentity, DIRECTORY_IDENTITY_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle expected workspace identity");
  requireExactObjectKeys(workspace.pathIdentity, DIRECTORY_IDENTITY_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle workspace path identity");
  requireExactObjectKeys(workspace.handleIdentity, DIRECTORY_IDENTITY_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle workspace handle identity");
  requireExactObjectKeys(runner.pathIdentity, FILE_IDENTITY_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle runner path identity");
  requireExactObjectKeys(runner.handleIdentity, FILE_IDENTITY_KEYS, "ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle runner handle identity");
  const directoryIdentities = [
    workspace.expectedRootIdentity,
    workspace.pathIdentity,
    workspace.handleIdentity,
  ];
  const fileIdentities = [runner.pathIdentity, runner.handleIdentity];
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "ALPHA_FINAL_HANDLE_OBSERVATION" ||
    record.observationProfile !== ALPHA_FINAL_HANDLE_OBSERVATION_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "OBSERVED_DURING_CALL_HANDLES_NOT_DESCRIPTOR_RELATIVE_NOT_AUTHORIZED" ||
    record.executionAuthority !== "NONE" ||
    record.maySpawnProcess !== false ||
    record.executionUseLimit !== 0 ||
    !isSha256Digest(capsule.capsuleDigest) ||
    !isSha256Digest(capsule.capsuleRecordDigest) ||
    !isSha256Digest(workspace.receiptDigest) ||
    !isSha256Digest(workspace.workspaceId) ||
    typeof workspace.canonicalPath !== "string" ||
    !isAbsolute(workspace.canonicalPath) ||
    resolve(workspace.canonicalPath) !== workspace.canonicalPath ||
    directoryIdentities.some((identity) =>
      !isUnsignedDecimalString(identity.deviceId) ||
      !isUnsignedDecimalString(identity.inodeId) ||
      !isUnsignedDecimalString(identity.ownerUid) ||
      !isUnsignedDecimalString(identity.ownerGid) ||
      identity.mode !== "0700"
    ) ||
    !directoryIdentityStampsEqual(workspace.expectedRootIdentity, workspace.pathIdentity) ||
    !directoryIdentityStampsEqual(workspace.pathIdentity, workspace.handleIdentity) ||
    typeof runner.canonicalPath !== "string" ||
    !isAbsolute(runner.canonicalPath) ||
    resolve(runner.canonicalPath) !== runner.canonicalPath ||
    !isSha256Digest(runner.binaryDigest) ||
    fileIdentities.some((identity) =>
      !isUnsignedDecimalString(identity.deviceId) ||
      !isUnsignedDecimalString(identity.inodeId) ||
      !isUnsignedDecimalString(identity.ctimeNs) ||
      !isUnsignedDecimalString(identity.mtimeNs) ||
      identity.linkCount !== "1" ||
      !isUnsignedDecimalString(identity.size) ||
      !isUnsignedDecimalString(identity.mode)
    ) ||
    !fileIdentityStampsEqual(runner.pathIdentity, runner.handleIdentity) ||
    lease.durability !== "NONE" ||
    lease.replayability !== "REACQUIRE_EXACT_CAPSULE_REQUIRED" ||
    lease.fdNumbersRecorded !== false ||
    lease.handlesExposed !== false ||
    guarantees.finalComponentNoFollow !== true ||
    guarantees.stableRunnerHandleReadback !== true ||
    guarantees.finalObjectHandlesHeldDuringAcquisition !== true ||
    requirements.ancestorComponentWalk !== "NATIVE_REQUIRED_NOT_IMPLEMENTED" ||
    requirements.descendantResolutionFromWorkspaceHandle !== "NATIVE_REQUIRED_NOT_IMPLEMENTED" ||
    requirements.executeVerifiedRunnerHandle !== "NATIVE_REQUIRED_NOT_IMPLEMENTED" ||
    requirements.atomicCurrentnessToSpawn !== "NATIVE_REQUIRED_NOT_IMPLEMENTED" ||
    requirements.nativeContainment !== "NATIVE_REQUIRED_NOT_IMPLEMENTED" ||
    requirements.satisfied !== false ||
    !isSha256Digest(record.observationDigest)
  ) {
    fail("ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle observation is outside the exact zero-authority process-local profile.");
  }
  const body = { ...record } as Partial<AlphaFinalHandleObservationV1>;
  delete body.observationDigest;
  if (
    record.observationDigest !==
    computeAlphaFinalHandleObservationDigest(
      body as Omit<AlphaFinalHandleObservationV1, "observationDigest">,
    )
  ) {
    fail("ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Alpha final-handle observation digest does not bind the exact record body.");
  }
  return record as AlphaFinalHandleObservationV1;
}

function buildAlphaFinalHandleObservation(
  capsule: AlphaRunnerBoundaryCapsuleV1,
  capsuleRecordDigest: string,
  workspacePath: string,
  workspacePathIdentity: DirectoryIdentityStamp,
  workspaceHandleIdentity: DirectoryIdentityStamp,
  runnerPathIdentity: FileIdentityStamp,
  runnerHandleIdentity: FileIdentityStamp,
): AlphaFinalHandleObservationV1 {
  const body: Omit<AlphaFinalHandleObservationV1, "observationDigest"> = {
    schemaVersion: 1,
    recordType: "ALPHA_FINAL_HANDLE_OBSERVATION",
    observationProfile: ALPHA_FINAL_HANDLE_OBSERVATION_PROFILE,
    scope: "LOCAL_STORE_ONLY",
    disposition: "OBSERVED_DURING_CALL_HANDLES_NOT_DESCRIPTOR_RELATIVE_NOT_AUTHORIZED",
    executionAuthority: "NONE",
    maySpawnProcess: false,
    executionUseLimit: 0,
    capsule: {
      capsuleDigest: capsule.capsuleDigest,
      capsuleRecordDigest,
    },
    workspace: {
      receiptDigest: capsule.workspace.receiptDigest,
      workspaceId: capsule.workspace.workspaceId,
      canonicalPath: workspacePath,
      expectedRootIdentity: { ...capsule.workspace.rootIdentity },
      pathIdentity: { ...workspacePathIdentity },
      handleIdentity: { ...workspaceHandleIdentity },
    },
    runner: {
      canonicalPath: capsule.runner.canonicalPath,
      binaryDigest: capsule.runner.binaryDigest,
      pathIdentity: { ...runnerPathIdentity },
      handleIdentity: { ...runnerHandleIdentity },
    },
    lease: {
      durability: "NONE",
      replayability: "REACQUIRE_EXACT_CAPSULE_REQUIRED",
      fdNumbersRecorded: false,
      handlesExposed: false,
    },
    guarantees: {
      finalComponentNoFollow: true,
      stableRunnerHandleReadback: true,
      finalObjectHandlesHeldDuringAcquisition: true,
    },
    requirements: {
      ancestorComponentWalk: "NATIVE_REQUIRED_NOT_IMPLEMENTED",
      descendantResolutionFromWorkspaceHandle: "NATIVE_REQUIRED_NOT_IMPLEMENTED",
      executeVerifiedRunnerHandle: "NATIVE_REQUIRED_NOT_IMPLEMENTED",
      atomicCurrentnessToSpawn: "NATIVE_REQUIRED_NOT_IMPLEMENTED",
      nativeContainment: "NATIVE_REQUIRED_NOT_IMPLEMENTED",
      satisfied: false,
    },
  };
  return validateAlphaFinalHandleObservation({
    ...body,
    observationDigest: computeAlphaFinalHandleObservationDigest(body),
  });
}

async function readAlphaFinalHandleObservationUnlocked(
  store: string,
  observationDigest: string,
): Promise<AlphaFinalHandleObservationV1> {
  if (!isSha256Digest(observationDigest)) {
    fail("ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Final-handle observation lookup requires an exact SHA-256 digest.");
  }
  const verified = await readVerifiedEnvelope<unknown>(
    join(store, "alpha-final-handle-observations", `${observationDigest}.json`),
  );
  const observation = validateAlphaFinalHandleObservation(verified.record);
  if (observation.observationDigest !== observationDigest) {
    fail("ALPHA_FINAL_HANDLE_OBSERVATION_INVALID", "Final-handle observation pathname and content digest disagree.");
  }
  return observation;
}

function cloneAlphaFinalHandleObservation(
  observation: AlphaFinalHandleObservationV1,
): AlphaFinalHandleObservationV1 {
  return validateAlphaFinalHandleObservation(
    JSON.parse(canonicalJson(observation)) as unknown,
  );
}

function alphaFinalHandleErrorCode(error: unknown): string {
  if (error instanceof VeritasError) return error.code;
  const code = (error as NodeJS.ErrnoException | null)?.code;
  if (typeof code === "string" && code.length !== 0) return code;
  if (error instanceof Error && error.name.length !== 0) return error.name;
  return "UNKNOWN_ERROR";
}

function poisonAlphaFinalHandleProcess(
  code: "ALPHA_FINAL_HANDLE_RELEASE_UNCONFIRMED" | "ALPHA_FINAL_HANDLE_ACQUISITION_CLEANUP_UNCONFIRMED",
  handles: AlphaFinalHandleFile[],
): void {
  for (const handle of handles) alphaFinalHandleQuarantine.add(handle);
  alphaFinalHandleProcessPoison = {
    code: alphaFinalHandleProcessPoison?.code ?? code,
    quarantinedHandleCount: alphaFinalHandleQuarantine.size,
  };
}

async function closeAlphaFinalHandleOnce(
  handle: AlphaFinalHandleFile,
  beforeClose: (() => Promise<void> | void) | undefined,
): Promise<void> {
  await beforeClose?.();
  await handle.close();
}

type AlphaFinalHandleCloseResult = {
  status: "NOT_OPENED" | "CLOSE_CONFIRMED" | "CLOSE_UNCONFIRMED";
  errorCode: string | null;
};

async function closeAlphaFinalHandleForCleanup(
  handle: AlphaFinalHandleFile | null,
  beforeClose: (() => Promise<void> | void) | undefined,
): Promise<AlphaFinalHandleCloseResult> {
  if (handle === null) return { status: "NOT_OPENED", errorCode: null };
  try {
    await closeAlphaFinalHandleOnce(handle, beforeClose);
    return { status: "CLOSE_CONFIRMED", errorCode: null };
  } catch (error) {
    return {
      status: "CLOSE_UNCONFIRMED",
      errorCode: alphaFinalHandleErrorCode(error),
    };
  }
}

function alphaFinalHandleReleaseFailureDetails(
  workspace: AlphaFinalHandleCloseResult,
  runner: AlphaFinalHandleCloseResult,
): JsonValue {
  return {
    workspace: {
      status: workspace.status,
      errorCode: workspace.errorCode,
    },
    runner: {
      status: runner.status,
      errorCode: runner.errorCode,
    },
  };
}

async function serializeAlphaFinalHandleLease<T>(
  lease: AlphaFinalHandleLease,
  operation: (state: AlphaFinalHandleLeaseState) => Promise<T>,
): Promise<T> {
  if (lease === null || typeof lease !== "object") {
    fail("ALPHA_FINAL_HANDLE_CAPABILITY_INVALID", "Final-handle inspection requires the exact opaque in-process lease.");
  }
  const state = alphaFinalHandleLeaseStates.get(lease as object);
  if (state === undefined) {
    fail("ALPHA_FINAL_HANDLE_CAPABILITY_INVALID", "Final-handle lease was not minted by this process.");
  }
  const previous = state.operationTail;
  let releaseQueue!: () => void;
  state.operationTail = new Promise<void>((resolvePromise) => {
    releaseQueue = resolvePromise;
  });
  await previous;
  try {
    return await operation(state);
  } finally {
    releaseQueue();
  }
}

async function acquireAlphaFinalHandleLease(
  storePath: string,
  capsuleDigest: string,
  hooks: AlphaFinalHandleHooks = {},
): Promise<{ lease: AlphaFinalHandleLease; observation: AlphaFinalHandleObservationV1 }> {
  if (alphaFinalHandleProcessPoison !== null) {
    fail(
      "ALPHA_FINAL_HANDLE_PROCESS_POISONED",
      "A prior final-handle close outcome is unconfirmed; this process cannot acquire another final-handle lease.",
      alphaFinalHandleProcessPoison,
    );
  }
  if (
    (hooks.afterWorkspacePathStat !== undefined ||
      hooks.afterRunnerPathStat !== undefined ||
      hooks.afterObservationBeforeStoreLockRelease !== undefined ||
      hooks.beforeWorkspaceHandleClose !== undefined ||
      hooks.beforeRunnerHandleClose !== undefined) &&
    !boundedTestLaneActive()
  ) {
    fail("TEST_ONLY_ALPHA_FINAL_HANDLE_HOOK_REJECTED", "Final-handle substitution hooks require the bounded test lane.");
  }
  const store = await ensureStore(storePath);
  let pendingWorkspaceHandle: Awaited<ReturnType<typeof open>> | null = null;
  let pendingRunnerHandle: Awaited<ReturnType<typeof open>> | null = null;
  try {
    const observation = await withStoreLock(store, async () => {
      await reconcileUnlocked(store);
      const ready = await readCoordinatorSnapshotUnlocked(store);
      const initial = await inspectAlphaRunnerBoundaryCapsuleForFinalHandleUnlocked(
        store,
        capsuleDigest,
        ready,
      );
      if (initial.status !== "CURRENT_INERT") {
        fail("ALPHA_FINAL_HANDLE_CAPSULE_NOT_CURRENT", "Final-handle acquisition requires one exact current inert runner capsule.", {
          status: initial.status,
        });
      }
      const { capsule, capsuleRecordDigest } = await readAlphaRunnerBoundaryCapsuleUnlocked(
        store,
        capsuleDigest,
      );
      if (canonicalJson(capsule) !== canonicalJson(initial.capsule)) {
        fail("ALPHA_FINAL_HANDLE_OBSERVATION_CONFLICT", "Runner capsule changed between exact readbacks.");
      }
      const workspacePath = join(store, capsule.workspace.relativePath);
      const workspaceOpen = await openAlphaFinalWorkspaceHandle(
        workspacePath,
        capsule.workspace.rootIdentity,
        hooks,
        (handle) => {
          pendingWorkspaceHandle = handle;
        },
      );
      const runnerOpen = await openAlphaFinalRunnerHandle(
        capsule.runner.canonicalPath,
        capsule.runner.binaryDigest,
        capsule.runner.fileIdentity,
        hooks,
        (handle) => {
          pendingRunnerHandle = handle;
        },
      );

      const readyAfterOpen = await readCoordinatorSnapshotUnlocked(store);
      const afterOpen = await inspectAlphaRunnerBoundaryCapsuleForFinalHandleUnlocked(
        store,
        capsuleDigest,
        readyAfterOpen,
      );
      if (
        afterOpen.status !== "CURRENT_INERT" ||
        canonicalJson(afterOpen.capsule) !== canonicalJson(capsule)
      ) {
        fail("ALPHA_FINAL_HANDLE_CAPSULE_NOT_CURRENT", "Runner capsule ceased to be current while final handles were acquired.", {
          status: afterOpen.status,
        });
      }
      const observation = buildAlphaFinalHandleObservation(
        capsule,
        capsuleRecordDigest,
        workspacePath,
        workspaceOpen.pathIdentity,
        workspaceOpen.handleIdentity,
        runnerOpen.pathIdentity,
        runnerOpen.handleIdentity,
      );
      const observationPath = join(
        store,
        "alpha-final-handle-observations",
        `${observation.observationDigest}.json`,
      );
      await writeImmutableRecord(observationPath, observation);
      const readback = await readAlphaFinalHandleObservationUnlocked(
        store,
        observation.observationDigest,
      );
      if (canonicalJson(readback) !== canonicalJson(observation)) {
        fail("ALPHA_FINAL_HANDLE_OBSERVATION_CONFLICT", "Final-handle observation readback differs from the exact record.");
      }
      return observation;
    }, hooks.afterObservationBeforeStoreLockRelease);
    if (pendingWorkspaceHandle === null || pendingRunnerHandle === null) {
      fail("ALPHA_FINAL_HANDLE_OBSERVATION_CONFLICT", "Final-handle acquisition completed without both process-local handles.");
    }
    const returnedObservation = cloneAlphaFinalHandleObservation(observation);
    const lease = Object.freeze(Object.create(null)) as AlphaFinalHandleLease;
    if (alphaFinalHandleProcessPoison !== null) {
      fail(
        "ALPHA_FINAL_HANDLE_PROCESS_POISONED",
        "A concurrent final-handle close outcome became unconfirmed before this lease could be published.",
        alphaFinalHandleProcessPoison,
      );
    }
    alphaFinalHandleLeaseStates.set(lease as object, {
      store,
      capsuleDigest,
      observation,
      workspaceHandle: pendingWorkspaceHandle,
      runnerHandle: pendingRunnerHandle,
      workspaceCloseStatus: "PENDING",
      runnerCloseStatus: "PENDING",
      lifecycle: "OPEN",
      releaseFailureDetails: null,
      closeHooks: {
        beforeWorkspaceHandleClose: hooks.beforeWorkspaceHandleClose,
        beforeRunnerHandleClose: hooks.beforeRunnerHandleClose,
      },
      operationTail: Promise.resolve(),
    });
    pendingWorkspaceHandle = null;
    pendingRunnerHandle = null;
    return { lease, observation: returnedObservation };
  } catch (error) {
    const workspaceHandle = pendingWorkspaceHandle;
    const runnerHandle = pendingRunnerHandle;
    const [workspaceClose, runnerClose] = await Promise.all([
      closeAlphaFinalHandleForCleanup(
        workspaceHandle,
        hooks.beforeWorkspaceHandleClose,
      ),
      closeAlphaFinalHandleForCleanup(
        runnerHandle,
        hooks.beforeRunnerHandleClose,
      ),
    ]);
    const unconfirmedHandles: AlphaFinalHandleFile[] = [];
    if (workspaceClose.status === "CLOSE_UNCONFIRMED" && workspaceHandle !== null) {
      unconfirmedHandles.push(workspaceHandle);
    }
    if (runnerClose.status === "CLOSE_UNCONFIRMED" && runnerHandle !== null) {
      unconfirmedHandles.push(runnerHandle);
    }
    if (unconfirmedHandles.length !== 0) {
      poisonAlphaFinalHandleProcess(
        "ALPHA_FINAL_HANDLE_ACQUISITION_CLEANUP_UNCONFIRMED",
        unconfirmedHandles,
      );
      fail(
        "ALPHA_FINAL_HANDLE_ACQUISITION_CLEANUP_UNCONFIRMED",
        "Final-handle acquisition failed and one or more cleanup close outcomes are unconfirmed.",
        {
          primaryErrorCode: alphaFinalHandleErrorCode(error),
          close: alphaFinalHandleReleaseFailureDetails(
            workspaceClose,
            runnerClose,
          ),
        },
      );
    }
    throw error;
  }
}

async function inspectAlphaFinalHandleLease(
  lease: AlphaFinalHandleLease,
): Promise<{ observation: AlphaFinalHandleObservationV1; status: AlphaFinalHandleInspectionStatusV1 }> {
  return serializeAlphaFinalHandleLease(lease, async (state) => {
    if (state.lifecycle === "CLOSED_CONFIRMED") {
      return {
        observation: cloneAlphaFinalHandleObservation(state.observation),
        status: "CLOSED",
      };
    }
    if (state.lifecycle === "RELEASE_UNCONFIRMED") {
      return {
        observation: cloneAlphaFinalHandleObservation(state.observation),
        status: "RELEASE_UNCONFIRMED",
      };
    }
    if (state.lifecycle !== "OPEN") {
      fail("ALPHA_FINAL_HANDLE_CAPABILITY_INVALID", "Final-handle lease is closing and cannot be inspected.");
    }
    const store = await ensureStore(state.store);
    return withStoreLock(store, async () => {
      await reconcileUnlocked(store);
      const storedObservation = await readAlphaFinalHandleObservationUnlocked(
        store,
        state.observation.observationDigest,
      );
      if (canonicalJson(storedObservation) !== canonicalJson(state.observation)) {
        fail("ALPHA_FINAL_HANDLE_OBSERVATION_CONFLICT", "Live lease and immutable observation disagree.");
      }
      const ready = await readCoordinatorSnapshotUnlocked(store);
      const capsuleInspection = await inspectAlphaRunnerBoundaryCapsuleForFinalHandleUnlocked(
        store,
        state.capsuleDigest,
        ready,
      );

      let workspaceHandleInformation: Awaited<ReturnType<Awaited<ReturnType<typeof open>>["stat"]>>;
      let runnerHandleInformation: Awaited<ReturnType<Awaited<ReturnType<typeof open>>["stat"]>>;
      try {
        workspaceHandleInformation = await state.workspaceHandle.stat({ bigint: true });
        runnerHandleInformation = await state.runnerHandle.stat({ bigint: true });
      } catch {
        return {
          observation: cloneAlphaFinalHandleObservation(state.observation),
          status: "HANDLE_OBSERVATION_FAILED",
        };
      }
      const workspaceHandleIdentity = directoryIdentityStampFromStat(workspaceHandleInformation);
      const runnerHandleIdentity = fileIdentityStamp(runnerHandleInformation);
      if (
        !workspaceHandleInformation.isDirectory() ||
        !directoryIdentityStampsEqual(
          workspaceHandleIdentity,
          state.observation.workspace.handleIdentity,
        )
      ) {
        return {
          observation: cloneAlphaFinalHandleObservation(state.observation),
          status: "WORKSPACE_DRIFT",
        };
      }
      if (
        !runnerHandleInformation.isFile() ||
        !fileIdentityStampsEqual(runnerHandleIdentity, state.observation.runner.handleIdentity)
      ) {
        return {
          observation: cloneAlphaFinalHandleObservation(state.observation),
          status: "RUNNER_DRIFT",
        };
      }

      try {
        const workspacePathInformation = await lstat(
          state.observation.workspace.canonicalPath,
          { bigint: true },
        );
        const runnerPathInformation = await lstat(
          state.observation.runner.canonicalPath,
          { bigint: true },
        );
        if (
          !workspacePathInformation.isDirectory() ||
          workspacePathInformation.isSymbolicLink() ||
          !runnerPathInformation.isFile() ||
          runnerPathInformation.isSymbolicLink() ||
          !directoryIdentityStampsEqual(
            directoryIdentityStampFromStat(workspacePathInformation),
            workspaceHandleIdentity,
          ) ||
          !fileIdentityStampsEqual(fileIdentityStamp(runnerPathInformation), runnerHandleIdentity)
        ) {
          return {
            observation: cloneAlphaFinalHandleObservation(state.observation),
            status: "PATH_REBOUND",
          };
        }
      } catch (error) {
        if (["ENOENT", "ENOTDIR", "ELOOP"].includes(
          (error as NodeJS.ErrnoException).code ?? "",
        )) {
          return {
            observation: cloneAlphaFinalHandleObservation(state.observation),
            status: "PATH_REBOUND",
          };
        }
        throw error;
      }

      try {
        const heldDigest = await hashAlphaFinalRunnerHandle(
          state.runnerHandle,
          state.observation.runner.handleIdentity,
        );
        if (heldDigest !== state.observation.runner.binaryDigest) {
          return {
            observation: cloneAlphaFinalHandleObservation(state.observation),
            status: "RUNNER_DRIFT",
          };
        }
      } catch (error) {
        if (
          error instanceof VeritasError &&
          error.code === "ALPHA_FINAL_HANDLE_RUNNER_DIGEST_MISMATCH"
        ) {
          return {
            observation: cloneAlphaFinalHandleObservation(state.observation),
            status: "RUNNER_DRIFT",
          };
        }
        throw error;
      }

      return {
        observation: cloneAlphaFinalHandleObservation(state.observation),
        status: capsuleInspection.status === "CURRENT_INERT"
          ? "CURRENT_INERT_PROCESS_LOCAL_FINAL_HANDLES"
          : capsuleInspection.status,
      };
    });
  });
}

async function releaseAlphaFinalHandleLease(
  lease: AlphaFinalHandleLease,
): Promise<{ status: "CLOSED" }> {
  return serializeAlphaFinalHandleLease(lease, async (state) => {
    if (state.lifecycle === "CLOSED_CONFIRMED") return { status: "CLOSED" };
    if (state.lifecycle === "RELEASE_UNCONFIRMED") {
      fail(
        "ALPHA_FINAL_HANDLE_RELEASE_UNCONFIRMED",
        "A prior final-handle release had an unconfirmed close outcome and cannot be retried safely.",
        state.releaseFailureDetails,
      );
    }
    if (state.lifecycle !== "OPEN") {
      fail("ALPHA_FINAL_HANDLE_CAPABILITY_INVALID", "Final-handle lease is already being released.");
    }
    state.lifecycle = "RELEASING";
    const [workspaceClose, runnerClose] = await Promise.all([
      closeAlphaFinalHandleForCleanup(
        state.workspaceHandle,
        state.closeHooks.beforeWorkspaceHandleClose,
      ),
      closeAlphaFinalHandleForCleanup(
        state.runnerHandle,
        state.closeHooks.beforeRunnerHandleClose,
      ),
    ]);
    state.workspaceCloseStatus = workspaceClose.status === "CLOSE_CONFIRMED"
      ? "CLOSE_CONFIRMED"
      : "CLOSE_UNCONFIRMED";
    state.runnerCloseStatus = runnerClose.status === "CLOSE_CONFIRMED"
      ? "CLOSE_CONFIRMED"
      : "CLOSE_UNCONFIRMED";
    if (
      state.workspaceCloseStatus === "CLOSE_CONFIRMED" &&
      state.runnerCloseStatus === "CLOSE_CONFIRMED"
    ) {
      state.lifecycle = "CLOSED_CONFIRMED";
      return { status: "CLOSED" };
    }
    const unconfirmedHandles: AlphaFinalHandleFile[] = [];
    if (state.workspaceCloseStatus === "CLOSE_UNCONFIRMED") {
      unconfirmedHandles.push(state.workspaceHandle);
    }
    if (state.runnerCloseStatus === "CLOSE_UNCONFIRMED") {
      unconfirmedHandles.push(state.runnerHandle);
    }
    state.releaseFailureDetails = alphaFinalHandleReleaseFailureDetails(
      workspaceClose,
      runnerClose,
    );
    state.lifecycle = "RELEASE_UNCONFIRMED";
    poisonAlphaFinalHandleProcess(
      "ALPHA_FINAL_HANDLE_RELEASE_UNCONFIRMED",
      unconfirmedHandles,
    );
    fail(
      "ALPHA_FINAL_HANDLE_RELEASE_UNCONFIRMED",
      "One or more process-local final-handle close outcomes are unconfirmed; the operation will not retry ambiguous descriptors.",
      state.releaseFailureDetails,
    );
  });
}

const C5_MESSAGE_TYPES = new Set<C5MessageTypeV1>([
  "HELLO",
  "CHALLENGE",
  "REQUEST_BOUND",
  "CURRENTNESS_BEFORE",
  "ROOTS_PINNED",
  "WORKSPACE_VERIFIED",
  "RUNNER_PINNED",
  "CURRENTNESS_AFTER",
  "ADMISSION_EVIDENCE",
  "CLOSE_REPORT",
]);
const C5_FRAME_SENDERS = new Set<C5NativeTranscriptFrameV1["sender"]>([
  "SUPERVISOR",
  "HELPER",
  "CURRENTNESS_AUTHORITY",
  "RECEIPT_AUTHORITY",
]);
const C5_TERMINATION_TRIGGERS = new Set<C5TerminationTriggerV1>([
  "NORMAL_CLOSE",
  "CLOSE_AMBIGUOUS",
  "HELPER_TIMEOUT",
  "IPC_DISCONNECT",
  "PROTOCOL_VIOLATION",
  "CURRENTNESS_REVOKED",
  "SUPERVISOR_CANCELLED",
  "HELPER_CRASH",
  "PARENT_RECOVERY",
]);
const C5_CLOSE_OUTCOMES = new Set<C5CloseOutcomeV1>([
  "ALL_CLOSES_CONFIRMED",
  "CLOSE_AMBIGUOUS_HELPER_TERMINATED",
  "CLOSE_NOT_REACHED_HELPER_TERMINATED",
]);
const C5_WAIT_OUTCOMES = new Set<C5WaitOutcomeV1>([
  "EXITED_ZERO",
  "EXITED_NONZERO",
  "SIGNALED",
  "FORCED_TERMINATION_CONFIRMED",
]);
const C5_ALLOWED_FRAME_SENDERS: Readonly<
  Record<C5MessageTypeV1, readonly C5NativeTranscriptFrameV1["sender"][]>
> = Object.freeze({
  HELLO: ["SUPERVISOR", "HELPER"],
  CHALLENGE: ["SUPERVISOR", "HELPER"],
  REQUEST_BOUND: ["SUPERVISOR", "HELPER"],
  CURRENTNESS_BEFORE: ["CURRENTNESS_AUTHORITY"],
  ROOTS_PINNED: ["HELPER"],
  WORKSPACE_VERIFIED: ["HELPER"],
  RUNNER_PINNED: ["HELPER"],
  CURRENTNESS_AFTER: ["CURRENTNESS_AUTHORITY"],
  ADMISSION_EVIDENCE: ["HELPER", "RECEIPT_AUTHORITY"],
  CLOSE_REPORT: ["HELPER"],
});

function requireC5ExactObjectKeys(
  value: unknown,
  expectedKeys: readonly string[],
  label: string,
): Record<string, unknown> {
  const record = requireExactObjectKeys(
    value,
    expectedKeys,
    "C5_CONTRACT_INVALID",
    label,
  );
  const prototype = Object.getPrototypeOf(record);
  if (prototype !== Object.prototype && prototype !== null) {
    fail(
      "C5_CONTRACT_INVALID",
      `${label} must be a plain data object without an inherited prototype.`,
    );
  }
  return record;
}

function isCanonicalLowerHexBytes(value: unknown, byteLength: number): value is string {
  return (
    typeof value === "string" &&
    value.length === byteLength * 2 &&
    /^[0-9a-f]+$/.test(value)
  );
}

function isCanonicalBase64UrlBytes(value: unknown, byteLength: number): value is string {
  if (typeof value !== "string" || !/^[A-Za-z0-9_-]+$/.test(value)) return false;
  try {
    const decoded = Buffer.from(value, "base64url");
    return decoded.length === byteLength && decoded.toString("base64url") === value;
  } catch {
    return false;
  }
}

function hasLoneUtf16Surrogate(value: string): boolean {
  for (let index = 0; index < value.length; index += 1) {
    const unit = value.charCodeAt(index);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = value.charCodeAt(index + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return true;
      index += 1;
    } else if (unit >= 0xdc00 && unit <= 0xdfff) {
      return true;
    }
  }
  return false;
}

function validateC5ComponentVector(value: unknown, label: string): string[] {
  if (
    !Array.isArray(value) ||
    value.length === 0 ||
    value.length > C5_COMPONENT_LIMITS.maxComponents
  ) {
    fail(
      "C5_COMPONENT_VECTOR_INVALID",
      `${label} must contain between one and ${C5_COMPONENT_LIMITS.maxComponents} components.`,
    );
  }
  const components: string[] = [];
  for (const component of value) {
    if (
      typeof component !== "string" ||
      component.length === 0 ||
      component.length > C5_COMPONENT_LIMITS.maxComponentBytes ||
      Buffer.byteLength(component, "utf8") > C5_COMPONENT_LIMITS.maxComponentBytes ||
      component === "." ||
      component === ".." ||
      component.includes("/") ||
      component.includes("\\") ||
      component.includes(":") ||
      component.includes("\0") ||
      hasLoneUtf16Surrogate(component) ||
      component.normalize("NFC") !== component
    ) {
      fail(
        "C5_COMPONENT_VECTOR_INVALID",
        `${label} contains an unsafe, noncanonical, or oversized component.`,
      );
    }
    components.push(component);
  }
  if (
    Buffer.byteLength(components.join("/"), "utf8") >
    C5_COMPONENT_LIMITS.maxCanonicalPathBytes
  ) {
    fail(
      "C5_COMPONENT_VECTOR_INVALID",
      `${label} exceeds the frozen canonical path byte limit.`,
    );
  }
  return components;
}

function omitC5Fields(
  value: Record<string, unknown>,
  fields: readonly string[],
): Record<string, unknown> {
  const copy = { ...value };
  for (const field of fields) delete copy[field];
  return copy;
}

function computeC5DomainDigest(profile: string, value: unknown): string {
  return sha256Bytes(`${profile}\0${canonicalJson(value)}`);
}

function computeC5EnvelopeRecordDigest(value: unknown): string {
  return sha256Bytes(canonicalJson(value));
}

function computeC5ComponentVectorDigest(components: readonly string[]): string {
  return computeC5DomainDigest(C5_COMPONENT_VECTOR_PROFILE, { components });
}

function computeC5NativeHelperBuildDigest(
  value: Omit<C5NativeHelperBuildV1, "buildDigest">,
): string {
  return computeC5DomainDigest(C5_NATIVE_HELPER_BUILD_PROFILE, value);
}

function computeC5NativeAdmissionRequestDigest(
  value: Omit<C5NativeAdmissionRequestV1, "requestDigest">,
): string {
  return computeC5DomainDigest(C5_NATIVE_ADMISSION_REQUEST_PROFILE, value);
}

function computeC5NativeAdmissionAttemptDigest(
  value: Omit<C5NativeAdmissionAttemptV1, "attemptDigest">,
): string {
  return computeC5DomainDigest(C5_NATIVE_ADMISSION_ATTEMPT_PROFILE, value);
}

function computeC5NativeTranscriptFrameDigest(
  value: Omit<C5NativeTranscriptFrameV1, "frameDigest">,
): string {
  return computeC5DomainDigest(C5_NATIVE_TRANSCRIPT_FRAME_PROFILE, value);
}

function computeC5AdmissionStatementDigest(
  value: Omit<
    C5UnverifiedDescriptorAdmissionReceiptV1,
    "statementDigest" | "signature" | "admissionDigest"
  >,
): string {
  return computeC5DomainDigest(C5_ADMISSION_STATEMENT_PROFILE, value);
}

function computeC5AdmissionReceiptDigest(
  value: Omit<C5UnverifiedDescriptorAdmissionReceiptV1, "admissionDigest">,
): string {
  return computeC5DomainDigest(C5_DESCRIPTOR_ADMISSION_RECEIPT_PROFILE, value);
}

function computeC5TerminationStatementDigest(
  value: Omit<
    C5UnverifiedHelperTerminationReceiptV1,
    "statementDigest" | "signature" | "terminationDigest"
  >,
): string {
  return computeC5DomainDigest(C5_TERMINATION_STATEMENT_PROFILE, value);
}

function computeC5TerminationReceiptDigest(
  value: Omit<C5UnverifiedHelperTerminationReceiptV1, "terminationDigest">,
): string {
  return computeC5DomainDigest(C5_HELPER_TERMINATION_RECEIPT_PROFILE, value);
}

function parseCanonicalC5RecordBytes(bytes: Buffer, label: string): unknown {
  if (bytes.length === 0 || bytes.length > C5_MAX_CANONICAL_RECORD_BYTES) {
    fail(
      "C5_RECORD_NONCANONICAL",
      `${label} exceeds the frozen canonical record byte limit.`,
    );
  }
  if (bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) {
    fail("C5_RECORD_NONCANONICAL", `${label} must not contain a UTF-8 byte-order mark.`);
  }
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    fail("C5_RECORD_NONCANONICAL", `${label} must contain strictly valid UTF-8.`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    fail("C5_RECORD_NONCANONICAL", `${label} must be valid canonical JSON bytes.`);
  }
  let canonicalText: string;
  try {
    canonicalText = `${canonicalJson(parsed)}\n`;
  } catch {
    fail(
      "C5_RECORD_NONCANONICAL",
      `${label} contains a value that canonical JSON cannot represent.`,
    );
  }
  if (text !== canonicalText) {
    fail(
      "C5_RECORD_NONCANONICAL",
      `${label} bytes must equal canonical JSON followed by exactly one newline.`,
    );
  }
  return parsed;
}

function validateC5NegativeAuthorityContract(
  record: Record<string, unknown>,
  label: string,
): void {
  if (
    record.executionAuthority !== "NONE" ||
    record.maySpawnGovernedRunner !== false ||
    record.governedRunnerUseLimit !== 0 ||
    record.reusableCapability !== false
  ) {
    fail(
      "C5_AUTHORITY_INVALID",
      `${label} must carry only the frozen zero-authority disposition.`,
    );
  }
}

function validateC5SafeCount(value: unknown, label: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0) {
    fail("C5_CONTRACT_INVALID", `${label} must be a non-negative safe integer.`);
  }
  return value as number;
}

function validateC5LineageContract(value: unknown): C5LineageV1 {
  const record = requireC5ExactObjectKeys(value, C5_LINEAGE_KEYS, "C5 lineage");
  const digestFields = C5_LINEAGE_KEYS.filter(
    (key) => key !== "storeId" && key !== "dependencyEpoch",
  );
  if (
    !isCanonicalUuidV4(record.storeId) ||
    digestFields.some((field) => !isSha256Digest(record[field])) ||
    !Number.isSafeInteger(record.dependencyEpoch) ||
    (record.dependencyEpoch as number) < 0
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 lineage must bind one canonical store, exact SHA-256 records, and a non-negative dependency epoch.",
    );
  }
  return record as unknown as C5LineageV1;
}

function validateC5RelativePathBindingContract(
  value: unknown,
  expectedRole: C5RelativePathBindingV1["rootRole"],
  label: string,
): C5RelativePathBindingV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_RELATIVE_PATH_BINDING_KEYS,
    label,
  );
  const components = validateC5ComponentVector(record.components, `${label} components`);
  if (
    record.rootRole !== expectedRole ||
    !isSha256Digest(record.protectedRootId) ||
    !isSha256Digest(record.componentsDigest) ||
    record.componentsDigest !== computeC5ComponentVectorDigest(components)
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      `${label} must bind the protected root role and exact component-vector digest.`,
    );
  }
  return record as unknown as C5RelativePathBindingV1;
}

function validateC5ExpectedEvidenceContract(value: unknown): C5ExpectedEvidenceV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_EXPECTED_EVIDENCE_KEYS,
    "C5 expected evidence",
  );
  if (C5_EXPECTED_EVIDENCE_KEYS.some((key) => !isSha256Digest(record[key]))) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 expected evidence must contain only exact SHA-256 bindings.",
    );
  }
  return record as unknown as C5ExpectedEvidenceV1;
}

function validateC5ProtectedProfilesContract(value: unknown): C5ProtectedProfilesV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_PROTECTED_PROFILES_KEYS,
    "C5 protected profiles",
  );
  if (C5_PROTECTED_PROFILES_KEYS.some((key) => !isSha256Digest(record[key]))) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 protected profiles must contain only exact SHA-256 bindings.",
    );
  }
  return record as unknown as C5ProtectedProfilesV1;
}

function validateC5NativeHelperBuildContract(value: unknown): C5NativeHelperBuildV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_NATIVE_HELPER_BUILD_KEYS,
    "C5 native helper build",
  );
  validateC5NegativeAuthorityContract(record, "C5 native helper build");
  const digestFields = [
    "sourceDigest",
    "compilerDigest",
    "sdkDigest",
    "flagsDigest",
    "binaryDigest",
    "importAuditDigest",
    "peerRequirementDigest",
  ] as const;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_NATIVE_HELPER_BUILD" ||
    record.buildProfile !== C5_NATIVE_HELPER_BUILD_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "BUILD_EVIDENCE_ONLY_NOT_ADMITTED_NOT_AUTHORIZED" ||
    record.implementationClass !== "TEST_ONLY_DISPOSABLE_NATIVE_HELPER_NOT_PROTECTED" ||
    record.platform !== "darwin" ||
    (record.architecture !== "arm64" && record.architecture !== "x86_64") ||
    digestFields.some((field) => !isSha256Digest(record[field])) ||
    record.protectedAdmissionEligible !== false ||
    record.helperStartAuthority !== "NONE" ||
    !isSha256Digest(record.buildDigest) ||
    record.buildDigest !== computeC5NativeHelperBuildDigest(
      omitC5Fields(record, ["buildDigest"]) as Omit<C5NativeHelperBuildV1, "buildDigest">,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 native helper build contract is malformed or its digest does not match.",
    );
  }
  return record as unknown as C5NativeHelperBuildV1;
}

function validateC5NativeAdmissionRequestContract(
  value: unknown,
): C5NativeAdmissionRequestV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_NATIVE_ADMISSION_REQUEST_KEYS,
    "C5 native admission request",
  );
  validateC5NegativeAuthorityContract(record, "C5 native admission request");
  const paths = requireC5ExactObjectKeys(record.paths, C5_REQUEST_PATHS_KEYS, "C5 request paths");
  validateC5LineageContract(record.lineage);
  validateC5RelativePathBindingContract(paths.workspace, "STORE_ROOT", "C5 workspace path");
  validateC5RelativePathBindingContract(paths.runner, "RUNNER_ROOT", "C5 runner path");
  validateC5ExpectedEvidenceContract(record.expectedEvidence);
  validateC5ProtectedProfilesContract(record.protectedProfiles);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_NATIVE_ADMISSION_REQUEST" ||
    record.requestProfile !== C5_NATIVE_ADMISSION_REQUEST_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "REQUEST_RECORDED_NOT_STARTED_NOT_AUTHORIZED" ||
    record.protocol !== C5_NATIVE_PROTOCOL ||
    record.operation !== "ADMIT_INERT_DESCRIPTOR_EVIDENCE" ||
    !isCanonicalUuidV4(record.requestId) ||
    !isCanonicalLowerHexBytes(record.supervisorNonce, 32) ||
    !isSha256Digest(record.requestDigest) ||
    record.requestDigest !== computeC5NativeAdmissionRequestDigest(
      omitC5Fields(record, ["requestDigest"]) as Omit<
        C5NativeAdmissionRequestV1,
        "requestDigest"
      >,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 native admission request contract is malformed or its digest does not match.",
    );
  }
  return record as unknown as C5NativeAdmissionRequestV1;
}

function validateC5NativeAdmissionAttemptContract(
  value: unknown,
): C5NativeAdmissionAttemptV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_NATIVE_ADMISSION_ATTEMPT_KEYS,
    "C5 native admission attempt",
  );
  validateC5NegativeAuthorityContract(record, "C5 native admission attempt");
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_NATIVE_ADMISSION_ATTEMPT" ||
    record.attemptProfile !== C5_NATIVE_ADMISSION_ATTEMPT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "INTENT_RECORDED_HELPER_NOT_STARTED_NOT_AUTHORIZED" ||
    record.state !== "NEW" ||
    !isCanonicalUuidV4(record.requestId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.requestRecordDigest) ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.supervisorIdentityDigest) ||
    !isSha256Digest(record.helperBuildDigest) ||
    record.recordConveysHelperStartAuthority !== false ||
    !isSha256Digest(record.attemptDigest) ||
    record.attemptDigest !== computeC5NativeAdmissionAttemptDigest(
      omitC5Fields(record, ["attemptDigest"]) as Omit<
        C5NativeAdmissionAttemptV1,
        "attemptDigest"
      >,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 native admission attempt contract is malformed or its digest does not match.",
    );
  }
  return record as unknown as C5NativeAdmissionAttemptV1;
}

function validateC5NativeTranscriptFrameContract(
  value: unknown,
): C5NativeTranscriptFrameV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_NATIVE_TRANSCRIPT_FRAME_KEYS,
    "C5 native transcript frame",
  );
  const messageType = record.messageType as C5MessageTypeV1;
  const sender = record.sender as C5NativeTranscriptFrameV1["sender"];
  const sequence = record.sequence as number;
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_NATIVE_TRANSCRIPT_FRAME" ||
    record.frameProfile !== C5_NATIVE_TRANSCRIPT_FRAME_PROFILE ||
    record.protocol !== C5_NATIVE_PROTOCOL ||
    record.persistence !== "TRANSIENT_ONLY_MUST_NOT_PERSIST" ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.helperInstanceDigest) ||
    !C5_FRAME_SENDERS.has(sender) ||
    !Number.isSafeInteger(record.sequence) ||
    sequence < 0 ||
    !C5_MESSAGE_TYPES.has(messageType) ||
    !C5_ALLOWED_FRAME_SENDERS[messageType]?.includes(sender) ||
    !isCanonicalLowerHexBytes(record.supervisorNonce, 32) ||
    !isCanonicalLowerHexBytes(record.helperNonce, 32) ||
    !(
      record.previousFrameDigest === null ||
      isSha256Digest(record.previousFrameDigest)
    ) ||
    (sequence === 0) !== (record.previousFrameDigest === null) ||
    !isSha256Digest(record.bodyDigest) ||
    record.authenticationProfile !== C5_FRAME_AUTHENTICATION_PROFILE ||
    !isCanonicalBase64UrlBytes(record.authenticationTag, 32) ||
    Buffer.byteLength(canonicalJson(record), "utf8") > C5_MAX_CANONICAL_FRAME_BYTES ||
    !isSha256Digest(record.frameDigest) ||
    record.frameDigest !== computeC5NativeTranscriptFrameDigest(
      omitC5Fields(record, ["frameDigest"]) as Omit<
        C5NativeTranscriptFrameV1,
        "frameDigest"
      >,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 native transcript frame contract is malformed, oversized, or digest-inconsistent.",
    );
  }
  return record as unknown as C5NativeTranscriptFrameV1;
}

function validateC5TranscriptClosureContract(
  value: unknown,
  requestValue: unknown,
  attemptValue: unknown,
): C5NativeTranscriptFrameV1[] {
  if (
    !Array.isArray(value) ||
    value.length === 0 ||
    value.length > C5_MAX_TRANSCRIPT_FRAMES
  ) {
    fail(
      "C5_TRANSCRIPT_INVALID",
      `C5 transcript must contain between one and ${C5_MAX_TRANSCRIPT_FRAMES} frames.`,
    );
  }
  const request = validateC5NativeAdmissionRequestContract(requestValue);
  const attempt = validateC5NativeAdmissionAttemptContract(attemptValue);
  const frames = value.map((entry) => validateC5NativeTranscriptFrameContract(entry));
  const first = frames[0] as C5NativeTranscriptFrameV1;
  for (let index = 0; index < frames.length; index += 1) {
    const frame = frames[index] as C5NativeTranscriptFrameV1;
    const previous = index === 0 ? null : (frames[index - 1] as C5NativeTranscriptFrameV1);
    if (
      frame.sequence !== index ||
      frame.previousFrameDigest !== (previous?.frameDigest ?? null) ||
      frame.sessionId !== attempt.sessionId ||
      frame.requestDigest !== request.requestDigest ||
      frame.supervisorNonce !== request.supervisorNonce ||
      frame.helperInstanceDigest !== first.helperInstanceDigest ||
      frame.helperNonce !== first.helperNonce
    ) {
      fail(
        "C5_TRANSCRIPT_INVALID",
        "C5 transcript frames must form one exact session-bound monotonic digest chain.",
      );
    }
  }
  return frames;
}

function computeC5F3AHandshakeBodyDigest(body: C5F3AHandshakeBodyV1): string {
  return computeC5DomainDigest(C5F3A_HANDSHAKE_BODY_PROFILE, body);
}

function computeC5F3AHandshakeSignatureInputDigest(
  frame: Omit<
    C5F3AHandshakeFrameV1,
    "signatureInputDigest" | "signature" | "frameDigest"
  >,
): string {
  return computeC5DomainDigest(C5F3A_HANDSHAKE_SIGNATURE_INPUT_PROFILE, frame);
}

function computeC5F3AHandshakeFrameDigest(
  frame: Omit<C5F3AHandshakeFrameV1, "frameDigest">,
): string {
  return computeC5DomainDigest(C5F3A_HANDSHAKE_FRAME_DIGEST_PROFILE, frame);
}

function computeC5F3AHandshakeTranscriptDigest(
  frames: readonly C5F3AHandshakeFrameV1[],
): string {
  return computeC5DomainDigest(C5F3A_HANDSHAKE_TRANSCRIPT_PROFILE, {
    orderedFrameDigests: frames.map((frame) => frame.frameDigest),
  });
}

function computeC5F3ASessionBodyDigest(body: C5F3ASessionBodyV1): string {
  return computeC5DomainDigest(C5F3A_SESSION_BODY_DIGEST_PROFILE, body);
}

function c5f3aSessionTagPreimage(
  frame: Omit<C5F3ASessionFrameV1, "authenticationTag" | "frameDigest">,
): Buffer {
  return Buffer.from(
    `${C5F3A_SESSION_TAG_INPUT_PROFILE}\0${canonicalJson(frame)}`,
    "utf8",
  );
}

function computeC5F3ASessionTag(
  frame: Omit<C5F3ASessionFrameV1, "authenticationTag" | "frameDigest">,
  directionKey: Buffer,
): string {
  return createHmac("sha256", directionKey)
    .update(c5f3aSessionTagPreimage(frame))
    .digest("base64url");
}

function computeC5F3ASessionFrameDigest(
  frame: Omit<C5F3ASessionFrameV1, "frameDigest">,
): string {
  return computeC5DomainDigest(C5F3A_SESSION_FRAME_DIGEST_PROFILE, frame);
}

function computeC5F3ASessionTranscriptDigest(
  frames: readonly C5F3ASessionFrameV1[],
): string {
  return computeC5DomainDigest(C5F3A_SESSION_TRANSCRIPT_PROFILE, {
    orderedFrameDigests: frames.map((frame) => frame.frameDigest),
  });
}

function parseCanonicalC5F3AEnvelopeBytes(bytes: Buffer): unknown {
  if (bytes.length === 0 || bytes.length > C5F3A_MAX_ENVELOPE_BYTES) {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope must be non-empty and within the frozen 16 KiB cap.",
    );
  }
  if (bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope must not contain a UTF-8 byte-order mark.",
    );
  }
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope must contain strictly valid UTF-8.",
    );
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text) as unknown;
  } catch {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope must be valid JSON.",
    );
  }
  let canonicalText: string;
  try {
    canonicalText = canonicalJson(parsed);
  } catch {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope contains a noncanonical JSON value.",
    );
  }
  if (text !== canonicalText) {
    fail(
      "C5F3A_ENVELOPE_NONCANONICAL",
      "C5F3A frame envelope bytes must equal exact canonical JSON without BOM, whitespace, newline, duplicate keys, or trailing bytes.",
    );
  }
  return parsed;
}

function encodeC5F3AWireEnvelope(value: unknown): Buffer {
  const envelope = Buffer.from(canonicalJson(value), "utf8");
  if (envelope.length === 0 || envelope.length > C5F3A_MAX_ENVELOPE_BYTES) {
    fail(
      "C5F3A_LENGTH_INVALID",
      "C5F3A encoded frame envelope is outside the frozen length range.",
    );
  }
  const wire = Buffer.alloc(C5F3A_LENGTH_PREFIX_BYTES + envelope.length);
  wire.writeUInt32BE(envelope.length, 0);
  envelope.copy(wire, C5F3A_LENGTH_PREFIX_BYTES);
  return wire;
}

function decodeC5F3AWireEnvelope(
  chunks: readonly C5F3AWireChunkV1[],
  budget: C5F3AWireBudgetV1,
  startTick: number,
): unknown {
  if (
    !Number.isSafeInteger(startTick) ||
    startTick < 0 ||
    chunks.length === 0 ||
    chunks.length > C5F3A_MAX_READ_CHUNKS
  ) {
    fail("C5F3A_READER_POLICY_INVALID", "C5F3A reader inputs exceed the frozen policy.");
  }
  if (
    !Number.isSafeInteger(budget.acceptedFrames) ||
    !Number.isSafeInteger(budget.acceptedWireBytes) ||
    !Number.isSafeInteger(budget.maxObservedAllocationBytes) ||
    budget.acceptedFrames < 0 ||
    budget.acceptedWireBytes < 0 ||
    budget.maxObservedAllocationBytes < 0
  ) {
    fail("C5F3A_READER_POLICY_INVALID", "C5F3A reader budget is malformed.");
  }
  const deadlineTick = startTick + C5F3A_FRAME_DEADLINE_TICKS;
  if (!Number.isSafeInteger(deadlineTick)) {
    fail("C5F3A_READER_POLICY_INVALID", "C5F3A absolute deadline arithmetic overflowed.");
  }
  const prefix = Buffer.alloc(C5F3A_LENGTH_PREFIX_BYTES);
  let prefixOffset = 0;
  let declaredLength: number | null = null;
  let envelope: Buffer | null = null;
  let envelopeOffset = 0;
  let previousTick = startTick;
  for (const chunk of chunks) {
    if (!Number.isSafeInteger(chunk.tick) || chunk.tick < previousTick) {
      fail("C5F3A_CLOCK_ROLLBACK", "C5F3A monotonic reader clock moved backwards.");
    }
    if (chunk.tick > deadlineTick) {
      fail("C5F3A_FRAME_DEADLINE_EXPIRED", "C5F3A absolute frame deadline expired.");
    }
    previousTick = chunk.tick;
    for (const byte of chunk.bytes) {
      if (declaredLength === null) {
        prefix[prefixOffset] = byte;
        prefixOffset += 1;
        if (prefixOffset === C5F3A_LENGTH_PREFIX_BYTES) {
          declaredLength = prefix.readUInt32BE(0);
          if (declaredLength === 0 || declaredLength > C5F3A_MAX_ENVELOPE_BYTES) {
            fail(
              "C5F3A_LENGTH_INVALID",
              "C5F3A declared envelope length is zero or exceeds 16 KiB.",
            );
          }
          const projectedWireBytes =
            budget.acceptedWireBytes + C5F3A_LENGTH_PREFIX_BYTES + declaredLength;
          if (
            !Number.isSafeInteger(projectedWireBytes) ||
            projectedWireBytes > C5F3A_MAX_SESSION_WIRE_BYTES
          ) {
            fail(
              "C5F3A_CUMULATIVE_LIMIT_EXCEEDED",
              "C5F3A cumulative session wire-byte cap would be exceeded.",
            );
          }
          if (budget.acceptedFrames + 1 > C5F3A_MAX_TOTAL_FRAMES) {
            fail(
              "C5F3A_FRAME_COUNT_EXCEEDED",
              "C5F3A cumulative frame-count cap would be exceeded.",
            );
          }
          envelope = Buffer.alloc(declaredLength);
          budget.maxObservedAllocationBytes = Math.max(
            budget.maxObservedAllocationBytes,
            declaredLength,
          );
        }
      } else if (envelopeOffset < declaredLength) {
        (envelope as Buffer)[envelopeOffset] = byte;
        envelopeOffset += 1;
      } else {
        fail(
          "C5F3A_TRAILING_BYTES",
          "C5F3A reader received bytes beyond the one declared frame envelope.",
        );
      }
    }
  }
  if (prefixOffset < C5F3A_LENGTH_PREFIX_BYTES) {
    fail("C5F3A_PREFIX_TRUNCATED", "C5F3A stream ended before the four-byte prefix.");
  }
  if (declaredLength === null || envelope === null || envelopeOffset < declaredLength) {
    fail("C5F3A_ENVELOPE_TRUNCATED", "C5F3A stream ended before the declared envelope.");
  }
  const parsed = parseCanonicalC5F3AEnvelopeBytes(envelope);
  budget.acceptedFrames += 1;
  budget.acceptedWireBytes += C5F3A_LENGTH_PREFIX_BYTES + declaredLength;
  return parsed;
}

function validateC5F3AHandshakeBody(value: unknown): C5F3AHandshakeBodyV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("C5F3A_HANDSHAKE_INVALID", "C5F3A handshake body must be an exact object.");
  }
  const bodyType = (value as Record<string, unknown>).bodyType;
  const expectedKeys = bodyType === "SUPERVISOR_HELLO"
    ? C5F3A_SUPERVISOR_HELLO_BODY_KEYS
    : bodyType === "HELPER_HELLO"
      ? C5F3A_HELPER_HELLO_BODY_KEYS
      : null;
  if (expectedKeys === null) {
    fail("C5F3A_HANDSHAKE_INVALID", "C5F3A handshake body type is not frozen.");
  }
  const record = requireExactObjectKeys(
    value,
    expectedKeys,
    "C5F3A_HANDSHAKE_INVALID",
    "C5F3A handshake body",
  );
  validateC5NegativeAuthorityContract(record, "C5F3A handshake body");
  const commonInvalid =
    record.bodyProfile !== C5F3A_HANDSHAKE_BODY_PROFILE ||
    record.peerEvidenceClass !== "TEST_ONLY_FIXED_FIXTURE_NOT_NATIVE_PEER" ||
    !isSha256Digest(record.peerEvidenceDigest) ||
    !isCanonicalBase64UrlBytes(record.ephemeralPublicKey, 32) ||
    !isCanonicalLowerHexBytes(record.senderNonce, 32);
  const specificInvalid = bodyType === "SUPERVISOR_HELLO"
    ? !isSha256Digest(record.expectedHelperBuildDigest)
    : (
      !isCanonicalLowerHexBytes(record.observedSupervisorNonce, 32) ||
      !isSha256Digest(record.helperInstanceDigest)
    );
  if (commonInvalid || specificInvalid) {
    fail(
      "C5F3A_HANDSHAKE_INVALID",
      "C5F3A handshake body is malformed or exceeds the zero-authority fixture boundary.",
    );
  }
  return record as unknown as C5F3AHandshakeBodyV1;
}

function validateC5F3AHandshakeFrame(value: unknown): C5F3AHandshakeFrameV1 {
  const record = requireExactObjectKeys(
    value,
    C5F3A_HANDSHAKE_FRAME_KEYS,
    "C5F3A_HANDSHAKE_INVALID",
    "C5F3A handshake frame",
  );
  const body = validateC5F3AHandshakeBody(record.body);
  const sequence = record.sequence as number;
  const sender = record.sender as string;
  const expectedBodyType = sender === "SUPERVISOR" ? "SUPERVISOR_HELLO" : "HELPER_HELLO";
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5F3A_HANDSHAKE_FRAME" ||
    record.frameProfile !== C5F3A_HANDSHAKE_FRAME_PROFILE ||
    record.protocol !== C5F3A_PROTOCOL ||
    record.persistence !== "TRANSIENT_ONLY_MUST_NOT_PERSIST" ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.helperBuildDigest) ||
    (sender !== "SUPERVISOR" && sender !== "HELPER") ||
    !Number.isSafeInteger(sequence) ||
    (sequence !== 0 && sequence !== 1) ||
    body.bodyType !== expectedBodyType ||
    (sequence === 0) !== (record.previousFrameDigest === null) ||
    (sequence === 1 && !isSha256Digest(record.previousFrameDigest)) ||
    !isSha256Digest(record.bodyDigest) ||
    record.bodyDigest !== computeC5F3AHandshakeBodyDigest(body) ||
    !isSha256Digest(record.signerKeyIdDigest) ||
    record.signatureProfile !== C5F3A_HANDSHAKE_SIGNATURE_PROFILE ||
    record.signatureVerification !== "NOT_PERFORMED" ||
    !isCanonicalBase64UrlBytes(record.signature, 64) ||
    !isSha256Digest(record.signatureInputDigest) ||
    record.signatureInputDigest !== computeC5F3AHandshakeSignatureInputDigest(
      omitC5Fields(record, ["signatureInputDigest", "signature", "frameDigest"]) as Omit<
        C5F3AHandshakeFrameV1,
        "signatureInputDigest" | "signature" | "frameDigest"
      >,
    ) ||
    !isSha256Digest(record.frameDigest) ||
    record.frameDigest !== computeC5F3AHandshakeFrameDigest(
      omitC5Fields(record, ["frameDigest"]) as Omit<C5F3AHandshakeFrameV1, "frameDigest">,
    )
  ) {
    fail(
      "C5F3A_HANDSHAKE_INVALID",
      "C5F3A handshake frame is malformed, out of phase, or digest-inconsistent.",
    );
  }
  return record as unknown as C5F3AHandshakeFrameV1;
}

function validateC5F3AHandshakeTranscript(
  value: unknown,
): { frames: [C5F3AHandshakeFrameV1, C5F3AHandshakeFrameV1]; transcriptDigest: string } {
  if (!Array.isArray(value) || value.length !== 2) {
    fail("C5F3A_TRANSCRIPT_INVALID", "C5F3A handshake requires exactly two frames.");
  }
  const supervisor = validateC5F3AHandshakeFrame(value[0]);
  const helper = validateC5F3AHandshakeFrame(value[1]);
  const supervisorBody = supervisor.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "SUPERVISOR_HELLO" }
  >;
  const helperBody = helper.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "HELPER_HELLO" }
  >;
  if (
    supervisor.sender !== "SUPERVISOR" ||
    supervisor.sequence !== 0 ||
    supervisor.previousFrameDigest !== null ||
    helper.sender !== "HELPER" ||
    helper.sequence !== 1 ||
    helper.previousFrameDigest !== supervisor.frameDigest ||
    helper.sessionId !== supervisor.sessionId ||
    helper.requestDigest !== supervisor.requestDigest ||
    helper.helperBuildDigest !== supervisor.helperBuildDigest ||
    supervisorBody.expectedHelperBuildDigest !== supervisor.helperBuildDigest ||
    helperBody.observedSupervisorNonce !== supervisorBody.senderNonce ||
    helperBody.senderNonce === supervisorBody.senderNonce
  ) {
    fail(
      "C5F3A_TRANSCRIPT_INVALID",
      "C5F3A handshake frames do not form one exact two-party digest-bound session.",
    );
  }
  const frames: [C5F3AHandshakeFrameV1, C5F3AHandshakeFrameV1] = [
    supervisor,
    helper,
  ];
  return { frames, transcriptDigest: computeC5F3AHandshakeTranscriptDigest(frames) };
}

function c5f3aDirectionContext(
  handshake: ReturnType<typeof validateC5F3AHandshakeTranscript>,
  direction: C5F3ADirectionV1,
): Record<string, unknown> {
  const [supervisor, helper] = handshake.frames;
  const supervisorBody = supervisor.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "SUPERVISOR_HELLO" }
  >;
  const helperBody = helper.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "HELPER_HELLO" }
  >;
  return {
    protocol: C5F3A_PROTOCOL,
    keyDerivationProfile: C5F3A_KEY_DERIVATION_PROFILE,
    sessionTagProfile: C5F3A_SESSION_TAG_PROFILE,
    sessionId: supervisor.sessionId,
    requestDigest: supervisor.requestDigest,
    helperBuildDigest: supervisor.helperBuildDigest,
    helperInstanceDigest: helperBody.helperInstanceDigest,
    handshakeTranscriptDigest: handshake.transcriptDigest,
    supervisorNonce: supervisorBody.senderNonce,
    helperNonce: helperBody.senderNonce,
    direction,
  };
}

function deriveC5F3ATestDirectionKeys(
  handshake: ReturnType<typeof validateC5F3AHandshakeTranscript>,
  testOnlySharedSecret: Buffer,
): C5F3ADirectionKeysV1 {
  if (testOnlySharedSecret.length !== 32) {
    fail(
      "C5F3A_KEY_DERIVATION_INVALID",
      "C5F3A test-only shared secret fixture must be exactly 32 bytes.",
    );
  }
  const supervisorContext = c5f3aDirectionContext(handshake, "SUPERVISOR_TO_HELPER");
  const helperContext = c5f3aDirectionContext(handshake, "HELPER_TO_SUPERVISOR");
  const supervisorToHelperInfoDigest = computeC5DomainDigest(
    C5F3A_KEY_DERIVATION_PROFILE,
    supervisorContext,
  );
  const helperToSupervisorInfoDigest = computeC5DomainDigest(
    C5F3A_KEY_DERIVATION_PROFILE,
    helperContext,
  );
  const salt = Buffer.from(handshake.transcriptDigest, "hex");
  const supervisorToHelper = Buffer.from(hkdfSync(
    "sha256",
    testOnlySharedSecret,
    salt,
    Buffer.from(canonicalJson(supervisorContext), "utf8"),
    32,
  ));
  const helperToSupervisor = Buffer.from(hkdfSync(
    "sha256",
    testOnlySharedSecret,
    salt,
    Buffer.from(canonicalJson(helperContext), "utf8"),
    32,
  ));
  if (timingSafeEqual(supervisorToHelper, helperToSupervisor)) {
    fail("C5F3A_KEY_DERIVATION_INVALID", "C5F3A direction keys must be distinct.");
  }
  return {
    supervisorToHelper,
    helperToSupervisor,
    supervisorToHelperInfoDigest,
    helperToSupervisorInfoDigest,
  };
}

function validateC5F3ASessionBody(value: unknown): C5F3ASessionBodyV1 {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    fail("C5F3A_SESSION_BODY_INVALID", "C5F3A session body must be an exact object.");
  }
  const bodyType = (value as Record<string, unknown>).bodyType;
  const expectedKeys = bodyType === "BIND_REQUEST"
    ? C5F3A_BIND_REQUEST_BODY_KEYS
    : bodyType === "READY_INERT"
      ? C5F3A_READY_INERT_BODY_KEYS
      : bodyType === "INERT_CLOSE_REQUEST"
        ? C5F3A_CLOSE_REQUEST_BODY_KEYS
        : bodyType === "INERT_CLOSE_REPORT"
          ? C5F3A_CLOSE_REPORT_BODY_KEYS
          : null;
  if (expectedKeys === null) {
    fail("C5F3A_SESSION_BODY_INVALID", "C5F3A session body type is not frozen.");
  }
  const record = requireExactObjectKeys(
    value,
    expectedKeys,
    "C5F3A_SESSION_BODY_INVALID",
    "C5F3A session body",
  );
  validateC5NegativeAuthorityContract(record, "C5F3A session body");
  let specificValid = false;
  if (bodyType === "BIND_REQUEST") {
    specificValid = isSha256Digest(record.requestDigest) && isSha256Digest(record.helperBuildDigest);
  } else if (bodyType === "READY_INERT") {
    specificValid = isSha256Digest(record.requestFrameDigest) && record.state === "READY_INERT";
  } else if (bodyType === "INERT_CLOSE_REQUEST") {
    specificValid =
      isSha256Digest(record.lastAcceptedFrameDigest) &&
      record.reason === "FOUNDATION_COMPLETE";
  } else if (bodyType === "INERT_CLOSE_REPORT") {
    specificValid =
      isSha256Digest(record.closeRequestFrameDigest) &&
      record.closeScope === "TRANSCRIPT_ONLY_NO_PROCESS_OR_DESCRIPTOR_CUSTODY" &&
      record.governedRunnerTouched === false &&
      record.readyToExit === true;
  }
  if (record.bodyProfile !== C5F3A_SESSION_BODY_PROFILE || !specificValid) {
    fail(
      "C5F3A_SESSION_BODY_INVALID",
      "C5F3A typed session body is malformed or not inert.",
    );
  }
  return record as unknown as C5F3ASessionBodyV1;
}

function c5f3aDirectionKey(
  direction: C5F3ADirectionV1,
  keys: C5F3ADirectionKeysV1,
): { key: Buffer; infoDigest: string } {
  return direction === "SUPERVISOR_TO_HELPER"
    ? { key: keys.supervisorToHelper, infoDigest: keys.supervisorToHelperInfoDigest }
    : { key: keys.helperToSupervisor, infoDigest: keys.helperToSupervisorInfoDigest };
}

function validateC5F3ASessionFrame(
  value: unknown,
  keys: C5F3ADirectionKeysV1,
): C5F3ASessionFrameV1 {
  const record = requireExactObjectKeys(
    value,
    C5F3A_SESSION_FRAME_KEYS,
    "C5F3A_SESSION_FRAME_INVALID",
    "C5F3A session frame",
  );
  const body = validateC5F3ASessionBody(record.body);
  const direction = record.direction as C5F3ADirectionV1;
  if (direction !== "SUPERVISOR_TO_HELPER" && direction !== "HELPER_TO_SUPERVISOR") {
    fail("C5F3A_SESSION_FRAME_INVALID", "C5F3A session direction is not frozen.");
  }
  const directionMaterial = c5f3aDirectionKey(direction, keys);
  const messageType = record.messageType as string;
  const allowedMessageTypes = new Set<C5F3ASessionMessageTypeV1>([
    "BIND_REQUEST",
    "READY_INERT",
    "INERT_CLOSE_REQUEST",
    "INERT_CLOSE_REPORT",
  ]);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5F3A_SESSION_FRAME" ||
    record.frameProfile !== C5F3A_SESSION_FRAME_PROFILE ||
    record.authenticationClass !== "TEST_ONLY_DERIVED_DIRECTION_TAG_NOT_PROTECTED" ||
    record.protectedPeerVerified !== false ||
    record.protocol !== C5F3A_PROTOCOL ||
    record.persistence !== "TRANSIENT_ONLY_MUST_NOT_PERSIST" ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.helperBuildDigest) ||
    !isSha256Digest(record.helperInstanceDigest) ||
    !isSha256Digest(record.handshakeTranscriptDigest) ||
    !isCanonicalLowerHexBytes(record.supervisorNonce, 32) ||
    !isCanonicalLowerHexBytes(record.helperNonce, 32) ||
    (record.sender !== "SUPERVISOR" && record.sender !== "HELPER") ||
    !Number.isSafeInteger(record.sequence) ||
    (record.sequence as number) < 0 ||
    !isSha256Digest(record.previousFrameDigest) ||
    !allowedMessageTypes.has(messageType as C5F3ASessionMessageTypeV1) ||
    body.bodyType !== messageType ||
    record.directionKeyInfoDigest !== directionMaterial.infoDigest ||
    !isSha256Digest(record.bodyDigest) ||
    record.bodyDigest !== computeC5F3ASessionBodyDigest(body) ||
    record.authenticationProfile !== C5F3A_SESSION_TAG_PROFILE ||
    !isCanonicalBase64UrlBytes(record.authenticationTag, 32) ||
    !isSha256Digest(record.frameDigest)
  ) {
    fail(
      "C5F3A_SESSION_FRAME_INVALID",
      "C5F3A session frame is malformed, non-inert, or digest-inconsistent.",
    );
  }
  const withoutTagAndDigest = omitC5Fields(
    record,
    ["authenticationTag", "frameDigest"],
  ) as Omit<C5F3ASessionFrameV1, "authenticationTag" | "frameDigest">;
  const expectedTag = Buffer.from(
    computeC5F3ASessionTag(withoutTagAndDigest, directionMaterial.key),
    "base64url",
  );
  const observedTag = Buffer.from(record.authenticationTag as string, "base64url");
  if (observedTag.length !== expectedTag.length || !timingSafeEqual(observedTag, expectedTag)) {
    fail(
      "C5F3A_TAG_INVALID",
      "C5F3A test-only direction tag does not match the exact canonical preimage.",
    );
  }
  if (
    record.frameDigest !== computeC5F3ASessionFrameDigest(
      omitC5Fields(record, ["frameDigest"]) as Omit<C5F3ASessionFrameV1, "frameDigest">,
    )
  ) {
    fail("C5F3A_SESSION_FRAME_INVALID", "C5F3A session frame digest does not match.");
  }
  return record as unknown as C5F3ASessionFrameV1;
}

function validateC5F3ASessionTranscript(
  value: unknown,
  handshake: ReturnType<typeof validateC5F3AHandshakeTranscript>,
): { frames: C5F3ASessionFrameV1[]; transcriptDigest: string } {
  if (!Array.isArray(value) || value.length !== 4) {
    fail("C5F3A_TRANSCRIPT_INVALID", "C5F3A inert session requires exactly four frames.");
  }
  const keys = deriveC5F3ATestDirectionKeys(
    handshake,
    Buffer.from(C5F3A_TEST_ONLY_SHARED_SECRET_HEX, "hex"),
  );
  const frames = value.map((frame) => validateC5F3ASessionFrame(frame, keys));
  const expected = [
    ["SUPERVISOR", "SUPERVISOR_TO_HELPER", "BIND_REQUEST"],
    ["HELPER", "HELPER_TO_SUPERVISOR", "READY_INERT"],
    ["SUPERVISOR", "SUPERVISOR_TO_HELPER", "INERT_CLOSE_REQUEST"],
    ["HELPER", "HELPER_TO_SUPERVISOR", "INERT_CLOSE_REPORT"],
  ] as const;
  const [supervisorHandshake, helperHandshake] = handshake.frames;
  const supervisorBody = supervisorHandshake.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "SUPERVISOR_HELLO" }
  >;
  const helperBody = helperHandshake.body as Extract<
    C5F3AHandshakeBodyV1,
    { bodyType: "HELPER_HELLO" }
  >;
  for (let index = 0; index < frames.length; index += 1) {
    const frame = frames[index] as C5F3ASessionFrameV1;
    const previousDigest = index === 0
      ? helperHandshake.frameDigest
      : (frames[index - 1] as C5F3ASessionFrameV1).frameDigest;
    if (
      frame.sequence !== index ||
      frame.sender !== expected[index]?.[0] ||
      frame.direction !== expected[index]?.[1] ||
      frame.messageType !== expected[index]?.[2] ||
      frame.previousFrameDigest !== previousDigest ||
      frame.sessionId !== supervisorHandshake.sessionId ||
      frame.requestDigest !== supervisorHandshake.requestDigest ||
      frame.helperBuildDigest !== supervisorHandshake.helperBuildDigest ||
      frame.helperInstanceDigest !== helperBody.helperInstanceDigest ||
      frame.handshakeTranscriptDigest !== handshake.transcriptDigest ||
      frame.supervisorNonce !== supervisorBody.senderNonce ||
      frame.helperNonce !== helperBody.senderNonce
    ) {
      fail(
        "C5F3A_TRANSCRIPT_INVALID",
        "C5F3A session frames violate the exact lockstep, direction, sequence, or binding chain.",
      );
    }
  }
  const bindBody = frames[0]?.body as Extract<C5F3ASessionBodyV1, { bodyType: "BIND_REQUEST" }>;
  const readyBody = frames[1]?.body as Extract<C5F3ASessionBodyV1, { bodyType: "READY_INERT" }>;
  const closeRequestBody = frames[2]?.body as Extract<
    C5F3ASessionBodyV1,
    { bodyType: "INERT_CLOSE_REQUEST" }
  >;
  const closeReportBody = frames[3]?.body as Extract<
    C5F3ASessionBodyV1,
    { bodyType: "INERT_CLOSE_REPORT" }
  >;
  if (
    bindBody.requestDigest !== supervisorHandshake.requestDigest ||
    bindBody.helperBuildDigest !== supervisorHandshake.helperBuildDigest ||
    readyBody.requestFrameDigest !== frames[0]?.frameDigest ||
    closeRequestBody.lastAcceptedFrameDigest !== frames[1]?.frameDigest ||
    closeReportBody.closeRequestFrameDigest !== frames[2]?.frameDigest
  ) {
    fail(
      "C5F3A_TRANSCRIPT_INVALID",
      "C5F3A typed bodies do not bind the exact prior phase artifacts.",
    );
  }
  return { frames, transcriptDigest: computeC5F3ASessionTranscriptDigest(frames) };
}

function validateC5RootEvidenceContract(value: unknown): C5RootEvidenceV1 {
  const record = requireC5ExactObjectKeys(value, C5_ROOT_EVIDENCE_KEYS, "C5 root evidence");
  if (
    !["STORE_ROOT", "WORKSPACE_ROOT", "RUNNER_ROOT"].includes(record.role as string) ||
    !isSha256Digest(record.protectedRootId) ||
    !isSha256Digest(record.openedIdentityDigest) ||
    !isSha256Digest(record.filesystemIdentityDigest) ||
    !isSha256Digest(record.orderedComponentEvidenceDigest)
  ) {
    fail("C5_CONTRACT_INVALID", "C5 root evidence is malformed.");
  }
  return record as unknown as C5RootEvidenceV1;
}

function validateC5WorkspaceEvidenceContract(value: unknown): C5WorkspaceEvidenceV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_WORKSPACE_EVIDENCE_KEYS,
    "C5 workspace evidence",
  );
  if (
    !isSha256Digest(record.manifestDigest) ||
    !isSha256Digest(record.directorySetDigest) ||
    !isSha256Digest(record.rootIdentityDigest)
  ) {
    fail("C5_CONTRACT_INVALID", "C5 workspace evidence digest bindings are malformed.");
  }
  validateC5SafeCount(record.entryCount, "C5 workspace entry count");
  validateC5SafeCount(record.byteCount, "C5 workspace byte count");
  return record as unknown as C5WorkspaceEvidenceV1;
}

function validateC5RunnerEvidenceContract(value: unknown): C5RunnerEvidenceV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_RUNNER_EVIDENCE_KEYS,
    "C5 runner evidence",
  );
  if (
    !isSha256Digest(record.identityDigest) ||
    !isSha256Digest(record.contentDigest) ||
    !isSha256Digest(record.filesystemIdentityDigest) ||
    typeof record.mode !== "string" ||
    !/^0[0-7]{3}$/.test(record.mode) ||
    record.linkCount !== 1
  ) {
    fail("C5_CONTRACT_INVALID", "C5 runner evidence is malformed.");
  }
  validateC5SafeCount(record.size, "C5 runner size");
  return record as unknown as C5RunnerEvidenceV1;
}

function validateC5AdmissionIssuerClaimContract(value: unknown): C5AdmissionIssuerClaimV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_ADMISSION_ISSUER_KEYS,
    "C5 admission issuer claim",
  );
  if (
    record.role !== "PROTECTED_RECEIPT_AUTHORITY" ||
    !isSha256Digest(record.keyIdDigest) ||
    record.verification !== "NOT_PERFORMED_BY_CONTRACT_VALIDATOR"
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 admission issuer claim is structural metadata only and must use the unverified disposition.",
    );
  }
  return record as unknown as C5AdmissionIssuerClaimV1;
}

function validateC5TerminationIssuerClaimContract(
  value: unknown,
): C5TerminationIssuerClaimV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_TERMINATION_ISSUER_KEYS,
    "C5 termination issuer claim",
  );
  if (
    record.role !== "PROTECTED_SUPERVISOR" ||
    !isSha256Digest(record.keyIdDigest) ||
    record.verification !== "NOT_PERFORMED_BY_CONTRACT_VALIDATOR"
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 termination issuer claim is structural metadata only and must use the unverified disposition.",
    );
  }
  return record as unknown as C5TerminationIssuerClaimV1;
}

function validateC5ReceiptSignatureContract(value: unknown): C5ReceiptSignatureV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_RECEIPT_SIGNATURE_KEYS,
    "C5 receipt signature",
  );
  if (
    record.algorithm !== "ED25519" ||
    record.profile !== C5_SIGNATURE_PROFILE ||
    !isCanonicalBase64UrlBytes(record.value, 64)
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 receipt signature has an invalid structural encoding or algorithm profile.",
    );
  }
  return record as unknown as C5ReceiptSignatureV1;
}

function validateC5UnverifiedDescriptorAdmissionReceiptContract(
  value: unknown,
): C5UnverifiedDescriptorAdmissionReceiptV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_DESCRIPTOR_ADMISSION_RECEIPT_KEYS,
    "C5 descriptor admission receipt",
  );
  validateC5NegativeAuthorityContract(record, "C5 descriptor admission receipt");
  validateC5LineageContract(record.lineage);
  validateC5ProtectedProfilesContract(record.protectedProfiles);
  if (!Array.isArray(record.rootEvidence) || record.rootEvidence.length !== 3) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 descriptor admission receipt must contain exactly three ordered root-evidence entries.",
    );
  }
  const rootEvidence = record.rootEvidence.map((entry) => validateC5RootEvidenceContract(entry));
  if (
    rootEvidence[0]?.role !== "STORE_ROOT" ||
    rootEvidence[1]?.role !== "WORKSPACE_ROOT" ||
    rootEvidence[2]?.role !== "RUNNER_ROOT"
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 root evidence order must be STORE_ROOT, WORKSPACE_ROOT, RUNNER_ROOT.",
    );
  }
  validateC5WorkspaceEvidenceContract(record.workspaceEvidence);
  validateC5RunnerEvidenceContract(record.runnerEvidence);
  validateC5AdmissionIssuerClaimContract(record.issuer);
  validateC5ReceiptSignatureContract(record.signature);
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_DESCRIPTOR_ADMISSION_RECEIPT" ||
    record.receiptProfile !== C5_DESCRIPTOR_ADMISSION_RECEIPT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "DESCRIPTOR_EVIDENCE_RECORDED_NOT_AUTHORIZED" ||
    !isCanonicalUuidV4(record.admissionId) ||
    record.state !== "ADMISSION_RECORDED_NONCURRENT" ||
    record.terminal !== false ||
    record.requiresMatchingTerminationReceipt !== true ||
    !isCanonicalUuidV4(record.requestId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.requestRecordDigest) ||
    !isSha256Digest(record.attemptDigest) ||
    !isSha256Digest(record.attemptRecordDigest) ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.supervisorIdentityDigest) ||
    !isSha256Digest(record.helperInstanceDigest) ||
    !isSha256Digest(record.helperBuildDigest) ||
    !isSha256Digest(record.transcriptDigestThroughAdmission) ||
    !isSha256Digest(record.currentnessBeforeDigest) ||
    !isSha256Digest(record.currentnessAfterDigest) ||
    !isSha256Digest(record.storageAdmissionRecordDigest) ||
    record.storageProfile !== C5_DARWIN_STORAGE_PROFILE ||
    record.capabilityMaterialPresent !== false ||
    !Array.isArray(record.limitations) ||
    canonicalJson(record.limitations) !== canonicalJson(C5_ADMISSION_LIMITATIONS) ||
    !isSha256Digest(record.statementDigest) ||
    record.statementDigest !== computeC5AdmissionStatementDigest(
      omitC5Fields(record, ["statementDigest", "signature", "admissionDigest"]) as Omit<
        C5UnverifiedDescriptorAdmissionReceiptV1,
        "statementDigest" | "signature" | "admissionDigest"
      >,
    ) ||
    !isSha256Digest(record.admissionDigest) ||
    record.admissionDigest !== computeC5AdmissionReceiptDigest(
      omitC5Fields(record, ["admissionDigest"]) as Omit<
        C5UnverifiedDescriptorAdmissionReceiptV1,
        "admissionDigest"
      >,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 descriptor admission receipt is malformed or digest-inconsistent; structural validation does not verify its claimed issuer.",
    );
  }
  return record as unknown as C5UnverifiedDescriptorAdmissionReceiptV1;
}

function validateC5UnverifiedHelperTerminationReceiptContract(
  value: unknown,
): C5UnverifiedHelperTerminationReceiptV1 {
  const record = requireC5ExactObjectKeys(
    value,
    C5_HELPER_TERMINATION_RECEIPT_KEYS,
    "C5 helper termination receipt",
  );
  validateC5NegativeAuthorityContract(record, "C5 helper termination receipt");
  validateC5TerminationIssuerClaimContract(record.issuer);
  validateC5ReceiptSignatureContract(record.signature);
  const trigger = record.trigger as C5TerminationTriggerV1;
  const closeOutcome = record.closeOutcome as C5CloseOutcomeV1;
  const waitOutcome = record.waitOutcome as C5WaitOutcomeV1;
  const admissionReferencesMatch =
    (record.admissionDigest === null && record.admissionRecordDigest === null) ||
    (isSha256Digest(record.admissionDigest) && isSha256Digest(record.admissionRecordDigest));
  const normalTerminationCoherent =
    trigger !== "NORMAL_CLOSE" ||
    (
      isSha256Digest(record.admissionDigest) &&
      isSha256Digest(record.admissionRecordDigest) &&
      closeOutcome === "ALL_CLOSES_CONFIRMED" &&
      waitOutcome === "EXITED_ZERO" &&
      record.terminalOutcome === "TERMINATED_INERT"
    );
  const failedTerminationCoherent =
    trigger === "NORMAL_CLOSE" || record.terminalOutcome === "TERMINATED_FAILED";
  const ambiguousCloseCoherent =
    trigger !== "CLOSE_AMBIGUOUS" ||
    closeOutcome === "CLOSE_AMBIGUOUS_HELPER_TERMINATED";
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5_HELPER_TERMINATION_RECEIPT" ||
    record.receiptProfile !== C5_HELPER_TERMINATION_RECEIPT_PROFILE ||
    record.scope !== "LOCAL_STORE_ONLY" ||
    record.disposition !== "HELPER_CUSTODY_ENDED_NOT_AUTHORIZED" ||
    !isCanonicalUuidV4(record.terminationId) ||
    record.state !== "TERMINATION_RECORDED" ||
    record.terminal !== true ||
    !isCanonicalUuidV4(record.requestId) ||
    !isSha256Digest(record.requestDigest) ||
    !isSha256Digest(record.requestRecordDigest) ||
    !isSha256Digest(record.attemptDigest) ||
    !isSha256Digest(record.attemptRecordDigest) ||
    !isCanonicalUuidV4(record.sessionId) ||
    !isSha256Digest(record.supervisorIdentityDigest) ||
    !isSha256Digest(record.helperInstanceDigest) ||
    !isSha256Digest(record.helperBuildDigest) ||
    !isSha256Digest(record.supervisorChildBindingDigest) ||
    !admissionReferencesMatch ||
    !isSha256Digest(record.finalTranscriptDigest) ||
    !C5_TERMINATION_TRIGGERS.has(trigger) ||
    !C5_CLOSE_OUTCOMES.has(closeOutcome) ||
    !C5_WAIT_OUTCOMES.has(waitOutcome) ||
    record.exactChildWaitConfirmed !== true ||
    record.exclusiveDescriptorCustodyEnded !== true ||
    !normalTerminationCoherent ||
    !failedTerminationCoherent ||
    !ambiguousCloseCoherent ||
    !isSha256Digest(record.statementDigest) ||
    record.statementDigest !== computeC5TerminationStatementDigest(
      omitC5Fields(record, ["statementDigest", "signature", "terminationDigest"]) as Omit<
        C5UnverifiedHelperTerminationReceiptV1,
        "statementDigest" | "signature" | "terminationDigest"
      >,
    ) ||
    !isSha256Digest(record.terminationDigest) ||
    record.terminationDigest !== computeC5TerminationReceiptDigest(
      omitC5Fields(record, ["terminationDigest"]) as Omit<
        C5UnverifiedHelperTerminationReceiptV1,
        "terminationDigest"
      >,
    )
  ) {
    fail(
      "C5_CONTRACT_INVALID",
      "C5 helper termination receipt is malformed, lifecycle-incoherent, or digest-inconsistent; structural validation does not verify its claimed issuer.",
    );
  }
  return record as unknown as C5UnverifiedHelperTerminationReceiptV1;
}

type C5RequestExpectedBindingsV1 = {
  lineage: C5LineageV1;
  paths: C5NativeAdmissionRequestV1["paths"];
  expectedEvidence: C5ExpectedEvidenceV1;
  protectedProfiles: C5ProtectedProfilesV1;
};

function assertC5RequestMatchesExpectedInputs(
  requestValue: unknown,
  expected: C5RequestExpectedBindingsV1,
): C5NativeAdmissionRequestV1 {
  const request = validateC5NativeAdmissionRequestContract(requestValue);
  validateC5LineageContract(expected.lineage);
  const expectedPaths = requireC5ExactObjectKeys(
    expected.paths,
    C5_REQUEST_PATHS_KEYS,
    "C5 expected request paths",
  );
  validateC5RelativePathBindingContract(
    expectedPaths.workspace,
    "STORE_ROOT",
    "C5 expected workspace path",
  );
  validateC5RelativePathBindingContract(
    expectedPaths.runner,
    "RUNNER_ROOT",
    "C5 expected runner path",
  );
  validateC5ExpectedEvidenceContract(expected.expectedEvidence);
  validateC5ProtectedProfilesContract(expected.protectedProfiles);
  if (
    canonicalJson(request.lineage) !== canonicalJson(expected.lineage) ||
    canonicalJson(request.paths) !== canonicalJson(expected.paths) ||
    canonicalJson(request.expectedEvidence) !== canonicalJson(expected.expectedEvidence) ||
    canonicalJson(request.protectedProfiles) !== canonicalJson(expected.protectedProfiles)
  ) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 request differs from the independently reconstructed expected inputs.",
    );
  }
  return request;
}

function assertC5AttemptMatchesRequestAndBuild(
  attemptValue: unknown,
  requestValue: unknown,
  buildValue: unknown,
): C5NativeAdmissionAttemptV1 {
  const attempt = validateC5NativeAdmissionAttemptContract(attemptValue);
  const request = validateC5NativeAdmissionRequestContract(requestValue);
  const build = validateC5NativeHelperBuildContract(buildValue);
  const requestRecordDigest = computeC5EnvelopeRecordDigest(request);
  if (
    attempt.requestId !== request.requestId ||
    attempt.requestDigest !== request.requestDigest ||
    attempt.requestRecordDigest !== requestRecordDigest ||
    attempt.helperBuildDigest !== build.buildDigest ||
    request.protectedProfiles.helperBuildDigest !== build.buildDigest
  ) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 admission attempt does not bind the exact request record and helper build.",
    );
  }
  return attempt;
}

function assertC5AdmissionMatchesRequestAttemptAndBuild(
  admissionValue: unknown,
  requestValue: unknown,
  attemptValue: unknown,
  buildValue: unknown,
  admissionTranscriptValue: unknown,
): C5UnverifiedDescriptorAdmissionReceiptV1 {
  const admission = validateC5UnverifiedDescriptorAdmissionReceiptContract(admissionValue);
  const request = validateC5NativeAdmissionRequestContract(requestValue);
  const attempt = assertC5AttemptMatchesRequestAndBuild(
    attemptValue,
    request,
    buildValue,
  );
  const build = validateC5NativeHelperBuildContract(buildValue);
  const admissionTranscript = validateC5TranscriptClosureContract(
    admissionTranscriptValue,
    request,
    attempt,
  );
  const finalAdmissionFrame = admissionTranscript[admissionTranscript.length - 1] as
    C5NativeTranscriptFrameV1;
  const requestRecordDigest = computeC5EnvelopeRecordDigest(request);
  const attemptRecordDigest = computeC5EnvelopeRecordDigest(attempt);
  if (
    admission.requestId !== request.requestId ||
    admission.requestDigest !== request.requestDigest ||
    admission.requestRecordDigest !== requestRecordDigest ||
    admission.attemptDigest !== attempt.attemptDigest ||
    admission.attemptRecordDigest !== attemptRecordDigest ||
    admission.sessionId !== attempt.sessionId ||
    admission.supervisorIdentityDigest !== attempt.supervisorIdentityDigest ||
    admission.helperBuildDigest !== build.buildDigest ||
    finalAdmissionFrame.messageType !== "ADMISSION_EVIDENCE" ||
    finalAdmissionFrame.sender !== "HELPER" ||
    finalAdmissionFrame.sessionId !== attempt.sessionId ||
    finalAdmissionFrame.requestDigest !== request.requestDigest ||
    finalAdmissionFrame.supervisorNonce !== request.supervisorNonce ||
    finalAdmissionFrame.helperInstanceDigest !== admission.helperInstanceDigest ||
    finalAdmissionFrame.frameDigest !== admission.transcriptDigestThroughAdmission ||
    canonicalJson(admission.lineage) !== canonicalJson(request.lineage) ||
    canonicalJson(admission.protectedProfiles) !== canonicalJson(request.protectedProfiles) ||
    admission.rootEvidence[0]?.protectedRootId !== request.paths.workspace.protectedRootId ||
    admission.rootEvidence[1]?.openedIdentityDigest !==
      request.expectedEvidence.workspaceRootIdentityDigest ||
    admission.rootEvidence[2]?.protectedRootId !== request.paths.runner.protectedRootId ||
    admission.workspaceEvidence.manifestDigest !== request.expectedEvidence.workspaceManifestDigest ||
    admission.workspaceEvidence.directorySetDigest !==
      request.expectedEvidence.workspaceDirectorySetDigest ||
    admission.workspaceEvidence.rootIdentityDigest !==
      request.expectedEvidence.workspaceRootIdentityDigest ||
    admission.runnerEvidence.contentDigest !== request.expectedEvidence.runnerBinaryDigest ||
    admission.runnerEvidence.identityDigest !== request.expectedEvidence.runnerIdentityDigest ||
    admission.storageAdmissionRecordDigest !==
      request.expectedEvidence.storageAdmissionRecordDigest
  ) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 admission receipt does not bind the exact request, attempt, helper build, lineage, roots, and expected evidence.",
    );
  }
  return admission;
}

function assertC5TerminationMatchesAdmission(
  terminationValue: unknown,
  requestValue: unknown,
  attemptValue: unknown,
  buildValue: unknown,
  finalTranscriptValue: unknown,
  admissionValue: unknown | null,
  admissionTranscriptValue: unknown | null,
): C5UnverifiedHelperTerminationReceiptV1 {
  const termination = validateC5UnverifiedHelperTerminationReceiptContract(terminationValue);
  const request = validateC5NativeAdmissionRequestContract(requestValue);
  const attempt = assertC5AttemptMatchesRequestAndBuild(attemptValue, request, buildValue);
  const build = validateC5NativeHelperBuildContract(buildValue);
  const finalTranscript = validateC5TranscriptClosureContract(
    finalTranscriptValue,
    request,
    attempt,
  );
  const finalTranscriptFrame = finalTranscript[finalTranscript.length - 1] as
    C5NativeTranscriptFrameV1;
  const requestRecordDigest = computeC5EnvelopeRecordDigest(request);
  const attemptRecordDigest = computeC5EnvelopeRecordDigest(attempt);
  if (
    termination.requestId !== request.requestId ||
    termination.requestDigest !== request.requestDigest ||
    termination.requestRecordDigest !== requestRecordDigest ||
    termination.attemptDigest !== attempt.attemptDigest ||
    termination.attemptRecordDigest !== attemptRecordDigest ||
    termination.sessionId !== attempt.sessionId ||
    termination.supervisorIdentityDigest !== attempt.supervisorIdentityDigest ||
    termination.helperBuildDigest !== build.buildDigest ||
    finalTranscriptFrame.sessionId !== attempt.sessionId ||
    finalTranscriptFrame.requestDigest !== request.requestDigest ||
    finalTranscriptFrame.supervisorNonce !== request.supervisorNonce ||
    termination.helperInstanceDigest !== finalTranscriptFrame.helperInstanceDigest ||
    termination.finalTranscriptDigest !== finalTranscriptFrame.frameDigest
  ) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 termination receipt does not bind the exact request, attempt, build, supervisor, helper, and final transcript frame.",
    );
  }
  if (admissionValue === null) {
    if (
      admissionTranscriptValue !== null ||
      termination.admissionDigest !== null ||
      termination.admissionRecordDigest !== null ||
      termination.trigger === "NORMAL_CLOSE"
    ) {
      fail(
        "C5_CROSS_BINDING_MISMATCH",
        "C5 pre-admission termination must not name an admission record or claim normal close.",
      );
    }
    return termination;
  }
  if (admissionTranscriptValue === null) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 linked termination requires the exact final admission frame.",
    );
  }
  const admission = assertC5AdmissionMatchesRequestAttemptAndBuild(
    admissionValue,
    request,
    attempt,
    build,
    admissionTranscriptValue,
  );
  const admissionTranscript = validateC5TranscriptClosureContract(
    admissionTranscriptValue,
    request,
    attempt,
  );
  const finalAdmissionFrame = admissionTranscript[admissionTranscript.length - 1] as
    C5NativeTranscriptFrameV1;
  const admissionRecordDigest = computeC5EnvelopeRecordDigest(admission);
  const transcriptPrefixMatches =
    finalTranscript.length >= admissionTranscript.length &&
    admissionTranscript.every(
      (frame, index) => finalTranscript[index]?.frameDigest === frame.frameDigest,
    );
  if (
    termination.admissionDigest !== admission.admissionDigest ||
    termination.admissionRecordDigest !== admissionRecordDigest ||
    termination.requestId !== admission.requestId ||
    termination.requestDigest !== admission.requestDigest ||
    termination.requestRecordDigest !== admission.requestRecordDigest ||
    termination.attemptDigest !== admission.attemptDigest ||
    termination.attemptRecordDigest !== admission.attemptRecordDigest ||
    termination.sessionId !== admission.sessionId ||
    termination.supervisorIdentityDigest !== admission.supervisorIdentityDigest ||
    termination.helperInstanceDigest !== admission.helperInstanceDigest ||
    termination.helperBuildDigest !== admission.helperBuildDigest ||
    !transcriptPrefixMatches ||
    (termination.trigger === "NORMAL_CLOSE" &&
      (
        finalTranscriptFrame.messageType !== "CLOSE_REPORT" ||
        finalTranscriptFrame.sender !== "HELPER" ||
        finalTranscript.length !== admissionTranscript.length + 1 ||
        finalTranscriptFrame.sequence !== finalAdmissionFrame.sequence + 1
      ))
  ) {
    fail(
      "C5_CROSS_BINDING_MISMATCH",
      "C5 termination receipt does not bind the exact admission, request, attempt, session, supervisor, and helper.",
    );
  }
  return termination;
}

function c5F2PermissionMode(mode: bigint): string {
  return (mode & 0o7777n).toString(8).padStart(4, "0");
}

async function assertC5F2ProtectedDirectory(
  directoryPath: string,
  label: string,
): Promise<void> {
  try {
    const information = await lstat(directoryPath, { bigint: true });
    if (
      !information.isDirectory() ||
      information.isSymbolicLink() ||
      String(information.uid) !== "0" ||
      (information.mode & 0o022n) !== 0n ||
      (await realpath(directoryPath)) !== directoryPath
    ) {
      fail(
        "C5F2_TOOLCHAIN_MISMATCH",
        `${label} is not one exact root-owned, non-writable physical directory.`,
      );
    }
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail("C5F2_TOOLCHAIN_MISMATCH", `${label} could not be attested.`, {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

type C5CleanupFailureProfileV1 = {
  cleanupOnlyCode: string;
  cleanupOnlyMessage: string;
  combinedMessage: string;
  secondaryDetailKey: "secondaryCloseFailureCodes" | "secondaryCleanupFailureCodes";
};

const NO_C5_PRIMARY_ERROR = Symbol("NO_C5_PRIMARY_ERROR");

function c5CleanupFailureCode(error: unknown): string {
  if (error instanceof VeritasError) return error.code;
  if (error !== null && typeof error === "object" && "code" in error) {
    const code = (error as { code?: unknown }).code;
    if (typeof code === "string" && code.length > 0) return code;
  }
  return "NON_VERITAS_ERROR";
}

function adjudicateC5CleanupOutcome(
  primaryError: unknown,
  cleanupErrors: unknown[],
  profile: C5CleanupFailureProfileV1,
): void {
  if (cleanupErrors.length === 0) {
    if (primaryError !== NO_C5_PRIMARY_ERROR) throw primaryError;
    return;
  }
  const failureCodes = cleanupErrors.map(c5CleanupFailureCode);
  const combinedErrors = primaryError === NO_C5_PRIMARY_ERROR
    ? cleanupErrors
    : [primaryError, ...cleanupErrors];
  const combined = new AggregateError(
    combinedErrors,
    primaryError === NO_C5_PRIMARY_ERROR ? profile.cleanupOnlyMessage : profile.combinedMessage,
    { cause: cleanupErrors[0] },
  );
  if (primaryError instanceof VeritasError) {
    throw new VeritasError(
      primaryError.code,
      primaryError.message,
      {
        primaryDetails: primaryError.details,
        [profile.secondaryDetailKey]: failureCodes,
      },
      { cause: combined },
    );
  }
  if (primaryError !== NO_C5_PRIMARY_ERROR) throw combined;
  throw new VeritasError(
    profile.cleanupOnlyCode,
    profile.cleanupOnlyMessage,
    { [profile.secondaryDetailKey]: failureCodes },
    { cause: combined },
  );
}

function assertC5CleanupAdjudicationFoundationV1(): 6 {
  const profile: C5CleanupFailureProfileV1 = {
    cleanupOnlyCode: "C5_TEST_CLEANUP_ONLY",
    cleanupOnlyMessage: "Test-only cleanup failure.",
    combinedMessage: "Test-only primary and cleanup failure.",
    secondaryDetailKey: "secondaryCleanupFailureCodes",
  };
  const capture = (action: () => void): { threw: boolean; value: unknown } => {
    try {
      action();
      return { threw: false, value: NO_C5_PRIMARY_ERROR };
    } catch (error) {
      return { threw: true, value: error };
    }
  };

  assert.deepEqual(
    capture(() => adjudicateC5CleanupOutcome(NO_C5_PRIMARY_ERROR, [], profile)),
    { threw: false, value: NO_C5_PRIMARY_ERROR },
  );

  const primaryError = new Error("primary-only");
  assert.deepEqual(
    capture(() => adjudicateC5CleanupOutcome(primaryError, [], profile)),
    { threw: true, value: primaryError },
  );

  assert.deepEqual(
    capture(() => adjudicateC5CleanupOutcome(null, [], profile)),
    { threw: true, value: null },
  );

  const cleanupOnly = capture(() =>
    adjudicateC5CleanupOutcome(NO_C5_PRIMARY_ERROR, [null], profile));
  assert.equal(cleanupOnly.threw, true);
  assert.equal(cleanupOnly.value instanceof VeritasError, true);
  assert.equal((cleanupOnly.value as VeritasError).code, "C5_TEST_CLEANUP_ONLY");
  assert.deepEqual(
    (cleanupOnly.value as VeritasError).details,
    { secondaryCleanupFailureCodes: ["NON_VERITAS_ERROR"] },
  );
  assert.equal((cleanupOnly.value as Error).cause instanceof AggregateError, true);
  assert.deepEqual(((cleanupOnly.value as Error).cause as AggregateError).errors, [null]);

  const combinedPrimary = new VeritasError(
    "C5_TEST_PRIMARY",
    "Test-only primary failure.",
    { phase: "primary" },
  );
  const combinedCleanup = Object.assign(new Error("cleanup"), { code: "ECLOSE" });
  const combinedVeritas = capture(() =>
    adjudicateC5CleanupOutcome(combinedPrimary, [combinedCleanup], profile));
  assert.equal(combinedVeritas.threw, true);
  assert.equal(combinedVeritas.value instanceof VeritasError, true);
  assert.equal((combinedVeritas.value as VeritasError).code, "C5_TEST_PRIMARY");
  assert.deepEqual(
    (combinedVeritas.value as VeritasError).details,
    {
      primaryDetails: { phase: "primary" },
      secondaryCleanupFailureCodes: ["ECLOSE"],
    },
  );
  assert.equal((combinedVeritas.value as Error).cause instanceof AggregateError, true);
  assert.deepEqual(
    ((combinedVeritas.value as Error).cause as AggregateError).errors,
    [combinedPrimary, combinedCleanup],
  );

  const combinedPrimitive = capture(() =>
    adjudicateC5CleanupOutcome(0, [undefined], profile));
  assert.equal(combinedPrimitive.threw, true);
  assert.equal(combinedPrimitive.value instanceof AggregateError, true);
  assert.deepEqual((combinedPrimitive.value as AggregateError).errors, [0, undefined]);

  return 6;
}

async function attestC5F2PinnedFile(
  filePath: string,
  expectedDigest: string,
  expectedMode: "0755" | "0644",
  label: string,
): Promise<C5F2PinnedFileV1> {
  let handle: Awaited<ReturnType<typeof open>> | null = null;
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: C5F2PinnedFileV1 | null = null;
  const closeErrors: unknown[] = [];
  try {
    if (!isAbsolute(filePath) || resolve(filePath) !== filePath) {
      fail("C5F2_TOOLCHAIN_MISMATCH", `${label} path is not absolute and normalized.`);
    }
    const pathBefore = await lstat(filePath, { bigint: true });
    if (
      !pathBefore.isFile() ||
      pathBefore.isSymbolicLink() ||
      String(pathBefore.uid) !== "0" ||
      c5F2PermissionMode(pathBefore.mode) !== expectedMode ||
      String(pathBefore.nlink) !== "1" ||
      (await realpath(filePath)) !== filePath
    ) {
      fail(
        "C5F2_TOOLCHAIN_MISMATCH",
        `${label} is not the frozen root-owned regular-file identity.`,
      );
    }
    handle = await open(filePath, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
    const handleBefore = await handle.stat({ bigint: true });
    const pathIdentity = fileIdentityStamp(pathBefore);
    const handleIdentity = fileIdentityStamp(handleBefore);
    if (
      !handleBefore.isFile() ||
      !fileIdentityStampsEqual(pathIdentity, handleIdentity) ||
      handleBefore.size <= 0n ||
      handleBefore.size > 268_435_456n
    ) {
      fail("C5F2_TOOLCHAIN_MISMATCH", `${label} changed before its bytes were pinned.`);
    }
    const hash = createHash("sha256");
    const expectedBytes = Number(handleBefore.size);
    let position = 0;
    while (position < expectedBytes) {
      const length = Math.min(1_048_576, expectedBytes - position);
      const buffer = Buffer.allocUnsafe(length);
      const { bytesRead } = await handle.read(buffer, 0, length, position);
      if (bytesRead <= 0) {
        fail("C5F2_TOOLCHAIN_MISMATCH", `${label} ended before its frozen size.`);
      }
      hash.update(buffer.subarray(0, bytesRead));
      position += bytesRead;
    }
    const extra = Buffer.alloc(1);
    const { bytesRead: extraBytes } = await handle.read(extra, 0, 1, expectedBytes);
    const handleAfter = await handle.stat({ bigint: true });
    const pathAfter = await lstat(filePath, { bigint: true });
    if (
      extraBytes !== 0 ||
      !fileIdentityStampsEqual(handleIdentity, fileIdentityStamp(handleAfter)) ||
      !fileIdentityStampsEqual(handleIdentity, fileIdentityStamp(pathAfter))
    ) {
      fail("C5F2_TOOLCHAIN_MISMATCH", `${label} changed while it was hashed.`);
    }
    const digest = hash.digest("hex");
    if (digest !== expectedDigest) {
      fail("C5F2_TOOLCHAIN_MISMATCH", `${label} bytes differ from the frozen digest.`, {
        expectedDigest,
        observedDigest: digest,
      });
    }
    result = {
      path: filePath,
      digest,
      size: expectedBytes,
      ownerUid: String(pathBefore.uid),
      mode: c5F2PermissionMode(pathBefore.mode),
      identity: handleIdentity,
    };
  } catch (error) {
    primaryError = error instanceof VeritasError
      ? error
      : new VeritasError("C5F2_TOOLCHAIN_MISMATCH", `${label} could not be pinned.`, {
        sourceCode: (error as NodeJS.ErrnoException).code ?? null,
      });
  } finally {
    if (handle !== null) {
      try {
        await handle.close();
      } catch (closeError) {
        closeErrors.push(closeError);
      }
    }
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F2_PINNED_FILE_CLOSE_FAILED",
    cleanupOnlyMessage: `${label} descriptor did not close cleanly after pinning.`,
    combinedMessage: `C5F2 ${label} pinning and descriptor close both failed.`,
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
  if (result === null) {
    fail("C5F2_TOOLCHAIN_MISMATCH", `${label} pinning completed without evidence.`);
  }
  return result;
}

async function assertC5F2PinnedFileUnchanged(
  evidence: C5F2PinnedFileV1,
  label: string,
): Promise<void> {
  try {
    const current = await lstat(evidence.path, { bigint: true });
    if (
      !current.isFile() ||
      current.isSymbolicLink() ||
      !fileIdentityStampsEqual(evidence.identity, fileIdentityStamp(current)) ||
      (await realpath(evidence.path)) !== evidence.path
    ) {
      fail("C5F2_TOOLCHAIN_MISMATCH", `${label} changed after use.`);
    }
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail("C5F2_TOOLCHAIN_MISMATCH", `${label} could not be revalidated.`, {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

async function attestC5F2Toolchain(): Promise<{
  manifest: C5F2ToolchainManifestV1;
  pinnedFiles: C5F2PinnedFileV1[];
}> {
  if (platform() !== "darwin" || process.arch !== "arm64") {
    fail(
      "C5F2_PLATFORM_UNSUPPORTED",
      "The frozen C5F2 foundation profile exists only for this exact Darwin arm64 lane.",
    );
  }
  for (const [directoryPath, label] of [
    ["/Applications/Xcode.app", "Xcode application root"],
    ["/Applications/Xcode.app/Contents", "Xcode contents root"],
    ["/Applications/Xcode.app/Contents/Developer", "Xcode developer root"],
    ["/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain", "Xcode default toolchain"],
    ["/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin", "Xcode tool directory"],
    ["/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs", "Xcode SDK directory"],
    [C5F2_SDK_ROOT, "Physical Xcode SDK root"],
  ] as const) {
    await assertC5F2ProtectedDirectory(directoryPath, label);
  }
  const [compiler, linker, nm, otool] = await Promise.all([
    attestC5F2PinnedFile(
      C5F2_COMPILER_PATH,
      C5F2_EXPECTED_TOOL_DIGESTS.compiler,
      "0755",
      "C5F2 direct cc1 compiler",
    ),
    attestC5F2PinnedFile(
      C5F2_LINKER_PATH,
      C5F2_EXPECTED_TOOL_DIGESTS.linker,
      "0755",
      "C5F2 direct linker",
    ),
    attestC5F2PinnedFile(
      C5F2_NM_PATH,
      C5F2_EXPECTED_TOOL_DIGESTS.nm,
      "0755",
      "C5F2 undefined-symbol auditor",
    ),
    attestC5F2PinnedFile(
      C5F2_OTOOL_PATH,
      C5F2_EXPECTED_TOOL_DIGESTS.otool,
      "0755",
      "C5F2 Mach-O auditor",
    ),
  ]);
  const manifestBody: Omit<C5F2ToolchainManifestV1, "manifestDigest"> = {
    schemaVersion: 1,
    profile: C5F2_TOOLCHAIN_MANIFEST_PROFILE,
    compiler: {
      role: "COMPILER",
      path: compiler.path,
      digest: compiler.digest,
      size: compiler.size,
      ownerUid: "0",
      mode: "0755",
    },
    linker: {
      role: "LINKER",
      path: linker.path,
      digest: linker.digest,
      size: linker.size,
      ownerUid: "0",
      mode: "0755",
    },
    nm: {
      role: "NM",
      path: nm.path,
      digest: nm.digest,
      size: nm.size,
      ownerUid: "0",
      mode: "0755",
    },
    otool: {
      role: "OTOOL",
      path: otool.path,
      digest: otool.digest,
      size: otool.size,
      ownerUid: "0",
      mode: "0755",
    },
    driverLookupUsed: false,
    shellUsed: false,
    pathLookupUsed: false,
    helperDispatchRoleExists: false,
  };
  return {
    manifest: {
      ...manifestBody,
      manifestDigest: computeC5DomainDigest(C5F2_TOOLCHAIN_MANIFEST_PROFILE, manifestBody),
    },
    pinnedFiles: [compiler, linker, nm, otool],
  };
}

async function attestC5F2Sdk(): Promise<{
  manifest: C5F2SdkManifestV1;
  pinnedFiles: C5F2PinnedFileV1[];
}> {
  try {
    const alias = await lstat(C5F2_SDK_ALIAS_PATH, { bigint: true });
    if (
      !alias.isSymbolicLink() ||
      String(alias.uid) !== "0" ||
      (await readlink(C5F2_SDK_ALIAS_PATH)) !== "MacOSX.sdk" ||
      (await realpath(C5F2_SDK_ALIAS_PATH)) !== C5F2_SDK_ROOT
    ) {
      fail("C5F2_SDK_MISMATCH", "The frozen Xcode SDK alias no longer resolves exactly.");
    }
    const [settingsJson, settingsPlist, systemVersionPlist, libSystemTbd] =
      await Promise.all([
        attestC5F2PinnedFile(
          C5F2_SDK_SETTINGS_JSON_PATH,
          C5F2_EXPECTED_SDK_DIGESTS.settingsJson,
          "0644",
          "C5F2 SDKSettings.json",
        ),
        attestC5F2PinnedFile(
          C5F2_SDK_SETTINGS_PLIST_PATH,
          C5F2_EXPECTED_SDK_DIGESTS.settingsPlist,
          "0644",
          "C5F2 SDKSettings.plist",
        ),
        attestC5F2PinnedFile(
          C5F2_SDK_SYSTEM_VERSION_PATH,
          C5F2_EXPECTED_SDK_DIGESTS.systemVersionPlist,
          "0644",
          "C5F2 SDK SystemVersion.plist",
        ),
        attestC5F2PinnedFile(
          C5F2_LIBSYSTEM_TBD_PATH,
          C5F2_EXPECTED_SDK_DIGESTS.libSystemTbd,
          "0644",
          "C5F2 SDK libSystem.B.tbd",
        ),
      ]);
    const settingsBytes = await readStableRegularFile(
      C5F2_SDK_SETTINGS_JSON_PATH,
      "C5F2_SDK_MISMATCH",
      "C5F2 SDKSettings.json",
    );
    const settings = JSON.parse(
      new TextDecoder("utf-8", { fatal: true }).decode(settingsBytes.bytes),
    ) as Record<string, unknown>;
    const systemVersionBytes = await readStableRegularFile(
      C5F2_SDK_SYSTEM_VERSION_PATH,
      "C5F2_SDK_MISMATCH",
      "C5F2 SDK SystemVersion.plist",
    );
    const systemVersionText = new TextDecoder("utf-8", { fatal: true }).decode(
      systemVersionBytes.bytes,
    );
    if (
      settings.Version !== "26.5" ||
      settings.CanonicalName !== "macosx26.5" ||
      settings.DefaultDeploymentTarget !== "26.5" ||
      !systemVersionText.includes("<key>ProductBuildVersion</key>\n\t<string>25F70</string>") ||
      !systemVersionText.includes("<key>ProductVersion</key>\n\t<string>26.5</string>")
    ) {
      fail("C5F2_SDK_MISMATCH", "The frozen SDK version metadata changed.");
    }
    const manifestBody: Omit<C5F2SdkManifestV1, "manifestDigest"> = {
      schemaVersion: 1,
      profile: C5F2_SDK_MANIFEST_PROFILE,
      physicalRoot: C5F2_SDK_ROOT,
      aliasPath: C5F2_SDK_ALIAS_PATH,
      aliasTarget: "MacOSX.sdk",
      version: "26.5",
      buildVersion: "25F70",
      canonicalName: "macosx26.5",
      settingsJsonDigest: settingsJson.digest,
      settingsPlistDigest: settingsPlist.digest,
      systemVersionPlistDigest: systemVersionPlist.digest,
      libSystemTbdDigest: libSystemTbd.digest,
    };
    return {
      manifest: {
        ...manifestBody,
        manifestDigest: computeC5DomainDigest(C5F2_SDK_MANIFEST_PROFILE, manifestBody),
      },
      pinnedFiles: [settingsJson, settingsPlist, systemVersionPlist, libSystemTbd],
    };
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail("C5F2_SDK_MISMATCH", "The frozen physical Xcode SDK could not be attested.", {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

function makeC5F2BuildRecipe(): C5F2BuildRecipeV1 {
  const recipeBody: Omit<C5F2BuildRecipeV1, "recipeDigest"> = {
    schemaVersion: 1,
    profile: C5F2_BUILD_RECIPE_PROFILE,
    cwd: "{DISPOSABLE_BUILD_ROOT}",
    environment: C5F2_FIXED_ENVIRONMENT,
    compilerArgs: C5F2_CC1_ARGS,
    linkerArgs: C5F2_LINK_ARGS,
    descriptorRoles: {
      fd3: "EXCLUSIVE_PRECREATED_OUTPUT",
      fd4: "PINNED_NOFOLLOW_INPUT",
    },
    sourceName: "helper.c",
    objectName: "helper.o",
    binaryName: "helper.raw",
    outputMode: "0600_NONEXECUTABLE",
    signing: "NOT_ATTEMPTED",
  };
  return {
    ...recipeBody,
    recipeDigest: computeC5DomainDigest(C5F2_BUILD_RECIPE_PROFILE, recipeBody),
  };
}

async function createC5F2BuildRoot(label: "a" | "b"): Promise<C5F2BuildRootV1> {
  const parentPath = await realpath(tmpdir());
  const parentIdentity = await readPrivateDirectoryIdentity(
    parentPath,
    "C5F2_TEMP_ROOT_INVALID",
    "C5F2 canonical temporary parent",
  );
  let parentHandle: C5F2FileHandle | null = null;
  let rootHandle: C5F2FileHandle | null = null;
  let rootPath: string | null = null;
  try {
    parentHandle = await open(
      parentPath,
      fsConstants.O_RDONLY | fsConstants.O_DIRECTORY | fsConstants.O_NOFOLLOW,
    );
    const heldParentIdentity = directoryIdentityStampFromStat(
      await parentHandle.stat({ bigint: true }),
    );
    if (!directoryIdentityStampsEqual(parentIdentity, heldParentIdentity)) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 temporary parent changed before root creation.");
    }
    rootPath = await mkdtemp(join(parentPath, `veritas-c5f2-${label}-`));
    await chmod(rootPath, 0o700);
    const canonicalRoot = await realpath(rootPath);
    if (canonicalRoot !== rootPath || dirname(rootPath) !== parentPath) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 build root escaped its canonical temp parent.");
    }
    const identity = await readPrivateDirectoryIdentity(
      rootPath,
      "C5F2_TEMP_ROOT_INVALID",
      `C5F2 build root ${label}`,
      "0700",
    );
    rootHandle = await open(
      rootPath,
      fsConstants.O_RDONLY | fsConstants.O_DIRECTORY | fsConstants.O_NOFOLLOW,
    );
    const heldRootIdentity = directoryIdentityStampFromStat(
      await rootHandle.stat({ bigint: true }),
    );
    const parentAfter = await readPrivateDirectoryIdentity(
      parentPath,
      "C5F2_TEMP_ROOT_INVALID",
      "C5F2 canonical temporary parent after root creation",
    );
    if (
      !directoryIdentityStampsEqual(identity, heldRootIdentity) ||
      !directoryIdentityStampsEqual(parentIdentity, parentAfter) ||
      !directoryIdentityStampsEqual(
        parentIdentity,
        directoryIdentityStampFromStat(await parentHandle.stat({ bigint: true })),
      )
    ) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 retained directory identities diverged.");
    }
    return {
      path: rootPath,
      parentPath,
      identity,
      parentIdentity,
      handle: rootHandle,
      parentHandle,
      retainedArtifacts: new Map(),
      cleanupDisposition: "ELIGIBLE",
    };
  } catch (error) {
    const cleanupFailures: string[] = [];
    if (rootPath !== null) {
      try {
        await rmdir(rootPath);
      } catch (cleanupError) {
        cleanupFailures.push(
          cleanupError instanceof VeritasError
            ? cleanupError.code
            : (cleanupError as NodeJS.ErrnoException).code ?? "NON_VERITAS_ERROR",
        );
      }
    }
    for (const handle of [rootHandle, parentHandle]) {
      if (handle === null) continue;
      try {
        await handle.close();
      } catch (closeError) {
        cleanupFailures.push((closeError as NodeJS.ErrnoException).code ?? "NON_VERITAS_ERROR");
      }
    }
    if (cleanupFailures.length > 0 && error instanceof VeritasError) {
      throw new VeritasError(error.code, error.message, {
        primaryDetails: error.details,
        secondaryCleanupFailureCodes: cleanupFailures,
      }, { cause: error });
    }
    if (cleanupFailures.length > 0) {
      throw new AggregateError(
        [error, ...cleanupFailures.map((code) => new Error(code))],
        "C5F2 root creation and cleanup both failed.",
        { cause: error },
      );
    }
    throw error;
  }
}

async function assertC5F2BuildRootCurrent(root: C5F2BuildRootV1): Promise<void> {
  try {
    if (
      root.cleanupDisposition !== "ELIGIBLE" ||
      dirname(root.path) !== root.parentPath ||
      (await realpath(root.path)) !== root.path ||
      (await realpath(root.parentPath)) !== root.parentPath
    ) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 build-root ancestry no longer resolves exactly.");
    }
    const current = await readPrivateDirectoryIdentity(
      root.path,
      "C5F2_TEMP_ROOT_INVALID",
      "C5F2 build root",
      "0700",
    );
    const currentParent = await readPrivateDirectoryIdentity(
      root.parentPath,
      "C5F2_TEMP_ROOT_INVALID",
      "C5F2 temporary parent",
    );
    const heldRoot = directoryIdentityStampFromStat(await root.handle.stat({ bigint: true }));
    const heldParent = directoryIdentityStampFromStat(
      await root.parentHandle.stat({ bigint: true }),
    );
    if (
      !directoryIdentityStampsEqual(current, root.identity) ||
      !directoryIdentityStampsEqual(heldRoot, root.identity) ||
      !directoryIdentityStampsEqual(currentParent, root.parentIdentity) ||
      !directoryIdentityStampsEqual(heldParent, root.parentIdentity)
    ) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 retained build-root ancestry changed during use.");
    }
  } catch (error) {
    root.cleanupDisposition = "QUARANTINED";
    if (error instanceof VeritasError) throw error;
    fail("C5F2_TEMP_ROOT_INVALID", "C5F2 retained build-root validation failed.", {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

function c5F2ToolSpec(role: C5F2ToolRoleV1): {
  command: string;
  args: readonly string[];
  descriptorCount: 1 | 2 | 3;
} {
  switch (role) {
    case "COMPILER_CC1":
      return { command: C5F2_COMPILER_PATH, args: C5F2_CC1_ARGS, descriptorCount: 2 };
    case "C5F3B1_COMPILER_SUPERVISOR":
      return {
        command: C5F2_COMPILER_PATH,
        args: C5F3B1_SUPERVISOR_CC1_ARGS,
        descriptorCount: 3,
      };
    case "C5F3B1_COMPILER_HELPER":
      return {
        command: C5F2_COMPILER_PATH,
        args: C5F3B1_HELPER_CC1_ARGS,
        descriptorCount: 3,
      };
    case "LINKER":
      return { command: C5F2_LINKER_PATH, args: C5F2_LINK_ARGS, descriptorCount: 2 };
    case "NM_UNDEFINED":
      return { command: C5F2_NM_PATH, args: ["-u", "/dev/fd/3"], descriptorCount: 1 };
    case "OTOOL_HEADER":
      return { command: C5F2_OTOOL_PATH, args: ["-hv", "/dev/fd/3"], descriptorCount: 1 };
    case "OTOOL_LIBRARIES":
      return { command: C5F2_OTOOL_PATH, args: ["-L", "/dev/fd/3"], descriptorCount: 1 };
    case "OTOOL_LOAD_COMMANDS":
      return { command: C5F2_OTOOL_PATH, args: ["-l", "/dev/fd/3"], descriptorCount: 1 };
  }
}

async function runBoundedC5F2Tool(
  role: C5F2ToolRoleV1,
  root: C5F2BuildRootV1,
  descriptors: number[],
): Promise<{
  stdout: Buffer;
  stderr: Buffer;
  directChildExitObserved: true;
  directChildStdioCloseObserved: true;
  processGroupKillRequired: false;
}> {
  if (c5F2ProcessPoisoned) {
    fail(
      "C5F2_PROCESS_POISONED",
      "C5F2 refuses later work after a child termination boundary became unconfirmed.",
    );
  }
  await assertC5F2BuildRootCurrent(root);
  const spec = c5F2ToolSpec(role);
  if (descriptors.length !== spec.descriptorCount) {
    fail("C5F2_TOOL_DISPATCH_INVALID", "C5F2 tool descriptor roles are incomplete.");
  }
  return new Promise((resolvePromise, rejectPromise) => {
    const child = spawn(spec.command, [...spec.args], {
      cwd: root.path,
      detached: true,
      env: { ...C5F2_FIXED_ENVIRONMENT },
      stdio: ["ignore", "pipe", "pipe", ...descriptors],
    });
    const childStdout = child.stdout;
    const childStderr = child.stderr;
    const stdout: Buffer[] = [];
    const stderr: Buffer[] = [];
    let outputBytes = 0;
    let settled = false;
    let exitObserved = false;
    let closeObserved = false;
    let killSent = false;
    let exitCode: number | null = null;
    let exitSignal: NodeJS.Signals | null = null;
    let requestedFailure: { code: string; message: string } | null = null;
    let exitDeadline: NodeJS.Timeout | null = null;
    let closeDeadline: NodeJS.Timeout | null = null;
    const clearDeadlines = (): void => {
      clearTimeout(runtimeDeadline);
      if (exitDeadline !== null) clearTimeout(exitDeadline);
      if (closeDeadline !== null) clearTimeout(closeDeadline);
    };
    const markTerminationUnconfirmed = (boundary: "EXIT" | "STDIO_CLOSE" | "SIGNAL"): void => {
      if (settled) return;
      settled = true;
      c5F2ProcessPoisoned = true;
      root.cleanupDisposition = "QUARANTINED";
      clearDeadlines();
      childStdout?.destroy();
      childStderr?.destroy();
      child.unref();
      rejectPromise(new VeritasError(
        "C5F2_TERMINATION_UNCONFIRMED",
        "A C5F2 tool did not reach its bounded direct-child termination boundary.",
        {
          role,
          boundary,
          exitObserved,
          closeObserved,
          killSent,
          processGroupEmptyProven: false,
          descendantAbsenceProven: false,
        },
      ));
    };
    const requestFailure = (code: string, message: string): void => {
      if (requestedFailure !== null || settled) return;
      requestedFailure = { code, message };
      if (
        !exitObserved &&
        child.exitCode === null &&
        child.signalCode === null &&
        child.pid !== undefined
      ) {
        try {
          process.kill(-child.pid, "SIGKILL");
          killSent = true;
        } catch (error) {
          if ((error as NodeJS.ErrnoException).code !== "ESRCH") {
            markTerminationUnconfirmed("SIGNAL");
            return;
          }
        }
      }
      if (!exitObserved && !settled) {
        exitDeadline = setTimeout(
          () => markTerminationUnconfirmed("EXIT"),
          C5F2_TOOL_KILL_ACK_TIMEOUT_MS,
        );
      }
    };
    const collect = (target: Buffer[], chunk: Buffer): void => {
      outputBytes += chunk.byteLength;
      if (outputBytes > C5F2_TOOL_OUTPUT_LIMIT_BYTES) {
        requestFailure("C5F2_TOOL_OUTPUT_LIMIT", "C5F2 tool output exceeded its frozen limit.");
        return;
      }
      target.push(Buffer.from(chunk));
    };
    childStdout?.on("data", (chunk: Buffer) => collect(stdout, chunk));
    childStderr?.on("data", (chunk: Buffer) => collect(stderr, chunk));
    const runtimeDeadline = setTimeout(() => {
      requestFailure("C5F2_TOOL_TIMEOUT", "C5F2 tool exceeded its frozen time limit.");
    }, C5F2_TOOL_TIMEOUT_MS);
    child.once("error", (error) => {
      if (settled) return;
      settled = true;
      clearDeadlines();
      rejectPromise(new VeritasError(
        "C5F2_TOOL_SPAWN_FAILED",
        "A frozen C5F2 tool could not be started.",
        { role, sourceCode: (error as NodeJS.ErrnoException).code ?? null },
      ));
    });
    child.once("exit", (code, signal) => {
      if (settled) return;
      exitObserved = true;
      exitCode = code;
      exitSignal = signal;
      clearTimeout(runtimeDeadline);
      if (exitDeadline !== null) {
        clearTimeout(exitDeadline);
        exitDeadline = null;
      }
      closeDeadline = setTimeout(
        () => markTerminationUnconfirmed("STDIO_CLOSE"),
        C5F2_TOOL_STDIO_CLOSE_TIMEOUT_MS,
      );
    });
    child.once("close", (code, signal) => {
      if (settled) return;
      closeObserved = true;
      if (!exitObserved) {
        markTerminationUnconfirmed("EXIT");
        return;
      }
      settled = true;
      clearDeadlines();
      const stdoutBytes = Buffer.concat(stdout);
      const stderrBytes = Buffer.concat(stderr);
      if (requestedFailure !== null) {
        rejectPromise(new VeritasError(
          requestedFailure.code,
          requestedFailure.message,
          {
            role,
            code,
            signal,
            stdoutDigest: sha256Bytes(stdoutBytes),
            stderrDigest: sha256Bytes(stderrBytes),
            outputBytes,
            directChildExitObserved: true,
            directChildStdioCloseObserved: true,
            processGroupKillRequired: killSent,
            processGroupEmptyProven: false,
            descendantAbsenceProven: false,
          },
        ));
        return;
      }
      if (
        code !== exitCode ||
        signal !== exitSignal ||
        exitCode !== 0 ||
        exitSignal !== null
      ) {
        rejectPromise(new VeritasError(
          "C5F2_TOOL_FAILED",
          "A frozen C5F2 tool returned a non-success disposition.",
          {
            role,
            code,
            signal,
            stdoutDigest: sha256Bytes(stdoutBytes),
            stderrDigest: sha256Bytes(stderrBytes),
            stderrPreview: stderrBytes.subarray(0, 1024).toString("utf8"),
          },
        ));
        return;
      }
      resolvePromise({
        stdout: stdoutBytes,
        stderr: stderrBytes,
        directChildExitObserved: true,
        directChildStdioCloseObserved: true,
        processGroupKillRequired: false,
      });
    });
    if (childStdout === null || childStderr === null) {
      requestFailure(
        "C5F2_TOOL_STDIO_UNAVAILABLE",
        "A frozen C5F2 tool did not expose both required output pipes.",
      );
    }
  });
}

async function readC5F2ArtifactHandle(
  handle: C5F2FileHandle,
  filePath: string,
  root: C5F2BuildRootV1,
  expectedMode: "0400" | "0600",
  label: string,
): Promise<{ bytes: Buffer; identity: FileIdentityStamp }> {
  const effectiveUid = typeof process.getuid === "function" ? String(process.getuid()) : null;
  if (effectiveUid === null) {
    fail("C5F2_ARTIFACT_INVALID", "C5F2 requires a concrete effective UID.");
  }
  const handleBefore = await handle.stat({ bigint: true });
  const pathBefore = await lstat(filePath, { bigint: true });
  const handleIdentity = fileIdentityStamp(handleBefore);
  if (
    !handleBefore.isFile() ||
    !pathBefore.isFile() ||
    pathBefore.isSymbolicLink() ||
    !fileIdentityStampsEqual(handleIdentity, fileIdentityStamp(pathBefore)) ||
    String(handleBefore.uid) !== effectiveUid ||
    String(handleBefore.nlink) !== "1" ||
    c5F2PermissionMode(handleBefore.mode) !== expectedMode ||
    String(handleBefore.dev) !== root.identity.deviceId ||
    handleBefore.size <= 0n ||
    handleBefore.size > 1_048_576n
  ) {
    fail(
      "C5F2_ARTIFACT_INVALID",
      `${label} is not one same-device, single-link, private regular artifact.`,
    );
  }
  const expectedBytes = Number(handleBefore.size);
  const bytes = Buffer.alloc(expectedBytes);
  let position = 0;
  while (position < expectedBytes) {
    const { bytesRead } = await handle.read(
      bytes,
      position,
      expectedBytes - position,
      position,
    );
    if (bytesRead <= 0) {
      fail("C5F2_ARTIFACT_INVALID", `${label} ended before its observed size.`);
    }
    position += bytesRead;
  }
  const extra = Buffer.alloc(1);
  const { bytesRead: extraBytes } = await handle.read(extra, 0, 1, expectedBytes);
  const handleAfter = await handle.stat({ bigint: true });
  const pathAfter = await lstat(filePath, { bigint: true });
  if (
    extraBytes !== 0 ||
    !fileIdentityStampsEqual(handleIdentity, fileIdentityStamp(handleAfter)) ||
    !fileIdentityStampsEqual(handleIdentity, fileIdentityStamp(pathAfter))
  ) {
    fail("C5F2_ARTIFACT_INVALID", `${label} changed during pinned readback.`);
  }
  return { bytes, identity: handleIdentity };
}

async function openC5F2PinnedInput(
  filePath: string,
  expectedIdentity: FileIdentityStamp,
  label: string,
): Promise<C5F2FileHandle> {
  try {
    const handle = await open(filePath, fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW);
    const information = await handle.stat({ bigint: true });
    if (!information.isFile() || !fileIdentityStampsEqual(
      expectedIdentity,
      fileIdentityStamp(information),
    )) {
      await handle.close();
      fail("C5F2_ARTIFACT_INVALID", `${label} changed before descriptor-backed use.`);
    }
    return handle;
  } catch (error) {
    if (error instanceof VeritasError) throw error;
    fail("C5F2_ARTIFACT_INVALID", `${label} could not be reopened without following links.`, {
      sourceCode: (error as NodeJS.ErrnoException).code ?? null,
    });
  }
}

function decodeC5F2ToolText(bytes: Buffer, label: string): string {
  let text: string;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    fail("C5F2_AUDIT_INVALID", `${label} did not emit strict UTF-8.`);
  }
  if (text.includes("\0") || text.includes("\r")) {
    fail("C5F2_AUDIT_INVALID", `${label} emitted noncanonical text.`);
  }
  return text;
}

function readC5F2FixedMachOName(bytes: Buffer, offset: number, length: number): string {
  const end = bytes.indexOf(0, offset);
  const boundedEnd = end === -1 || end > offset + length ? offset + length : end;
  return bytes.subarray(offset, boundedEnd).toString("ascii");
}

function readC5F2MachOCString(
  bytes: Buffer,
  commandOffset: number,
  commandSize: number,
  relativeOffset: number,
): string {
  if (relativeOffset < 8 || relativeOffset >= commandSize) {
    fail("C5F2_MACHO_INVALID", "Mach-O load-command string offset is out of bounds.");
  }
  const start = commandOffset + relativeOffset;
  const endLimit = commandOffset + commandSize;
  const end = bytes.indexOf(0, start);
  if (end === -1 || end >= endLimit) {
    fail("C5F2_MACHO_INVALID", "Mach-O load-command string is not terminated in bounds.");
  }
  const value = bytes.subarray(start, end);
  if (value.some((byte) => byte < 0x20 || byte > 0x7e)) {
    fail("C5F2_MACHO_INVALID", "Mach-O load-command string is not frozen ASCII.");
  }
  return value.toString("ascii");
}

function inspectC5F2MachOBytes(binaryBytes: Buffer): {
  loadCommandLayout: Array<{ command: number; commandSize: number }>;
  textSectionBytes: 8;
  entryOffset: 688;
  loadedDylibsExact: ["/usr/lib/libSystem.B.dylib"];
  undefinedSymbolCount: 0;
  indirectSymbolCount: 0;
  chainedFixupsImportCount: 0;
} {
  if (
    binaryBytes.byteLength !== 16_544 ||
    sha256Bytes(binaryBytes) !== C5F2_EXPECTED_RAW_BINARY_DIGEST ||
    binaryBytes.readUInt32LE(0) !== 0xfeedfacf ||
    binaryBytes.readUInt32LE(4) !== 0x0100000c ||
    binaryBytes.readUInt32LE(8) !== 0 ||
    binaryBytes.readUInt32LE(12) !== 2 ||
    binaryBytes.readUInt32LE(16) !== 14 ||
    binaryBytes.readUInt32LE(20) !== 624 ||
    binaryBytes.readUInt32LE(24) !== 0x00200085 ||
    binaryBytes.readUInt32LE(28) !== 0
  ) {
    fail("C5F2_MACHO_INVALID", "C5F2 raw bytes are not the frozen thin arm64 executable.");
  }
  const expectedLayout = [
    { command: 0x19, commandSize: 72 },
    { command: 0x19, commandSize: 152 },
    { command: 0x19, commandSize: 72 },
    { command: 0x80000034, commandSize: 16 },
    { command: 0x80000033, commandSize: 16 },
    { command: 0x2, commandSize: 24 },
    { command: 0xb, commandSize: 80 },
    { command: 0xe, commandSize: 32 },
    { command: 0x32, commandSize: 32 },
    { command: 0x2a, commandSize: 16 },
    { command: 0x80000028, commandSize: 24 },
    { command: 0xc, commandSize: 56 },
    { command: 0x26, commandSize: 16 },
    { command: 0x29, commandSize: 16 },
  ];
  const loadCommandLayout: Array<{ command: number; commandSize: number }> = [];
  const loadedDylibs: string[] = [];
  let textSectionBytes = -1;
  let entryOffset = -1;
  let undefinedSymbolCount = -1;
  let indirectSymbolCount = -1;
  let chainedImportCount = -1;
  let hasUuid = false;
  let hasCodeSignature = false;
  let hasRpath = false;
  let offset = 32;
  for (let index = 0; index < 14; index += 1) {
    if (offset + 8 > binaryBytes.byteLength) {
      fail("C5F2_MACHO_INVALID", "Mach-O load-command table ended early.");
    }
    const command = binaryBytes.readUInt32LE(offset);
    const commandSize = binaryBytes.readUInt32LE(offset + 4);
    const expected = expectedLayout[index];
    if (
      command !== expected.command ||
      commandSize !== expected.commandSize ||
      offset + commandSize > 656
    ) {
      fail("C5F2_MACHO_INVALID", "Mach-O load-command identity or exact size is invalid.");
    }
    loadCommandLayout.push({ command, commandSize });
    if (command === 0x1b) hasUuid = true;
    if (command === 0x1d) hasCodeSignature = true;
    if (command === 0x8000001c) hasRpath = true;
    if (command === 0x19) {
      const segmentName = readC5F2FixedMachOName(binaryBytes, offset + 8, 16);
      const sections = binaryBytes.readUInt32LE(offset + 64);
      if (commandSize !== 72 + sections * 80) {
        fail("C5F2_MACHO_INVALID", "Mach-O segment section table is malformed.");
      }
      if (segmentName === "__TEXT") {
        for (let section = 0; section < sections; section += 1) {
          const sectionOffset = offset + 72 + section * 80;
          const sectionName = readC5F2FixedMachOName(binaryBytes, sectionOffset, 16);
          const sectionSegment = readC5F2FixedMachOName(
            binaryBytes,
            sectionOffset + 16,
            16,
          );
          if (sectionName === "__text" && sectionSegment === "__TEXT") {
            const size = binaryBytes.readBigUInt64LE(sectionOffset + 40);
            textSectionBytes = Number(size);
          }
        }
      }
    }
    if (command === 0x80000034) {
      const dataOffset = binaryBytes.readUInt32LE(offset + 8);
      const dataSize = binaryBytes.readUInt32LE(offset + 12);
      if (dataSize < 28 || dataOffset + dataSize > binaryBytes.byteLength) {
        fail("C5F2_MACHO_INVALID", "Mach-O chained-fixups data is out of bounds.");
      }
      chainedImportCount = binaryBytes.readUInt32LE(dataOffset + 16);
    }
    if (command === 0xb) {
      undefinedSymbolCount = binaryBytes.readUInt32LE(offset + 28);
      indirectSymbolCount = binaryBytes.readUInt32LE(offset + 60);
      if (indirectSymbolCount !== 0) {
        fail("C5F2_MACHO_INVALID", "Mach-O contains indirect symbols.");
      }
    }
    if (command === 0xe) {
      const name = readC5F2MachOCString(
        binaryBytes,
        offset,
        commandSize,
        binaryBytes.readUInt32LE(offset + 8),
      );
      if (name !== "/usr/lib/dyld") {
        fail("C5F2_MACHO_INVALID", "Mach-O uses an unexpected dynamic linker.");
      }
    }
    if (command === 0x32) {
      if (
        binaryBytes.readUInt32LE(offset + 8) !== 1 ||
        binaryBytes.readUInt32LE(offset + 12) !== 0x001a0500 ||
        binaryBytes.readUInt32LE(offset + 16) !== 0x001a0500 ||
        binaryBytes.readUInt32LE(offset + 20) !== 1 ||
        binaryBytes.readUInt32LE(offset + 24) !== 3
      ) {
        fail("C5F2_MACHO_INVALID", "Mach-O build-version command is outside the frozen profile.");
      }
    }
    if (command === 0x80000028) {
      entryOffset = Number(binaryBytes.readBigUInt64LE(offset + 8));
    }
    if (command === 0xc) {
      loadedDylibs.push(readC5F2MachOCString(
        binaryBytes,
        offset,
        commandSize,
        binaryBytes.readUInt32LE(offset + 8),
      ));
    }
    offset += commandSize;
  }
  if (
    offset !== 656 ||
    canonicalJson(loadCommandLayout) !== canonicalJson(expectedLayout) ||
    textSectionBytes !== 8 ||
    entryOffset !== 688 ||
    undefinedSymbolCount !== 0 ||
    indirectSymbolCount !== 0 ||
    chainedImportCount !== 0 ||
    hasUuid ||
    hasCodeSignature ||
    hasRpath ||
    canonicalJson(loadedDylibs) !== canonicalJson(["/usr/lib/libSystem.B.dylib"])
  ) {
    fail("C5F2_MACHO_INVALID", "Mach-O structure or import policy differs from the frozen allowlist.");
  }
  return {
    loadCommandLayout,
    textSectionBytes: 8,
    entryOffset: 688,
    loadedDylibsExact: ["/usr/lib/libSystem.B.dylib"],
    undefinedSymbolCount: 0,
    indirectSymbolCount: 0,
    chainedFixupsImportCount: 0,
  };
}

async function runC5F2AuditTool(
  role: "NM_UNDEFINED" | "OTOOL_HEADER" | "OTOOL_LIBRARIES" | "OTOOL_LOAD_COMMANDS",
  root: C5F2BuildRootV1,
  binaryPath: string,
  binaryIdentity: FileIdentityStamp,
): Promise<{ stdout: Buffer; stderr: Buffer }> {
  const input = await openC5F2PinnedInput(binaryPath, binaryIdentity, "C5F2 raw binary");
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: { stdout: Buffer; stderr: Buffer } | null = null;
  const closeErrors: unknown[] = [];
  try {
    result = await runBoundedC5F2Tool(role, root, [input.fd]);
  } catch (error) {
    primaryError = error;
  } finally {
    try {
      await input.close();
    } catch (closeError) {
      closeErrors.push(closeError);
    }
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F2_AUDIT_HANDLE_CLOSE_FAILED",
    cleanupOnlyMessage: `A C5F2 ${role} input descriptor did not close cleanly.`,
    combinedMessage: "C5F2 auditor and input-descriptor close both failed.",
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
  if (result === null) {
    fail("C5F2_TOOL_FAILED", "C5F2 audit completed without tool evidence.", { role });
  }
  return result;
}

async function auditC5F2MachO(
  root: C5F2BuildRootV1,
  binaryPath: string,
  binaryBytes: Buffer,
  binaryIdentity: FileIdentityStamp,
): Promise<C5F2MachOAuditV1> {
  const parsed = inspectC5F2MachOBytes(binaryBytes);
  const nm = await runC5F2AuditTool("NM_UNDEFINED", root, binaryPath, binaryIdentity);
  const header = await runC5F2AuditTool("OTOOL_HEADER", root, binaryPath, binaryIdentity);
  const libraries = await runC5F2AuditTool(
    "OTOOL_LIBRARIES",
    root,
    binaryPath,
    binaryIdentity,
  );
  const loadCommands = await runC5F2AuditTool(
    "OTOOL_LOAD_COMMANDS",
    root,
    binaryPath,
    binaryIdentity,
  );
  for (const [label, result] of [
    ["nm", nm],
    ["otool header", header],
    ["otool libraries", libraries],
    ["otool load commands", loadCommands],
  ] as const) {
    if (result.stderr.byteLength !== 0) {
      fail("C5F2_AUDIT_INVALID", `${label} emitted unexpected stderr.`);
    }
  }
  const headerText = decodeC5F2ToolText(header.stdout, "C5F2 otool header");
  const librariesText = decodeC5F2ToolText(
    libraries.stdout,
    "C5F2 otool libraries",
  );
  const loadCommandsText = decodeC5F2ToolText(
    loadCommands.stdout,
    "C5F2 otool load commands",
  );
  const observedCommandNames = [...loadCommandsText.matchAll(/^\s*cmd (LC_[A-Z0-9_]+)$/gm)]
    .map((match) => match[1]);
  const expectedCommandNames = [
    "LC_SEGMENT_64", "LC_SEGMENT_64", "LC_SEGMENT_64", "LC_DYLD_CHAINED_FIXUPS",
    "LC_DYLD_EXPORTS_TRIE", "LC_SYMTAB", "LC_DYSYMTAB", "LC_LOAD_DYLINKER",
    "LC_BUILD_VERSION", "LC_SOURCE_VERSION", "LC_MAIN", "LC_LOAD_DYLIB",
    "LC_FUNCTION_STARTS", "LC_DATA_IN_CODE",
  ];
  if (
    nm.stdout.byteLength !== 0 ||
    !/^\/dev\/fd\/3:\nMach header\n[\s\S]*MH_MAGIC_64\s+ARM64\s+ALL\s+0x00\s+EXECUTE\s+14\s+624\s+NOUNDEFS DYLDLINK TWOLEVEL PIE\n$/.test(headerText) ||
    librariesText !==
      "/dev/fd/3:\n\t/usr/lib/libSystem.B.dylib (compatibility version 1.0.0, current version 1356.0.0)\n" ||
    canonicalJson(observedCommandNames) !== canonicalJson(expectedCommandNames) ||
    !loadCommandsText.includes("platform 1\n    minos 26.5\n      sdk 26.5") ||
    !loadCommandsText.includes("nundefsym 0") ||
    !loadCommandsText.includes("nindirectsyms 0") ||
    !loadCommandsText.includes("name /usr/lib/dyld (offset 12)") ||
    !loadCommandsText.includes("name /usr/lib/libSystem.B.dylib (offset 24)") ||
    loadCommandsText.includes("LC_UUID") ||
    loadCommandsText.includes("LC_CODE_SIGNATURE") ||
    loadCommandsText.includes("LC_RPATH")
  ) {
    fail("C5F2_AUDIT_INVALID", "Independent Mach-O tool output differs from the exact allowlist.");
  }
  const auditBody: Omit<C5F2MachOAuditV1, "auditDigest"> = {
    schemaVersion: 1,
    profile: C5F2_MACHO_AUDIT_PROFILE,
    architecture: "arm64",
    fileType: "MH_EXECUTE",
    binaryDigest: sha256Bytes(binaryBytes),
    binaryBytes: 16_544,
    loadCommandLayout: parsed.loadCommandLayout,
    textSectionBytes: parsed.textSectionBytes,
    entryOffset: parsed.entryOffset,
    loadedDylibsExact: parsed.loadedDylibsExact,
    undefinedSymbolCount: parsed.undefinedSymbolCount,
    indirectSymbolCount: parsed.indirectSymbolCount,
    chainedFixupsImportCount: parsed.chainedFixupsImportCount,
    zeroDylibDependenciesConfirmed: false,
    hasUuid: false,
    hasCodeSignature: false,
    hasRpath: false,
    nmOutputDigest: sha256Bytes(nm.stdout),
    otoolHeaderOutputDigest: sha256Bytes(header.stdout),
    otoolLibrariesOutputDigest: sha256Bytes(libraries.stdout),
    otoolLoadCommandsOutputDigest: sha256Bytes(loadCommands.stdout),
  };
  return {
    ...auditBody,
    auditDigest: computeC5DomainDigest(C5F2_MACHO_AUDIT_PROFILE, auditBody),
  };
}

async function buildC5F2Once(
  root: C5F2BuildRootV1,
): Promise<C5F2BuildObservationV1> {
  await assertC5F2BuildRootCurrent(root);
  const sourcePath = join(root.path, "helper.c");
  const objectPath = join(root.path, "helper.o");
  const binaryPath = join(root.path, "helper.raw");
  const openHandles = new Set<C5F2FileHandle>();
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: C5F2BuildObservationV1 | null = null;
  const closeErrors: unknown[] = [];
  const track = (handle: C5F2FileHandle): C5F2FileHandle => {
    openHandles.add(handle);
    return handle;
  };
  const closeTracked = async (handle: C5F2FileHandle): Promise<void> => {
    await handle.close();
    openHandles.delete(handle);
  };
  try {
    const sourceBytes = Buffer.from(C5F2_HELPER_SOURCE, "ascii");
    const sourceWriter = track(await open(
      sourcePath,
      fsConstants.O_RDWR |
        fsConstants.O_CREAT |
        fsConstants.O_EXCL |
        fsConstants.O_NOFOLLOW,
      0o400,
    ));
    const objectOutput = track(await open(
      objectPath,
      fsConstants.O_RDWR |
        fsConstants.O_CREAT |
        fsConstants.O_EXCL |
        fsConstants.O_NOFOLLOW,
      0o600,
    ));
    const binaryOutput = track(await open(
      binaryPath,
      fsConstants.O_RDWR |
        fsConstants.O_CREAT |
        fsConstants.O_EXCL |
        fsConstants.O_NOFOLLOW,
      0o600,
    ));
    await sourceWriter.chmod(0o400);
    await objectOutput.chmod(0o600);
    await binaryOutput.chmod(0o600);
    const written = await sourceWriter.write(sourceBytes, 0, sourceBytes.byteLength, 0);
    if (written.bytesWritten !== sourceBytes.byteLength) {
      fail("C5F2_SOURCE_INVALID", "C5F2 fixed source write was incomplete.");
    }
    await sourceWriter.sync();
    const sourceEvidence = await readC5F2ArtifactHandle(
      sourceWriter,
      sourcePath,
      root,
      "0400",
      "C5F2 fixed source",
    );
    if (
      !sourceEvidence.bytes.equals(sourceBytes) ||
      sha256Bytes(sourceEvidence.bytes) !== C5F2_EXPECTED_SOURCE_DIGEST
    ) {
      fail("C5F2_SOURCE_INVALID", "C5F2 fixed source readback differs from its embedded bytes.");
    }
    const sourceInput = track(await openC5F2PinnedInput(
      sourcePath,
      sourceEvidence.identity,
      "C5F2 fixed source",
    ));
    const compile = await runBoundedC5F2Tool(
      "COMPILER_CC1",
      root,
      [objectOutput.fd, sourceInput.fd],
    );
    if (compile.stdout.byteLength !== 0 || compile.stderr.byteLength !== 0) {
      fail("C5F2_TOOL_OUTPUT_UNEXPECTED", "C5F2 direct cc1 emitted unexpected output.");
    }
    const objectEvidence = await readC5F2ArtifactHandle(
      objectOutput,
      objectPath,
      root,
      "0600",
      "C5F2 object",
    );
    if (sha256Bytes(objectEvidence.bytes) !== C5F2_EXPECTED_OBJECT_DIGEST) {
      fail("C5F2_OBJECT_MISMATCH", "C5F2 direct cc1 object differs from the frozen bytes.");
    }
    await closeTracked(sourceInput);
    const objectInput = track(await openC5F2PinnedInput(
      objectPath,
      objectEvidence.identity,
      "C5F2 object",
    ));
    const linked = await runBoundedC5F2Tool(
      "LINKER",
      root,
      [binaryOutput.fd, objectInput.fd],
    );
    if (linked.stdout.byteLength !== 0 || linked.stderr.byteLength !== 0) {
      fail("C5F2_TOOL_OUTPUT_UNEXPECTED", "C5F2 direct linker emitted unexpected output.");
    }
    const binaryEvidence = await readC5F2ArtifactHandle(
      binaryOutput,
      binaryPath,
      root,
      "0600",
      "C5F2 raw binary",
    );
    if (sha256Bytes(binaryEvidence.bytes) !== C5F2_EXPECTED_RAW_BINARY_DIGEST) {
      fail("C5F2_BINARY_NONDETERMINISTIC", "C5F2 raw binary differs from the frozen bytes.");
    }
    await closeTracked(objectInput);
    const audit = await auditC5F2MachO(
      root,
      binaryPath,
      binaryEvidence.bytes,
      binaryEvidence.identity,
    );
    const sourceAfter = await readC5F2ArtifactHandle(
      sourceWriter,
      sourcePath,
      root,
      "0400",
      "C5F2 fixed source after build",
    );
    if (
      !sourceAfter.bytes.equals(sourceBytes) ||
      !fileIdentityStampsEqual(sourceAfter.identity, sourceEvidence.identity)
    ) {
      fail("C5F2_SOURCE_INVALID", "C5F2 fixed source changed during the build.");
    }
    for (const [name, handle, identity] of [
      ["helper.c", sourceWriter, sourceEvidence.identity],
      ["helper.o", objectOutput, objectEvidence.identity],
      ["helper.raw", binaryOutput, binaryEvidence.identity],
    ] as const) {
      root.retainedArtifacts.set(name, { name, handle, identity });
      openHandles.delete(handle);
    }
    result = {
      sourceDigest: sha256Bytes(sourceEvidence.bytes),
      objectDigest: sha256Bytes(objectEvidence.bytes),
      binaryDigest: sha256Bytes(binaryEvidence.bytes),
      binaryBytes: binaryEvidence.bytes,
      audit,
      exclusiveFinalComponentCreateObserved: true,
      descriptorBackingConfirmed: true,
      ancestorBindingProven: false,
      c5f2HelperDispatchAttemptCount: 0,
      toolInvocationCount: 6,
    };
  } catch (error) {
    primaryError = error;
  } finally {
    const handlesToClose = [...openHandles];
    const closeResults = await Promise.allSettled(
      handlesToClose.map(async (handle) => handle.close()),
    );
    openHandles.clear();
    closeErrors.push(...closeResults.flatMap((closeResult) =>
      closeResult.status === "rejected" ? [closeResult.reason] : []));
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F2_BUILD_HANDLE_CLOSE_FAILED",
    cleanupOnlyMessage: "One or more C5F2 build descriptors did not close cleanly.",
    combinedMessage: "C5F2 build and descriptor close both failed.",
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
  if (result === null) {
    fail("C5F2_BUILD_FAILED", "C5F2 build completed without observation evidence.");
  }
  return result;
}

async function closeC5F2RootHandles(root: C5F2BuildRootV1): Promise<unknown[]> {
  const handles = [
    ...[...root.retainedArtifacts.values()].map((artifact) => artifact.handle),
    root.handle,
    root.parentHandle,
  ];
  root.retainedArtifacts.clear();
  const results = await Promise.allSettled(handles.map(async (handle) => handle.close()));
  return results.flatMap((result) => result.status === "rejected" ? [result.reason] : []);
}

async function cleanupC5F2BuildRoot(root: C5F2BuildRootV1): Promise<void> {
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  const closeErrors: unknown[] = [];
  try {
    await assertC5F2BuildRootCurrent(root);
    const allowedEntries = new Set(["helper.c", "helper.o", "helper.raw"]);
    const entries = [...await readdir(root.path, { withFileTypes: true })]
      .sort((left, right) => codePointCompare(left.name, right.name));
    if (entries.some((entry) => !allowedEntries.has(entry.name) || entry.isDirectory())) {
      fail(
        "C5F2_CLEANUP_UNCONFIRMED",
        "C5F2 build root contains an unknown or traversable entry; recursive deletion is forbidden.",
      );
    }
    const retainedCleanup = root.retainedArtifacts.size > 0;
    if (
      retainedCleanup &&
      (
        root.retainedArtifacts.size !== 3 ||
        entries.length !== 3 ||
        entries.some((entry) => !root.retainedArtifacts.has(entry.name))
      )
    ) {
      fail(
        "C5F2_CLEANUP_UNCONFIRMED",
        "C5F2 retained artifact set differs from the exact successful-build set.",
      );
    }
    for (const entry of entries) {
      const entryPath = join(root.path, entry.name);
      const information = await lstat(entryPath, { bigint: true });
      if (!information.isFile() && !information.isSymbolicLink()) {
        fail("C5F2_CLEANUP_UNCONFIRMED", "C5F2 cleanup refuses a non-flat artifact.");
      }
      const retained = root.retainedArtifacts.get(entry.name);
      if (retained !== undefined) {
        const held = await retained.handle.stat({ bigint: true });
        if (
          !held.isFile() ||
          !fileIdentityStampsEqual(retained.identity, fileIdentityStamp(held)) ||
          !fileIdentityStampsEqual(retained.identity, fileIdentityStamp(information))
        ) {
          fail(
            "C5F2_CLEANUP_UNCONFIRMED",
            "C5F2 named artifact no longer matches its retained descriptor before cleanup.",
          );
        }
      }
    }
    for (const entry of entries) {
      await assertC5F2BuildRootCurrent(root);
      const entryPath = join(root.path, entry.name);
      const retained = root.retainedArtifacts.get(entry.name);
      if (retained !== undefined) {
        const pathBefore = await lstat(entryPath, { bigint: true });
        if (!fileIdentityStampsEqual(retained.identity, fileIdentityStamp(pathBefore))) {
          fail("C5F2_CLEANUP_UNCONFIRMED", "C5F2 artifact changed before exact unlink.");
        }
      }
      await unlink(entryPath);
      if (retained !== undefined) {
        const heldAfter = await retained.handle.stat({ bigint: true });
        if (
          String(heldAfter.dev) !== retained.identity.deviceId ||
          String(heldAfter.ino) !== retained.identity.inodeId ||
          String(heldAfter.nlink) !== "0"
        ) {
          fail(
            "C5F2_CLEANUP_UNCONFIRMED",
            "C5F2 retained artifact did not reflect exact final-component unlink.",
          );
        }
      }
    }
    await assertC5F2BuildRootCurrent(root);
    if ((await readdir(root.path)).length !== 0) {
      fail("C5F2_CLEANUP_UNCONFIRMED", "C5F2 build root did not become exactly empty.");
    }
    const heldRootBeforeRemoval = directoryIdentityStampFromStat(
      await root.handle.stat({ bigint: true }),
    );
    await rmdir(root.path);
    if (
      await pathExists(root.path) ||
      !directoryIdentityStampsEqual(
        heldRootBeforeRemoval,
        directoryIdentityStampFromStat(await root.handle.stat({ bigint: true })),
      )
    ) {
      fail("C5F2_CLEANUP_UNCONFIRMED", "C5F2 retained root does not match exact path absence.");
    }
  } catch (error) {
    primaryError = error;
    root.cleanupDisposition = "QUARANTINED";
  } finally {
    closeErrors.push(...await closeC5F2RootHandles(root));
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F2_CLEANUP_UNCONFIRMED",
    cleanupOnlyMessage: "C5F2 retained cleanup descriptors did not all close.",
    combinedMessage: "C5F2 cleanup and retained-descriptor close both failed.",
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
}

async function withC5F2ParentEnvironmentPoison<T>(
  suffix: "A" | "B",
  operation: () => Promise<T>,
): Promise<T> {
  const names = [
    "CFLAGS", "COMPILER_PATH", "CPATH", "DEVELOPER_DIR", "DYLD_LIBRARY_PATH",
    "LD_LIBRARY_PATH", "LIBRARY_PATH", "MACOSX_DEPLOYMENT_TARGET", "PATH",
    "SDKROOT", "SOURCE_DATE_EPOCH", "TMPDIR", "ZERO_AR_DATE",
  ];
  const previous = new Map<string, string | undefined>();
  for (const name of names) {
    previous.set(name, process.env[name]);
    process.env[name] = `VERITAS_C5F2_PARENT_POISON_${suffix}_${name}`;
  }
  try {
    return await operation();
  } finally {
    for (const name of names) {
      const value = previous.get(name);
      if (value === undefined) delete process.env[name];
      else process.env[name] = value;
    }
  }
}

async function assertC5DisposableHelperBuildV1(): Promise<C5DisposableHelperBuildCheckV1> {
  assert.equal(ALPHA_EXECUTION_ENABLED, false);
  assert.equal(c5F2ProcessPoisoned, false);
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.length, 164);
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.at(-1), "T163_ALPHA_FINAL_HANDLE_OBSERVATION_AUTHORITY_TAMPER_REJECTED");
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.some((id) => /^T(?:16[4-9]|17\d|18[0-3])_/.test(id)), false);
  const cleanupAdjudicationCases = assertC5CleanupAdjudicationFoundationV1();
  await assertSelfTestSourceSnapshotStable();
  const sourceBytes = Buffer.from(C5F2_HELPER_SOURCE, "ascii");
  if (
    sourceBytes.byteLength !== 32 ||
    sourceBytes.toString("ascii") !== C5F2_HELPER_SOURCE ||
    [...C5F2_HELPER_SOURCE].some((character) => character.charCodeAt(0) > 0x7f) ||
    C5F2_HELPER_SOURCE.includes("\r") ||
    C5F2_HELPER_SOURCE.includes("\0") ||
    sha256Bytes(sourceBytes) !== C5F2_EXPECTED_SOURCE_DIGEST
  ) {
    fail("C5F2_SOURCE_INVALID", "The embedded C5F2 helper source differs from its exact ASCII/LF bytes.");
  }
  const toolchain = await attestC5F2Toolchain();
  const sdk = await attestC5F2Sdk();
  const recipe = makeC5F2BuildRecipe();
  let rootA: C5F2BuildRootV1 | null = null;
  let rootB: C5F2BuildRootV1 | null = null;
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: C5DisposableHelperBuildCheckV1 | null = null;
  const cleanupErrors: unknown[] = [];
  try {
    rootA = await createC5F2BuildRoot("a");
    rootB = await createC5F2BuildRoot("b");
    if (
      rootA.path === rootB.path ||
      directoryIdentityStampsEqual(rootA.identity, rootB.identity)
    ) {
      fail("C5F2_TEMP_ROOT_INVALID", "C5F2 two-build roots are not distinct identities.");
    }
    const first = await withC5F2ParentEnvironmentPoison("A", async () =>
      buildC5F2Once(rootA as C5F2BuildRootV1));
    const second = await withC5F2ParentEnvironmentPoison("B", async () =>
      buildC5F2Once(rootB as C5F2BuildRootV1));
    if (
      !first.binaryBytes.equals(second.binaryBytes) ||
      first.sourceDigest !== second.sourceDigest ||
      first.objectDigest !== second.objectDigest ||
      first.binaryDigest !== second.binaryDigest ||
      canonicalJson(first.audit) !== canonicalJson(second.audit) ||
      first.c5f2HelperDispatchAttemptCount !== 0 ||
      second.c5f2HelperDispatchAttemptCount !== 0
    ) {
      fail("C5F2_BINARY_NONDETERMINISTIC", "C5F2 two-build evidence is not byte-identical.");
    }
    for (const evidence of [...toolchain.pinnedFiles, ...sdk.pinnedFiles]) {
      await assertC5F2PinnedFileUnchanged(evidence, `C5F2 pinned file ${evidence.path}`);
    }
    const flagsDigest = computeC5DomainDigest(C5F2_BUILD_RECIPE_PROFILE, {
      recipeDigest: recipe.recipeDigest,
      toolchainManifestDigest: toolchain.manifest.manifestDigest,
      linkerDigest: toolchain.manifest.linker.digest,
      nmDigest: toolchain.manifest.nm.digest,
      otoolDigest: toolchain.manifest.otool.digest,
      directCc1: true,
      directLinker: true,
    });
    const peerRequirementDigest = computeC5DomainDigest(
      C5F2_UNSIGNED_PEER_STATEMENT_PROFILE,
      {
        signing: "NOT_ATTEMPTED",
        peerAuthentication: "NOT_IMPLEMENTED",
        protectedAdmissionEligible: false,
        helperStartAuthority: "NONE",
      },
    );
    const negativeAuthority: C5NegativeAuthorityV1 = {
      executionAuthority: "NONE",
      maySpawnGovernedRunner: false,
      governedRunnerUseLimit: 0,
      reusableCapability: false,
    };
    const buildBody: Omit<C5NativeHelperBuildV1, "buildDigest"> = {
      ...negativeAuthority,
      schemaVersion: 1,
      recordType: "C5_NATIVE_HELPER_BUILD",
      buildProfile: C5_NATIVE_HELPER_BUILD_PROFILE,
      scope: "LOCAL_STORE_ONLY",
      disposition: "BUILD_EVIDENCE_ONLY_NOT_ADMITTED_NOT_AUTHORIZED",
      implementationClass: "TEST_ONLY_DISPOSABLE_NATIVE_HELPER_NOT_PROTECTED",
      platform: "darwin",
      architecture: "arm64",
      sourceDigest: first.sourceDigest,
      compilerDigest: toolchain.manifest.compiler.digest,
      sdkDigest: sdk.manifest.manifestDigest,
      flagsDigest,
      binaryDigest: first.binaryDigest,
      importAuditDigest: first.audit.auditDigest,
      peerRequirementDigest,
      protectedAdmissionEligible: false,
      helperStartAuthority: "NONE",
    };
    const build: C5NativeHelperBuildV1 = {
      ...buildBody,
      buildDigest: computeC5NativeHelperBuildDigest(buildBody),
    };
    validateC5NativeHelperBuildContract(build);
    result = {
      id: "C5F2_DISPOSABLE_HELPER_BUILD",
      status: "PASS",
      scope: "TWO_BUILD_DISPOSABLE_UNSIGNED_NATIVE_ARTIFACT_AND_STATIC_AUDIT_ONLY",
      foundationOnly: true,
      legacyManifestUnchanged: true,
      testsPerRun: 164,
      creditedTestIds: [],
      t164ThroughT183Evidence: false,
      t171Evidence: false,
      t182Evidence: false,
      nativeHelperBuilt: true,
      buildCount: 2,
      distinctTempRoots: true,
      exclusiveFinalComponentCreateObserved: true,
      descriptorBackingConfirmed: true,
      ancestorBindingProven: false,
      pinnedDirectToolExecutableBytesConfirmed: true,
      pinnedSelectedSdkInputBytesConfirmed: true,
      fixedChildEnvironmentConfirmed: true,
      completeToolRuntimeDependencyClosureConfirmed: false,
      directToolChildExitObserved: true,
      directToolStdioCloseObserved: true,
      processGroupKillRequired: false,
      processGroupEmptyProven: false,
      descendantAbsenceProven: false,
      rawBinaryByteEqual: true,
      sourceDigest: first.sourceDigest,
      objectDigest: first.objectDigest,
      rawBinaryDigest: first.binaryDigest,
      toolchainManifestDigest: toolchain.manifest.manifestDigest,
      sdkDigest: sdk.manifest.manifestDigest,
      recipeDigest: recipe.recipeDigest,
      machoAuditDigest: first.audit.auditDigest,
      buildDigest: build.buildDigest,
      adHocSigning: { status: "NOT_ATTEMPTED", deterministic: null },
      cleanupExpectedPathsAbsentObserved: true,
      cleanupRetainedHandleChecksPassed: true,
      cleanupAdjudicationCases,
      cleanupSameUidRaceProof: false,
      helperDispatchedByC5F2: false,
      c5f2HelperDispatchAttemptCount: 0,
      helperPathAvailableToToolDispatch: false,
      helperOutputExecutableBits: 0,
      systemWideHelperProcessAbsenceObserved: false,
      protectedAdmissionEligible: false,
      protectedSignerVerified: false,
      protectedCurrentnessVerified: false,
      governedRunnerExecuted: false,
      executionAuthority: "NONE",
    };
  } catch (error) {
    primaryError = error;
  } finally {
    for (const root of [rootA, rootB]) {
      if (root === null) continue;
      try {
        if (root.cleanupDisposition === "QUARANTINED") {
          const closeErrors = await closeC5F2RootHandles(root);
          if (closeErrors.length > 0) {
            cleanupErrors.push(new VeritasError(
              "C5F2_QUARANTINE_HANDLE_CLOSE_FAILED",
              "C5F2 quarantined-root descriptors did not all close.",
              {
                closeFailureCodes: closeErrors.map((error) =>
                  (error as NodeJS.ErrnoException).code ?? "NON_VERITAS_ERROR"),
              },
              { cause: new AggregateError(closeErrors, "C5F2 quarantined-root close failures.") },
            ));
          }
        } else {
          await cleanupC5F2BuildRoot(root);
        }
      } catch (error) {
        cleanupErrors.push(error);
      }
    }
  }
  adjudicateC5CleanupOutcome(primaryError, cleanupErrors, {
    cleanupOnlyCode: "C5F2_CLEANUP_UNCONFIRMED",
    cleanupOnlyMessage: "C5F2 cleanup did not confirm exact flat-root removal.",
    combinedMessage: "C5F2 build and root cleanup both failed.",
    secondaryDetailKey: "secondaryCleanupFailureCodes",
  });
  if (result === null) {
    fail("C5F2_BUILD_FAILED", "C5F2 completed without deterministic build evidence.");
  }
  await assertSelfTestSourceSnapshotStable();
  assert.equal(ALPHA_EXECUTION_ENABLED, false);
  return result;
}

