function c5F3B1Names(role: C5F3B1ArtifactRoleV1): {
  source: C5F2RetainedArtifactV1["name"];
  object: C5F2RetainedArtifactV1["name"];
  raw: C5F2RetainedArtifactV1["name"];
  dependency: C5F2RetainedArtifactV1["name"];
} {
  return role === "NATIVE_SUPERVISOR"
    ? { source: "supervisor.c", object: "supervisor.o", raw: "supervisor.raw", dependency: "supervisor.d" }
    : { source: "helper-b1.c", object: "helper-b1.o", raw: "helper-b1.raw", dependency: "helper-b1.d" };
}

function c5F3B1Source(role: C5F3B1ArtifactRoleV1): string {
  return role === "NATIVE_SUPERVISOR" ? C5F3B1_SUPERVISOR_SOURCE : C5F3B1_HELPER_SOURCE;
}

function c5F3B1CompilerRole(
  role: C5F3B1ArtifactRoleV1,
): Extract<C5F2ToolRoleV1, "C5F3B1_COMPILER_SUPERVISOR" | "C5F3B1_COMPILER_HELPER"> {
  return role === "NATIVE_SUPERVISOR"
    ? "C5F3B1_COMPILER_SUPERVISOR"
    : "C5F3B1_COMPILER_HELPER";
}

function assertC5F3B1PinnedToolClosure(): number {
  const roles: C5F2ToolRoleV1[] = [
    "C5F3B1_COMPILER_SUPERVISOR", "C5F3B1_COMPILER_HELPER", "LINKER",
    "NM_UNDEFINED", "OTOOL_HEADER", "OTOOL_LIBRARIES", "OTOOL_LOAD_COMMANDS",
  ];
  const allowedCommands = new Set([C5F2_COMPILER_PATH, C5F2_LINKER_PATH, C5F2_NM_PATH, C5F2_OTOOL_PATH]);
  for (const role of roles) {
    const spec = c5F2ToolSpec(role);
    if (!allowedCommands.has(spec.command) || spec.command.endsWith(".raw") || spec.args.some((arg) => arg.endsWith(".raw"))) {
      fail("C5F3B1_TOOL_DISPATCH_INVALID", "B1 tool closure escaped pinned compiler/linker/nm/otool roles.", { role });
    }
  }
  return roles.length;
}

async function createC5F3B1BuildRoot(
  role: C5F3B1ArtifactRoleV1,
  repetition: C5F3B1RepetitionV1,
): Promise<C5F3B1BuildRootV1> {
  const root = await createC5F2BuildRoot(repetition === "A" ? "a" : "b");
  return Object.assign(root, { role, repetition });
}

async function cleanupC5F3B1BuildRoot(root: C5F3B1BuildRootV1): Promise<void> {
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  const closeErrors: unknown[] = [];
  try {
    await assertC5F2BuildRootCurrent(root);
    const names = c5F3B1Names(root.role);
    const allowed = new Set([names.source, names.object, names.raw, names.dependency]);
    const entries = [...await readdir(root.path, { withFileTypes: true })]
      .sort((left, right) => codePointCompare(left.name, right.name));
    if (entries.length === 0 && root.retainedArtifacts.size === 0) {
      await rmdir(root.path);
      if (await pathExists(root.path)) {
        fail("C5F3B1_CLEANUP_UNCONFIRMED", "Empty B1 root remained addressable after removal.");
      }
    } else {
      if (
        entries.length !== 4 ||
        root.retainedArtifacts.size !== 4 ||
        entries.some((entry) => !allowed.has(entry.name as C5F2RetainedArtifactV1["name"]) ||
          entry.isDirectory() || !root.retainedArtifacts.has(entry.name))
      ) {
        fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 root differs from its exact role-bound flat artifact set.");
      }
      for (const entry of entries) {
        await assertC5F2BuildRootCurrent(root);
        const retained = root.retainedArtifacts.get(entry.name);
        if (retained === undefined) {
          fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 cleanup lost a retained artifact identity.");
        }
        const entryPath = join(root.path, entry.name);
        const pathBefore = await lstat(entryPath, { bigint: true });
        const heldBefore = await retained.handle.stat({ bigint: true });
        if (
          !pathBefore.isFile() || pathBefore.isSymbolicLink() ||
          !fileIdentityStampsEqual(retained.identity, fileIdentityStamp(pathBefore)) ||
          !fileIdentityStampsEqual(retained.identity, fileIdentityStamp(heldBefore))
        ) {
          fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 artifact changed before exact unlink.");
        }
        await unlink(entryPath);
        const heldAfter = await retained.handle.stat({ bigint: true });
        if (String(heldAfter.nlink) !== "0") {
          fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 retained artifact did not observe exact unlink.");
        }
      }
      if ((await readdir(root.path)).length !== 0) {
        fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 root did not become exactly empty.");
      }
      await rmdir(root.path);
      if (await pathExists(root.path)) {
        fail("C5F3B1_CLEANUP_UNCONFIRMED", "B1 root remained addressable after removal.");
      }
    }
  } catch (error) {
    primaryError = error;
    root.cleanupDisposition = "QUARANTINED";
  } finally {
    closeErrors.push(...await closeC5F2RootHandles(root));
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F3B1_CLEANUP_UNCONFIRMED",
    cleanupOnlyMessage: "B1 cleanup descriptors did not all close.",
    combinedMessage: "B1 cleanup and retained-descriptor close both failed.",
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
}

function inspectC5F3B1MachOBytes(binaryBytes: Buffer): C5F3B1MachOShapeV1 {
  if (
    binaryBytes.byteLength < 4_096 || binaryBytes.byteLength > 1_048_576 ||
    binaryBytes.readUInt32LE(0) !== 0xfeedfacf ||
    binaryBytes.readUInt32LE(4) !== 0x0100000c ||
    binaryBytes.readUInt32LE(8) !== 0 || binaryBytes.readUInt32LE(12) !== 2
  ) {
    fail("C5F3B1_MACHO_INVALID", "B1 artifact is not one bounded thin arm64 MH_EXECUTE image.");
  }
  const commandCount = binaryBytes.readUInt32LE(16);
  const commandBytes = binaryBytes.readUInt32LE(20);
  if (commandCount < 10 || commandCount > 64 || commandBytes < 128 || 32 + commandBytes > binaryBytes.byteLength) {
    fail("C5F3B1_MACHO_INVALID", "B1 Mach-O command table is outside frozen safety bounds.");
  }
  const layout: Array<{ command: number; commandSize: number }> = [];
  const dylibs: string[] = [];
  let textSectionBytes = -1;
  let entryOffset = -1;
  let undefinedSymbolCount = -1;
  let indirectSymbolCount = -1;
  let chainedFixupsImportCount = -1;
  let minOs = -1;
  let sdk = -1;
  let hasUuid = false;
  let hasCodeSignature = false;
  let hasRpath = false;
  let offset = 32;
  for (let index = 0; index < commandCount; index += 1) {
    if (offset + 8 > 32 + commandBytes) {
      fail("C5F3B1_MACHO_INVALID", "B1 Mach-O command table ended early.");
    }
    const command = binaryBytes.readUInt32LE(offset);
    const commandSize = binaryBytes.readUInt32LE(offset + 4);
    if (commandSize < 8 || commandSize % 8 !== 0 || offset + commandSize > 32 + commandBytes) {
      fail("C5F3B1_MACHO_INVALID", "B1 Mach-O command size is invalid.");
    }
    layout.push({ command, commandSize });
    if (command === 0x1b) hasUuid = true;
    if (command === 0x1d) hasCodeSignature = true;
    if (command === 0x8000001c) hasRpath = true;
    if (command === 0x19) {
      const segmentName = readC5F2FixedMachOName(binaryBytes, offset + 8, 16);
      const sections = binaryBytes.readUInt32LE(offset + 64);
      if (commandSize !== 72 + sections * 80) {
        fail("C5F3B1_MACHO_INVALID", "B1 segment section table is malformed.");
      }
      if (segmentName === "__TEXT") {
        for (let section = 0; section < sections; section += 1) {
          const sectionOffset = offset + 72 + section * 80;
          if (
            readC5F2FixedMachOName(binaryBytes, sectionOffset, 16) === "__text" &&
            readC5F2FixedMachOName(binaryBytes, sectionOffset + 16, 16) === "__TEXT"
          ) {
            textSectionBytes = Number(binaryBytes.readBigUInt64LE(sectionOffset + 40));
          }
        }
      }
    }
    if (command === 0x80000034) {
      const dataOffset = binaryBytes.readUInt32LE(offset + 8);
      const dataSize = binaryBytes.readUInt32LE(offset + 12);
      if (dataSize < 28 || dataOffset + dataSize > binaryBytes.byteLength) {
        fail("C5F3B1_MACHO_INVALID", "B1 chained-fixups payload is out of bounds.");
      }
      chainedFixupsImportCount = binaryBytes.readUInt32LE(dataOffset + 16);
    }
    if (command === 0xb) {
      undefinedSymbolCount = binaryBytes.readUInt32LE(offset + 28);
      indirectSymbolCount = binaryBytes.readUInt32LE(offset + 60);
    }
    if (command === 0x32) {
      if (binaryBytes.readUInt32LE(offset + 8) !== 1) {
        fail("C5F3B1_MACHO_INVALID", "B1 build-version platform is not macOS.");
      }
      minOs = binaryBytes.readUInt32LE(offset + 12);
      sdk = binaryBytes.readUInt32LE(offset + 16);
    }
    if (command === 0x80000028) entryOffset = Number(binaryBytes.readBigUInt64LE(offset + 8));
    if (command === 0xc) {
      dylibs.push(readC5F2MachOCString(
        binaryBytes,
        offset,
        commandSize,
        binaryBytes.readUInt32LE(offset + 8),
      ));
    }
    offset += commandSize;
  }
  if (
    offset !== 32 + commandBytes || textSectionBytes <= 0 || entryOffset <= 0 ||
    undefinedSymbolCount < 0 || indirectSymbolCount < 0 || chainedFixupsImportCount < 0 ||
    minOs !== 0x001a0500 || sdk !== 0x001a0500 || hasUuid || hasCodeSignature || hasRpath ||
    canonicalJson(dylibs) !== canonicalJson(["/usr/lib/libSystem.B.dylib"])
  ) {
    fail("C5F3B1_MACHO_INVALID", "B1 Mach-O violates the closed platform/layout policy.");
  }
  return {
    loadCommandLayout: layout,
    textSectionBytes,
    entryOffset,
    loadedDylibsExact: dylibs,
    undefinedSymbolCount,
    indirectSymbolCount,
    chainedFixupsImportCount,
    minOs,
    sdk,
    hasUuid,
    hasCodeSignature,
    hasRpath,
  };
}

function parseC5F3B1UndefinedSymbols(bytes: Buffer): string[] {
  const text = decodeC5F2ToolText(bytes, "C5F3B1 llvm-nm undefined-symbol output");
  if (text.length === 0) return [];
  const symbols = text.split("\n").filter((line) => line.length > 0);
  if (symbols.some((symbol) => !/^_[A-Za-z0-9_$]+$/.test(symbol))) {
    fail("C5F3B1_AUDIT_INVALID", "B1 undefined-symbol output is not one canonical symbol per line.");
  }
  if (new Set(symbols).size !== symbols.length) {
    fail("C5F3B1_AUDIT_INVALID", "B1 undefined-symbol output contains duplicates.");
  }
  return [...symbols].sort(codePointCompare);
}

async function resolveC5F3B1HeaderClosure(
  dependencyBytes: Buffer,
): Promise<Array<{ path: string; digest: string }>> {
  const dependencyText = decodeC5F2ToolText(dependencyBytes, "C5F3B1 dependency file")
    .replace(/\\\n/g, " ");
  const separator = dependencyText.indexOf(":");
  if (separator < 1 || !dependencyText.endsWith("\n")) {
    fail("C5F3B1_HEADER_CLOSURE_INVALID", "B1 dependency output is not canonical make syntax.");
  }
  const paths = dependencyText.slice(separator + 1).trim().split(/\s+/u)
    .filter((path) => path !== "/dev/fd/4");
  const unique = [...new Set(paths)].sort(codePointCompare);
  if (unique.length === 0 || unique.length !== paths.length) {
    fail("C5F3B1_HEADER_CLOSURE_INVALID", "B1 transitive header list is empty or duplicated.");
  }
  const closure: Array<{ path: string; digest: string }> = [];
  for (const headerPath of unique) {
    if (
      !isAbsolute(headerPath) || resolve(headerPath) !== headerPath ||
      (!headerPath.startsWith(`${C5F2_SDK_ROOT}/`) &&
        !headerPath.startsWith(`${C5F3B1_CLANG_RESOURCE_INCLUDE}/`))
    ) {
      fail("C5F3B1_HEADER_CLOSURE_INVALID", "B1 header escaped the two pinned include roots.", {
        headerPath,
      });
    }
    const information = await lstat(headerPath, { bigint: true });
    if (
      !information.isFile() || information.isSymbolicLink() || String(information.uid) !== "0" ||
      (information.mode & 0o022n) !== 0n || information.nlink < 1n
    ) {
      fail("C5F3B1_HEADER_CLOSURE_INVALID", "B1 header is not one root-owned immutable regular file.", {
        headerPath,
      });
    }
    const stable = await readStableRegularFile(
      headerPath,
      "C5F3B1_HEADER_CLOSURE_INVALID",
      `C5F3B1 header ${headerPath}`,
    );
    closure.push({ path: headerPath, digest: sha256Bytes(stable.bytes) });
  }
  return closure;
}

async function auditC5F3B1MachO(
  role: C5F3B1ArtifactRoleV1,
  root: C5F3B1BuildRootV1,
  binaryPath: string,
  binaryBytes: Buffer,
  binaryIdentity: FileIdentityStamp,
): Promise<C5F3B1AuditV1> {
  const shape = inspectC5F3B1MachOBytes(binaryBytes);
  const nm = await runC5F2AuditTool("NM_UNDEFINED", root, binaryPath, binaryIdentity);
  const header = await runC5F2AuditTool("OTOOL_HEADER", root, binaryPath, binaryIdentity);
  const libraries = await runC5F2AuditTool("OTOOL_LIBRARIES", root, binaryPath, binaryIdentity);
  const loadCommands = await runC5F2AuditTool(
    "OTOOL_LOAD_COMMANDS",
    root,
    binaryPath,
    binaryIdentity,
  );
  for (const result of [nm, header, libraries, loadCommands]) {
    if (result.stderr.byteLength !== 0) {
      fail("C5F3B1_AUDIT_INVALID", "B1 auditor emitted unexpected stderr.");
    }
  }
  const undefinedSymbolsExact = parseC5F3B1UndefinedSymbols(nm.stdout);
  const roleMarker = role === "NATIVE_SUPERVISOR"
    ? "VERITAS_C5F3B1_NATIVE_SUPERVISOR_V1"
    : "VERITAS_C5F3B1_NATIVE_HELPER_V1";
  const fixedHelperPathPresent = binaryBytes.includes(Buffer.from(C5F3B1_FIXED_HELPER_PATH, "ascii"));
  const forbiddenStrings = [
    "posix_spawnp", "system", "popen", "dlopen", "dlsym", "SCM_RIGHTS",
    "LAUNCH_RUNNER", "EXECUTE_COMMAND", "GRANTED", "CERTIFIED", "receiptProfile",
  ];
  if (
    !binaryBytes.includes(Buffer.from(roleMarker, "ascii")) ||
    (role === "NATIVE_SUPERVISOR" && !fixedHelperPathPresent) ||
    (role === "NATIVE_HELPER" && fixedHelperPathPresent) ||
    forbiddenStrings.some((value) => binaryBytes.includes(Buffer.from(value, "ascii")))
  ) {
    fail("C5F3B1_AUDIT_INVALID", "B1 role marker, fixed path, or forbidden-string audit failed.");
  }
  const body: Omit<C5F3B1AuditV1, "auditDigest"> = {
    schemaVersion: 1,
    profile: C5F3B1_AUDIT_PROFILE,
    role,
    binaryDigest: sha256Bytes(binaryBytes),
    binaryBytes: binaryBytes.byteLength,
    shape,
    undefinedSymbolsExact,
    nmOutputDigest: sha256Bytes(nm.stdout),
    otoolHeaderOutputDigest: sha256Bytes(header.stdout),
    otoolLibrariesOutputDigest: sha256Bytes(libraries.stdout),
    otoolLoadCommandsOutputDigest: sha256Bytes(loadCommands.stdout),
    roleMarkerPresent: true,
    fixedHelperPathPresent,
    forbiddenStringsAbsent: true,
  };
  return {
    ...body,
    auditDigest: computeC5DomainDigest(C5F3B1_AUDIT_PROFILE, body),
  };
}

function makeC5F3B1Recipe(role: C5F3B1ArtifactRoleV1): {
  role: C5F3B1ArtifactRoleV1;
  compilerArgs: readonly string[];
  linkerArgs: readonly string[];
  environment: typeof C5F2_FIXED_ENVIRONMENT;
  outputMode: "0600_NONEXECUTABLE";
  signing: "NOT_ATTEMPTED";
  generatedArtifactExecutionAllowed: false;
  recipeDigest: string;
} {
  const compilerArgs = role === "NATIVE_SUPERVISOR"
    ? C5F3B1_SUPERVISOR_CC1_ARGS
    : C5F3B1_HELPER_CC1_ARGS;
  const body = {
    role,
    compilerArgs,
    linkerArgs: C5F2_LINK_ARGS,
    environment: C5F2_FIXED_ENVIRONMENT,
    outputMode: "0600_NONEXECUTABLE" as const,
    signing: "NOT_ATTEMPTED" as const,
    generatedArtifactExecutionAllowed: false as const,
  };
  return {
    ...body,
    recipeDigest: computeC5DomainDigest(C5F3B1_RECIPE_PROFILE, body),
  };
}

async function buildC5F3B1RoleOnce(root: C5F3B1BuildRootV1): Promise<C5F3B1ObservationV1> {
  await assertC5F2BuildRootCurrent(root);
  const names = c5F3B1Names(root.role);
  const sourcePath = join(root.path, names.source);
  const objectPath = join(root.path, names.object);
  const binaryPath = join(root.path, names.raw);
  const dependencyPath = join(root.path, names.dependency);
  const openHandles = new Set<C5F2FileHandle>();
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: C5F3B1ObservationV1 | null = null;
  const closeErrors: unknown[] = [];
  const track = (handle: C5F2FileHandle): C5F2FileHandle => {
    openHandles.add(handle);
    return handle;
  };
  const closeTracked = async (handle: C5F2FileHandle): Promise<void> => {
    await handle.close();
    openHandles.delete(handle);
  };
  try {
    const sourceBytes = Buffer.from(c5F3B1Source(root.role), "ascii");
    const sourceWriter = track(await open(
      sourcePath,
      fsConstants.O_RDWR | fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_NOFOLLOW,
      0o400,
    ));
    const objectOutput = track(await open(
      objectPath,
      fsConstants.O_RDWR | fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_NOFOLLOW,
      0o600,
    ));
    const binaryOutput = track(await open(
      binaryPath,
      fsConstants.O_RDWR | fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_NOFOLLOW,
      0o600,
    ));
    const dependencyOutput = track(await open(
      dependencyPath,
      fsConstants.O_RDWR | fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_NOFOLLOW,
      0o600,
    ));
    await sourceWriter.chmod(0o400);
    await objectOutput.chmod(0o600);
    await binaryOutput.chmod(0o600);
    await dependencyOutput.chmod(0o600);
    const written = await sourceWriter.write(sourceBytes, 0, sourceBytes.byteLength, 0);
    if (written.bytesWritten !== sourceBytes.byteLength) {
      fail("C5F3B1_SOURCE_INVALID", "B1 exact source write was incomplete.");
    }
    await sourceWriter.sync();
    const sourceEvidence = await readC5F2ArtifactHandle(
      sourceWriter,
      sourcePath,
      root,
      "0400",
      `C5F3B1 ${root.role} source`,
    );
    if (!sourceEvidence.bytes.equals(sourceBytes)) {
      fail("C5F3B1_SOURCE_INVALID", "B1 source readback differs from embedded exact bytes.");
    }
    const sourceInput = track(await openC5F2PinnedInput(
      sourcePath,
      sourceEvidence.identity,
      `C5F3B1 ${root.role} source`,
    ));
    const compile = await runBoundedC5F2Tool(
      c5F3B1CompilerRole(root.role),
      root,
      [objectOutput.fd, sourceInput.fd, dependencyOutput.fd],
    );
    if (compile.stdout.byteLength !== 0 || compile.stderr.byteLength !== 0) {
      fail("C5F3B1_TOOL_OUTPUT_UNEXPECTED", "B1 direct cc1 emitted unexpected output.");
    }
    const objectEvidence = await readC5F2ArtifactHandle(
      objectOutput,
      objectPath,
      root,
      "0600",
      `C5F3B1 ${root.role} object`,
    );
    const dependencyEvidence = await readC5F2ArtifactHandle(
      dependencyOutput,
      dependencyPath,
      root,
      "0600",
      `C5F3B1 ${root.role} dependency file`,
    );
    await closeTracked(sourceInput);
    const objectInput = track(await openC5F2PinnedInput(
      objectPath,
      objectEvidence.identity,
      `C5F3B1 ${root.role} object`,
    ));
    const linked = await runBoundedC5F2Tool("LINKER", root, [binaryOutput.fd, objectInput.fd]);
    if (linked.stdout.byteLength !== 0 || linked.stderr.byteLength !== 0) {
      fail("C5F3B1_TOOL_OUTPUT_UNEXPECTED", "B1 direct linker emitted unexpected output.");
    }
    const binaryEvidence = await readC5F2ArtifactHandle(
      binaryOutput,
      binaryPath,
      root,
      "0600",
      `C5F3B1 ${root.role} raw artifact`,
    );
    await closeTracked(objectInput);
    const headerClosure = await resolveC5F3B1HeaderClosure(dependencyEvidence.bytes);
    const recipe = makeC5F3B1Recipe(root.role);
    const audit = await auditC5F3B1MachO(
      root.role,
      root,
      binaryPath,
      binaryEvidence.bytes,
      binaryEvidence.identity,
    );
    for (const [name, handle, identity] of [
      [names.source, sourceWriter, sourceEvidence.identity],
      [names.object, objectOutput, objectEvidence.identity],
      [names.raw, binaryOutput, binaryEvidence.identity],
      [names.dependency, dependencyOutput, dependencyEvidence.identity],
    ] as const) {
      root.retainedArtifacts.set(name, { name, handle, identity });
      openHandles.delete(handle);
    }
    result = {
      role: root.role,
      repetition: root.repetition,
      sourceDigest: sha256Bytes(sourceEvidence.bytes),
      recipeDigest: recipe.recipeDigest,
      objectDigest: sha256Bytes(objectEvidence.bytes),
      rawDigest: sha256Bytes(binaryEvidence.bytes),
      rawBytes: binaryEvidence.bytes,
      dependencyFileDigest: sha256Bytes(dependencyEvidence.bytes),
      headerCount: headerClosure.length,
      headerClosureDigest: computeC5DomainDigest(C5F3B1_RECIPE_PROFILE, headerClosure),
      headerClosure,
      audit,
      artifactMode: "0600_NONEXECUTABLE",
      artifactStartAttemptCount: 0,
      dynamicLoadAttemptCount: 0,
      ipcOpenAttemptCount: 0,
    };
  } catch (error) {
    primaryError = error;
    root.cleanupDisposition = "QUARANTINED";
  } finally {
    const closeResults = await Promise.allSettled([...openHandles].map(async (handle) => handle.close()));
    openHandles.clear();
    closeErrors.push(...closeResults.flatMap((closeResult) =>
      closeResult.status === "rejected" ? [closeResult.reason] : []));
  }
  adjudicateC5CleanupOutcome(primaryError, closeErrors, {
    cleanupOnlyCode: "C5F3B1_BUILD_HANDLE_CLOSE_FAILED",
    cleanupOnlyMessage: "B1 build descriptors did not all close.",
    combinedMessage: "B1 build and descriptor close both failed.",
    secondaryDetailKey: "secondaryCloseFailureCodes",
  });
  if (result === null) {
    fail("C5F3B1_BUILD_FAILED", "B1 build completed without observation evidence.");
  }
  return result;
}

type C5F3B1RoleEvidenceV1 = {
  role: C5F3B1ArtifactRoleV1;
  sourceDigest: string;
  recipeDigest: string;
  objectDigest: string;
  rawDigest: string;
  dependencyFileDigest: string;
  headerCount: number;
  headerClosureDigest: string;
  headerClosure: Array<{ path: string; digest: string }>;
  auditDigest: string;
  artifactMode: "0600_NONEXECUTABLE";
};

type C5F3B1PairEvidenceV1 = C5NegativeAuthorityV1 & {
  schemaVersion: 1;
  recordType: "C5F3B1_NATIVE_PAIR_BUILD_STATIC_AUDIT";
  profile: typeof C5F3B1_PAIR_PROFILE;
  status: "BUILT_NOT_EXECUTED";
  evidenceClass: "DETERMINISTIC_BUILD_AND_STATIC_AUDIT_ONLY";
  supervisor: C5F3B1RoleEvidenceV1;
  helper: C5F3B1RoleEvidenceV1;
  sameRoleTwoBuildByteEquality: true;
  crossRoleByteInequality: true;
  distinctPrivateRoots: true;
  generatedArtifactStartAttemptCount: 0;
  dynamicLoadAttemptCount: 0;
  ipcOpenAttemptCount: 0;
  supervisorStarted: false;
  helperStarted: false;
  ipcOpened: false;
  exactChildWaitObserved: false;
  protectedPeerVerified: false;
  protectedAuthenticationVerified: false;
  admissionReceiptIssued: false;
  terminationReceiptIssued: false;
  creditedTestIds: readonly [];
  t164ThroughT183Evidence: false;
  b2Authorized: false;
  c5f3bComplete: false;
  alphaExecutionEnabled: false;
  pairDigest: string;
};

type C5F3B1FoundationCheckV1 = {
  id: "C5F3B1_NATIVE_BUILD_AND_STATIC_AUDIT";
  status: "PASS";
  scope: "ROLE_SEPARATED_TWO_BUILD_STATIC_AUDIT_ONLY";
  foundationOnly: true;
  legacyManifestUnchanged: true;
  legacyTestsPerRun: 164;
  supervisorBuilt: true;
  helperBuilt: true;
  buildCountPerRole: 2;
  pair: C5F3B1PairEvidenceV1;
  toolchainManifestDigest: string;
  sdkManifestDigest: string;
  staticMutationCases: number;
  staticForbiddenSurfaceChecks: number;
  limitations: readonly string[];
};

const C5F3B1_PAIR_KEYS = [
  "admissionReceiptIssued", "alphaExecutionEnabled", "b2Authorized", "c5f3bComplete",
  "creditedTestIds", "crossRoleByteInequality", "distinctPrivateRoots",
  "dynamicLoadAttemptCount", "evidenceClass", "exactChildWaitObserved", "executionAuthority",
  "generatedArtifactStartAttemptCount", "governedRunnerUseLimit", "helper", "helperStarted",
  "ipcOpenAttemptCount", "ipcOpened", "maySpawnGovernedRunner", "pairDigest", "profile",
  "protectedAuthenticationVerified", "protectedPeerVerified", "recordType", "reusableCapability",
  "sameRoleTwoBuildByteEquality", "schemaVersion", "status", "supervisor", "supervisorStarted",
  "t164ThroughT183Evidence", "terminationReceiptIssued",
] as const;
const C5F3B1_ROLE_KEYS = [
  "artifactMode", "auditDigest", "dependencyFileDigest", "headerClosure", "headerClosureDigest", "headerCount",
  "objectDigest", "rawDigest", "recipeDigest", "role", "sourceDigest",
] as const;

function c5F3B1RoleEvidence(observation: C5F3B1ObservationV1): C5F3B1RoleEvidenceV1 {
  return {
    role: observation.role,
    sourceDigest: observation.sourceDigest,
    recipeDigest: observation.recipeDigest,
    objectDigest: observation.objectDigest,
    rawDigest: observation.rawDigest,
    dependencyFileDigest: observation.dependencyFileDigest,
    headerCount: observation.headerCount,
    headerClosureDigest: observation.headerClosureDigest,
    headerClosure: observation.headerClosure,
    auditDigest: observation.audit.auditDigest,
    artifactMode: "0600_NONEXECUTABLE",
  };
}

function c5F3B1ExpectedFromObservation(observation: C5F3B1ObservationV1): C5F3B1ExpectedRoleV1 {
  return {
    sourceDigest: observation.sourceDigest,
    recipeDigest: observation.recipeDigest,
    objectDigest: observation.objectDigest,
    rawDigest: observation.rawDigest,
    dependencyFileDigest: observation.dependencyFileDigest,
    headerCount: observation.headerCount,
    headerClosureDigest: observation.headerClosureDigest,
    auditDigest: observation.audit.auditDigest,
    binaryBytes: observation.audit.binaryBytes,
    shape: observation.audit.shape,
    undefinedSymbolsExact: observation.audit.undefinedSymbolsExact,
    nmOutputDigest: observation.audit.nmOutputDigest,
    otoolHeaderOutputDigest: observation.audit.otoolHeaderOutputDigest,
    otoolLibrariesOutputDigest: observation.audit.otoolLibrariesOutputDigest,
    otoolLoadCommandsOutputDigest: observation.audit.otoolLoadCommandsOutputDigest,
  };
}

function assertC5F3B1ObservationMatchesExpected(
  observation: C5F3B1ObservationV1,
  expected: C5F3B1ExpectedRoleV1,
): void {
  const actual = c5F3B1ExpectedFromObservation(observation);
  if (canonicalJson(actual) !== canonicalJson(expected)) {
    fail("C5F3B1_FROZEN_EVIDENCE_MISMATCH", "B1 role evidence differs from its frozen exact vector.", {
      role: observation.role,
      actual,
      expected,
    });
  }
}

function validateC5F3B1PairEvidence(value: unknown): C5F3B1PairEvidenceV1 {
  const record = requireC5F3B0ExactObjectKeys(
    value,
    C5F3B1_PAIR_KEYS,
    "C5F3B1_PAIR_INVALID",
    "C5F3B1 pair evidence",
  );
  const supervisor = requireC5F3B0ExactObjectKeys(
    record.supervisor,
    C5F3B1_ROLE_KEYS,
    "C5F3B1_PAIR_INVALID",
    "C5F3B1 supervisor evidence",
  );
  const helper = requireC5F3B0ExactObjectKeys(
    record.helper,
    C5F3B1_ROLE_KEYS,
    "C5F3B1_PAIR_INVALID",
    "C5F3B1 helper evidence",
  );
  validateC5NegativeAuthorityContract(record, "C5F3B1 pair evidence");
  const digestBody = omitC5Fields(record, ["pairDigest"]);
  const roleMatchesExpected = (
    candidate: Record<string, unknown>,
    expected: C5F3B1ExpectedRoleV1,
  ): boolean => {
    const closure = candidate.headerClosure;
    if (!Array.isArray(closure)) return false;
    const normalizedClosure: Array<{ path: string; digest: string }> = [];
    for (const entry of closure) {
      if (typeof entry !== "object" || entry === null || Array.isArray(entry) ||
        Object.getPrototypeOf(entry) !== Object.prototype ||
        Object.keys(entry).sort(codePointCompare).join("\0") !== "digest\0path" ||
        typeof entry.path !== "string" || !isAbsolute(entry.path) || !isSha256Digest(entry.digest)) {
        return false;
      }
      normalizedClosure.push({ path: entry.path, digest: entry.digest });
    }
    if (normalizedClosure.some((entry, index) => index > 0 &&
      codePointCompare(normalizedClosure[index - 1].path, entry.path) >= 0)) return false;
    return candidate.sourceDigest === expected.sourceDigest &&
      candidate.recipeDigest === expected.recipeDigest &&
      candidate.objectDigest === expected.objectDigest && candidate.rawDigest === expected.rawDigest &&
      candidate.dependencyFileDigest === expected.dependencyFileDigest &&
      candidate.headerCount === expected.headerCount &&
      candidate.headerClosureDigest === expected.headerClosureDigest &&
      candidate.auditDigest === expected.auditDigest &&
      computeC5DomainDigest(C5F3B1_RECIPE_PROFILE, normalizedClosure) === expected.headerClosureDigest;
  };
  if (
    record.schemaVersion !== 1 ||
    record.recordType !== "C5F3B1_NATIVE_PAIR_BUILD_STATIC_AUDIT" ||
    record.profile !== C5F3B1_PAIR_PROFILE || record.status !== "BUILT_NOT_EXECUTED" ||
    record.evidenceClass !== "DETERMINISTIC_BUILD_AND_STATIC_AUDIT_ONLY" ||
    supervisor.role !== "NATIVE_SUPERVISOR" || helper.role !== "NATIVE_HELPER" ||
    !roleMatchesExpected(supervisor, C5F3B1_EXPECTED.NATIVE_SUPERVISOR) ||
    !roleMatchesExpected(helper, C5F3B1_EXPECTED.NATIVE_HELPER) ||
    [...C5F3B1_ROLE_KEYS].filter((key) => key.endsWith("Digest")).some((key) =>
      !isSha256Digest(supervisor[key]) || !isSha256Digest(helper[key])) ||
    !Number.isSafeInteger(supervisor.headerCount) || Number(supervisor.headerCount) <= 0 ||
    !Number.isSafeInteger(helper.headerCount) || Number(helper.headerCount) <= 0 ||
    !Array.isArray(supervisor.headerClosure) || supervisor.headerClosure.length !== supervisor.headerCount ||
    !Array.isArray(helper.headerClosure) || helper.headerClosure.length !== helper.headerCount ||
    supervisor.artifactMode !== "0600_NONEXECUTABLE" ||
    helper.artifactMode !== "0600_NONEXECUTABLE" ||
    record.sameRoleTwoBuildByteEquality !== true || record.crossRoleByteInequality !== true ||
    record.distinctPrivateRoots !== true || record.generatedArtifactStartAttemptCount !== 0 ||
    record.dynamicLoadAttemptCount !== 0 || record.ipcOpenAttemptCount !== 0 ||
    record.supervisorStarted !== false || record.helperStarted !== false || record.ipcOpened !== false ||
    record.exactChildWaitObserved !== false || record.protectedPeerVerified !== false ||
    record.protectedAuthenticationVerified !== false || record.admissionReceiptIssued !== false ||
    record.terminationReceiptIssued !== false || !Array.isArray(record.creditedTestIds) ||
    record.creditedTestIds.length !== 0 || record.t164ThroughT183Evidence !== false ||
    record.b2Authorized !== false || record.c5f3bComplete !== false ||
    record.alphaExecutionEnabled !== false || !isSha256Digest(record.pairDigest) ||
    record.pairDigest !== computeC5DomainDigest(C5F3B1_PAIR_PROFILE, digestBody)
  ) {
    fail("C5F3B1_PAIR_INVALID", "B1 pair evidence exceeds the frozen nonexecuting boundary.");
  }
  return record as unknown as C5F3B1PairEvidenceV1;
}

function assertC5F3B1SourceContracts(): number {
  for (const [role, source] of [
    ["NATIVE_SUPERVISOR", C5F3B1_SUPERVISOR_SOURCE],
    ["NATIVE_HELPER", C5F3B1_HELPER_SOURCE],
  ] as const) {
    const bytes = Buffer.from(source, "ascii");
    if (
      bytes.toString("ascii") !== source ||
      [...source].some((character) => character.charCodeAt(0) > 0x7f) ||
      source.includes("\r") || source.includes("\0") || !source.endsWith("\n")
    ) {
      fail("C5F3B1_SOURCE_INVALID", "B1 source is not exact ASCII/LF text.", { role });
    }
  }
  const supervisorMainOrder = [
    "socketpair(AF_UNIX, SOCK_STREAM, 0, pair)",
    "set_cloexec(pair[0])", "set_cloexec(pair[1])",
    "posix_spawn_file_actions_init(&actions)", "posix_spawn_file_actions_addchdir(&actions, \"/\")",
    "add_dup_close(&actions, null_in, 0)",
    "posix_spawn_file_actions_adddup2(&actions, null_out, 1)",
    "posix_spawn_file_actions_adddup2(&actions, null_out, 2)",
    "posix_spawn_file_actions_addclose(&actions, null_out)",
    "add_dup_close(&actions, child_fd, 3)", "POSIX_SPAWN_CLOEXEC_DEFAULT",
    "posix_spawn(&child, k_helper_path", "exact_wait(child, &origin, &status, &first_error)",
  ];
  let prior = -1;
  for (const surface of supervisorMainOrder) {
    const index = C5F3B1_SUPERVISOR_SOURCE.indexOf(surface);
    if (index <= prior) fail("C5F3B1_SOURCE_INVALID", "B1 supervisor required surfaces are absent or reordered.", { surface });
    prior = index;
  }
  const supervisorLifecycleSurfaces = [
    "posix_spawn_file_actions_adddup2", "signal_once(child, SIGTERM", "signal_once(child, SIGKILL",
    "waitid(P_PID, (id_t)child", "waitpid(child, status, 0)",
  ];
  for (const surface of supervisorLifecycleSurfaces) {
    if (!C5F3B1_SUPERVISOR_SOURCE.includes(surface)) {
      fail("C5F3B1_SOURCE_INVALID", "B1 supervisor lifecycle surface is absent.", { surface });
    }
  }
  if (C5F3B1_SUPERVISOR_SOURCE.indexOf("elapsed >= 2500 && signal_once(child, SIGTERM") >=
    C5F3B1_SUPERVISOR_SOURCE.indexOf("elapsed >= 3000 && signal_once(child, SIGKILL")) {
    fail("C5F3B1_SOURCE_INVALID", "B1 signal-once escalation order changed.");
  }
  const spawnSucceeded = C5F3B1_SUPERVISOR_SOURCE.indexOf(
    "if (spawn_result != 0 || child <= 0) return 73;",
  );
  const reapedDominatesReturns = C5F3B1_SUPERVISOR_SOURCE.indexOf(
    "(void)exact_wait(child, &origin, &status, &first_error);",
    spawnSucceeded,
  );
  const postSpawnPreReap = C5F3B1_SUPERVISOR_SOURCE.slice(spawnSucceeded, reapedDominatesReturns);
  if (
    spawnSucceeded < 0 || reapedDominatesReturns < 0 ||
    (postSpawnPreReap.match(/\breturn\b/gu) ?? []).length !== 1 ||
    C5F3B1_SUPERVISOR_SOURCE.includes("errno != ESRCH") ||
    C5F3B1_SUPERVISOR_SOURCE.includes("return WAIT_POISONED") ||
    !C5F3B1_SUPERVISOR_SOURCE.includes("return poisoned_ownership_wait(child, status, first_error")
  ) {
    fail("C5F3B1_SOURCE_INVALID", "B1 post-spawn return graph is not dominated by exact WAIT_REAPED ownership.");
  }
  const poisonStart = C5F3B1_SUPERVISOR_SOURCE.indexOf("static int poisoned_ownership_wait(");
  const poisonEnd = C5F3B1_SUPERVISOR_SOURCE.indexOf("static int exact_wait(", poisonStart);
  const poisonBody = C5F3B1_SUPERVISOR_SOURCE.slice(poisonStart, poisonEnd);
  const killCallCount: number = (C5F3B1_SUPERVISOR_SOURCE.match(/\bkill\s*\(/gu) ?? []).length;
  const timeoutBranch = "if (elapsed >= 3500) { remember_error(first_error, ETIMEDOUT); return poisoned_ownership_wait";
  const exactWaitStart = C5F3B1_SUPERVISOR_SOURCE.indexOf("static int exact_wait(");
  const deadlineDecision = C5F3B1_SUPERVISOR_SOURCE.indexOf(timeoutBranch, exactWaitStart);
  const exitObservation = C5F3B1_SUPERVISOR_SOURCE.indexOf("waitid(P_PID", exactWaitStart);
  if (
    poisonStart < 0 || poisonEnd < 0 || poisonBody.includes("kill(") || poisonBody.includes("signal_once(") ||
    killCallCount !== 1 || deadlineDecision < exactWaitStart || exitObservation <= deadlineDecision ||
    !C5F3B1_SUPERVISOR_SOURCE.includes("if (*attempted != 0) return 0; *attempted = 1;") ||
    !C5F3B1_SUPERVISOR_SOURCE.includes("&term_attempted, &kill_attempted") ||
    !C5F3B1_SUPERVISOR_SOURCE.includes("if (first_error != 0) return 74;")
  ) {
    fail("C5F3B1_SOURCE_INVALID", "B1 timeout or shared signal-once ownership invariant is absent.");
  }
  const modelLateExitAfterDeadline = (
    exitStatus: number,
    firstError: number = 60,
  ): "FAILURE" | "SUCCESS" => {
    // ETIMEDOUT is frozen as nonzero before the late exact reap.
    return firstError !== 0 || exitStatus !== 0 ? "FAILURE" : "SUCCESS";
  };
  const modelSignalAttempts = (iterations: number): { term: number; kill: number } => {
    let term = 0; let kill = 0;
    for (let index = 0; index < iterations; index += 1) {
      if (term === 0) term = 1;
      if (kill === 0) kill = 1;
    }
    return { term, kill };
  };
  if (modelLateExitAfterDeadline(0) !== "FAILURE" ||
    canonicalJson(modelSignalAttempts(10_000)) !== canonicalJson({ term: 1, kill: 1 })) {
    fail("C5F3B1_SOURCE_INVALID", "B1 timeout or prolonged-wait signal model admitted success/retry.");
  }
  const helperMainOrder = [
    "if (validate_null_descriptors() != 0)", "if (validate_control_descriptor() != 0)",
    "if (closefrom_barrier() != 0)", "return close(3)",
  ];
  prior = -1;
  for (const surface of helperMainOrder) {
    const index = C5F3B1_HELPER_SOURCE.indexOf(surface);
    if (index <= prior) fail("C5F3B1_SOURCE_INVALID", "B1 helper required surfaces are absent or reordered.", { surface });
    prior = index;
  }
  if (!C5F3B1_HELPER_SOURCE.includes("fcntl(3, F_SETFD, descriptor_flags | FD_CLOEXEC)")) {
    fail("C5F3B1_SOURCE_INVALID", "B1 helper fd3 CLOEXEC restoration surface is absent.");
  }
  const forbiddenBoth = [
    /\bposix_spawnp\s*\(/u, /\bfork\s*\(/u, /\bexec[a-z]*\s*\(/u,
    /\bsystem\s*\(/u, /\bpopen\s*\(/u, /\bdlopen\s*\(/u, /\bdlsym\s*\(/u,
    /\bsocket\s*\(/u, /\bbind\s*\(/u, /\bconnect\s*\(/u, /\blisten\s*\(/u,
    /\baccept\s*\(/u, /\bsendmsg\s*\(/u, /\brecvmsg\s*\(/u, /SCM_RIGHTS/u,
    /\bgetenv\s*\(/u, /\bsetenv\s*\(/u, /\benviron\b/u,
  ];
  for (const pattern of forbiddenBoth) {
    if (pattern.test(C5F3B1_SUPERVISOR_SOURCE) || pattern.test(C5F3B1_HELPER_SOURCE)) {
      fail("C5F3B1_SOURCE_INVALID", "B1 source contains a forbidden dynamic or authority-bearing surface.", {
        pattern: pattern.source,
      });
    }
  }
  for (const pattern of [/\bposix_spawn\s*\(/u, /\bwaitpid\s*\(/u, /\bwaitid\s*\(/u, /\bkill\s*\(/u, /\bsocketpair\s*\(/u]) {
    if (pattern.test(C5F3B1_HELPER_SOURCE)) {
      fail("C5F3B1_SOURCE_INVALID", "B1 helper acquired a supervisor-only lifecycle surface.");
    }
  }
  return supervisorMainOrder.length + supervisorLifecycleSurfaces.length + helperMainOrder.length +
    forbiddenBoth.length * 2 + 6;
}

type C5F3B1PairStaticEvidenceBuildV1 = {
  observations: Record<C5F3B1ArtifactRoleV1, [C5F3B1ObservationV1, C5F3B1ObservationV1]>;
  toolchain: Awaited<ReturnType<typeof attestC5F2Toolchain>>;
  sdk: Awaited<ReturnType<typeof attestC5F2Sdk>>;
};

async function buildC5F3B1PairStaticEvidence(): Promise<C5F3B1PairStaticEvidenceBuildV1> {
  const toolchain = await attestC5F2Toolchain();
  const sdk = await attestC5F2Sdk();
  await assertC5F2ProtectedDirectory(C5F3B1_CLANG_RESOURCE_INCLUDE, "C5F3B1 Clang resource include root");
  await assertC5F2ProtectedDirectory(C5F3B1_SDK_INCLUDE, "C5F3B1 SDK include root");
  const roots: C5F3B1BuildRootV1[] = [];
  let primaryError: unknown = NO_C5_PRIMARY_ERROR;
  let result: C5F3B1PairStaticEvidenceBuildV1 | null = null;
  const cleanupErrors: unknown[] = [];
  try {
    for (const role of ["NATIVE_SUPERVISOR", "NATIVE_HELPER"] as const) {
      for (const repetition of ["A", "B"] as const) {
        roots.push(await createC5F3B1BuildRoot(role, repetition));
      }
    }
    if (new Set(roots.map((root) => `${root.identity.deviceId}:${root.identity.inodeId}`)).size !== 4) {
      fail("C5F3B1_ROOT_INVALID", "B1 role/repetition roots are not four distinct identities.");
    }
    const supervisorA = await withC5F2ParentEnvironmentPoison("A", async () => buildC5F3B1RoleOnce(roots[0]));
    const supervisorB = await withC5F2ParentEnvironmentPoison("B", async () => buildC5F3B1RoleOnce(roots[1]));
    const helperA = await withC5F2ParentEnvironmentPoison("A", async () => buildC5F3B1RoleOnce(roots[2]));
    const helperB = await withC5F2ParentEnvironmentPoison("B", async () => buildC5F3B1RoleOnce(roots[3]));
    result = {
      observations: {
        NATIVE_SUPERVISOR: [supervisorA, supervisorB],
        NATIVE_HELPER: [helperA, helperB],
      },
      toolchain,
      sdk,
    };
  } catch (error) {
    primaryError = error;
  } finally {
    for (const root of roots) {
      try {
        if (root.cleanupDisposition === "QUARANTINED") {
          const closeErrors = await closeC5F2RootHandles(root);
          cleanupErrors.push(...closeErrors);
        } else {
          await cleanupC5F3B1BuildRoot(root);
        }
      } catch (error) {
        cleanupErrors.push(error);
      }
    }
  }
  adjudicateC5CleanupOutcome(primaryError, cleanupErrors, {
    cleanupOnlyCode: "C5F3B1_CLEANUP_UNCONFIRMED",
    cleanupOnlyMessage: "B1 exact root cleanup failed.",
    combinedMessage: "B1 pair build and exact root cleanup both failed.",
    secondaryDetailKey: "secondaryCleanupFailureCodes",
  });
  if (result === null) {
    fail("C5F3B1_BUILD_FAILED", "B1 pair build completed without static evidence.");
  }
  return result;
}

function redigestC5F3B1Pair(record: C5F3B1PairEvidenceV1): C5F3B1PairEvidenceV1 {
  const body = omitC5Fields(record, ["pairDigest"]);
  return {
    ...record,
    pairDigest: computeC5DomainDigest(C5F3B1_PAIR_PROFILE, body),
  };
}

async function assertC5F3B1NativeBuildAndStaticAuditV1(): Promise<C5F3B1FoundationCheckV1> {
  assert.equal(ALPHA_EXECUTION_ENABLED, false);
  assert.equal(C5F3B1_FIRST_RUN_AUTHORIZED, false);
  assert.equal(c5F2ProcessPoisoned, false);
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.length, 164);
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.at(-1), "T163_ALPHA_FINAL_HANDLE_OBSERVATION_AUTHORITY_TAMPER_REJECTED");
  assert.equal(EXPECTED_SELF_TEST_IDS_V1.some((id) => /^T(?:16[4-9]|17\d|18[0-3])_/.test(id)), false);
  const staticForbiddenSurfaceChecks = assertC5F3B1SourceContracts();
  const pinnedToolClosureChecks = assertC5F3B1PinnedToolClosure();
  await assertSelfTestSourceSnapshotStable();
  const built = await buildC5F3B1PairStaticEvidence();
  const [supervisorA, supervisorB] = built.observations.NATIVE_SUPERVISOR;
  const [helperA, helperB] = built.observations.NATIVE_HELPER;
  for (const [first, second] of [[supervisorA, supervisorB], [helperA, helperB]] as const) {
    if (
      !first.rawBytes.equals(second.rawBytes) ||
      canonicalJson(c5F3B1ExpectedFromObservation(first)) !==
        canonicalJson(c5F3B1ExpectedFromObservation(second)) ||
      canonicalJson(first.headerClosure) !== canonicalJson(second.headerClosure)
    ) {
      fail("C5F3B1_BINARY_NONDETERMINISTIC", "B1 same-role clean builds are not byte/evidence identical.", {
        role: first.role,
      });
    }
  }
  if (
    supervisorA.rawBytes.equals(helperA.rawBytes) ||
    supervisorA.sourceDigest === helperA.sourceDigest || supervisorA.recipeDigest === helperA.recipeDigest ||
    supervisorA.objectDigest === helperA.objectDigest || supervisorA.rawDigest === helperA.rawDigest ||
    supervisorA.audit.auditDigest === helperA.audit.auditDigest
  ) {
    fail("C5F3B1_ROLE_ALIAS", "B1 supervisor and helper identities are not role-separated.");
  }
  assertC5F3B1ObservationMatchesExpected(supervisorA, C5F3B1_EXPECTED.NATIVE_SUPERVISOR);
  assertC5F3B1ObservationMatchesExpected(helperA, C5F3B1_EXPECTED.NATIVE_HELPER);
  for (const evidence of [...built.toolchain.pinnedFiles, ...built.sdk.pinnedFiles]) {
    await assertC5F2PinnedFileUnchanged(evidence, `C5F3B1 pinned file ${evidence.path}`);
  }
  const negativeAuthority: C5NegativeAuthorityV1 = {
    executionAuthority: "NONE",
    maySpawnGovernedRunner: false,
    governedRunnerUseLimit: 0,
    reusableCapability: false,
  };
  const pairBody: Omit<C5F3B1PairEvidenceV1, "pairDigest"> = {
    ...negativeAuthority,
    schemaVersion: 1,
    recordType: "C5F3B1_NATIVE_PAIR_BUILD_STATIC_AUDIT",
    profile: C5F3B1_PAIR_PROFILE,
    status: "BUILT_NOT_EXECUTED",
    evidenceClass: "DETERMINISTIC_BUILD_AND_STATIC_AUDIT_ONLY",
    supervisor: c5F3B1RoleEvidence(supervisorA),
    helper: c5F3B1RoleEvidence(helperA),
    sameRoleTwoBuildByteEquality: true,
    crossRoleByteInequality: true,
    distinctPrivateRoots: true,
    generatedArtifactStartAttemptCount: 0,
    dynamicLoadAttemptCount: 0,
    ipcOpenAttemptCount: 0,
    supervisorStarted: false,
    helperStarted: false,
    ipcOpened: false,
    exactChildWaitObserved: false,
    protectedPeerVerified: false,
    protectedAuthenticationVerified: false,
    admissionReceiptIssued: false,
    terminationReceiptIssued: false,
    creditedTestIds: [],
    t164ThroughT183Evidence: false,
    b2Authorized: false,
    c5f3bComplete: false,
    alphaExecutionEnabled: false,
  };
  const pair = validateC5F3B1PairEvidence({
    ...pairBody,
    pairDigest: computeC5DomainDigest(C5F3B1_PAIR_PROFILE, pairBody),
  });
  const mutations: Array<(value: C5F3B1PairEvidenceV1) => void> = [
    (value) => { value.status = "EXECUTED" as C5F3B1PairEvidenceV1["status"]; },
    (value) => { value.supervisor.rawDigest = "0".repeat(64); },
    (value) => { value.helper.sourceDigest = "0".repeat(64); },
    (value) => { value.supervisor.objectDigest = value.helper.objectDigest; },
    (value) => { value.helper.auditDigest = value.supervisor.auditDigest; },
    (value) => { value.supervisor.artifactMode = "0755_EXECUTABLE" as "0600_NONEXECUTABLE"; },
    (value) => { value.supervisor.headerCount = 0; },
    (value) => { value.helper.headerClosure = []; },
    (value) => { (value as unknown as Record<string, unknown>).generatedArtifactStartAttemptCount = 1; },
    (value) => { (value as unknown as Record<string, unknown>).dynamicLoadAttemptCount = 1; },
    (value) => { (value as unknown as Record<string, unknown>).ipcOpenAttemptCount = 1; },
    (value) => { (value as unknown as Record<string, unknown>).supervisorStarted = true; },
    (value) => { (value as unknown as Record<string, unknown>).helperStarted = true; },
    (value) => { (value as unknown as Record<string, unknown>).ipcOpened = true; },
    (value) => { (value as unknown as Record<string, unknown>).exactChildWaitObserved = true; },
    (value) => { (value as unknown as Record<string, unknown>).protectedPeerVerified = true; },
    (value) => { (value as unknown as Record<string, unknown>).protectedAuthenticationVerified = true; },
    (value) => { (value as unknown as Record<string, unknown>).admissionReceiptIssued = true; },
    (value) => { (value as unknown as Record<string, unknown>).terminationReceiptIssued = true; },
    (value) => { value.creditedTestIds = ["T171"] as unknown as []; },
    (value) => { (value as unknown as Record<string, unknown>).t164ThroughT183Evidence = true; },
    (value) => { (value as unknown as Record<string, unknown>).b2Authorized = true; },
    (value) => { (value as unknown as Record<string, unknown>).c5f3bComplete = true; },
    (value) => { (value as unknown as Record<string, unknown>).alphaExecutionEnabled = true; },
    (value) => { (value as unknown as Record<string, unknown>).executionAuthority = "GRANTED"; },
    (value) => { (value as unknown as Record<string, unknown>).maySpawnGovernedRunner = true; },
    (value) => { (value as unknown as Record<string, unknown>).governedRunnerUseLimit = 1; },
    (value) => { (value as unknown as Record<string, unknown>).reusableCapability = true; },
    (value) => {
      const supervisor = value.supervisor;
      value.supervisor = value.helper as unknown as C5F3B1RoleEvidenceV1;
      value.helper = supervisor as unknown as C5F3B1RoleEvidenceV1;
    },
  ];
  for (const [mutationIndex, mutate] of mutations.entries()) {
    const candidate = structuredClone(pair) as C5F3B1PairEvidenceV1;
    mutate(candidate);
    const recomputed = redigestC5F3B1Pair(candidate);
    assert.throws(
      () => validateC5F3B1PairEvidence(recomputed),
      (error: unknown) => error instanceof VeritasError &&
        ["C5F3B1_PAIR_INVALID", "C5_AUTHORITY_INVALID"].includes(error.code),
      `Expected B1 mutation ${mutationIndex} to reject.`,
    );
  }
  const extra = structuredClone(pair) as unknown as Record<string, unknown>;
  extra.launchOpcode = "forbidden";
  assert.throws(
    () => validateC5F3B1PairEvidence(extra),
    (error: unknown) => error instanceof VeritasError && error.code === "C5F3B1_PAIR_INVALID",
  );
  const source = requireSelfTestSourceSnapshot().source;
  const beginIndex = source.indexOf("// C5F3B1_NATIVE_BUILD_STATIC_AUDIT_BEGIN");
  const endIndex = source.indexOf("// C5F3B1_NATIVE_BUILD_STATIC_AUDIT_END");
  assert(beginIndex >= 0 && endIndex > beginIndex);
  const region = source.slice(beginIndex, endIndex);
  let maskedRegion = region;
  for (const [startToken, endToken] of [
    ["const C5F3B1_INERT_PROTOCOL_SOURCE = [", "] as const;"],
    ["const C5F3B1_SUPERVISOR_SOURCE = [", "].join(\"\\n\") + \"\\n\";"],
    ["const C5F3B1_HELPER_SOURCE = [", "].join(\"\\n\") + \"\\n\";"],
  ] as const) {
    const start = maskedRegion.indexOf(startToken);
    const finishStart = maskedRegion.indexOf(endToken, start + startToken.length);
    if (start < 0 || finishStart < 0) fail("C5F3B1_SOURCE_INVALID", "B1 embedded C masking boundary is absent.");
    const finish = finishStart + endToken.length;
    maskedRegion = maskedRegion.slice(0, start) + maskedRegion.slice(start, finish).replace(/[^\n]/gu, " ") +
      maskedRegion.slice(finish);
  }
  const regionForbidden = [
    /C5F3B1_FIRST_RUN_AUTHORIZED\s*=\s*true/u,
    /ALPHA_EXECUTION_ENABLED\s*=\s*true/u,
    /chmod\([^\n]*0o7/u,
    /runC5F3B1Generated/u,
    /startC5F3B1Artifact/u,
    /importC5F3B1Artifact/u,
    /dlopenC5F3B1/u,
  ];
  for (const pattern of regionForbidden) {
    assert.equal(pattern.test(maskedRegion), false, `Forbidden B1 implementation surface: ${pattern.source}`);
  }
  const fragmentedForbidden = [
    new RegExp("\\b" + "sp" + "awn(?:Sync)?\\s*\\(", "u"),
    new RegExp("\\bexec" + "(?:File)?(?:Sync)?\\s*\\(", "u"),
    new RegExp("\\bf" + "ork\\s*\\(", "u"),
    new RegExp("\\bdl" + "open\\s*\\(", "u"),
    new RegExp("process\\s*(?:\\.|\\[)[^\\n]{0,24}" + "dlopen", "u"),
    new RegExp("\\bB" + "un\\b|\\bD" + "eno\\b", "u"),
    new RegExp("\\bsock" + "et\\s*\\(|\\b(?:net|tls|dgram)\\s*\\.", "u"),
    new RegExp("\\b(?:createServer|connect|listen|accept|sendmsg|recvmsg)\\s*\\(", "u"),
    new RegExp("\\bch" + "mod\\s*\\([^\\n]*(?:0o?7|S_IX)", "u"),
    new RegExp("\\bmmap\\s*\\([^\\n]*PROT_" + "EXEC", "u"),
  ];
  for (const pattern of fragmentedForbidden) {
    assert.equal(pattern.test(maskedRegion), false, `Forbidden masked B1 runtime surface: ${pattern.source}`);
  }
  await assertSelfTestSourceSnapshotStable();
  assert.equal(ALPHA_EXECUTION_ENABLED, false);
  assert.equal(C5F3B1_FIRST_RUN_AUTHORIZED, false);
  return {
    id: "C5F3B1_NATIVE_BUILD_AND_STATIC_AUDIT",
    status: "PASS",
    scope: "ROLE_SEPARATED_TWO_BUILD_STATIC_AUDIT_ONLY",
    foundationOnly: true,
    legacyManifestUnchanged: true,
    legacyTestsPerRun: 164,
    supervisorBuilt: true,
    helperBuilt: true,
    buildCountPerRole: 2,
    pair,
    toolchainManifestDigest: built.toolchain.manifest.manifestDigest,
    sdkManifestDigest: built.sdk.manifest.manifestDigest,
    staticMutationCases: mutations.length + 1,
    staticForbiddenSurfaceChecks: staticForbiddenSurfaceChecks + pinnedToolClosureChecks +
      regionForbidden.length + fragmentedForbidden.length,
    limitations: [
      "BUILT_NOT_EXECUTED",
      "NO_GENERATED_ARTIFACT_EXECUTION",
      "BUILD_AND_AUDITOR_CHILD_PROCESSES_ONLY",
      "NO_GENERATED_ARTIFACT_EXECUTE_BITS_DYNAMIC_LOAD_OR_IPC",
      "SOURCE_IMPORT_LAYOUT_AND_HEADER_CLOSURE_STATIC_EVIDENCE_ONLY",
      "NO_RUNTIME_FD_CLOEXEC_SPAWN_SIGNAL_WAIT_OR_RLIMIT_OBSERVATION",
      "B2_REQUIRES_FRESH_EXACT_SOURCE_AND_DUAL_ARTIFACT_DIGEST_REVIEW",
      "NO_PROTECTED_PEER_AUTHENTICATION_CURRENTNESS_OR_RECEIPTS",
      "NO_T164_TO_T183_CREDIT",
      "ALPHA_EXECUTION_DISABLED",
      "NO_PATENT_PRODUCTION_SIGNING_OR_RELEASE_CREDIT",
    ],
  };
}
// C5F3B1_NATIVE_BUILD_STATIC_AUDIT_END

// C5F3B2_DORMANT_AUTHORIZATION_GATE_BEGIN
const C5F3B2_STATIC_TUPLE_PROFILE =
  "veritas-c5f3b2-static-tuple-v1:exact-b1-vectors+blocked-path+zero-authority";
const C5F3B2_AUTHORIZATION_PROFILE =
  "veritas-c5f3b2-external-authorization-v1:independent-detached-signature+one-use-shape";
const C5F3B2_RESERVATION_PROFILE =
  "veritas-c5f3b2-reservation-contract-v1:pure-in-process-no-writer";
const C5F3B2_DORMANT_FOUNDATION_PROFILE =
  "veritas-c5f3b2-dormant-foundation-v1:validate-shape-then-refuse";
const C5F3B2_EXECUTION_IMPLEMENTED = false;
const C5F3B2_AUTHORIZATION_RECORD: C5F3B2ExternalAuthorizationV1 | null = null;
