    pathOpened: false,
    pathIdentityVerified: false,
    pathChangeRequiresFreshB1Freeze: true,
    b1VectorsFrozenForCurrentPath: true,
    executionImplemented: false,
    authorizationRecordPresent: false,
    independentTrustAnchorPresent: false,
    reservationWriterImplemented: false,
    generatedArtifactStartAttemptCount: 0,
    dynamicLoadAttemptCount: 0,
    ipcOpenAttemptCount: 0,
    authorizedUseLimit: 0,
    firstRunAuthorized: false,
    supervisorStarted: false,
    helperStarted: false,
    exactChildWaitObserved: false,
    protectedPeerVerified: false,
    protectedAuthenticationVerified: false,
    protectedCurrentnessVerified: false,
    admissionReceiptIssued: false,
    terminationReceiptIssued: false,
