    reservationEvidenceClass: "PURE_IN_PROCESS_RESERVATION_CONTRACT_NO_WRITER",
    stateMachineEvidenceClass: "PURE_IN_PROCESS_REFUSAL_TRANSITION_GRAMMAR_ONLY",
