      assert.equal(recovery.actions[0]?.transactionId, pendingPromotion.transactionId);
      const accepted = await readAcceptedReference(fixture.store);
      assert.equal(accepted?.objectDigest, checked.decision.candidate.digest);
      assert.equal(accepted?.transactionId, pendingPromotion.transactionId);
      const receiptPath = join(fixture.store, "receipts", `${checked.decision.decisionId}.json`);
      const receipt = await readVerifiedEnvelope<Receipt>(receiptPath);
      assert.equal(receipt.record.lifecycle, "ACTIVE");
